### NEW v0.20.2 LX2 — Linux start-up crash with colour emoji fonts ###
# Tk before 8.6.13 on X11 (Ubuntu 22.04: Tk 8.6.12 + Xft) crashes (segmentation fault in XSync, under
# Tk_AllocFontFromObj) when a colour font (Noto Color Emoji; fontconfig also gives it for "Segoe UI Emoji") was
# loaded and the next font is loaded before the window is drawn: the main window's header did exactly that.
# Before the first Tk window, fontconfig is told to skip colour fonts for this process; the emoji then come from a
# black-and-white font if one is installed (else they show as boxes). MEDIACLINIC_COLOR_EMOJI=1 keeps colour fonts,
# =0 skips them on any Tk; an own FONTCONFIG_FILE is never replaced. Windows and macOS: nothing changes.
_FC_NO_COLOUR_XML = """<?xml version="1.0"?>
<!DOCTYPE fontconfig SYSTEM "fonts.dtd">
<fontconfig>
  <include ignore_missing="yes">{conf}</include>
  <selectfont><rejectfont>
    <pattern><patelt name="color"><bool>true</bool></patelt></pattern>
  </rejectfont></selectfont>
</fontconfig>
"""


def _tk_version_tuple(text):
    """'8.6.12' → (8, 6, 12); '8.6b1' → (8, 6, 0)-like; missing parts are 0."""
    out = []
    for part in str(text).split(".")[:3]:
        digits = ""
        for ch in part:
            if not ch.isdigit():
                break
            digits += ch
        out.append(int(digits) if digits else 0)
    return tuple(out + [0] * (3 - len(out)))


def x11_skip_colour_fonts(environ=None, platform=None, patchlevel=None, system_conf="/etc/fonts/fonts.conf",
                          folder=None):
    """Point FONTCONFIG_FILE at a config that includes the system one and rejects colour fonts, when Tk would
    crash on them.  Returns the file written, or None (nothing changed).  Call it before the first tk.Tk()."""
    environ = os.environ if environ is None else environ
    platform = sys.platform if platform is None else platform
    if platform.startswith(("win", "cygwin", "darwin")):
        return None
    if environ.get("FONTCONFIG_FILE"):
        return None                                              # the user's own font config is left alone
    choice = environ.get("MEDIACLINIC_COLOR_EMOJI", "").strip()
    if choice == "1":
        return None
    if choice != "0":
        if patchlevel is None:
            try:
                patchlevel = tk.Tcl().eval("info patchlevel")    # Tcl only: no display, no fonts loaded yet
            except Exception:
                return None
        if _tk_version_tuple(patchlevel) >= (8, 6, 13):
            return None
    if not os.path.isfile(system_conf):
        return None                                              # without the system config there would be no fonts
    try:
        import tempfile
        fd, path = tempfile.mkstemp(prefix="mediaclinic-fonts-", suffix=".conf", dir=folder)
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            f.write(_FC_NO_COLOUR_XML.format(conf=_xml_escape(system_conf)))
    except OSError:
        return None
    environ["FONTCONFIG_FILE"] = path
    return path


_FC_SKIP_COLOUR_FILE = x11_skip_colour_fonts()                   # before any Tk window (the self-test imports first)


### NEW v0.19.4 L5 / I15b — theme colour tokens (the values of the Catppuccin-Mocha-like theme) ###
C_BG, C_MANTLE, C_ROW_ALT = "#1e1e2e", "#181825", "#252535"
C_SURFACE, C_SURFACE2, C_HOVER = "#313244", "#45475a", "#585b70"
C_TEXT, C_SUBTEXT, C_DIM = "#cdd6f4", "#a6adc8", "#6c7086"
C_ACCENT, C_OK, C_WARN, C_ERR, C_PEACH = "#89b4fa", "#a6e3a1", "#f9e2af", "#f38ba8", "#fab387"
_UI_SCALE = 1.0                                                  # set by _apply_theme from Tk's scaling
_NAMED_FONTS = {}                                                # the MC.* fonts: a Font object deletes its Tk font when collected


def px(n):                                                       ### NEW v0.19.4 L5 / I15b ###
    """*n* logical pixels (designed at 100 %) at the current UI scale (125 % → ×1.25)."""
    return int(round(n * _UI_SCALE))


def _apply_theme(root):                                          ### NEW v0.19.4 L5 / I15b — once, at start ###
    """ttk theme + styles, named fonts, the UI scale.  Before v0.19.4 the
    notebook tabs were styled only when Help or Settings first opened."""
    global _UI_SCALE
    import tkinter.font as _tkfont
    try:
        _UI_SCALE = max(1.0, float(root.tk.call("tk", "scaling")) / (96 / 72))
    except (tk.TclError, ValueError):
        _UI_SCALE = 1.0
    if os.name != "nt":                                          ### NEW v0.19.6 TR8 ###
        # X11 Tk draws a 1-px focus ring in a light colour around every button and checkbox even without focus
        # (white boxes on the dark theme): the ring rests in the background colour and shows only on focus
        root.option_add("*highlightBackground", C_BG)
        root.option_add("*highlightColor", C_ACCENT)
    style = ttk.Style(root)
    style.theme_use("clam")
    style.configure("TNotebook", background=C_BG, borderwidth=0)
    style.configure("TNotebook.Tab", background=C_SURFACE, foreground=C_TEXT, padding=[10, 5], font=("Helvetica", 9))
    style.map("TNotebook.Tab", background=[("selected", C_SURFACE2)], foreground=[("selected", C_ACCENT)])
    style.configure("Vertical.TScrollbar", background=C_SURFACE2, troughcolor=C_BG, arrowcolor=C_TEXT)
    style.configure("Horizontal.TScrollbar", background=C_SURFACE2, troughcolor=C_BG, arrowcolor=C_TEXT)
    for name, spec in (("MC.Body", ("Helvetica", 10)), ("MC.Bold", ("Helvetica", 10, "bold")),
                       ("MC.Small", ("Helvetica", 9)), ("MC.Heading", ("Helvetica", 13, "bold"))):
        fam, size = spec[0], spec[1]
        weight = "bold" if "bold" in spec[2:] else "normal"
        try:
            f = _tkfont.Font(root=root, name=name, family=fam, size=size, weight=weight, exists=True)
            f.configure(family=fam, size=size, weight=weight)
        except tk.TclError:
            f = _tkfont.Font(root=root, name=name, family=fam, size=size, weight=weight)
        _NAMED_FONTS[name] = f
    return style


import mc_i18n as _i18n                                         ### NEW v0.20.0 UI1c — needed by the registry below ###


def _n(n, word, fmt="", plural=None):                            ### NEW v0.19.4 B105 — one plurals helper ###
    """'1 movie', '2 movies', '0 movies' — *fmt* formats the number (e.g.
    ','), *plural* for irregular words ('entry' → 'entries' is automatic).
    ### MODIFIED v0.20.0 UI1c ### a word with a catalog key ("n.movie" …) comes from tn() in the interface
    language (CLDR plurals; "," → num(): 1,204 / 1.204); other words keep the English rule until UI1d."""
    if plural is None and _i18n.has("n." + word):
        shown = _i18n.num(n) if fmt == "," else (format(n, fmt) if fmt else None)
        return _i18n.tn("n." + word, n, as_text=shown)
    try:
        one = float(n) == 1
    except (TypeError, ValueError):
        one = False
    num = format(n, fmt) if fmt else f"{n}"
    if plural is None:
        plural = (word[:-1] + "ies") if (word.endswith("y") and word[-2:-1] not in "aeiou") else word + "s"
    return f"{num} {word if one else plural}"


### NEW v0.19.4 I13 — one action registry ###
# Every menu / shortcut action: label, keys, run(app), needs_results (the B91
# "scan running" check), path (the menu it lives in, for messages).  The Tools
# menu, the Help menu's fixed entries and the shortcuts are built from it, so
# labels, shortcuts and commands cannot drift; layout F (L1 / L2) moves the
# entries by changing only the lists below.
ACTIONS = {}

### NEW v0.20.0 UI1c — labels in the interface language ###
# A label is (icon, catalog key, shortcut hint): the catalog holds the words only, the code adds the icon, two
# spaces and "  (Ctrl+…)", so the English labels stay exactly as before and menu_path() / the right-click Repeat
# work in every language.  Labels built at import are rebuilt by _i18n_refresh() once the language is chosen
# (init_interface_language, before the first widget) — the module constants below are plain strings again then.
_I18N_LABELS = {}                                               # global name → (icon, key, hint)


def ui_label(icon, key, hint=""):                                ### NEW v0.20.0 UI1c ###
    """'🕘  Backup History / Undo…' / '📤  Export Movie List…  (Ctrl+Shift+E)' in the interface language."""
    s = _i18n.t(key)
    return (f"{icon}  {s}" if icon else s) + (f"  ({hint})" if hint else "")


def _label_const(name, icon, key, hint=""):                      ### NEW v0.20.0 UI1c ###
    """A module-level menu label that follows the interface language (rebuilt by _i18n_refresh)."""
    _I18N_LABELS[name] = (icon, key, hint)
    return ui_label(icon, key, hint)


def _spec(name):                                                 ### NEW v0.20.0 UI1c ###
    """The (icon, key, hint) of a label constant, for register_action."""
    return _I18N_LABELS[name]


def register_action(aid, label, run=None, keys=(), needs_results=False, path="Tools", part="movies"):
    """### v0.19.4 I14 ### part: the action works only while that part is shown
    (None = app-wide: Settings, Help, Backup History, About …).
    ### v0.20.0 UI1c ### *label* is (icon, catalog key, hint); the shown label follows the interface language."""
    spec = tuple(label) if isinstance(label, tuple) else None
    ACTIONS[aid] = {"id": aid, "label": ui_label(*spec) if spec else label, "spec": spec, "run": run,
                    "keys": tuple(keys), "needs_results": needs_results, "path": path, "part": part}


def short_label_text(text):                                      ### NEW v0.20.1 TM1 ###
    """A label inside a Tools submenu: 'Normalize Sources — All Movies…' → 'Normalize Sources…' (the submenu's
    heading says the entries work on all movies). Labels without ' — ' stay as they are."""
    head, sep, _tail = str(text).partition(" — ")
    return (head + ("…" if text.rstrip().endswith("…") and not head.rstrip().endswith("…") else "")) if sep else text


def action_short_label(aid):                                     ### NEW v0.20.1 TM1 ###
    """The label of an action inside a Tools submenu (icon and shortcut hint kept), in the interface language."""
    a = ACTIONS[aid]
    spec = a.get("spec")
    if not spec:
        return short_label_text(a["label"])
    icon, key, hint = (tuple(spec) + ("",))[:3]
    txt = short_label_text(_i18n.t(key))
    return (f"{icon}  {txt}" if icon else txt) + (f"  ({hint})" if hint else "")


def menu_path(aid):
    """'Tools → Backup History / Undo…' for messages (the label without its
    topic emoji and shortcut hint).  ### v0.20.0 UI1c ### in the interface language.
    ### v0.20.1 TM1 ### an entry inside a Tools submenu: 'Tools → IDs → Normalize Sources…'."""
    a = ACTIONS[aid]
    if a.get("spec"):
        lbl = _i18n.t(a["spec"][1])
        if a.get("sub") and a["path"]:
            return f"{_i18n.t('path.' + a['path'].lower())} → {_i18n.t(a['sub'])} → {short_label_text(lbl)}"
        return f"{_i18n.t('path.' + a['path'].lower())} → {lbl}" if a["path"] else lbl
    lbl = re.sub(r"^\S+\s{2,}", "", a["label"].strip())
    lbl = re.sub(r"\s+\((?:Ctrl|F\d)[^)]*\)$", "", lbl)
    return f"{a['path']} → {lbl}" if a["path"] else lbl


