import queue as _queue_mod                                        ### NEW v0.19.4 (D23 / B25) ###
_UI_QUEUE = _queue_mod.SimpleQueue()                              # put() is safe inside a destructor
_UI_ROOT = [None]                                                 # the main window (App) that drains the queue
_RF_POST_LOCK = threading.Lock()


def _ui_call(fn, args):                                           ### NEW v0.19.4 (D23 / B25) ###
    """One queued call on the Tk thread; a window closed meanwhile is not an error (it was not with after(0))."""
    try:
        fn(*args)
    except tk.TclError:
        pass


def ui_post(fn, *args):                                           ### NEW v0.19.4 (D23 / B25) ###
    """Run fn(*args) on the Tk thread.  From the Tk thread: after(0).  From a worker: a queue the main window drains
    every 25 ms — a worker never calls Tk itself (CLAUDE.md rule 4)."""
    root = _UI_ROOT[0]
    if root is not None and threading.current_thread() is threading.main_thread():
        try:
            root.after(0, _ui_call, fn, args)
        except (RuntimeError, tk.TclError):
            pass
        return
    _UI_QUEUE.put((fn, args))


def _ui_queue_clear():                                            ### NEW v0.19.5 B115 ###
    """Drop what is left in the queue: those calls belong to a window that is gone. Decided: a closed window's items never
    run. A Tk clean-up among them needs nothing either, because its interpreter is gone with the window."""
    n = 0
    while True:
        try:
            _UI_QUEUE.get_nowait()
            n += 1
        except _queue_mod.Empty:
            return n


_MAIN_THREAD_ID = threading.main_thread().ident


def _tk_del_on_ui_thread(cls):                                    ### NEW v0.19.4 — a freeze found by CI ###
    """A Tk object's clean-up belongs on the Tk thread.  The garbage collector can run __del__ on any thread: a Tcl call
    there waits for the Tk thread, and if the Tk thread is waiting for that thread (Thread.start() waits until the new
    thread runs), the app freezes for good.  On another thread the clean-up now goes through the ui_post queue."""
    orig = cls.__dict__.get("__del__")
    if orig is None or getattr(orig, "_mc_safe", False):
        return

    def __del__(self):
        if threading.get_ident() == _MAIN_THREAD_ID:           # not current_thread(): a starting thread is not registered yet
            orig(self)
        else:
            _UI_QUEUE.put((orig, (self,)))
    __del__._mc_safe = True
    cls.__del__ = __del__


_tk_del_on_ui_thread(tk.Variable)
_tk_del_on_ui_thread(tk.Image)
import tkinter.font as _tkfont_del                                ### NEW v0.19.5 B114 — Font.__del__ is a Tcl call too ###
_tk_del_on_ui_thread(_tkfont_del.Font)
if _PIL_AVAILABLE:
    _tk_del_on_ui_thread(_PILImageTk.PhotoImage)
    _tk_del_on_ui_thread(_PILImageTk.BitmapImage)
