# ── Text editor opener ────────────────────────────────────────────────────────
# _find_notepadpp is imported from settings_controller (v0.18.3)
def open_in_editor(filepath):
    """
    Open a file in the configured text editor.
    For NFO/XML files with Notepad++: notepad++.exe "path\\file.xml" -lxml
    (file path MUST come before -lxml — putting it after causes Notepad++ to
    show a 'Create new file?' dialog treating the path as a language tag).
    Falls back to OS default handler — no intermediate Notepad with -l flag.
    """
    editor = SETTINGS.get("text_editor", "").strip()
    ext = os.path.splitext(filepath)[1].lower()
    is_markup = ext in (".xml", ".nfo")

    def _launch_npp(npp_path):
        """Launch Notepad++ with filepath FIRST, then -lxml (correct order)."""
        try:
            cmd = [npp_path, filepath, "-lxml"] if is_markup else [npp_path, filepath]
            subprocess.Popen(cmd,
                             creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
            return True
        except Exception:
            return False

    # 1. Use configured editor if set
    if editor and os.path.isfile(editor):
        if is_markup and "notepad++" in editor.lower():
            if _launch_npp(editor):
                return
        else:
            try:
                subprocess.Popen([editor, filepath],
                                 creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
                return
            except Exception:
                pass

    # 2. Auto-detect Notepad++ on Windows
    if os.name == "nt" and is_markup:
        npp = _find_notepadpp()
        if npp and _launch_npp(npp):
            return

    # 3. Fall back to OS default (no prompts)
    try:
        if os.name == "nt":
            os.startfile(filepath)
        else:
            subprocess.Popen([unix_open_command(), filepath])          # v0.19.6 TR8
    except Exception as e:
        messagebox.showerror(_i18n.t("mc.cannot_open_6a5c"), str(e))


def unix_open_command():                                        ### NEW v0.19.6 TR8 ###
    """Linux / macOS: the program that opens a file or folder with its default app
    (macOS `open`, else `xdg-open`). A clear message when it is missing (WSL and
    minimal installs have no xdg-utils; v0.19.5 then tried macOS's `open` and said
    "No such file or directory: 'open'")."""
    cmd = "open" if sys.platform == "darwin" else "xdg-open"
    if not shutil.which(cmd):
        raise OSError(f"'{cmd}' was not found, so files and folders cannot be opened from MediaClinic.\n"
                      "Debian / Ubuntu: sudo apt install xdg-utils  (Fedora: sudo dnf install xdg-utils)")
    return cmd


def os_open(path):
    """Open any file/folder with default OS handler."""
    try:
        if os.name == "nt":
            os.startfile(path)
        else:
            subprocess.Popen([unix_open_command(), path])              # v0.19.6 TR8
    except Exception as e:
        messagebox.showerror(_i18n.t("mc.cannot_open_6a5c"), str(e))

