# ── v0.19.2 F4b: the optional AI upscaler (Real-ESRGAN ncnn-vulkan) ───────────
def upscaler_dir():                                              ### NEW v0.19.2 F4b ###
    """tools\\realesrgan under the config folder (never next to the program)."""
    return os.path.join(_sc.get_config_dir(), "tools", "realesrgan")


def upscaler_exe():
    return os.path.join(upscaler_dir(), UPSCALER_DOWNLOAD["exe"])


def upscaler_installed():
    return os.name == "nt" and os.path.isfile(upscaler_exe())


def upscaler_cmd(inp, out, scale=4):                             ### NEW v0.19.2 F4b ###
    """The upscaler command line (the self-test replaces it by a fake upscaler).
    ### MODIFIED v0.19.3 B62 ### "gentle" (default): tiles of 256 px and one
    load / process / save thread, so the PC and the app keep responding."""
    cmd = [upscaler_exe(), "-i", inp, "-o", out, "-n", UPSCALER_DOWNLOAD["model"], "-s", str(scale)]
    if upscaler_mode() == "gentle":
        cmd += ["-t", "256", "-j", "1:1:1"]
    return cmd


def upscaler_mode():                                             ### NEW v0.19.3 B62 ###
    """"gentle" (default: slower, the PC stays usable) or "fast"."""
    m = (SETTINGS.get("image_fix_prefs") or {}).get("ai_mode", "gentle")
    return m if m in ("gentle", "fast") else "gentle"


UPSCALER_HUNG_SEC = 30                                           ### NEW v0.19.3 B62 ###


def upscaler_state():                                            ### NEW v0.19.2 F4 / F4b ###
    """(usable, text for the dialog) of the optional AI upscaler."""
    if os.name != "nt":
        return False, _i18n.t("uf.ai_upscale_windows_only_cca7")
    if not upscaler_installed():
        return False, _i18n.t("uf.ai_upscale_not_installed_2ab7")
    t = (SETTINGS.get("image_fix_prefs") or {}).get("ai_test", "")
    if t == "ok":
        return True, _i18n.t("uf.ai_upscale_ready_real_6301")
    if t:
        return False, _i18n.t("uf.ai_upscale_off_plain_3cd7", t=t)
    return False, _i18n.t("uf.ai_upscale_installed_not_0882")


def upscaler_download_info():                                    ### NEW v0.19.2 F4 / F4b ###
    """The pinned download (url, size, sha256 …) or None (not Windows)."""
    return dict(UPSCALER_DOWNLOAD) if os.name == "nt" else None


def _third_party_file(name):
    for base in (getattr(sys, "_MEIPASS", None), _APP_DIR):
        if base:
            p = os.path.join(base, "third_party", name)
            if os.path.isfile(p):
                return p
    return None


def download_upscaler(progress=None, cancel=None, info=None):    ### NEW v0.19.2 F4b ###
    """Worker thread: download the pinned zip, check its size and SHA-256,
    unpack it (no demo files, no path outside the folder) next to the two
    licence texts, then swap it in.  Nothing half-installed is left behind.
    Returns the install folder; raises on any failure."""
    import hashlib, urllib.request, zipfile
    info = info or UPSCALER_DOWNLOAD
    d = upscaler_dir()
    os.makedirs(os.path.dirname(d), exist_ok=True)
    tmp = d + ".download"
    staging = d + ".new"
    h = hashlib.sha256(); n = 0
    try:
        with urllib.request.urlopen(urllib.request.Request(info["url"], headers={"User-Agent": _UA}),   # A11
                                    timeout=60) as r, open(tmp, "wb") as f:
            while True:
                if cancel and cancel():
                    raise RuntimeError("cancelled")
                b = r.read(1 << 16)
                if not b:
                    break
                f.write(b); h.update(b); n += len(b)
                if progress:
                    progress(n, info["size"])
        if n != info["size"] or h.hexdigest() != info["sha256"]:
            raise RuntimeError(f"the download does not match the pinned release (size {n:,}, "
                               f"SHA-256 {h.hexdigest()[:16]}…) — not installed")
        shutil.rmtree(staging, ignore_errors=True)
        with zipfile.ZipFile(tmp) as z:
            for zi in z.infolist():
                name = zi.filename.replace("\\", "/")
                parts = [x for x in name.split("/") if x]
                if zi.is_dir() or not parts or name.startswith("/") or not all(zip_part_ok(x) for x in parts):   ### MODIFIED v0.19.4 B96a ###
                    continue
                if os.path.splitext(name)[1].lower() in (".mp4", ".jpg"):   # demo files
                    continue
                dest = os.path.join(staging, *parts)
                if not inside_dir(dest, staging):                ### NEW v0.19.4 B96a ###
                    continue
                os.makedirs(os.path.dirname(dest), exist_ok=True)
                with z.open(zi) as src, open(dest, "wb") as out:
                    shutil.copyfileobj(src, out)
        if not os.path.isfile(os.path.join(staging, info["exe"])):
            raise RuntimeError(f"{info['exe']} is not in the download — not installed")
        for lic in info.get("licences", ()):
            lp = _third_party_file(lic)
            if lp:
                shutil.copy2(lp, os.path.join(staging, lic))
        ### MODIFIED v0.19.4 B83 — was rmtree(d, ignore_errors) + replace: a locked file left a
        ### half-deleted install.  Now the old folder is renamed aside first (a locked file makes
        ### the rename fail and the old install keeps working), removed only after the swap. ###
        old = d + ".old"
        if os.path.isdir(d):
            shutil.rmtree(old, ignore_errors=True)
            try:
                os.replace(d, old)
            except OSError as e:
                raise RuntimeError(f"the installed upscaler is in use ({e}) — the old install was kept; "
                                   "close what uses it and try again") from e
        try:
            os.replace(staging, d)
        except OSError:
            if os.path.isdir(old) and not os.path.exists(d):
                os.replace(old, d)                              # put the old install back
            raise
        shutil.rmtree(old, ignore_errors=True)
        logger.info(f"AI upscaler installed: {info.get('release', info['url'])} → {d} ({n:,} bytes, SHA-256 checked)")
        return d
    finally:
        for p in (tmp,):
            try:
                if os.path.exists(p):
                    os.remove(p)
            except OSError:
                pass
        shutil.rmtree(staging, ignore_errors=True)


def test_upscaler(timeout=30):                                   ### NEW v0.19.2 F4b ###
    """Worker thread: (ok, reason) — the upscaler run once on a tiny generated
    image through the B28 runner.  A non-zero exit or no output = no usable
    Vulkan GPU."""
    import tempfile
    td = tempfile.mkdtemp(prefix="mc_upscale_test_")
    try:
        inp, out = os.path.join(td, "in.png"), os.path.join(td, "out.png")
        _PILImage.new("RGB", (32, 32), (120, 80, 40)).save(inp)
        st, rc, _o, err = _run_ffmpeg(upscaler_cmd(inp, out), timeout=timeout)
        if st == FF_TIMEOUT:
            return False, f"the test did not finish in {timeout} s"
        if st != FF_OK or rc != 0:
            return False, f"no usable Vulkan GPU (exit code {rc})"
        if not os.path.isfile(out):
            return False, "no usable Vulkan GPU (no output)"
        with _PILImage.open(out) as im:
            if im.size != (128, 128):
                return False, f"unexpected output size {im.size[0]}×{im.size[1]}"
        return True, ""
    except Exception as e:
        return False, str(e)
    finally:
        shutil.rmtree(td, ignore_errors=True)


def upscale_function(cancel=None):                               ### NEW v0.19.2 F4 / F4b; cancel v0.19.3 B62 ###
    """original PIL image → 4× PIL image (None on failure: the fix then uses
    the plain resize), for image_fix.render; None when the upscaler is not
    usable.  The function's .failed list records failures for the message.
    ### v0.19.3 B62 ### *cancel* (plain callable) stops the upscaler; gentle
    mode runs it at IDLE priority; no CPU for 30 s = hung → stopped."""
    ok, _why = upscaler_state()
    if not ok:
        return None
    import tempfile

    def _up(img):
        td = tempfile.mkdtemp(prefix="mc_upscale_")
        try:
            inp, out = os.path.join(td, "in.png"), os.path.join(td, "out.png")
            img.convert("RGB").save(inp)
            st, rc, _o, err = _run_ffmpeg(upscaler_cmd(inp, out), timeout=max(60, _ff_run_budget()), cancel=cancel,
                                          priority="idle" if upscaler_mode() == "gentle" else None,
                                          hung_after=UPSCALER_HUNG_SEC)          ### MODIFIED v0.19.3 B62 ###
            if st != FF_OK or rc != 0 or not os.path.isfile(out):
                if st == FF_HUNG:
                    _up.failed.append(_i18n.t("uf.the_upscaler_stopped_responding_26d4", upscaler_hung_sec=UPSCALER_HUNG_SEC))
                    logger.warning(f"AI upscaler stopped responding (no CPU for {UPSCALER_HUNG_SEC} s) — stopped, plain resize used")
                elif st == FF_TIMEOUT:
                    _up.failed.append(_i18n.t("uf.the_upscaler_took_longer_3091", max=max(60, _ff_run_budget())))
                    logger.warning("AI upscale took longer than the run budget — stopped, plain resize used")
                else:
                    _up.failed.append(_i18n.t("uf.status_exit_code_4eed", st=st, rc=rc))
                    logger.warning(f"AI upscale failed ({st}, exit code {rc}): {(err or '')[-300:]} — plain resize used")
                return None
            with _PILImage.open(out) as im:
                im.load()
                return im.copy()
        finally:
            shutil.rmtree(td, ignore_errors=True)
    _up.failed = []
    return _up
_FIX_KINDS = ("poster", "folder", "fanart")
_FIX_KIND_LABEL = {"poster": "Poster", "folder": "Folder image", "fanart": "Fanart"}


def image_fix_kinds(row):                                        ### NEW v0.19.2 F4 ###
    """Images of the row that a fix can help: present, decodable, with wrong
    proportions or below the minimum resolution."""
    out = []
    for k in _FIX_KINDS:
        fl = row.get(f"{k}_flags") or {}
        if row.get(f"{k}_exists") and not fl.get("corrupt") and (fl.get("bad_ratio") or fl.get("low_res")):
            out.append(k)
    return out


def _dim_of(row, kind):
    """(w, h) from the row's "W×H" text, or (None, None)."""
    try:
        w, h = str(row.get(f"{kind}_dim") or "").replace("x", "×").split("×")
        return int(w), int(h)
    except (ValueError, TypeError):
        return None, None


def image_fix_target(row, kind):                                 ### NEW v0.19.2 F4 ###
    """(dest, remove_after, format) for the fixed image (F4.6 item 1): the file
    found is overwritten in its own format family (JPEG / .tbn → JPEG, PNG →
    PNG); a .webp / .gif / .bmp is written as the .jpg of the same name and
    the old file removed after a successful write (artwork_write_target)."""
    src = row[f"{kind}_path"]
    ext = os.path.splitext(src)[1].lower()
    if ext in (".jpg", ".jpeg", ".tbn"):
        return src, None, "JPEG"
    if ext == ".png":
        return src, None, "PNG"
    dest, rm = artwork_write_target(row["subfolder_path"], kind)
    return dest, rm, "JPEG"


class ImageFixStopped(RuntimeError):                           ### NEW v0.19.3 B62 ###
    def __init__(self):
        super().__init__("stopped — nothing was changed")


_IMAGE_FIX_LOCK = threading.Lock()                               ### NEW v0.19.3 B62 — one image fix at a time ###
APP_CLOSING = threading.Event()                                  ### NEW v0.20.1 T9 — set when the window closes: workers stop ###


_FIX_PAIR = {"poster": "folder", "folder": "poster"}              ### NEW v0.19.3 B66 ###


def image_fix_copy_default(row, kind):                           ### NEW v0.19.3 B66 ###
    """The other image of the poster / folder.jpg pair that a fix of *kind*
    also writes by default ("Also copy the result to …", ticked), or None
    (fanart, or the other file is missing)."""
    other = _FIX_PAIR.get(kind)
    return other if other and row.get(f"{other}_exists") and row.get(f"{other}_path") else None


def image_fix_pair_mode(row, kind):                             ### NEW v0.20.0 RD7 ###
    """(other, mode) for the poster / folder.jpg pair of a fix of *kind*: mode "copy" when the two are the same
    picture (the result is copied, as in B66), "fix" when they are different pictures (the other one is fixed on its
    own and keeps its picture), or (None, None).  A Reddit tester's different folder.jpg was replaced by the fixed
    poster; the user (2026-11-14): fix each, keep both."""
    other = image_fix_copy_default(row, kind)
    if not other:
        return None, None
    return other, ("fix" if _poster_folder_differ(row) else "copy")


class _FixWritten(list):                                         ### NEW v0.19.5 WR-B6 ###
    """The files apply_image_fix wrote, and what could not be done after the main image was written."""
    def __init__(self, *a):
        super().__init__(*a)
        self.problems = []


def apply_image_fix(row, kind, method, target, upscale=None, batch_ref=None, cancel=None,
                    copy_to=None):   ### NEW v0.19.2 F4; cancel v0.19.3 B62; copy_to v0.19.3 B66 ###
    """Fix one image on disk (worker thread; no Tk): backup, render, atomic
    write, old file removed, folder.jpg kept in sync when it was identical to
    the poster.  Returns the written paths; raises on failure.
    ### v0.19.3 B62 ### *cancel* (plain callable): checked after the render,
    before anything is written (ImageFixStopped).
    ### v0.19.3 B66 ### *copy_to*: None = as before (folder.jpg follows a
    poster it was identical to); "folder" / "poster" = the fixed image is also
    written as that file (backed up in the same run); False = only *kind*."""
    src = row[f"{kind}_path"]
    dest, rm, fmt = image_fix_target(row, kind)
    if copy_to is None:
        copy_to = "folder" if (kind == "poster" and row.get("folder_exists") and row.get("folder_path")
                               and not _poster_folder_differ(row)) else False
    if copy_to and (copy_to == kind or not row.get(f"{copy_to}_exists") or not row.get(f"{copy_to}_path")):
        copy_to = False
    o_src = row.get(f"{copy_to}_path") if copy_to else None
    o_dest, o_rm, _o_fmt = image_fix_target(row, copy_to) if copy_to else (None, None, None)
    sync = bool(copy_to)
    paths = [p for p in dict.fromkeys((src, dest, o_src, o_dest)) if p]
    name = row.get("movie_name", row.get("subfolder", ""))
    _ref = batch_ref if batch_ref is not None else [None]      ### MODIFIED v0.19.5 WR-C2 — a run to record new files in ###
    _new = [p for p in (dest, o_dest if sync else None) if p and not os.path.exists(p)]
    ok = _batch_backup_ok(name, _ref, *paths)
    if not ok:
        raise BackupFailed()
    with _PILImage.open(src) as im:
        im.load()
        out = _ifx.render(im, kind, method, target, upscale)
    if cancel and cancel():                                     ### NEW v0.19.3 B62 ###
        raise ImageFixStopped()
    tmp = f"{dest}.{threading.get_ident() % 100000}.mctmp"     # v0.20.2 PA15: one temp file per writer
    try:
        out.save(tmp, fmt, **({"quality": _ifx.JPEG_QUALITY} if fmt == "JPEG" else {}))
        _sc._replace_retry(tmp, dest)                            # v0.19.5 WR-B1
        _cache_forget(dest)                                     ### NEW v0.19.3 I11 ###
    finally:
        if os.path.exists(tmp):
            try:
                os.remove(tmp)
            except OSError:
                pass
    written = _FixWritten([dest])
    if dest in _new:
        _sc.note_created(_BACKUP_ROOT, name, _ref, dest, None, logger=logger)   # NEW v0.19.5 WR-C2: Undo removes it
    ### MODIFIED v0.19.5 WR-B6 — the image is written: a later step that fails is said as such, it does not read "Not changed" ###
    def _later(what, fn, *args):
        try:
            fn(*args)
            return True
        except OSError as e:
            written.problems.append(f"{what}: {e}")
            logger.warning(f"Fix image: {name}: {what}: {e}")
            return False
    if rm and os.path.normcase(rm) != os.path.normcase(dest) and os.path.isfile(rm):
        _later(f"{os.path.basename(rm)} could not be removed", _sc._replace_retry, rm, rm + ".mcdel", 20, 0.05, lambda s, d: os.remove(s))
    if sync:                                                    ### MODIFIED v0.19.3 B66 — either direction ###
        if _later(f"{os.path.basename(o_dest)} could not be written", _copy_image_as, dest, o_dest):
            written.append(o_dest)
            if o_dest in _new:
                _sc.note_created(_BACKUP_ROOT, name, _ref, o_dest, None, logger=logger)   # NEW v0.19.5 WR-C2
            if o_rm and os.path.normcase(o_rm) != os.path.normcase(o_dest) and os.path.isfile(o_rm):
                _later(f"{os.path.basename(o_rm)} could not be removed", _sc._replace_retry, o_rm, o_rm + ".mcdel", 20, 0.05, lambda s, d: os.remove(s))
    logger.info(f"Fix image: {name} — {os.path.basename(src)} → {os.path.basename(dest)} "
                f"{out.size[0]}×{out.size[1]} ({method})"
                + (f" + copied to {os.path.basename(o_dest)}" if sync else ""))
    return written


def _fix_method_for(kind):
    prefs = SETTINGS.get("image_fix_prefs") or {}
    m = prefs.get("fanart_method" if kind == "fanart" else "poster_method")
    return m if _ifx and m in _ifx.METHODS else (_ifx.DEFAULT_METHOD[kind] if _ifx else "blur")


def image_fix_batch_plan(rows, settings=None, ai=False):          ### NEW v0.19.2 F4; ai v0.20.1 TF6 ###
    """[(row, kind, method, target | None, note)] for the batch (only ✓
    sizes; target None = skipped).  A folder image identical to a poster
    that is fixed is updated with it, so it has no line of its own."""
    s = settings if settings is not None else SETTINGS
    plan = []
    for r in rows:
        kinds = image_fix_kinds(r)
        poster_fixed = False
        for k in kinds:
            # ### MODIFIED v0.19.3 B66 ### a folder image follows a poster that is
            # fixed, also when it was a different picture that needs a fix too
            if k == "folder" and "poster" in kinds and (poster_fixed or not _poster_folder_differ(r)):
                continue
            w, h = _dim_of(r, k)
            if not (w and h):
                continue
            m = _fix_method_for(k)
            target, note = _ifx.batch_choice(k, w, h, m, _min_quality_level(k, s), ai=ai)   # v0.20.1 TF6
            if k == "poster" and target and image_fix_batch_copy(r, k):
                poster_fixed = True
            plan.append((r, k, m, target, note))
    return plan


def poster_tier_size(label):                                     ### NEW v0.20.1 TF1 ###
    """(min_w, min_h) of a poster tier ('1080p' → (1000, 1500)); an unknown label gives 1080p's."""
    t = {lbl: (w, h) for lbl, w, h, _px, _sz in POSTER_QUALITY_TIERS}
    return t.get(label, t["1080p"])


def lowres_poster_candidates(rows, tier):                        ### NEW v0.20.1 TF1 ###
    """Pure: [(row, why, (w, h))] for "Replace Low-Resolution Posters": a poster that is corrupt (why "corrupt", size
    (0, 0)) or below *tier* (±5 %, why "low"). Movies without a poster are left to Fetch Metadata (v0.21.0, F1)."""
    mw, mh = poster_tier_size(tier)
    out = []
    for r in rows:
        if not r.get("poster_exists") or not r.get("poster_path"):
            continue
        if (r.get("poster_flags") or {}).get("corrupt"):
            out.append((r, "corrupt", (0, 0)))
            continue
        w, h = _dim_of(r, "poster")
        if w and h and (w < mw * (1 - _IMG_QUALITY_TOLERANCE) or h < mh * (1 - _IMG_QUALITY_TOLERANCE)):
            out.append((r, "low", (w, h)))
    return out


def review_poster_rows(kind, rows, tier):                         ### NEW v0.20.1 TF5 ###
    """The movies of a Review Posters set: 'low' = below *tier* or corrupt (as Replace Low-Resolution Posters);
    'ratio' = a readable poster with wrong proportions; 'selection' / 'filter' = *rows* that have a poster. Movies
    without a poster are left to Fetch Metadata (F1, v0.21.0)."""
    if kind == "low":
        return [c[0] for c in lowres_poster_candidates(rows, tier)]
    have = [r for r in rows if r.get("poster_exists") and r.get("poster_path")]
    if kind == "ratio":
        return [r for r in have if (r.get("poster_flags") or {}).get("bad_ratio") and not (r.get("poster_flags") or {}).get("corrupt")]
    return have


def review_upscale_target(w, h, method):                         ### NEW v0.20.1 TF5 ###
    """The size "Upscale (AI)" makes of a w×h poster: the largest tier the AI upscaler reaches with a ✓ mark
    (up to ×2, UPSCALE_LIMITS["ai"]) that is bigger than the poster after the proportions fix; None = no such tier."""
    if not (w and h) or _ifx is None:
        return None
    cw, ch = _ifx.corrected_size(w, h, "poster", method)
    opts, _d = _ifx.size_options("poster", cw, ch, True)
    ok = [o for o in opts if o["key"] != "keep" and o["mark"] == "ok" and o["h"] > ch]
    if not ok:
        return None
    best = max(ok, key=lambda o: o["h"])
    return (best["w"], best["h"])


def extrafanart_plan(rows):                                      ### v0.20.1 checkup — worker thread (reads the folders) ###
    """[(row, extrafanart folder, [(file, new name)])] for Convert extrafanart. An image that already has an identical
    copy next to the video (an earlier run) is left out, so a second run finds nothing to do."""
    import filecmp
    plan = []
    for r in rows:
        if r.get("has_extrafanart") is False:                      # the scan saw no such folder (no disk access)
            continue
        folder = r.get("subfolder_path", "")
        src = os.path.join(folder, _nc.EXTRAFANART_DIR)
        try:
            if not os.path.isdir(src):
                continue
            files, here = os.listdir(src), os.listdir(folder)
        except OSError:
            continue
        fp = os.path.basename(r.get("fanart_path") or "")
        vb = os.path.splitext(os.path.basename(r.get("video_path") or ""))[0]
        prefix = f"{vb}-" if (vb and fp.lower().startswith(vb.lower() + "-fanart")) else ""
        copies = [h for h in here if re.match(rf"{re.escape(prefix)}fanart\d+\.(?:jpg|png)$", h, re.I)]
        new = []
        for f in files:
            a = os.path.join(src, f)
            try:
                dup = any(os.path.getsize(a) == os.path.getsize(os.path.join(folder, c))
                          and filecmp.cmp(a, os.path.join(folder, c), shallow=False) for c in copies)
            except OSError:
                dup = False
            if not dup:
                new.append(f)
        items = _ea.fanart_numbers_plan(new, here, prefix)
        if items:
            plan.append((r, src, items))
    return plan


def actor_photos_plan(rows):                                      ### NEW v0.20.1 T8 — worker thread (reads the files) ###
    """[(row, .actors folder, [(name, url, file name)])] — the photos Download Actor Photos would get."""
    plan = []
    for r in rows:
        nfo = r.get("nfo_path") if r.get("nfo_exists") else None
        if not nfo:
            continue
        adir = os.path.join(os.path.dirname(nfo), _ac.ACTORS_DIR)
        try:
            listing = os.listdir(adir) if os.path.isdir(adir) else []
        except OSError:
            listing = []
        items = _ac.download_plan(_ac.read_actors(_read_text(nfo) or ""), listing)
        if items:
            plan.append((r, adir, items))
    return plan


ARTWORK_REFRESH_PROGRAMS = ("kodi", "emby", "jellyfin", "plex", "infuse")   ### NEW v0.20.1 RV4 ###


def artwork_refresh_note(rows, settings=None):                   ### NEW v0.20.1 RV4 ###
    """The lines that say how each ticked program shows a replaced image (players keep a copy of the old one)."""
    progs = []
    for r in rows:
        for pg in media_programs(_lib_root_of(r), settings):
            if pg in ARTWORK_REFRESH_PROGRAMS and pg not in progs:
                progs.append(pg)
    if not progs:
        return ""
    return _i18n.t("rv4.head") + "".join("\n  • " + _i18n.t("rv4." + pg) for pg in progs)


def image_fix_batch_copy(row, kind):                             ### NEW v0.19.3 B66 ###
    """copy_to for one batch line: the poster fix also writes folder.jpg when folder.jpg is the same picture.
    ### MODIFIED v0.20.0 RD7 ### a different folder.jpg is never replaced: when it needs a fix it has its own line."""
    if kind != "poster" or not image_fix_copy_default(row, "poster"):
        return False
    return "folder" if image_fix_pair_mode(row, "poster")[1] == "copy" else False


def image_fix_batch_text(plan):                                  ### NEW v0.19.2 F4 ###
    """Preview text of the batch."""
    todo = [p for p in plan if p[3]]
    movies = {id(p[0]) for p in plan}
    lines = [_i18n.t("rp.to_fix_skipped_in_efdc", shown_action=shown_action(IMAGE_FIX_ACTION), n=_n(len(todo), 'image'), v=len(plan) - len(todo), n2=_n(len(movies), 'movie')), ""]
    last = None
    for r, k, _m, target, note in plan:
        if id(r) != last:
            lines.append(f"🎬 {r.get('movie_name', r.get('subfolder', ''))}")
            last = id(r)
        w, h = _dim_of(r, k)
        _cp = image_fix_batch_copy(r, k) if target else False     ### NEW v0.19.3 B66 ###
        lines.append(f"   {os.path.basename(r.get(f'{k}_path') or '')} {w}×{h}: {note}"
                     + (_i18n.t("if.copied_to", name=os.path.basename(r.get('folder_path') or 'folder.jpg')) if _cp else ""))
    lines += ["", _i18n.t("rp.only_sizes_are_used_82e7"),
              _i18n.t("rp.right_click_fix_image_a8cb"),
              _i18n.t("rp.every_changed_file_is_43d6", menu_path=menu_path('backup_history'))]   # v0.19.4 I13
    return "\n".join(lines)


def resolve_nfo(lst, sub_name, vb=None):
    """(path, exists, name, kodi_reads_it).  Kodi reads "<video>.nfo" or
    "movie.nfo" (for a disc structure "VIDEO_TS.nfo" / "index.nfo" next to
    VIDEO_TS.IFO / index.bdmv, or movie.nfo in the movie folder); MediaClinic
    also accepts "<folder name>.nfo" (its own layout, identical to the Kodi
    name when the video is named like the folder).  kodi_reads_it is False
    when only a folder-named NFO exists and Kodi would look for another name."""
    for cl, n, kodi in _nfo_order(lst, sub_name, vb):             ### MODIFIED v0.19.2 F5 — movie.nfo first ###
        if cl.has(n):
            real = cl.files[n.lower()][0]
            if kodi is None:            # folder-named NFO: Kodi reads it when it IS the video name …
                disc = _disc_info(lst)
                vb2 = vb if vb is not None else _video_basename(lst)
                kodi = (not disc) and ((not vb2) or real.lower() == f"{vb2.lower()}.nfo" or _lone_nfo(lst))   # … or alone (KR1.3)
            return cl.path_of(n), True, real, kodi
    if not _disc_info(lst) and _lone_nfo(lst):                    ### NEW v0.20.0 RD10 — Kodi reads the folder's only NFO, any name ###
        real = next(f[0] for n, f in lst.files.items() if n.endswith(".nfo"))
        try:                                                      # a release-info text file is not a movie NFO
            with open(lst.path_of(real), "rb") as fh:
                head = fh.read(4096).lower()
        except OSError:
            head = b""
        if b"<movie" in head:
            return lst.path_of(real), True, real, True
    return lst.path_of(f"{sub_name}.nfo"), False, f"{sub_name}.nfo", True


def _lone_nfo(lst):                                              ### NEW v0.20.0 KR1.3 ###
    """True when the folder holds exactly one .nfo: Kodi then reads it whatever its name ("Movies are in separate
    folders", VideoTagLoaderNFO).  One place: the rule, Auto Repair and the rename offers all read nfo_kodi_name."""
    return sum(1 for n in lst.files if n.endswith(".nfo")) == 1


def _nfo_order(lst, sub_name, vb=None):                          ### NEW v0.19.2 F5 ###
    """[(listing, name, kodi_reads)] in the reading order the servers share:
    disc NFO (VIDEO_TS.nfo / index.nfo), movie.nfo (Kodi, Jellyfin and Emby
    read it first — user decision 2026-10-15), "<video>.nfo", then
    MediaClinic's "<folder>.nfo" (kodi_reads decided by the caller)."""
    disc = _disc_info(lst)
    vb = vb if vb is not None else _video_basename(lst)
    order = []
    if disc:
        order.append((disc["listing"], f"{disc['vb']}.nfo", True))
    order.append((lst, "movie.nfo", True))
    if vb and not disc:
        order.append((lst, f"{vb}.nfo", True))
        st = _stack_title(lst)                                   ### NEW v0.20.0 RD10 — 'Movie.nfo' next to 'Movie-CD1.mkv' (PatK9) ###
        if st and st.lower() != vb.lower():
            order.append((lst, f"{st}.nfo", True))               # Kodi FindNFO: after the first part's names
    order.append((lst, f"{sub_name}.nfo", None))
    return order


def readable_nfos(lst, sub_name, vb=None):                       ### NEW v0.19.2 F5 ###
    """Every NFO of the movie the servers could read, in reading order (names
    as on disk, one entry per file).  More than one → warning multiple_nfo_files."""
    out, seen = [], set()
    for cl, n, _k in _nfo_order(lst, sub_name, vb):
        if cl.has(n):
            real = cl.files[n.lower()]
            if real[1].lower() not in seen:
                seen.add(real[1].lower()); out.append((real[0], real[1]))
    return out


# ── v0.19.3 B73: rename a folder-named NFO so Kodi reads it ─────────────────
NFO_RENAME_ACTION = "Rename NFO for Kodi"                         # backup label (Backup History / Undo)
NFO_RENAME_LABEL = _label_const("NFO_RENAME_LABEL", "🏷", "act.nfo_rename")
NFO_RENAME_ALL_LABEL = _label_const("NFO_RENAME_ALL_LABEL", "🏷", "act.nfo_rename_all")
NFO_MOVIE_NOTE = ("movie.nfo: Kodi reads it when the source is set to \"Movies are in separate folders "
                  "that match the movie title\"; Jellyfin and Emby always read it.")


def nfo_rename_plan(sub_path, sub_name=None):                    ### NEW v0.19.3 B73 ###
    """What renaming the folder-named NFO would do (one listing, no writes),
    or None when Kodi already reads the NFO (or there is none):
      {"src", "name", "choices": [(mode, dest path, dest name)], "default", "why"}
    mode "video" = "<video>.nfo" (the default for one video: Kodi reads it
    whatever the source settings), "movie" = "movie.nfo" (the default for a
    DVD / Blu-ray folder, a multi-part movie or several versions: one file
    for all of them).  Option C (rename the video) is for the v0.20.0 renamer."""
    lst = _FolderListing(sub_path)
    sub_name = sub_name or os.path.basename(os.path.normpath(sub_path))
    vb = _video_basename(lst)
    src, exists, real, kodi = resolve_nfo(lst, sub_name, vb)
    if not exists or kodi:
        return None
    disc = _disc_info(lst)
    group = classify_videos(lst)["group"]
    choices = []
    if vb and not disc:
        choices.append(("video", os.path.join(lst.path, f"{vb}.nfo"), f"{vb}.nfo"))
    choices.append(("movie", os.path.join(lst.path, "movie.nfo"), "movie.nfo"))
    why = ({"DVD": "DVD folder", "BD": "Blu-ray folder"}.get(disc["type"]) if disc
           else {"stack": "multi-part movie", "versions": "several versions"}.get(group))
    default = "movie" if (why or not vb) else "video"
    return {"src": src, "name": real, "choices": choices, "default": default, "why": why}


def rename_case_safe(src, dst):                                  ### NEW v0.20.2 B18 ###
    """Rename *src* to *dst* through a temporary name (a case-only rename on Windows needs two steps). When the
    second step fails, the file gets its old name back (no "X.mcrename" is left behind) and the error is raised."""
    tmp = src + ".mcrename"
    _sc._replace_retry(src, tmp, op=os.rename)
    try:
        _sc._replace_retry(tmp, dst, op=os.rename)
    except OSError:
        try:
            _sc._replace_retry(tmp, src, op=os.rename)
        except OSError as ex2:
            logger.error(f"Rename: {os.path.basename(tmp)} could not get its old name back: {ex2}")
        raise


def apply_nfo_rename(plan, mode, movie_name, batch_ref=None, backup=True):   ### NEW v0.19.3 B73 ###
    """Rename the NFO (worker thread; no Tk): backup first, never over an
    existing file, Undo-able (the manifest records the new name).  Returns
    the new path; raises on failure."""
    if not nfo_in_use(library_of(os.path.dirname(plan["src"]))):   # v0.19.6 TR1b; v0.20.0 F3: the library's own programs
        raise RuntimeError("the NFO is not used in this health mode (movie.xml only) — not renamed")
    dest = next((d for m, d, _n in plan["choices"] if m == mode), None)
    if dest is None:
        raise RuntimeError(f"'{mode}' is not offered for this folder")
    src = plan["src"]
    if not os.path.isfile(src):
        raise RuntimeError(f"{os.path.basename(src)} not found")
    same = os.path.normcase(os.path.abspath(src)) == os.path.normcase(os.path.abspath(dest))
    if os.path.exists(dest) and not same:
        raise RuntimeError(f"{os.path.basename(dest)} already exists — not renamed (compare the two NFOs first)")
    if backup:
        ok = _batch_backup_ok(movie_name, batch_ref, src) if batch_ref is not None else _backup_ok(movie_name, src)
        if not ok:
            raise BackupFailed()
    if same:                                                    # only the case differs
        rename_case_safe(src, dest)                              # v0.20.2 B18 (v0.19.5 WR-B1 inside)
    else:
        _sc._replace_retry(src, dest, op=os.rename)              # v0.19.5 WR-B1
    _sc.note_renamed(src, dest)
    _cache_forget(src)
    _cache_forget(dest)
    logger.info(f"Rename NFO for Kodi: {movie_name} — {os.path.basename(src)} → {os.path.basename(dest)}")
    return dest


def nfo_rename_batch_text(items):                                ### NEW v0.19.3 B73 ###
    """Preview text: [(row, plan)] → one line per movie."""
    lines = [_i18n.t("rp.rename_nfo_for_kodi_121b", n=_n(len(items), 'movie')), ""]
    for r, p in items:
        dest = next(n for m, _d, n in p["choices"] if m == p["default"])
        lines.append(f"🎬 {r.get('movie_name') or r.get('subfolder', '')}")
        lines.append(f"   {p['name']}  →  {dest}" + (f"   ({p['why']})" if p.get("why") else ""))
    lines += ["", _i18n.t("au.nfo_rename_head"),
              _i18n.t("rp.versions_4c57", nfo_movie_note=NFO_MOVIE_NOTE),
              _i18n.t("rp.every_nfo_is_backed_eaff", menu_path=menu_path('backup_history'))]   # v0.19.4 I13
    return "\n".join(lines)


_NFO_ROOT_RX = re.compile(r"<\s*([A-Za-z_][\w.-]*)")


def _nfo_root_tag(path):                                        ### NEW v0.19.2 B53 ###
    """Root element of an NFO ("movie", "tvshow" …) from its first 4 KB, or
    None (unreadable / not XML: the classifier then treats it as a movie NFO)."""
    try:
        with open(path, "rb") as f:
            head = f.read(4096).decode("utf-8", "replace")
    except OSError:
        return None
    head = re.sub(r"<\?.*?\?>|<!--.*?-->|<!DOCTYPE[^>]*>", "", head, flags=re.S)
    m = _NFO_ROOT_RX.search(head)
    return m.group(1).lower() if m else None


def classify_listing(lst):                                      ### NEW v0.19.2 B53 ###
    """(kind, reason, detail) of a library sub-folder — folder_classifier with
    this script's video extensions; sub-folders are listed (peek) only for a
    folder without a video at its top level."""
    return _fc.classify_folder(lst, peek=_FolderListing, nfo_root=_nfo_root_tag, video_exts=VIDEO_EXTENSIONS)


def ignored_item(path, kind, reason, detail, lst=None, root=None):   ### NEW v0.19.2 B53; root v0.19.6 TR5 ###
    """One entry of the Ignored folders report (plain data, saved as JSON)."""
    return {"path": _norm_lib(path), "library_root": _norm_lib(root) if root else library_of(path),
            "kind": kind, "reason": reason, "detail": detail,
            "mtime": lst.newest_mtime() if lst is not None else 0.0}


### NEW v0.19.6 TR5 — movie folders at any depth below a library ###
# A tester keeps Movies\Single Movies\{SD,DVD,HD,4K}\<movie> and Movies\Boxsets\<saga>\<movie>; Kodi and
# tinyMediaManager find those movies, MediaClinic skipped the folder of folders ("one level too high").  Now a
# folder of folders is walked into, down to SCAN_MAX_DEPTH levels below the library; every row keeps its library.
SCAN_MAX_DEPTH = 4                 # folders of folders walked into; a movie can sit up to 5 levels below the library


class SubEntry:
    """A movie folder found below a library (os.DirEntry-like: .path, .name), with its library (.root)."""
    __slots__ = ("path", "name", "root", "depth")

    def __init__(self, path, root, depth=1):
        self.path, self.name, self.root, self.depth = path, os.path.basename(os.path.normpath(path)), root, depth

    def is_dir(self):
        return True


def library_of(path, libraries=None):
    """The library a folder belongs to: the deepest library folder above it (a movie can sit deeper since
    v0.19.6 TR5); a folder outside every library: its parent."""
    libs = libraries if libraries is not None else (SETTINGS.get("library_folders") or [])
    k, best = _pkey(path), ""
    for lib in libs:
        lk = _pkey(lib).rstrip("\\/")
        if lk and k.startswith(lk + os.sep) and len(lk) > len(_pkey(best)):
            best = lib
    return _norm_lib(best) if best else _norm_lib(os.path.dirname(os.path.normpath(path)))


def too_deep_reason(level):                                     ### NEW v0.20.0 RD4 ###
    """Why a folder of folders *level* levels below the library was not searched, with the numbers (a Reddit
    tester read only "this library may be one level too high" and could not tell why their box sets were left out)."""
    return (f"Too deep: this folder is {level} levels below the library and holds more folders; the scan looks for "
            f"movies down to {SCAN_MAX_DEPTH + 1} levels, so the folders inside were not searched. Add this folder "
            f"as a library to include them")


def _is_collection_folder(path):                                 ### NEW v0.20.0 CF1 ###
    """The collection folder (Libraries… → Collection folder) holds collection artwork, not movies: the scans skip it."""
    cf = SETTINGS.get("collection_folder") or ""
    return bool(cf) and _pkey(path) == _pkey(cf)


def suggest_collection_folder(libraries):                        ### NEW v0.20.0 CF1 ###
    """'Sets' next to the first movie folder (D:\\Movies → D:\\Sets), or inside it when it is a drive root."""
    libs = [x for x in (libraries or []) if x]
    if not libs:
        return ""
    first = os.path.normpath(libs[0])
    drive, rest = os.path.splitdrive(first)
    if not rest.strip("\\/"):                                    # v0.20.0 AU12: "Z:\" gave the drive-RELATIVE "Z:Sets"
        return os.path.join(drive + os.sep if drive else first, "Sets")
    parent = os.path.dirname(first.rstrip("\\/")) or first
    return os.path.join(parent if parent != first else first, "Sets")


def walk_container(path, root, depth=1, known=(), cancelled=None):
    """The folders below a folder of folders: (entries, ignored, listings, kinds).  A movie folder becomes a
    SubEntry; a deeper folder of folders is walked too, down to SCAN_MAX_DEPTH; any other folder goes to the
    Ignored folders report.  A sub-folder in *known* (a movie row of the last scan) is taken without listing
    it (Quick Scan)."""
    entries, ignored, listings, kinds = [], [], {}, {}
    try:
        subs = sorted((e.path for e in os.scandir(path) if e.is_dir()), key=lambda p: os.path.basename(p).lower())
    except OSError as ex:
        ignored.append(ignored_item(path, "unreadable", f"Could not be read: {ex}", "", root=root))
        return entries, ignored, listings, kinds
    for sp in subs:
        if cancelled and cancelled():
            break
        if _is_collection_folder(sp):                              # v0.20.0 CF1: collection artwork, not movies
            continue
        if _pkey(sp) in known:
            entries.append(SubEntry(sp, root, depth))
            continue
        lst = _FolderListing(sp)
        kind, reason, detail = classify_listing(lst)
        if kind == "container" and depth < SCAN_MAX_DEPTH:
            e2, i2, l2, k2 = walk_container(sp, root, depth + 1, known, cancelled)
            entries += e2; ignored += i2; listings.update(l2); kinds.update(k2)
        elif kind in _fc.IGNORED_KINDS:
            if kind == "container":
                reason = too_deep_reason(depth + 1)                 # MODIFIED v0.20.0 RD4 — with the numbers
            ignored.append(ignored_item(sp, kind, reason, detail, lst, root=root))
        else:
            entries.append(SubEntry(sp, root, depth)); listings[sp] = lst; kinds[sp] = kind
    return entries, ignored, listings, kinds


