def extra_art_names(lst, vb=None):                              ### NEW v0.20.0 RD9 (was inside naming_row_fields) ###
    """The folder's extra artwork files (clearlogo, landscape, disc …, also as '<video>-<kind>'), sorted."""
    return sorted({f[0] for f in lst.files.values()
                   if os.path.splitext(f[0])[1].lower() in _ART_EXTS
                   and (os.path.splitext(f[0])[0].lower() in _nc.EXTRA_ART_KINDS
                        or (vb and os.path.splitext(f[0])[0].lower().startswith(vb.lower() + "-")
                            and os.path.splitext(f[0])[0].lower()[len(vb) + 1:] in _nc.EXTRA_ART_KINDS))})


def actor_row_fields(lst, nfo_path):                             ### NEW v0.20.1 AC1 ###
    """The Actors column's facts: the NFO's <actor> blocks against the files in ".actors" next to the NFO (Kodi's
    place). No extra disk access for a movie folder without ".actors" (the folder listing has it); an NFO in a disc
    folder (VIDEO_TS / BDMV) is looked up there."""
    if not nfo_path:
        return {"actors_state": "none", "actors_counts": {}, "actors_mismatch": [], "actors_orphans": [], "actors_dir": ""}
    actors = _ac.read_actors(_read_text(nfo_path) or "")
    base = os.path.dirname(nfo_path)
    adir = os.path.join(base, _ac.ACTORS_DIR)
    if os.path.normcase(base) == os.path.normcase(lst.path):
        has = _ac.ACTORS_DIR in lst.dirs
    else:
        has = os.path.isdir(adir)
    try:
        listing = os.listdir(adir) if has else None
    except OSError:
        listing = None
    st = _ac.actors_state(actors, listing)
    return {"actors_state": st["state"], "actors_counts": {k: st[k] for k in ("local", "links", "nophoto", "total")},
            "actors_mismatch": st["mismatches"], "actors_orphans": st["orphans"], "actors_dir": adir if listing is not None else ""}


def naming_row_fields(lst, sub_name, vb=None):                   ### NEW v0.19.2 F5 ###
    """Row fields from the names in the folder (no extra disk access, except
    comparing NFO contents when there are several):
      nfo_all (names of every readable NFO, the used one first), nfo_all_differ,
      xml_notes (mymovies.xml …), art_notes (Kodi name case …),
      extra_art (clearlogo, landscape … — information only),
      poster_servers / fanart_servers / folder_servers (who reads the file found)."""
    vb = vb if vb is not None else _video_basename(lst)
    nfos = readable_nfos(lst, sub_name, vb)
    differ = False
    if len(nfos) > 1:
        try:
            contents = {open(p, "rb").read() for _n, p in nfos}
            differ = len(contents) > 1
        except OSError:
            differ = False
    xml_notes = []
    for old in _nc.OLD_XML_NAMES:
        if lst.has(old):
            xml_notes.append(f"{lst.files[old][0]} found — no current server reads it (it is not movie.xml; "
                             f"convert it by hand if you need the data)")
    art_notes, servers = [], {}
    for key in ("poster", "fanart", "folder"):
        r = resolve_artwork(lst, key, vb)
        if not r["exists"]:
            continue
        servers[f"{key}_servers"] = art_servers(r["name"], key, vb)
        if vb and r["name"].lower().startswith(vb.lower() + "-") and not r["name"].startswith(vb + "-"):
            art_notes.append(f"{r['name']}: Kodi matches '<video>-{key}' case-sensitively — "
                             f"rename it to '{vb}-{key}…' for Kodi")
    extra = extra_art_names(lst, vb)                             # v0.20.0 RD9: one helper
    extra_dirs = sorted(lst.dirs[d].rsplit(os.sep, 1)[-1] for d in lst.dirs if d in _nc.EXTRA_FOLDERS)
    return {"nfo_all": [n for n, _p in nfos], "nfo_all_differ": differ, "xml_notes": xml_notes,
            "art_notes": art_notes, "extra_art": extra, "extra_dirs": extra_dirs, **servers,
            "has_extrafanart": _nc.EXTRAFANART_DIR in lst.dirs,          # v0.20.1 checkup: extra_dirs never held it
            **actor_row_fields(lst, nfos[0][1] if nfos else None),      # v0.20.1 AC1
            "extra_art_alpha": {n: _ea.png_alpha(os.path.join(lst.path, n)) for n in extra    # v0.20.1 EA2
                                if n.lower().endswith(".png") and _ea.KODI_NAME.get(_ea.kind_of(n, set(_ea.SKIN_KINDS) | set(_ea.KODI_NAME)) or "", _ea.kind_of(n, set(_ea.SKIN_KINDS) | set(_ea.KODI_NAME))) in _ea.TRANSPARENT_KINDS}}


def backdrop_naming(sub_path):                                  ### NEW v0.19.1 B23 ###
    """("plain"|"kodi", listing, video basename) — how new backdrops are named."""
    lst = _FolderListing(sub_path)
    vb = _video_basename(lst)
    return artwork_style(lst, vb), lst, vb


def new_backdrop_paths(sub_path, n, free=()):                   ### NEW v0.19.1 B23 ###
    """n free paths for new backdrops in the folder's naming style:
    plain (Emby/Jellyfin) → backdrop.jpg, backdrop1.jpg …;
    Kodi → "<video>-fanart1.jpg" … (a disc structure: fanart1.jpg … in the
    movie folder).  Numbers already used by any backdrop/fanart name are
    skipped.  ### v0.19.4 B78 ### *free*: files about to be replaced (their
    names count as free: Replace All Backdrops downloads before it deletes)."""
    style, lst, vb = backdrop_naming(sub_path)
    names = set(lst.files) - {os.path.basename(p).lower() for p in free}
    out = []
    if style == "kodi":
        prefix = "" if (_disc_info(lst) or not vb) else f"{vb}-"
        used = set()
        for f in names:
            m = re.match(r'^(?:.*-)?fanart(\d+)\.(?:jpg|png)$', f)
            if m:
                used.add(int(m.group(1)))
        k = 1
        while len(out) < n:
            if k not in used:
                out.append(os.path.join(sub_path, f"{prefix}fanart{k}.jpg"))
            k += 1
        return out
    used = {int(m.group(1)) for f in names for m in [re.match(r'^backdrop(\d+)\.jpg$', f)] if m}
    if "backdrop.jpg" not in names and len(out) < n:
        out.append(os.path.join(sub_path, "backdrop.jpg"))
    k = 1
    while len(out) < n:
        if k not in used:
            out.append(os.path.join(sub_path, f"backdrop{k}.jpg"))
        k += 1
    return out


def count_backdrop_videos(lst):                                  ### NEW v0.20.2 FB1 — Emby / Jellyfin theme videos ###
    """The video files in the movie's backdrops\\ sub-folder: Emby and Jellyfin play them as moving backdrops (theme
    videos); Kodi and Plex do not read them.  One listing, only when the folder exists."""
    d = lst.dirs.get("backdrops")
    if not d:
        return 0
    try:
        return sum(1 for e in os.scandir(d) if e.is_file() and os.path.splitext(e.name)[1].lower() in VIDEO_EXTENSIONS)
    except OSError:
        return 0


def backdrop_total(row):                                         ### NEW v0.20.2 FB1 — the main fanart counts ###
    """The backdrops a program shows for the movie: the main fanart (every program uses it as the backdrop) plus the
    extra backdrop images (backdrop_count) — the fanart once, also when its file is one of the extra names."""
    n = int(row.get("backdrop_count") or 0)
    fp = row.get("fanart_path")
    if row.get("fanart_exists") and fp \
            and os.path.normcase(fp) not in {os.path.normcase(p) for p in row.get("backdrop_paths") or ()}:
        n += 1
    return n


def backdrop_videos_of(row):                                     ### NEW v0.20.2 FB1 ###
    """The row's backdrop videos; a row cached before FB1 (no count yet) counts a backdrops\\ folder as one."""
    n = row.get("backdrop_videos")
    if n is None:
        return 1 if any(str(x).lower() == "backdrops" for x in row.get("extra_dirs") or ()) else 0
    return n


def replaceable_backdrops(sub_path):                            ### NEW v0.19.1 B23 ###
    """The backdrop files Replace All Backdrops replaces: backdrop*.jpg in a
    plain folder; Kodi extra fanart (fanartN, "<video>-fanartN", the
    extrafanart folder) in a Kodi-style folder.  Never the main fanart."""
    style, lst, vb = backdrop_naming(sub_path)
    _n, paths, _a = count_backdrops(sub_path, listing=lst)
    if style == "kodi":
        return [p for p in paths if not re.match(r'^backdrop\d*\.jpg$', os.path.basename(p).lower())]
    return [p for p in paths if re.match(r'^backdrop\d*\.jpg$', os.path.basename(p).lower())
            and os.path.dirname(p) == sub_path]


def count_backdrops(sub_path, listing=None):                     ### MODIFIED v0.18.4 — listing ###
    ### UPDATED v0.18.0 — scan all backdrop*.jpg; no longer stops at first gap ###
    ### MODIFIED v0.19.1 B23 — Kodi extra fanart counts too: fanart1.jpg…,
    ### "<video>-fanart1.jpg"…, and the images in an "extrafanart" sub-folder ###
    lst = listing or _FolderListing(sub_path)
    _vb0 = _video_basename(lst)
    vb = (_vb0 or "").lower()
    paths = []
    sizes = {}

    _kodi_rx = re.compile(r'^(?:' + (re.escape(vb) + '-' if vb else '') + r')?fanart(\d+)\.(?:jpg|png)$') if vb \
        else re.compile(r'^fanart(\d+)\.(?:jpg|png)$')
    # ### MODIFIED v0.19.2 F5 ### every name the servers read as an extra backdrop
    # (backdrop-N, fanart-N, background(-N), art-N …) in every picture extension
    _exts = "|".join(e.lstrip(".") for e in _ART_EXTS)
    _bk_rx = re.compile(r"^(?:" + "|".join(p.replace("{video}", re.escape(vb)) for p in _nc.BACKDROP_STEM_PATTERNS
                                         if vb or "{video}" not in p) + r")\.(?:" + _exts + r")$")
    for name, path, size, _m in lst.files.values():
        n = name.lower()
        if n == "backdrop.jpg" or re.match(r'^backdrop\d+\.jpg$', n) or _kodi_rx.match(n) or _bk_rx.match(n):
            paths.append(path); sizes[path] = size
    _disc = _disc_info(lst)                                      ### NEW v0.19.1 B23 — VIDEO_TS-fanart1.jpg … ###
    if _disc and _disc["listing"] is not lst:
        _drx = re.compile(r'^' + re.escape(_disc["vb"].lower()) + r'-fanart(\d+)\.(?:jpg|png)$')
        for name, path, size, _m in _disc["listing"].files.values():
            if _drx.match(name.lower()):
                paths.append(path); sizes[path] = size
    _xf = lst.dirs.get("extrafanart")
    if _xf:
        try:
            for e in os.scandir(_xf):
                if e.is_file() and os.path.splitext(e.name)[1].lower() in _ART_EXTS:
                    paths.append(e.path); sizes[e.path] = e.stat().st_size
        except OSError:
            pass
    # Sort deterministically: backdrop.jpg, backdrop1…, then Kodi fanart1…, then extrafanart
    def _sort_key(p):
        n = os.path.basename(p).lower()
        if os.path.dirname(p) != lst.path and os.path.basename(os.path.dirname(p)).lower() == "extrafanart":
            return (3, n)
        if n == "backdrop.jpg":
            return (0, -1)
        m = re.match(r'^backdrop(\d+)\.jpg$', n)
        if m:
            return (0, int(m.group(1)))
        m = _kodi_rx.match(n)
        return (2, int(m.group(1))) if m else (9, n)
    paths.sort(key=_sort_key)
    ### NEW v0.20.0 AU5 (pre-build audit) ### the image the scan uses as the MAIN fanart (background.jpg, backdrop.jpg
    # when there is no fanart.jpg) is not also a backdrop: Replace All Backdrops replaced or deleted it ("Missing fanart")
    try:
        _main = resolve_artwork(lst, "fanart", _vb0)
        # a plain backdrop*.jpg stays a backdrop (B17: replacing it leaves a fanart in place); background.jpg,
        # art.jpg … chosen as THE fanart were deleted by the swap ("Missing fanart")
        if (_main.get("exists") and _main.get("path")
                and not re.match(r"^backdrop\d*\.", os.path.basename(_main["path"]).lower())):
            _mk = os.path.normcase(_main["path"])
            paths = [p for p in paths if os.path.normcase(p) != _mk]
    except Exception:
        pass
    count = len(paths)
    total_bytes = sum(sizes.get(p, 0) for p in paths)
    avg_bytes = (total_bytes // count) if count > 0 else 0          ### NEW v0.15.0 ###
    return count, paths, avg_bytes                                   ### NEW v0.15.0 ###


# ══════════════════════════════════════════════════════════════════════════════
# Video / subtitle / language helpers
# ══════════════════════════════════════════════════════════════════════════════

def _pkey(path):                                               ### NEW v0.18.3 ###
    """Normalised dict key for a folder path (forward and back slashes compare equal)."""
    try:
        return os.path.normcase(os.path.normpath(path or ""))
    except Exception:
        return path or ""


### NEW v0.19.4 B85 — Quick Scan's change test: a signature of the folder ###
SIG_SUBDIRS = ("subs", "extrafanart", "video_ts", "bdmv")


def folder_signature(sub_path, listing=None):
    """A short hash of the sorted (name, size, mtime) of the files in the
    movie folder, the names of its sub-folders, and the own mtimes of Subs\\,
    extrafanart\\, VIDEO_TS\\ and BDMV\\ (a file added, removed or renamed in
    them changes it).  A deleted poster, a rename, a copy that keeps the
    source's mtime or a change in Subs\\ changes the signature (the newest
    mtime alone missed them).  One os.stat per such sub-folder: the time the
    parent's listing gives for a sub-folder is not refreshed by NTFS when a
    file inside it changes."""
    import hashlib
    lst = listing or _FolderListing(sub_path)
    files = lst.files
    parts = [f"f|{f[0]}|{f[2]}|{f[3]:.3f}" for f in (files[k] for k in sorted(files))]
    for k in sorted(lst.dirs):
        if k in SIG_SUBDIRS:
            try:
                parts.append(f"d|{k}|{os.stat(lst.dirs[k]).st_mtime:.3f}")
            except OSError:
                parts.append(f"d|{k}|?")
        else:
            parts.append(f"d|{k}")
    return hashlib.sha1("\n".join(parts).encode("utf-8", "surrogatepass")).hexdigest()[:20]


def _folder_mtime(sub_path, listing=None):                     ### NEW v0.18.3, listing v0.18.4 ###
    """Newest modification time (float seconds) among the files directly in
    *sub_path*, or 0.  Stored per row as scan_mtime so Quick Scan can detect
    modified movies by comparing against the value recorded at scan time."""
    return (listing or _FolderListing(sub_path)).newest_mtime()


def scan_video_files(sub_path, listing=None):                  ### MODIFIED v0.18.4 — listing ###
    lst = listing or _FolderListing(sub_path)
    videos = sorted(lst.by_ext(VIDEO_EXTENSIONS), key=lambda f: f[2], reverse=True)
    if not videos:
        disc = _disc_info(lst)                                   ### NEW v0.19.1 B23 — DVD / Blu-ray folders ###
        if disc:
            rel = os.path.relpath(disc["marker"], sub_path)
            return {"video_count":1,"video_files":[rel],
                    "video_ext":"DVD" if disc["type"] == "DVD" else "BLU-RAY",
                    "video_path":disc["probe"],"video_bytes":disc["bytes"],
                    "video_size":format_size(disc["bytes"]),
                    "video_width":None,"video_height":None,"video_quality":"—"}
        return {"video_count":0,"video_files":[],"video_ext":"—",
                "video_path":None,"video_bytes":0,"video_size":"—",
                "video_width":None,"video_height":None,"video_quality":"—"}
    cv = classify_videos(lst)                                    ### MODIFIED v0.19.2 F5 — trailers, extras, stacks, versions ###
    name, path, size, _m = cv["main"]
    ext = os.path.splitext(name)[1].lower()
    # Quality determined later when ffprobe runs (phased scan)
    return {"video_count":cv["n_main"],"video_files":[name] + [v[0] for v in videos if v[0] != name],
            "video_kinds":dict(cv["kinds"]),"video_group":cv["group"],
            "video_ext":ext.lstrip('.').upper(),"video_path":path,
            "video_mtime":_m,                                     ### NEW v0.19.4 B86 ###
            "video_bytes":size,"video_size":format_size(size),
            "video_width":None,"video_height":None,"video_quality":"—"}

def ffprobe_reusable(prior, vi):                                ### NEW v0.19.4 B86 ###
    """True when a stored row's FFprobe data (resolution, audio, internal
    subtitles) belongs to this video: same path, same size and — when both
    are recorded — the same mtime.  A replaced video (720p → 1080p) is not."""
    if not prior or not prior.get("video_path") or not (vi or {}).get("video_path"):
        return False
    if _pkey(prior["video_path"]) != _pkey(vi["video_path"]) or prior.get("video_bytes") != vi.get("video_bytes"):
        return False
    pm, vm = prior.get("video_mtime"), vi.get("video_mtime")
    return pm is None or vm is None or abs(float(pm) - float(vm)) < 1.0


def _ffprobe_enabled(flag=None):
    """True when ffprobe may run: a path exists and the flag (or the global
    setting when flag is None) allows it.                    ### NEW v0.18.3 ###"""
    if not FFPROBE_PATH:
        return False
    return bool(SETTINGS.get("use_ffprobe", True)) if flag is None else bool(flag)


# ══════════════════════════════════════════════════════════════════════════════
# NEW v0.19.1 I5 — ONE ffprobe per video, cached (ffprobe_cache.json)
# ══════════════════════════════════════════════════════════════════════════════
# v0.19.0 ran four ffprobe processes per video and scan (resolution, audio,
# subtitles, the Lang OK? audio check).  Now one "-show_streams -show_format"
# call gives everything, and the result is kept per path + size + mtime_ns, so
# an unchanged video is never probed again (network shares!).  "Update (with
# FFprobe)" forces a fresh probe.  Setting: ffprobe_cache_enabled.
_FFPROBE_CACHE = None                       # loaded lazily from settings_controller
_FFPROBE_LOCK = threading.Lock()
_FFPROBE_DIRTY = [False]
_FFPROBE_STATS = {"runs": 0, "hits": 0}     # self-test spy
_FFPROBE_MEMO = {}                          # cache OFF: result kept ~10 s (one movie's scan), never saved
_FFPROBE_MEMO_TTL = 10.0
_FFPROBE_FAILED = {}                        ### NEW v0.19.4 B87 — key -> (size, mtime_ns) of a probe that failed in this scan ###
FFPROBE_FAILED_TEXT = "FFprobe could not read the video"        ### NEW v0.19.4 B87 ###


def ffprobe_failed(video_path):                                 ### NEW v0.19.4 B87 ###
    """True when the probe of this (unchanged) video failed or timed out in
    the current scan."""
    if not video_path:
        return False
    try:
        st = os.stat(video_path)
    except OSError:
        return False
    return _FFPROBE_FAILED.get(os.path.normcase(os.path.abspath(video_path))) == (st.st_size, st.st_mtime_ns)


def _ffprobe_cache():
    global _FFPROBE_CACHE
    with _FFPROBE_LOCK:
        if _FFPROBE_CACHE is None:
            _FFPROBE_CACHE = _sc.load_ffprobe_cache()
        return _FFPROBE_CACHE


def _run_ffprobe_json(video_path, timeout=30):
    """The one ffprobe process: -show_streams -show_format → dict ({} on failure)."""
    _FFPROBE_STATS["runs"] += 1
    try:
        status, rc, out, _err = _run_ffmpeg(                    ### MODIFIED v0.19.2 B28 — runner: priority, killed on close ###
            [FFPROBE_PATH, "-v", "quiet", "-print_format", "json",
             "-show_streams", "-show_format", video_path], timeout)
        if status == FF_OK and rc == 0 and out.strip():
            d = json.loads(out)
            return d if isinstance(d, dict) else {}
    except Exception:
        pass
    return {}


def _probe_json(video_path, use_ffprobe=None, force=False):     ### NEW v0.19.1 I5 ###
    """FFprobe data of *video_path* (format + streams), from the cache when
    the file's size and mtime_ns are unchanged.  force=True probes again."""
    if not video_path or not _ffprobe_enabled(use_ffprobe):
        return {}
    try:
        st = os.stat(video_path)
    except OSError:
        return {}
    key = os.path.normcase(os.path.abspath(video_path))
    use_cache = bool(SETTINGS.get("ffprobe_cache_enabled", True))
    if use_cache and not force:
        e = _ffprobe_cache().get(key)
        if e and e.get("size") == st.st_size and e.get("mtime_ns") == st.st_mtime_ns:
            _FFPROBE_STATS["hits"] += 1
            return e["data"]
    if not use_cache and not force:                     # still ONE probe per video and scan
        m = _FFPROBE_MEMO.get(key)
        if m and m[0] == (st.st_size, st.st_mtime_ns) and time.time() - m[1] < _FFPROBE_MEMO_TTL:
            return m[2]
    if not force and _FFPROBE_FAILED.get(key) == (st.st_size, st.st_mtime_ns):   ### NEW v0.19.4 B87 — not again in this scan ###
        return {}
    data = _run_ffprobe_json(video_path)
    if not data:                                                ### NEW v0.19.4 B87 ###
        _FFPROBE_FAILED[key] = (st.st_size, st.st_mtime_ns)
    if data and not use_cache:
        _FFPROBE_MEMO[key] = ((st.st_size, st.st_mtime_ns), time.time(), data)
        if len(_FFPROBE_MEMO) > 256:
            _FFPROBE_MEMO.clear()
    if data and use_cache:
        c = _ffprobe_cache()
        with _FFPROBE_LOCK:
            c[key] = {"size": st.st_size, "mtime_ns": st.st_mtime_ns, "data": data}
            _FFPROBE_DIRTY[0] = True
    return data


def _ffprobe_cache_flush(known=None):                           ### NEW v0.19.1 I5 ###
    """Save the cache when it changed (worker threads; called after scans).
    ### v0.19.4 B93 ### *known* (the video paths of every row after a scan):
    entries of other videos are dropped — the file never stops growing
    otherwise."""
    if known is not None and _FFPROBE_CACHE is not None:
        keep = {os.path.normcase(os.path.abspath(p)) for p in known if p}
        with _FFPROBE_LOCK:
            gone = [k for k in _FFPROBE_CACHE if k not in keep]
            for k in gone:
                del _FFPROBE_CACHE[k]
            if gone:
                _FFPROBE_DIRTY[0] = True
        if gone:
            logger.info(f"ffprobe cache: {len(gone)} entr{'y' if len(gone) == 1 else 'ies'} of videos no longer in the table removed")
    if not _FFPROBE_DIRTY[0] or _FFPROBE_CACHE is None:
        return
    with _FFPROBE_LOCK:
        snap = dict(_FFPROBE_CACHE)
        _FFPROBE_DIRTY[0] = False
    try:
        _sc.save_ffprobe_cache(snap)
    except Exception as ex:
        logger.warning(f"ffprobe_cache.json not saved: {ex}")


def _probe_streams(video_path, kind, use_ffprobe=None):         ### NEW v0.19.1 I5 ###
    """Streams of one codec_type ("video" / "audio" / "subtitle")."""
    return [s for s in (_probe_json(video_path, use_ffprobe).get("streams") or [])
            if s.get("codec_type") == kind]


def _get_video_resolution(video_path, use_ffprobe=None):
    """Return (width, height) of first video stream, or (None, None).
    ### MODIFIED v0.19.1 I5 — from the one cached probe ###"""
    for s in _probe_streams(video_path, "video", use_ffprobe):
        if (s.get("disposition") or {}).get("attached_pic") == 1:   # v0.20.0 AU16: an embedded cover image (MP4 /
            continue                                                # MKV cover art) is not the video
        w = s.get("width"); h = s.get("height")
        if w and h:
            return int(w), int(h)
        break
    return None, None

def _get_ffprobe_full(video_path, use_ffprobe=None):
    """Return full ffprobe JSON dict (format + streams), or {}.
    ### MODIFIED v0.19.1 I5 — the one cached probe ###"""
    return _probe_json(video_path, use_ffprobe)

def scan_subtitles(sub_path, video_path, use_ffprobe=None, listing=None):  ### MODIFIED v0.18.4 — listing ###
    result = {"subs_internal":[],"subs_external":[],"subs_summary":"—"}
    lst = listing or _FolderListing(sub_path)
    vstem = os.path.splitext(os.path.basename(video_path))[0] if video_path else None   ### MODIFIED v0.19.2 F5 ###
    _sub_lists = [("", lst)]
    if lst.dirs.get(_nc.SUBS_DIR):                               # Kodi: Subs\ next to the video
        _sub_lists.append(("Subs\\", _FolderListing(lst.dirs[_nc.SUBS_DIR])))
    for prefix, sl in _sub_lists:
        for name, _p, _s, _m in sorted(sl.by_ext(SUBTITLE_EXTENSIONS)):
            lang, flags = _nc.parse_subtitle_name(os.path.splitext(name)[0], vstem)
            ent = {"lang": lang, "file": prefix + name}
            if flags:
                ent["flags"] = flags
            result["subs_external"].append(ent)
    if video_path and _ffprobe_enabled(use_ffprobe):
        for stream in _probe_streams(video_path, "subtitle", use_ffprobe):   ### MODIFIED v0.19.1 I5 ###
            tags = stream.get("tags", {})
            result["subs_internal"].append({
                "lang":  tags.get("language") or tags.get("LANGUAGE") or "und",
                "title": tags.get("title")    or tags.get("TITLE")    or ""})
    result["subs_summary"] = _subs_summary(result["subs_internal"], result["subs_external"], video_path)
    return result
def _lang3(value):                                              ### NEW v0.19.1 B16 ###
    """'por' / 'pt' / 'Portuguese' / 'pt-BR' → 'POR'; None when unknown or undefined."""
    v = (value or "").strip().lower()
    if not v or v in ("und", "undefined", "unknown", "zxx", "mis", "mul"):
        return None
    if re.fullmatch(r"[a-z]{3}", v):
        return v.upper()
    for iso2, aliases in _LANG_ALIASES.items():
        if v in aliases:
            return normalize_lang_code(iso2)
    if re.fullmatch(r"[a-z]{2}", v):
        return normalize_lang_code(v)
    return None


### NEW v0.19.4 B89 — ISO 639-2 bibliographic codes = their terminology twins ###
_LANG_B2T = {"GER": "DEU", "FRE": "FRA", "DUT": "NLD", "CHI": "ZHO", "CZE": "CES", "GRE": "ELL",
             "PER": "FAS", "RUM": "RON", "SLO": "SLK", "ALB": "SQI", "ARM": "HYE", "BAQ": "EUS",
             "BUR": "MYA", "GEO": "KAT", "ICE": "ISL", "MAC": "MKD", "MAO": "MRI", "MAY": "MSA",
             "TIB": "BOD", "WEL": "CYM"}


def lang_key(value):                                            ### NEW v0.19.4 B89 ###
    """One comparable code for a language value: 'en' / 'English' / 'eng' →
    'ENG', 'ger' / 'deu' / 'German' → 'DEU'; None when unknown.
    ### MODIFIED v0.19.5 AS-A10 ### through the alias table too: Lang OK and the required-language rules give one answer."""
    _t = str(value or "").strip().lower()
    for _iso, _names in _LANG_ALIASES.items():
        if _t in _names:
            value = _iso
            break
    c = _lang3(value)
    if c is None and value and re.search(r"[-_]", str(value)):          # 'pt-BR' → 'pt'
        c = _lang3(re.split(r"[-_]", str(value))[0])
    if c is None:
        c = normalize_lang_code(value or "") or None
        c = c.upper() if c else None
    if c in ("UND", "ZXX", "MIS", "MUL", "UNDEFINED", "UNKNOWN"):    # an unknown language matches nothing
        return None
    return _LANG_B2T.get(c, c) if c else None


def lang_same(a, b):                                            ### NEW v0.19.4 B89 ###
    ka = lang_key(a)
    return ka is not None and ka == lang_key(b)


def _file_audio_langs(nfo_path, xml_path):                      ### NEW v0.19.1 B16 ###
    """Audio-language candidate lists from the files, in order of trust:
    [("NFO", fileinfo/streamdetails/audio/language…), ("XML", Audio/Language…),
     ("NFO", video/language…)].  Unknown / undefined values are dropped."""
    out = []
    nroot = _parse_root(nfo_path) if nfo_path and os.path.isfile(nfo_path) else None
    xroot = _parse_root(xml_path) if xml_path and os.path.isfile(xml_path) else None
    if nroot is not None:
        out.append(("NFO", [c for c in (_lang3(a.findtext("language")) for a in nroot.iter("audio")) if c]))
    if xroot is not None:
        out.append(("XML", [c for c in (_lang3(a.findtext("Language")) for a in xroot.iter("Audio")) if c]))
    if nroot is not None:
        out.append(("NFO", [c for c in (_lang3(v.findtext("language")) for v in nroot.iter("video")) if c]))
    return [(src, lst) for src, lst in out if lst]


def fill_audio_lang_from_files(tracks, nfo_path, xml_path):     ### NEW v0.19.1 B16 ###
    """FFprobe stays primary: only tracks whose language is UND/empty get one
    from the NFO/XML — by position when the file lists as many languages as
    there are tracks, the single language when there is one undefined track
    and one language, or the common language when all listed ones are equal.
    Otherwise the track stays UND (no guessing).  A filled track carries
    language_src ("NFO"/"XML") and language_raw (what FFprobe said), so it is
    re-filled from scratch every time (an edited NFO is picked up).  Nothing
    is written to the files.  Returns a new list."""
    base = []
    for t in tracks or []:
        t = dict(t)
        if t.get("language_src"):                    # undo an earlier fill
            t["language"] = t.pop("language_raw", "UND") or "UND"
            t.pop("language_src", None)
        base.append(t)
    und = [i for i, t in enumerate(base) if (t.get("language") or "UND").upper() in ("UND", "")]
    if not und:
        return base
    for src, langs in _file_audio_langs(nfo_path, xml_path):
        if len(langs) == len(base):
            pick = {i: langs[i] for i in und}
        elif len(und) == 1 and len(langs) == 1:
            pick = {und[0]: langs[0]}
        elif len(langs) >= 2 and len(set(langs)) == 1:   # several listed, all equal
            pick = {i: langs[0] for i in und}
        else:
            continue
        for i, code in pick.items():
            base[i]["language_raw"] = base[i].get("language") or "UND"
            base[i]["language"] = code
            base[i]["language_src"] = src
        return base
    return base


def _refill_audio_row(r):                                       ### NEW v0.19.1 B16 ###
    """Apply fill_audio_lang_from_files to a row; a filled target-language
    track also makes Lang OK? = Y."""
    nfo = r.get("nfo_path") if r.get("nfo_exists") else None
    xml = r.get("xml_path") if r.get("xml_exists") else None
    if not r.get("audio_tracks"):
        return r
    r["audio_tracks"] = fill_audio_lang_from_files(r["audio_tracks"], nfo, xml)
    if r.get("video_path") and r.get("lang_ok") == "N":
        iso = SETTINGS.get("lang_ok_code", "PT")
        if any(t.get("language_src") and is_target_lang(t["language"], iso) for t in r["audio_tracks"]):
            r["lang_ok"] = "Y"
    return r


def scan_audio_tracks(video_path, use_ffprobe=None):             ### NEW v0.15.0 ###
    """
    Extract audio tracks from video_path using ffprobe.
    Returns list of dicts: [{language, codec, channels, bitrate}, ...]
    Only runs if FFPROBE_PATH is available.
    """
    if not video_path or not _ffprobe_enabled(use_ffprobe):
        return []
    try:
        tracks = []
        for stream in _probe_streams(video_path, "audio", True):   ### MODIFIED v0.19.1 I5 — the one cached probe ###
            tags    = stream.get("tags", {})
            lang    = (tags.get("language") or tags.get("LANGUAGE") or
                       tags.get("lang") or "und").upper()
            codec   = (stream.get("codec_name") or "").upper()
            # Channels
            ch_layout = stream.get("channel_layout", "")
            channels_int = stream.get("channels", 0)
            if ch_layout:
                _ch_map = {"mono": "1.0", "stereo": "2.0",
                           "2.1": "2.1", "3.0": "3.0",
                           "4.0": "4.0", "5.0": "5.0",
                           "5.1": "5.1", "6.0": "6.0",
                           "6.1": "6.1", "7.0": "7.0",
                           "7.1": "7.1"}
                channels = _ch_map.get(ch_layout.lower(), ch_layout)
            elif channels_int:
                _int_map = {1:"1.0",2:"2.0",3:"2.1",4:"4.0",5:"5.0",6:"5.1",
                            7:"6.1",8:"7.1"}
                channels = _int_map.get(channels_int, str(channels_int))
            else:
                channels = ""
            # Bitrate (kbps)
            br_raw = stream.get("bit_rate") or stream.get("BIT_RATE")
            try:
                bitrate = int(int(br_raw) / 1000) if br_raw else None
            except Exception:
                bitrate = None
            tracks.append({
                "language": lang, "codec": codec,
                "channels": channels, "bitrate": bitrate})
        return tracks
    except Exception:
        return []



def _file_stream_langs(nfo_path, xml_path):                      ### NEW v0.19.5 B121 ###
    """The audio and subtitle languages written in the files: NFO fileinfo/streamdetails, XML MediaInfo."""
    out = []
    if nfo_path and os.path.isfile(nfo_path):
        try:
            root = _parse_root(nfo_path)
            if root is not None:
                for sd in root.iter("streamdetails"):
                    for kind in ("audio", "subtitle"):
                        out += [(e.findtext("language") or "").strip() for e in sd.findall(kind)]
            else:                                                 # a file that does not parse: only inside its streamdetails
                m = re.search(r"<streamdetails>(.*?)</streamdetails>", _read_text(nfo_path) or "", re.IGNORECASE | re.DOTALL)
                if m:
                    out += [x.strip() for x in re.findall(r"<language>([^<]+)</language>", m.group(1), re.IGNORECASE)]
        except Exception:
            pass
    if xml_path and os.path.isfile(xml_path):
        try:
            root = _parse_root(xml_path)
            if root is not None:
                for kind in ("Audio", "Subtitle"):
                    out += [(e.findtext("Language") or "").strip() for e in root.iter(kind)]
        except Exception:
            pass
    return [x for x in out if x]


def lang_in_stored_streams(row, iso_code):                       ### NEW v0.19.5 AS-A1 ###
    """The target language in the FFprobe data the row kept. A rescan without FFprobe judges from this and the files it read
    now, never from the old Y: a subtitle that was deleted must turn the answer to N."""
    return (any(is_target_lang(t.get("language", ""), iso_code) for t in (row.get("audio_tracks") or []))
            or any(is_target_lang(s.get("lang", ""), iso_code) for s in (row.get("subs_internal") or [])))


def compute_lang_ok(video_path, subs_internal, subs_external, nfo_path, xml_path,
                    iso_code="PT", use_ffprobe=None, subs_hard=None):
    """
    Y  — target language audio OR subtitle is present (ffprobe, subtitle files, streams written in XML / NFO)
    N  — video present but no target language found
    —  — no video file
    subs_hard — hard-coded subtitle codes marked by the user (v0.19.1 B15)
    """
    if not video_path:
        return "—"

    # 0. Hard-coded subtitles marked by the user (no probe needed) ### NEW v0.19.1 B15 ###
    for c in (subs_hard or []):
        if is_target_lang(c, iso_code):
            return "Y"

    # 1. FFprobe audio streams (the one cached probe — v0.19.1 I5)
    if _ffprobe_enabled(use_ffprobe):
        for stream in _probe_streams(video_path, "audio", use_ffprobe):
            tags = stream.get("tags", {})
            lang = tags.get("language") or tags.get("LANGUAGE") or ""
            if is_target_lang(lang, iso_code):
                return "Y"

    # 2. Internal subtitles (ffprobe)
    for s in subs_internal:
        if is_target_lang(s.get("lang", ""), iso_code):
            return "Y"

    # 3. External subtitle files
    for s in subs_external:
        if is_target_lang(s.get("lang", ""), iso_code):
            return "Y"

    # 4. Stream languages written in the files. ### MODIFIED v0.19.5 B121 ### only streams: NFO <language>, XML <Language> and
    # <LanguageCode> at the top level are the language for metadata downloads (Jellyfin, Emby), not the film's language.
    for lang in _file_stream_langs(nfo_path, xml_path):
        if is_target_lang(lang, iso_code):
            return "Y"

    return "N"

def extract_language_from_xml(filepath):
    """The top-level <Language> of movie.xml, what its header says. ### MODIFIED v0.19.5 B121 ### a stream's <Language> inside
    MediaInfo is not this tag; every empty form reads the same. "—" = no tag, "Unknown" = an empty tag."""
    if not filepath or not os.path.isfile(filepath): return "—"
    try:
        root = _parse_root(filepath)
        if root is not None:
            e = root.find("Language")
            if e is None:
                return "—"
            return (e.text or "").strip() or "Unknown"
        content = re.sub(r"<MediaInfo\b.*?</MediaInfo>", "", _read_text(filepath) or "", flags=re.IGNORECASE | re.DOTALL)
        m = re.search(r"<Language>([^<]*)</Language>", content)
        if m:
            return m.group(1).strip() or "Unknown"
        return "Unknown" if re.search(r"<Language\s*/>", content) else "—"
    except Exception: return "—"

def nfo_language_fields(nfo_path):                               ### NEW v0.19.6 TR1 ###
    """(the NFO's top-level <language> or "", the first audio language of its streamdetails or "").
    The top-level tag means what movie.xml's <Language> means (Jellyfin and Emby write it)."""
    if not nfo_path or not os.path.isfile(nfo_path):
        return "", ""
    try:
        root = _parse_root(nfo_path)
        if root is None:
            return "", ""
        e = root.find("language")
        top = (e.text or "").strip() if e is not None else ""
        aud = next((c for c in (_lang3(a.findtext("language")) for a in root.iter("audio")) if c), "")
        return top, aud or ""
    except Exception:
        return "", ""


_AUDIO_SRC_NAMES = {"NFO": "the NFO's streamdetails", "XML": "movie.xml's MediaInfo"}


def derive_language(r):                                          ### NEW v0.19.6 TR1 ###
    """The Language column (the user's rule, 2026-11-13): movie.xml's <Language> when the movie has a movie.xml;
    without one, the NFO's top-level <language>, else the language of the first audio track (FFprobe, else the
    NFO's streamdetails).  Sets r['language'] and r['language_src'] (said by the tooltip)."""
    if r.get("xml_exists"):
        v = r.get("xml_language") or r.get("language") or "—"
        r["xml_language"], r["language"], r["language_src"] = v, v, "movie.xml <Language>"
        return r
    top = (r.get("nfo_language") or "").strip()
    if top:
        r["language"], r["language_src"] = top, "the NFO's <language>"
        return r
    for t in r.get("audio_tracks") or []:
        c = (t.get("language") or "").strip()
        if c and c.upper() not in ("UND", "ZXX", "MIS", "MUL"):
            src = _AUDIO_SRC_NAMES.get(t.get("language_src"), "FFprobe")
            r["language"], r["language_src"] = c, f"the first audio track ({src})"
            return r
    if r.get("nfo_audio_lang"):
        r["language"], r["language_src"] = r["nfo_audio_lang"], "the first audio track (the NFO's streamdetails)"
        return r
    r["language"], r["language_src"] = "—", ""
    return r

