_RN_VCODEC = {"hevc": "HEVC", "h264": "H.264", "av1": "AV1", "mpeg2video": "MPEG-2", "vc1": "VC-1", "mpeg4": "MPEG-4",
              "vp9": "VP9", "vp8": "VP8"}
