def _coll_root(settings=None):                                   ### NEW v0.19.4 fix 2e ###
    """The collection folder setting, normalised: askdirectory gives "Z:/x" and os.path.join adds "\\"."""
    r = str((settings or SETTINGS).get("collection_folder") or "").strip()
    return os.path.normpath(r) if r else ""


def collection_tmdb_id(rows):                                    ### NEW v0.19.4 fix 2d ###
    """The TMDB collection id of a collection's rows (checked online first, then the NFO's tmdbcolid) or None."""
    for k in ("tmdb", "nfo"):
        for r in rows:
            c = (r.get("coll_tmdb") or {}).get("id") if k == "tmdb" else (r.get("coll_nfo") or {}).get("tmdbcolid")
            if c:
                try:
                    return int(c)
                except (TypeError, ValueError):
                    pass
    return None


def collection_tmdb_url(cid, name=""):                           ### NEW v0.19.4 fix 2d ###
    """The collection's TMDB page, or a TMDB collection search for the name when the id is not known."""
    if cid:
        return f"https://www.themoviedb.org/collection/{int(cid)}"
    import urllib.parse
    return "https://www.themoviedb.org/search/collection?query=" + urllib.parse.quote(str(name or ""))


def read_collection_folders(root, names, aliases=None):          ### NEW v0.19.4 B110g — I/O: call it in a worker ###
    """{group key: {"dir", "art", "near", "near_name", "legal"}} for the collection *names* under *root*;
    None when *root* is empty or not reachable (then nothing is "missing": not checked).
    v0.19.4 fix 15: *aliases* {name: [other TMDB names of that collection]} — a folder named like one of them,
    used by no collection and holding files, is the collection's old folder ("old_dir", "old_name")."""
    root = os.path.normpath(root) if root else root               ### v0.19.4 fix 2e ###
    if not root or not os.path.isdir(root):
        return None
    try:
        dirs = [e.name for e in os.scandir(root) if e.is_dir()]
    except OSError:
        return None
    out = {}
    used = {_cr.kodi_legal_name(n).casefold() for n in names}     # v0.19.4 fix 15
    for name in names:
        legal = _cr.kodi_legal_name(name)
        found, near = _cr.match_folder(legal, dirs)
        st = {"dir": None, "art": {}, "near": near, "near_name": found if near else None, "legal": legal, "set_nfo": None}
        if found and near != "accent":
            st["dir"] = os.path.join(root, found)
            try:
                _ls = os.listdir(st["dir"])
                st["art"] = _cr.art_types(_ls)
                ### NEW v0.20.1 CF2 — set.nfo: its tags, or False when there is none ###
                _sf = next((f for f in _ls if f.lower() == _sn.FILE_NAME), None)
                st["set_nfo"] = (_sn.read(_read_text(os.path.join(st["dir"], _sf))) or {}) if _sf else False
            except OSError:
                st["art"] = {}
        for alias in (aliases or {}).get(name) or ():               ### NEW v0.19.4 fix 15 ###
            al = _cr.kodi_legal_name(alias)
            if not al or al.casefold() in used or al.casefold() == legal.casefold():
                continue
            f2, n2 = _cr.match_folder(al, dirs)
            if f2 and n2 != "accent":
                p2 = os.path.join(root, f2)
                if _has_pictures(p2):                               # P3 (B6): pictures, not Thumbs.db / desktop.ini
                    st["old_dir"], st["old_name"] = p2, f2
                    break
        out[_cr.norm_name(name)] = st
    return out


def collection_aliases(rows):                                    ### NEW v0.19.4 fix 15 ###
    """{collection name in use: [the other TMDB names of its collection]} (the cache's names in every language
    and the movies' TMDB name) — where an older name's folder may still hold the images."""
    out = {}
    for r in rows:
        nm = collection_name(r)
        if not nm:
            continue
        cid = (r.get("coll_tmdb") or {}).get("id") or (r.get("coll_nfo") or {}).get("tmdbcolid")
        if not cid:
            continue
        lst = out.setdefault(nm, [])
        cand = list(((COLL_CACHE.get(str(cid)) or {}).get("names") or {}).values())
        cand.append((r.get("coll_tmdb") or {}).get("name"))
        for a in cand:
            if a and _cr.norm_name(a) != _cr.norm_name(nm) and a not in lst:
                lst.append(a)
    return {k: v for k, v in out.items() if v}


def _unique_path(path):                                          ### NEW v0.19.4 fix 15 ###
    if not os.path.exists(path):
        return path
    base, ext = os.path.splitext(path)
    i = 2
    while os.path.exists(f"{base} ({i}){ext}"):
        i += 1
    return f"{base} ({i}){ext}"


_JUNK_FILES = {"thumbs.db", "desktop.ini", ".ds_store"}         ### NEW v0.19.4 P3 (B6) — not the user's images ###


def _has_pictures(path):                                          ### NEW v0.19.4 P3 (B6) ###
    """True when *path* (or a sub-folder) holds a picture file — Thumbs.db / desktop.ini do not count."""
    try:
        for _dp, _dn, fn in os.walk(path):
            if any(os.path.splitext(f)[1].lower() in _cr.ART_EXTS for f in fn):
                return True
    except OSError:
        pass
    return False


def migrate_collection_folder(root, old_name, new_name, ref, backup_name="collection folder"):   ### NEW v0.19.4 fix 15 ###
    """Worker thread (inside a backup action): move the files of <root>\\<old> into <root>\\<new>.
    The new folder is made when missing; an image of the new folder that the old folder also has (same art type,
    e.g. poster.png vs poster.jpg, or the same file name) is set aside in <new>\\replaced\\ (the user's decision:
    the old folder's image was the one in use); the old folder is removed when empty.  Every file is backed up
    first and noted as renamed, so Backup History / Undo puts it back; ### v0.19.4 P3 ### the folders it makes are
    recorded too (Undo removes them when empty) and are made only after the backups; Thumbs.db / desktop.ini are
    not moved (backed up, then removed with the old folder).  Returns a note, or None when there is nothing to move."""
    old = os.path.join(root, _cr.kodi_legal_name(old_name))
    new = os.path.join(root, _cr.kodi_legal_name(new_name))
    if not os.path.isdir(old) or os.path.normcase(old) == os.path.normcase(new):
        return None
    files, junk = [], []
    for dp, _dn, fn in os.walk(old):
        for f in sorted(fn):
            full = os.path.join(dp, f)
            (junk if f.lower() in _JUNK_FILES else files).append((os.path.relpath(full, old), full))
    if not files:
        if junk and not _batch_backup_ok(backup_name, ref, *[full for _rel, full in junk]):
            raise BackupFailed("backup of the old collection folder failed — nothing removed")
        for _rel, full in junk:
            try:
                os.remove(full)
            except OSError:
                pass
        _remove_empty_tree(old)
        return f"'{os.path.basename(old)}': empty old folder removed"
    new_made = not os.path.isdir(new)
    try:
        top_new = [] if new_made else [e.name for e in os.scandir(new) if e.is_file()]
    except OSError:
        top_new = []
    new_art = {}
    for f in top_new:
        base, ext = os.path.splitext(f)
        if ext.lower() in _cr.ART_EXTS:
            new_art.setdefault(base.lower(), []).append(f)
    conflicts, seen = [], set()

    def _conf(p):
        k = os.path.normcase(p)
        if k not in seen and os.path.isfile(p):
            seen.add(k)
            conflicts.append(p)
    if not new_made:
        for rel, _full in files:
            _conf(os.path.join(new, rel))
            if os.sep not in rel:
                base, ext = os.path.splitext(rel)
                if ext.lower() in _cr.ART_EXTS:
                    for f in new_art.get(base.lower(), []):
                        _conf(os.path.join(new, f))
    # backups first (P3 B16): the old folder's files, then the ones set aside — Undo restores in this order
    if not _batch_backup_ok(backup_name, ref, *[full for _rel, full in files + junk]):
        raise BackupFailed("backup of the old collection folder failed — nothing moved")
    if conflicts and not _batch_backup_ok(backup_name, ref, *conflicts):
        raise BackupFailed("backup of the collection folder's images failed — nothing moved")
    if new_made:
        os.makedirs(new)
        _sc.note_created(_BACKUP_ROOT, backup_name, ref, new, new, logger=logger)   # P3 (F9): Undo removes it
    rep_dir = os.path.join(new, "replaced")
    for p in conflicts:
        if not os.path.isdir(rep_dir):
            os.makedirs(rep_dir)
            _sc.note_created(_BACKUP_ROOT, backup_name, ref, rep_dir, rep_dir, logger=logger)
        dst = _unique_path(os.path.join(rep_dir, os.path.relpath(p, new)))
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        shutil.move(p, dst)
        _sc.note_renamed(p, dst)
    moved = 0
    try:
        for rel, full in files:
            dst = os.path.join(new, rel)
            os.makedirs(os.path.dirname(dst), exist_ok=True)
            shutil.move(full, dst)
            _sc.note_renamed(full, dst)
            moved += 1
    except Exception as ex:                                        # P3 (B16): say how far it got
        raise RuntimeError(f"{moved} of {len(files)} files moved, then: {ex} (Undo puts the moved ones back)")
    for _rel, full in junk:
        try:
            os.remove(full)                                        # backed up above
        except OSError:
            pass
    _remove_empty_tree(old)
    note = f"'{os.path.basename(old)}' → '{os.path.basename(new)}': {_n(len(files), 'file')} moved"
    if conflicts:
        note += f", {_n(len(conflicts), 'image')} of the new folder kept in replaced\\"
    if os.path.isdir(old):
        note += " (the old folder still holds something and was kept)"
    logger.info(f"Collection folder: {note}")
    return note


def _remove_empty_tree(path):                                    ### NEW v0.19.4 fix 15 ###
    """Remove *path* and its sub-folders when they hold no files (bottom-up); a folder with files stays."""
    for dp, _dn, _fn in sorted(os.walk(path, topdown=False), key=lambda t: -len(t[0])):
        try:
            if not os.listdir(dp):
                os.rmdir(dp)
        except OSError:
            pass


def set_nfo_overview(cid, settings=None):                         ### NEW v0.20.1 CF2 ###
    """TMDB's overview of collection *cid* in the app's TMDB language (the library language, RV6), English when TMDB
    has none; '' when the collection was not checked online yet (COLL_CACHE, filled by Check All Collections Online)."""
    s = settings if settings is not None else SETTINGS
    ov = (COLL_CACHE.get(str(cid)) or {}).get("overviews") or {} if cid else {}
    lg = _tmdb_lang_for(s.get("lang_ok_code", "EN")).split("-")[0].lower()
    return ov.get(lg) or ov.get("en") or ""


def write_set_nfo(path, text):                                   ### NEW v0.20.1 CF2 ###
    """Write a set.nfo atomically (temp file + replace). A collection folder is outside the libraries, so the NFO
    writers' health-mode guard does not apply here."""
    ### MODIFIED v0.20.1 B16 ### an existing file keeps its BOM and its line endings (a new one: LF, no BOM)
    bom, nl = b"", "\n"
    try:
        with open(path, "rb") as f:
            head = f.read(1 << 16)
        bom = _UTF8_BOM if head.startswith(_UTF8_BOM) else b""
        nl = "\r\n" if b"\r\n" in head else "\n"
    except OSError:
        pass
    text = text.replace("\r\n", "\n").replace("\r", "\n").lstrip("\ufeff")
    # the bytes are UTF-8: a prolog that names another encoding would make Kodi read "AmÃ©lie" (as AU2 for the NFO)
    text = re.sub(r"""\A(<\?xml\b[^>]*?\bencoding=)(["'])(?!utf-?8\2)[^"']*\2""",
                  lambda m: f"{m.group(1)}{m.group(2)}UTF-8{m.group(2)}", text, count=1, flags=re.I)
    tmp = f"{path}.{threading.get_ident() % 100000}.mctmp"       # v0.20.2 PA15
    try:                                                         # v0.20.2 PB5: no set.nfo.mctmp left on a failure
        with open(tmp, "wb") as f:
            f.write(bom + text.replace("\n", nl).encode("utf-8"))
        _sc._replace_retry(tmp, path)
    finally:
        _drop_tmp(tmp)
    _cache_forget(path)


def collection_set_nfo_findings(key, name, rows, settings=None):   ### NEW v0.20.1 CF2 ###
    """None when the check does not apply (rule off, Kodi not ticked, no collection folder set, the folder not there
    yet — the folder rule speaks then); else set_nfo.check(...) + {"path", "existing"}."""
    s = settings if settings is not None else SETTINGS
    if not (s.get("health_rules") or {}).get("collection_set_nfo", True) or not _coll_root(s):
        return None
    if not any("kodi" in media_programs(_lib_root_of(r), s) for r in rows):
        return None
    st = COLL_FOLDERS.get(key) or {}
    if not st.get("dir") or st.get("set_nfo") is None:
        return None
    existing = st["set_nfo"] if st["set_nfo"] is not False else None
    lang = _tmdb_lang_for(s.get("lang_ok_code", "EN"))
    cid = collection_kind(rows)[1]                                # MODIFIED v0.20.2 SE: a mixed / own collection has no TMDB text
    out = _sn.check(existing, name, (COLL_CACHE.get(str(cid)) or {}).get("overviews") or {} if cid else {}, lang)
    out.update(path=os.path.join(st["dir"], _sn.FILE_NAME), existing=existing)
    return out


SET_NFO_EDIT_ACTION = "Edit set.nfo"                             ### NEW v0.20.2 SE — backup label ###


def collection_kind(rows):                                       ### NEW v0.20.2 SE / CG ###
    """("tmdb" | "mixed" | "user" | "gone" | "unchecked", TMDB collection ID or None) — collection_rules.collection_kind."""
    return _cr.collection_kind(rows, COLL_CACHE)


def set_nfo_editor_state(key, name, rows, settings=None):         ### NEW v0.20.2 SE ###
    """Where the set.nfo editor stands for one collection; None when it does not apply (Kodi not ticked for any of its
    libraries). Else {"mode", "kind", "cid", "read", "dir", "path", "make_dir"}:
    read False = the collection folders were not read yet (or no collection folder is set) — read them first;
    mode "edit" = a set.nfo is there; "create" = an own collection (user / mixed / gone, the online check found no
    TMDB collection) without one — also when its folder does not exist yet (made first, named from the collection
    name in the NFOs); None = a TMDB / unchecked collection without set.nfo (Write set.nfo gives TMDB's text)."""
    s = settings if settings is not None else SETTINGS
    if not rows or not any("kodi" in media_programs(_lib_root_of(r), s) for r in rows):
        return None
    kind, cid = collection_kind(rows)
    root = _coll_root(s)
    st = COLL_FOLDERS.get(key) if root else None
    out = {"mode": None, "kind": kind, "cid": cid, "read": st is not None, "dir": None, "path": None, "make_dir": False}
    if st is None:
        return out
    d = st.get("dir") or os.path.join(root, st.get("legal") or _cr.kodi_legal_name(name))
    out.update(dir=d, path=os.path.join(d, _sn.FILE_NAME), make_dir=not st.get("dir"))
    if st.get("dir") and isinstance(st.get("set_nfo"), dict):
        out["mode"] = "edit"
    elif kind in _cr.KINDS_OWN:
        out["mode"] = "create"
    return out


# ── v0.20.2 CG: Collection Gaps ──
CG_ACTION = "Collection Gaps fix"                                ### NEW v0.20.2 CG — backup label of its fixes ###


def collection_gap_groups(rows):                                 ### NEW v0.20.2 CG ###
    """([{"cid", "name", "members"}], [(name, reason)]) for the collections of *rows*: the TMDB collections (every
    spelling of one TMDB collection is ONE group, named by the spelling most of its movies use) and the others with
    the reason they are not analysed: "user" / "mixed" / "gone" / "not_checked"."""
    by = {}
    for r in rows:
        k = _cr.group_key(r)
        if k:
            by.setdefault(k, (collection_name(r), []))[1].append(r)
    tm, skipped = {}, []
    for _k, (nm, rs) in sorted(by.items(), key=lambda kv: kv[1][0].casefold()):
        kind, cid = collection_kind(rs)
        if kind == "tmdb":
            g = tm.setdefault(cid, {"cid": cid, "names": [], "members": []})
            g["names"].append((len(rs), nm))
            g["members"].extend(rs)
        else:
            skipped.append((nm, "not_checked" if kind == "unchecked" else kind))
    groups = [{"cid": cid, "name": sorted(g["names"], key=lambda x: (-x[0], x[1].casefold()))[0][1], "members": g["members"]}
              for cid, g in tm.items()]
    return sorted(groups, key=lambda g: g["name"].casefold()), skipped


def collection_gaps_results(groups, library, ignored, today, gone=()):   ### NEW v0.20.2 CG ###
    """(analyse() results, [(name, reason)]) — a group without the collection's movie list in the cache is
    "not_checked" (or "gone" when TMDB answered 404 this run). *library* = every row (the WHOLE library)."""
    idx = _cg.build_index(library)
    out, skipped = [], []
    for g in groups:
        ent = COLL_CACHE.get(str(g["cid"])) or {}
        if str(g["cid"]) in {str(x) for x in gone}:
            skipped.append((g["name"], "gone"))
            continue
        if "part_info" not in ent:
            skipped.append((g["name"], "not_checked"))
            continue
        out.append(_cg.analyse(g["cid"], g["name"], g["members"], ent["part_info"], idx,
                               _cg.ignored_ids(ignored, g["cid"]), today,
                               has_nfo=lambda r: bool(_metadata_targets(r)[0]),
                               confirmed=lambda r: (r.get("id_check") or {}).get("result") in ID_GOOD))
    return out, skipped


def collection_set_nfo_groups(rows, settings=None):              ### NEW v0.20.1 CF2 ###
    """[(key, name, rows, findings)] for every collection of *rows* the check applies to."""
    by = {}
    for r in rows:
        k = _cr.group_key(r)
        if k:
            by.setdefault(k, (collection_name(r), []))[1].append(r)
    out = []
    for k, (nm, rs) in sorted(by.items(), key=lambda kv: kv[1][0].lower()):
        f = collection_set_nfo_findings(k, nm, rs, settings)
        if f is not None:
            out.append((k, nm, rs, f))
    return out


def collection_folder_items(rows, root, complete=False):         ### NEW v0.19.4 B110g ###
    """One item per collection of *rows*: {"name", "key", "tmdb", "dir", "make", "need", "have", "rows"}.
    ### v0.19.5 B117 ### complete: also a collection that has everything, when TMDB can give new images."""
    root = os.path.normpath(root)                                 ### v0.19.4 fix 2e — no "Z:/x\\Name" ###
    by = {}
    for r in rows:
        k = _cr.group_key(r)
        if not k:
            continue
        it = by.setdefault(k, {"name": collection_name(r), "key": k, "tmdb": None, "rows": []})
        it["rows"].append(r)
        cid = (r.get("coll_tmdb") or {}).get("id") or (r.get("coll_nfo") or {}).get("tmdbcolid")
        if cid and not it["tmdb"]:
            it["tmdb"] = int(cid)
    out = []
    for k, it in by.items():
        st = COLL_FOLDERS.get(k) or {}
        d = st.get("dir") or os.path.join(root, _cr.kodi_legal_name(it["name"]))
        have = dict(st.get("art") or {})
        it.update(dir=d, make=not st.get("dir"), have=have,
                  need=[t for t in ("poster", "fanart") if t not in have] if it["tmdb"] else [])
        if it["make"] or it["need"] or (complete and it["tmdb"]):
            out.append(it)
    return out


def collection_folder_text(items):                               ### NEW v0.19.4 B110g ###
    L = [_i18n.t("rp.kodi_s_movie_set_8b59", n=_n(len(items), 'collection')), ""]
    for it in items:
        L.append(f"  {it['name']}:  {'create ' if it['make'] else ''}{it['dir']}")
        for t in it["need"]:
            L.append(_i18n.t("rp.jpg_tmdb_7a1e", t=t))
        for t, fn in sorted(it["have"].items()):
            L.append(_i18n.t("rp.exists_kept_unless_you_c866", fn=fn))
        if not it["tmdb"]:
            L.append(_i18n.t("rp.your_own_collection_no_31c7"))
    L += ["", _i18n.t("rp.existing_files_are_kept_670d"),
          _i18n.t("rp.undo_backup_history_puts_b8e3")]
    return "\n".join(L)
def collection_fix_items(rows, cache=None, lib_lang="en"):        ### NEW v0.19.4 B110e ###
    """([(row, (name, tmdbcolid, overview))], {why: count}) — the movies the collection fix changes."""
    items, skipped = [], {}
    for r in rows:
        if not r.get("nfo_exists"):
            skipped["no NFO"] = skipped.get("no NFO", 0) + 1
            continue
        mark_coll_none(r)                                        ### NEW v0.19.4 fix 3b ###
        name, cid, ov, why = _cr.fix_target(r, COLL_CACHE if cache is None else cache, lib_lang,
                                            _COLL_CHOSEN if cache is None else None, explicit=True)   # fix 5: one name per collection; v0.19.5 CO-D2: the user's Fix
        if why and why != "already right" and r.get("coll_nfo"):   ### NEW v0.19.4 fix 5 — a spelling split (no TMDB name) ###
            nfo = r["coll_nfo"]
            key = (r.get("coll_tmdb") or {}).get("id") or nfo.get("tmdbcolid") or _cr.norm_name(nfo.get("name"))
            sp = _COLL_SPELLINGS.get(key) or {}
            if len(sp) > 1:
                best = max(sorted(sp), key=lambda s: sp[s])
                if best != nfo.get("name"):
                    items.append((r, (best, nfo.get("tmdbcolid"), None)))
                    continue
        if why:
            skipped[why] = skipped.get(why, 0) + 1
        else:
            items.append((r, (name, cid, ov)))
    return items, skipped


def collection_fix_targets(rows, items):                         ### NEW v0.20.1 SN1 ###
    """[(group key, name, rows)] — the collections of *rows* under the name they have AFTER the fix *items*
    [(row, (name, tmdbcolid, overview))]; rows with no collection are left out. Pure."""
    after = {id(r): t[0] for r, t in items if t and t[0] and t[0] != "title"}
    by = {}
    for r in rows:
        nm = after.get(id(r)) or collection_name(r)
        if nm:
            by.setdefault(_cr.norm_name(nm), (nm, []))[1].append(r)
    return [(k, nm, rs) for k, (nm, rs) in sorted(by.items(), key=lambda kv: kv[1][0].lower())]


def collection_siblings(rows, results):                          ### NEW v0.19.4 fix 5 ###
    """*rows* plus every other movie of the same collections (same TMDB collection or same name key): a
    collection fix writes ONE name to all of them."""
    ids, keys = set(), set()
    for r in rows:
        c = (r.get("coll_tmdb") or {}).get("id") or (r.get("coll_nfo") or {}).get("tmdbcolid")
        if c:
            ids.add(str(c))
        if _cr.group_key(r):
            keys.add(_cr.group_key(r))
    seen = {id(r) for r in rows}
    out = list(rows)
    for r in results or []:
        if id(r) in seen:
            continue
        c = (r.get("coll_tmdb") or {}).get("id") or (r.get("coll_nfo") or {}).get("tmdbcolid")
        if (c and str(c) in ids) or (_cr.group_key(r) and _cr.group_key(r) in keys):
            out.append(r)
            seen.add(id(r))
    return out


def collection_fix_text(items, skipped):                         ### NEW v0.19.4 B110e ###
    """The preview: one line per movie 'current → new'; the skipped counts."""
    L = [_i18n.t("rp.get_the_collection_tmdb_e068", n=_n(len(items), 'movie')), ""]
    for r, (name, cid, _ov) in items:
        cur = (r.get("coll_nfo") or {}).get("name") or "(none)"
        L.append(f"  {r.get('movie_name') or r.get('subfolder')}:  {cur}  →  {name}  (TMDB {cid})")
    if skipped:
        L += ["", _i18n.t("sn1.not_changed")] + [f"  {_n(k, 'movie')} — {why}" for why, k in sorted(skipped.items())]   # v0.20.1 SN1
    L += ["", _i18n.t("rp.each_nfo_and_movie_ff11")]
    return "\n".join(L)


