def _tmdb_fetch_json(url, timeout=15):                         ### NEW v0.17.0-bug2, FIX v0.17.2 ###
    """
    Fetch a TMDB API URL and return the decoded JSON dict.
    Does NOT request gzip to avoid double-decompression on platforms where
    urllib auto-decompresses.  If the response happens to be gzip anyway,
    we decompress defensively.
    """
    import urllib.request, gzip as _gzip
    req = urllib.request.Request(
        url,
        headers={"User-Agent": _UA})
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        raw = resp.read()
    # Detect gzip by magic bytes — decompress only if really gzip
    if len(raw) >= 2 and raw[0] == 0x1f and raw[1] == 0x8b:
        try:
            raw = _gzip.decompress(raw)
        except Exception:
            pass   # already decompressed by urllib or not actually gzip
    # Try UTF-8 first, fall back to latin-1
    try:
        return json.loads(raw.decode("utf-8"))
    except UnicodeDecodeError:
        return json.loads(raw.decode("latin-1"))


# ══════════════════════════════════════════════════════════════════════════════
# One HTTP client for TMDb / OMDb (v0.19.1)                     ### NEW v0.19.1 ###
# ══════════════════════════════════════════════════════════════════════════════
# Every TMDb/OMDb API call goes through _http_get_json(service, url): a token
# bucket per service, retries with backoff on 429 / 5xx / timeouts / resets
# (Retry-After honoured), no retry on 4xx.  Call it from worker threads only.
_HTTP_LIMITS = {"tmdb": (40, 10.0), "omdb": (5, 1.0), "fanarttv": (5, 1.0)}   # fanarttv: v0.19.1 I10
_HTTP_RETRIES = 3
_HTTP_BACKOFF = (1.0, 2.0, 4.0)
_HTTP_RETRY_AFTER_MAX = 30.0
_HTTP_TIMES = {}                                   # service -> deque of request times
_HTTP_LOCK  = threading.Lock()


def _http_rate_wait(service):
    n_max, window = _HTTP_LIMITS.get(service, (10, 1.0))
    dq = _HTTP_TIMES.setdefault(service, collections.deque())
    while True:
        with _HTTP_LOCK:
            now = time.monotonic()                              ### MODIFIED v0.19.4 B96c — was time.time(): a clock change made workers sleep for hours ###
            while dq and now - dq[0] > window:
                dq.popleft()
            if len(dq) < n_max:
                dq.append(now)
                return
            wait = dq[0] + window - now + 0.05
        time.sleep(wait)


def _http_retry_delay(exc, attempt):
    """Seconds to wait before retrying *exc*, or None when it must not be retried."""
    import urllib.error as _ue, socket as _so
    if isinstance(exc, _ue.HTTPError):
        if exc.code not in (429, 500, 502, 503, 504):
            return None
        ra = None
        try:
            ra = float((exc.headers or {}).get("Retry-After") or "")
        except (TypeError, ValueError):
            ra = None
        if ra is not None:
            return max(0.0, min(ra, _HTTP_RETRY_AFTER_MAX))
        return _HTTP_BACKOFF[min(attempt, len(_HTTP_BACKOFF) - 1)]
    if isinstance(exc, _ue.URLError):
        r = str(exc.reason).lower()
        if "timed out" in r or "reset" in r or "10054" in r or "temporarily" in r:
            return _HTTP_BACKOFF[min(attempt, len(_HTTP_BACKOFF) - 1)]
        return None
    if isinstance(exc, (TimeoutError, ConnectionResetError, _so.timeout)):
        return _HTTP_BACKOFF[min(attempt, len(_HTTP_BACKOFF) - 1)]
    return None


# ── v0.19.1 B20 + B22: refusals, failure kinds, pauses ──────────────────────────
# B20: inside a batch run a service that REFUSES (daily limit / invalid key)
# is not asked again until the run ends.  The run state lives in thread-local
# storage (per run, per worker thread); single-movie actions are never inside
# a run.
# B22: every failure is classified (rate_limited, daily_limit, invalid_key,
# offline, server_error, timeout) into ONE message + advice; a rate limit,
# daily limit or repeated server error starts a per-service PAUSE that is saved
# in settings.json ("api_pauses") and survives a restart; a batch run asks the
# user ONCE per service what to do (pause this run / continue with the other
# source / cancel) when a run-level callback is installed.
_RUN = threading.local()
_SERVICE_LABEL = {"tmdb": "TMDB", "omdb": "OMDb (IMDb data)", "fanarttv": "fanart.tv"}
_REFUSAL_TEXT = {"daily_limit": "daily request limit reached", "invalid_key": "API key rejected",
                 "rate_limited": "too many requests", "offline": "no connection",
                 "server_error": "not responding", "timeout": "no answer in time"}
_REFUSAL_KINDS = ("daily_limit", "invalid_key")


def api_failure_message(service, kind):                         ### NEW v0.19.1 B22 ###
    """"<message> <advice>" for a service + failure kind (never contains a key)."""
    other = (" " + _i18n.t("uf.tmdb_ratings_still_work_c20a").strip()) if service == "omdb" else ""   # v0.20.0 AU23
    m, a = api_failure_text(_SERVICE_LABEL.get(service, service), kind, other)
    return f"{m} {a}"


def classify_api_failure(service, exc=None, data=None):          ### NEW v0.19.1 B22 ###
    """Failure kind of a request (None = no service failure, e.g. HTTP 404 or
    "movie not found")."""
    import urllib.error as _ue, socket as _so
    if isinstance(exc, ServiceUnavailable):
        return exc.kind
    if data is not None:
        if isinstance(data, dict) and str(data.get("Response", "")).lower() == "false":
            el = str(data.get("Error") or "").lower()
            if "limit" in el:
                return "daily_limit"
            if "invalid api key" in el or "no api key" in el:
                return "invalid_key"
        return None
    if isinstance(exc, _ue.HTTPError):
        body = _http_error_body(exc)
        return classify_http_status(exc.code, str(body.get("Error") or body.get("status_message")
                                                  or body.get("error message") or ""))   # "error message": fanart.tv
    if isinstance(exc, _ue.URLError):
        return classify_network_reason(str(exc.reason))
    if isinstance(exc, (TimeoutError, _so.timeout)):
        return "timeout"
    if isinstance(exc, (ConnectionError, OSError)):
        return "offline"
    return None


class ServiceUnavailable(Exception):                             ### NEW v0.19.1 B20 ###
    """Raised instead of a request when the service refused / failed earlier in
    this run (or is paused), so no request is made."""
    def __init__(self, service, kind):
        self.service, self.kind = service, kind
        super().__init__(f"{_SERVICE_LABEL.get(service, service)} unavailable "
                         f"({_REFUSAL_TEXT.get(kind, kind)})")


# ── B22: per-service pause, saved in settings.json ────────────────────────────
_API_PAUSES = {}
_PAUSE_LOCK = threading.RLock()
_PAUSE_LISTENERS = []                 # callables, called (any thread) after a pause starts / ends


def _pause_notify():
    for cb in list(_PAUSE_LISTENERS):
        try:
            cb()
        except Exception:
            pass


def _pause_persist():
    SETTINGS["api_pauses"] = {k: dict(v) for k, v in _API_PAUSES.items()}
    try:
        _save_settings(SETTINGS)
    except Exception as ex:
        logger.warning(f"api_pauses not saved: {_redact(ex)}")


def api_pause_start(service, kind):                              ### NEW v0.19.1 B22 ###
    """Pause *service* for API_PAUSE_SECONDS[kind] (no pause for other kinds)."""
    secs = API_PAUSE_SECONDS.get(kind)
    if not secs:
        return None
    until = datetime.datetime.now() + datetime.timedelta(seconds=secs)
    entry = {"until": until.isoformat(timespec="seconds"), "kind": kind,
             "message": api_failure_message(service, kind)}
    with _PAUSE_LOCK:
        _API_PAUSES[service] = entry
        _pause_persist()
    logger.warning(f"{_SERVICE_LABEL.get(service, service)} paused until {entry['until']} ({kind})")
    _pause_notify()
    return entry


def api_pause_end(service):                                      ### NEW v0.19.1 B22 ###
    with _PAUSE_LOCK:
        if _API_PAUSES.pop(service, None) is None:
            return False
        _pause_persist()
    logger.info(f"{_SERVICE_LABEL.get(service, service)} pause ended")
    _pause_notify()
    return True


def api_pause_get(service):                                      ### NEW v0.19.1 B22 ###
    """The active pause entry of *service* (an expired one is dropped), or None."""
    with _PAUSE_LOCK:
        e = _API_PAUSES.get(service)
        if not e:
            return None
        try:
            expired = datetime.datetime.fromisoformat(e["until"]) <= datetime.datetime.now()
        except Exception:
            expired = True
    if expired:
        api_pause_end(service)
        return None
    return e


def api_pauses_active():                                         ### NEW v0.19.1 B22 ###
    return {s: e for s in list(_API_PAUSES) for e in [api_pause_get(s)] if e}


def api_pauses_load():                                           ### NEW v0.19.1 B22 ###
    """On start: restore the saved pauses, drop the expired ones."""
    with _PAUSE_LOCK:
        _API_PAUSES.clear()
        for s, e in (SETTINGS.get("api_pauses") or {}).items():
            if isinstance(e, dict) and e.get("until"):
                _API_PAUSES[s] = dict(e)
        before = set(_API_PAUSES)
    active = api_pauses_active()
    if set(active) != before:
        with _PAUSE_LOCK:
            _pause_persist()
    return active


def _api_pauses_clear():                                         ### NEW v0.19.1 B22 — self-test helper ###
    with _PAUSE_LOCK:
        had = bool(_API_PAUSES)
        _API_PAUSES.clear()
        if had or SETTINGS.get("api_pauses"):
            _pause_persist()
    _pause_notify()


# ── run state ─────────────────────────────────────────────────────────────────
def _service_run_begin(on_failure=None, alternatives=None, cancel_check=None):   ### NEW v0.19.1 B20, B22 ###
    """Start a batch run.  on_failure(service, kind, other_label) → "pause" |
    "continue" | "cancel" is asked once per service at its first failure."""
    _RUN.blocked = {}
    _RUN.skipped = collections.Counter()
    _RUN.decided = {}                                   # v0.20.0 AU4: service → the user's answer
    _RUN.on_failure = on_failure
    _RUN.alternatives = dict(alternatives or {})
    _RUN.cancel_check = cancel_check
    _RUN.cancelled = False


def _service_blocked(service):                                  ### NEW v0.19.1 B20 ###
    """The refusal kind when *service* is blocked in the current run, else None."""
    return (getattr(_RUN, "blocked", None) or {}).get(service)


def _service_run_cancelled():                                   ### NEW v0.19.1 B22 ###
    # v0.20.2 PB2 (audit): the app closing stops the run too (Auto Repair kept going until the 2 s at exit killed it)
    return bool(getattr(_RUN, "cancelled", False)) or APP_CLOSING.is_set()


def _service_run_summary():                                     ### NEW v0.19.1 B20, MODIFIED B22 ###
    """One line per service blocked in this run (for the final message)."""
    out = []
    for svc, kind in (getattr(_RUN, "blocked", None) or {}).items():
        n = (getattr(_RUN, "skipped", None) or {}).get(svc, 0)
        out.append(f"{_SERVICE_LABEL.get(svc, svc)} unavailable for the rest of this run "
                   f"({_REFUSAL_TEXT.get(kind, kind)}) — not asked again"
                   + (f" ({_n(n, 'request')} saved)." if n else ".")
                   + f"\n  {api_failure_message(svc, kind)}")
    return out


def _service_run_end():                                         ### NEW v0.19.1 B20 ###
    for k in ("blocked", "skipped", "decided", "on_failure", "alternatives", "cancel_check"):
        setattr(_RUN, k, None)
    _RUN.cancelled = False


def _http_error_body(exc):                                      ### NEW v0.19.1 B20 ###
    """The JSON body of an HTTPError, read once and cached on the exception
    (an HTTPError body can only be read one time)."""
    if not hasattr(exc, "_mc_body"):
        try:
            exc._mc_body = json.loads(exc.read() or b"{}")
            if not isinstance(exc._mc_body, dict):                ### NEW v0.19.5 CO-D13 — a body of null or a list ###
                exc._mc_body = {}
        except Exception:
            exc._mc_body = {}
    return exc._mc_body




def _run_on_failure(service, kind):                             ### NEW v0.19.1 B22 ###
    """Inside a run: the user's decision for the first failure of *service*:
    "pause" / "continue" / "cancel", or None (no callback → B20 rules)."""
    if getattr(_RUN, "blocked", None) is None:
        return None
    if service in _RUN.decided:
        ### MODIFIED v0.20.0 AU4 (pre-build audit) ### the answer is remembered: "Pause this run" used to hold for the
        # first failure only — the second one blocked the service for the rest of the run
        return _RUN.decided[service]
    cb = getattr(_RUN, "on_failure", None)
    if not cb:
        return None
    _RUN.decided[service] = "continue"                          # asked once, also when the callback fails
    try:
        _RUN.decided[service] = cb(service, kind, (_RUN.alternatives or {}).get(service)) or "continue"
    except Exception as ex:
        logger.error(f"service failure callback: {ex}")
    return _RUN.decided[service]


def _wait_for_pause(service):                                   ### NEW v0.19.1 B22 ###
    """Worker thread: sleep until *service*'s pause ends (Cancel aborts).
    Returns False when the run was cancelled."""
    while True:
        e = api_pause_get(service)
        if not e:
            return True
        cc = getattr(_RUN, "cancel_check", None)
        if cc and cc():
            _RUN.cancelled = True
            return False
        time.sleep(1.0)


def _http_get_json(service, url, timeout=15, _waited=False):
    """GET *url* (TMDb or OMDb API) and return the decoded JSON, with the
    service's rate limit and retries.  Raises the last exception on failure
    (its text never contains the API key).
    ### MODIFIED v0.19.1 B20 / B22 ### inside a batch run a blocked or paused
    service raises ServiceUnavailable without a request; failures are
    classified, start a pause when due, and the run asks the user once."""
    if getattr(_RUN, "blocked", None) is not None:
        _blk = _service_blocked(service)
        if _blk:
            _RUN.skipped[service] += 1
            raise ServiceUnavailable(service, _blk)
        _p = api_pause_get(service)
        if _p and not _waited:                    # paused while the run was going (other thread / earlier failure)
            dec = _run_on_failure(service, _p.get("kind", "server_error"))
            if dec == "pause" and _wait_for_pause(service):
                return _http_get_json(service, url, timeout, _waited=True)
            _RUN.blocked[service] = _p.get("kind", "server_error")
            if dec == "cancel":
                _RUN.cancelled = True
            _RUN.skipped[service] += 1
            raise ServiceUnavailable(service, _RUN.blocked[service])
    last = None
    for attempt in range(_HTTP_RETRIES + 1):
        _http_rate_wait(service)
        try:
            data = _tmdb_fetch_json(url, timeout=timeout)
            _k = classify_api_failure(service, data=data)
            if _k:
                dec = _handle_failure(service, _k)
                if dec == "pause" and not _waited and _wait_for_pause(service):
                    return _http_get_json(service, url, timeout, _waited=True)
            return data
        except Exception as ex:
            last = ex
            delay = _http_retry_delay(ex, attempt)
            if delay is None or attempt >= _HTTP_RETRIES:
                break
            logger.warning(f"{service.upper()} request retry {attempt + 1}/{_HTTP_RETRIES} in {delay:.1f}s: "
                           f"{_redact(ex)}  [{_redact(url)}]")
            time.sleep(delay)
    _k = classify_api_failure(service, exc=last)
    if _k:
        dec = _handle_failure(service, _k)
        if dec == "pause" and not _waited and _wait_for_pause(service):
            return _http_get_json(service, url, timeout, _waited=True)
    raise last


def _handle_failure(service, kind):                             ### NEW v0.19.1 B22 ###
    """Bookkeeping for one classified failure: start the pause when due, and
    inside a run block the service (refusals always; other kinds when the
    user chose "continue" / "cancel").  Returns the run decision or None."""
    if kind in API_PAUSE_SECONDS:
        api_pause_start(service, kind)
    if getattr(_RUN, "blocked", None) is None:
        return None
    dec = _run_on_failure(service, kind)
    if dec is None:                               # no callback: B20 rules
        if kind in _REFUSAL_KINDS:
            _RUN.blocked[service] = kind
            logger.warning(f"{_SERVICE_LABEL.get(service, service)}: {_REFUSAL_TEXT[kind]} — "
                           f"not asked again in this run")
        return None
    if dec == "pause" and kind in API_PAUSE_SECONDS:
        return "pause"
    _RUN.blocked[service] = kind
    if dec == "cancel":
        _RUN.cancelled = True
    logger.warning(f"{_SERVICE_LABEL.get(service, service)}: {_REFUSAL_TEXT.get(kind, kind)} — "
                   f"not asked again in this run ({dec})")
    return dec


# Per-thread record of the last failed rating fetch, so Ratings Sync can tell
# "the source has no rating" from "the source could not be asked".
_FETCH_STATE = threading.local()


def _note_fetch_error(service, exc):
    msgs = getattr(_FETCH_STATE, "errors", None)
    if msgs is None:
        msgs = _FETCH_STATE.errors = []
    msgs.append(f"{service}: {_api_error_message(exc, service)}".splitlines()[0])


def _take_fetch_errors():
    msgs = list(getattr(_FETCH_STATE, "errors", None) or [])
    _FETCH_STATE.errors = []
    return msgs


def _api_error_message(exc, service="TMDB"):                    ### NEW v0.19.1, MODIFIED B22 ###
    """Human-readable message + advice for a TMDB or OMDb failure (no API key in it)."""
    import urllib.error as _ue
    if isinstance(exc, ServiceUnavailable):                     ### NEW v0.19.1 B20 ###
        return str(exc)
    if service.lower() == "omdb":
        if isinstance(exc, _ue.HTTPError):
            kind = classify_api_failure("omdb", exc=exc)
            if kind:
                return f"{api_failure_message('omdb', kind)} (HTTP {exc.code})"
            body = _http_error_body(exc)
            return _redact(f"OMDb returned HTTP {exc.code}: {body.get('Error') or exc.reason}")
        kind = classify_api_failure("omdb", exc=exc)
        if kind:
            return api_failure_message("omdb", kind)
        el = str(exc).lower()                                   # OMDb refusal given as a JSON answer
        if "limit" in el:
            return api_failure_message("omdb", "daily_limit")
        if "invalid api key" in el:
            return api_failure_message("omdb", "invalid_key")
        return _redact(f"Unexpected OMDb error: {type(exc).__name__}: {exc}")
    return _tmdb_error_message(exc)


def _tmdb_error_message(exc):                                  ### NEW v0.17.0-bug2 ###
    """Convert a urllib/network exception into a human-readable TMDB error string.
    ### MODIFIED v0.19.1 — never contains the API key ###"""
    return _redact(_tmdb_error_message_raw(exc))


def _tmdb_error_message_raw(exc):
    """### MODIFIED v0.19.1 B22 — one message + advice per failure kind ###"""
    import urllib.error as _ue
    if isinstance(exc, ServiceUnavailable):                     ### NEW v0.19.1 B20 ###
        return f"{exc}. {api_failure_message(exc.service, exc.kind)}"
    if isinstance(exc, _ue.HTTPError):
        body = _http_error_body(exc)                            ### MODIFIED v0.19.1 B20 — body read once ###
        reason = body.get("status_message") or f"{exc.reason}"
        if exc.code == 404:
            return (f"Movie not found on TMDB (HTTP 404).\n"
                    f"The TMDB ID in your file may be incorrect.\n"
                    f"Detail: {reason}")
        kind = classify_api_failure("tmdb", exc=exc)
        if kind:
            return f"{api_failure_message('tmdb', kind)} (HTTP {exc.code})"
        return f"TMDB returned HTTP {exc.code}: {reason}"
    if isinstance(exc, _ue.URLError):
        r = str(exc.reason)
        if "SSL" in r or "certificate" in r.lower():
            return "Network error: SSL certificate problem — check your internet connection."
        return api_failure_message("tmdb", classify_api_failure("tmdb", exc=exc))
    kind = classify_api_failure("tmdb", exc=exc)
    if kind:
        return api_failure_message("tmdb", kind)
    return f"Unexpected error: {type(exc).__name__}: {exc}"


def is_network_error(ex):                                       ### NEW v0.19.4 B77 ###
    """True for a network failure that should stop a run (no connection, DNS,
    timeout, reset); False for an HTTP answer and for file errors
    (PermissionError, a locked or read-only NFO …)."""
    import urllib.error as _ue
    if isinstance(ex, _ue.HTTPError):
        return False
    return isinstance(ex, (_ue.URLError, ConnectionError, TimeoutError))


def _tmdb_download_image(url, dest_path, retries=2):           ### NEW v0.18.0 ###
    """
    Download a TMDB image URL to dest_path using urllib with manual retry logic.

    Uses short timeouts (connect=3s, read=10s) and exponential backoff between
    retries (0.5s, 1.0s).  Catches ConnectionResetError / WinError 10054 and
    retries automatically.  Does NOT require the 'requests' library.

    Parameters
    ----------
    url : str
        Full TMDB image URL (original or thumbnail).
    dest_path : str
        Absolute path where the downloaded bytes should be written.
    retries : int
        Number of retry attempts after the first try (default 2 → up to 3 total).

    Returns
    -------
    (True, None)   on success
    (False, str)   on failure, where str is a human-readable error message
    """
    import urllib.request, urllib.error, time as _time, socket as _socket

    _CONNECT_TIMEOUT = 3    # seconds to establish connection
    _READ_TIMEOUT    = 10   # seconds to read the full response
    _BACKOFF         = [0.5, 1.0]  # wait before retry 1 and retry 2

    last_err = "Unknown error"
    for attempt in range(retries + 1):
        if attempt > 0:
            wait = _BACKOFF[min(attempt - 1, len(_BACKOFF) - 1)]
            _time.sleep(wait)
        try:
            req = urllib.request.Request(
                url, headers={"User-Agent": _UA})
            with urllib.request.urlopen(req,
                    timeout=_CONNECT_TIMEOUT + _READ_TIMEOUT) as resp:
                data = resp.read()
            try:                                                ### MODIFIED v0.19.4 B79 — temp file, check, replace ###
                write_image_atomic(dest_path, data)
            except NotAnImageError as nie:                      # not retried: the server answered, but not with an image
                logger.warning(f"_tmdb_download_image: {url}: {nie}")
                return False, (f"The server did not send an image ({len(data)} bytes) — "
                               "the old file was kept.")
            return True, None

        # NOTE v0.18.3: HTTPError/URLError are subclasses of OSError, so they
        # MUST be handled before the generic OSError branch (they used to be
        # unreachable, which disabled every retry).           ### FIXED v0.18.3 ###
        except urllib.error.HTTPError as e:
            if e.code in (429, 500, 502, 503, 504):
                last_err = f"HTTP {e.code} from TMDB (will retry)"
                logger.warning(f"_tmdb_download_image attempt {attempt+1}: {last_err}")
                continue
            # Non-retryable HTTP error
            last_err = _tmdb_error_message(e)
            return False, last_err

        except urllib.error.URLError as e:
            last_err = _tmdb_error_message(e)
            # Timeout / connection resets are worth retrying; DNS failures are not
            reason = str(e.reason).lower()
            if "timed out" in reason or "10054" in reason or "reset" in reason:
                logger.warning(f"_tmdb_download_image attempt {attempt+1}: {last_err}")
                continue
            return False, last_err

        except (ConnectionResetError, TimeoutError) as e:
            last_err = f"Connection reset by TMDB server (will retry): {e}"
            logger.warning(f"_tmdb_download_image attempt {attempt+1}: {last_err}")
            continue

        except OSError as e:
            err_str = str(e)
            # v0.20.2 PB6: a file error names its path ("The French Connection") — only a real network error retries
            if (getattr(e, "winerror", None) == 10054 or isinstance(e, ConnectionError)
                    or (not getattr(e, "filename", None) and ("10054" in err_str or "connection" in err_str.lower()))):
                last_err = f"Connection reset (WinError): {e}"
                logger.warning(f"_tmdb_download_image attempt {attempt+1}: {last_err}")
                continue
            # Other OS errors (disk full, permission) — do not retry
            last_err = f"File write error: {e}"
            logger.error(f"_tmdb_download_image: {last_err}")
            return False, last_err

        except Exception as e:
            last_err = f"Unexpected download error: {type(e).__name__}: {e}"
            logger.error(f"_tmdb_download_image: {last_err}")
            return False, last_err

    return False, last_err.replace(" (will retry)", "")             # v0.20.0 AU16: the retries are used up


def _fetch_tmdb_rating(tmdb_id, api_key):
    """
    Fetch rating and vote count from TMDb.
    Returns (rating_str, votes_str) or (None, None) on failure.
    """
    if not tmdb_id or not api_key:
        return None, None
    try:
        url = (f"https://api.themoviedb.org/3/movie/{tmdb_id}"
               f"?api_key={api_key}&language=en-US")
        data = _tmdb_rate_limited_fetch(url, timeout=10)      ### MODIFIED v0.19.1 — shared client ###
        rating = data.get("vote_average")
        votes  = data.get("vote_count")
        if rating is not None and votes is not None:
            return f"{rating:.1f}", str(int(votes))
    except Exception as ex:
        if not _is_http_404(ex):                              ### NEW v0.19.1 — "could not ask" ###
            _note_fetch_error("TMDB", ex)
            logger.warning(f"TMDB rating for {tmdb_id}: {_api_error_message(ex, 'TMDB')}")
    return None, None

def _fetch_tmdb_rating_by_imdb(imdb_id, api_key):                ### NEW v0.19.6 TR2 ###
    """TMDB's rating for a movie known only by its IMDb ID (TMDB's /find).  A tester whose movies held only IMDb IDs
    and who had only a TMDB key got nothing.  Returns (rating_str, votes_str) or (None, None)."""
    if not imdb_id or not api_key:
        return None, None
    try:
        import urllib.parse
        url = (f"https://api.themoviedb.org/3/find/{urllib.parse.quote(str(imdb_id))}"
               f"?api_key={api_key}&external_source=imdb_id&language=en-US")
        data = _tmdb_rate_limited_fetch(url, timeout=10)
        hits = data.get("movie_results") or []
        if hits:
            rating, votes = hits[0].get("vote_average"), hits[0].get("vote_count")
            if rating is not None and votes is not None:
                return f"{rating:.1f}", str(int(votes))
    except Exception as ex:
        if not _is_http_404(ex):
            _note_fetch_error("TMDB", ex)
            logger.warning(f"TMDB rating for {imdb_id}: {_api_error_message(ex, 'TMDB')}")
    return None, None


def ratings_skip_reason(imdb_id, tmdb_id, use_tmdb, use_omdb):     ### NEW v0.19.6 TR2 ###
    """Why no source can be asked for this movie, or None when one can.  TMDB takes a TMDB or an IMDb ID,
    OMDb only an IMDb ID."""
    if (use_tmdb and (tmdb_id or imdb_id)) or (use_omdb and imdb_id):
        return None
    if not imdb_id and not tmdb_id:
        return "no IMDb or TMDB ID in the files (Search Sources… finds it)"
    return "OMDb needs the IMDb ID: add it (Search Sources…), or set a TMDB key"


def _fetch_omdb_rating(imdb_id, api_key):
    """
    Fetch rating and vote count from OMDb (IMDb data).
    Returns (rating_str, votes_str) or (None, None) on failure.
    """
    if not imdb_id or not api_key:
        return None, None
    try:
        url = f"https://www.omdbapi.com/?apikey={api_key}&i={imdb_id}&type=movie"
        data = _http_get_json("omdb", url, timeout=10)        ### MODIFIED v0.19.1 — shared client ###
        if data.get("Response") == "True":
            rating = data.get("imdbRating")
            votes  = (data.get("imdbVotes") or "").replace(",", "")
            if rating and rating != "N/A" and votes and votes != "N/A":
                return rating, votes
        else:
            err = str(data.get("Error") or "")
            if "limit" in err.lower() or "invalid api key" in err.lower():
                _note_fetch_error("OMDb", RuntimeError(err))
                logger.warning(f"OMDb rating for {imdb_id}: {err}")
    except Exception as ex:
        _note_fetch_error("OMDb", ex)                         ### NEW v0.19.1 — "could not ask" ###
        logger.warning(f"OMDb rating for {imdb_id}: {_api_error_message(ex, 'OMDb')}")
    return None, None

def write_rating_to_files(nfo_path, xml_path, rating, votes, movie_name="rating_sync", backup=True, source=None):  ### MODIFIED v0.18.3; backup= v0.19.4 B82 ###
    """
    Write rating and votes to all matching tags in NFO and XML.
    NFO: <rating>, <votes>
    XML: <IMDBrating>, <Rating>, <Votes>, <VoteCount>
    Preserves all other content.
    v0.11.0: backup created before writing.            ### NEW v0.11.0 ###
    ### v0.19.4 B82 ### backup=False: the caller (a batch run) has already
    backed the files up into its own run folder — no second backup folder.
    ### v0.19.5 B122 ### source = "imdb" or "themoviedb": the value goes in that source's <ratings> entry, made if missing, and
    that entry becomes the only default; other entries keep their values. source=None (typed, an average): the current default.
    ### v0.19.5 WR-A5 ### a file with no rating tag gets them, so a fix never counts as done with nothing written.
    """
    errors = []
    if not (nfo_path and os.path.isfile(nfo_path)) and not (xml_path and os.path.isfile(xml_path)):
        return ["no NFO or XML to write the rating to"]

    def _replace_tag(content, tag, value):
        """Replace <tag>old</tag> or add before closing root if missing."""
        pattern = rf'(<{tag}\b[^>/]*>)[^<]*(</\s*{tag}\s*>)'
        if re.search(pattern, content, re.IGNORECASE):
            return re.sub(pattern, rf'\g<1>{value}\2', content,
                          flags=re.IGNORECASE)
        return re.sub(rf'<({tag})\b[^>]*/>', rf'<\g<1>>{value}</\g<1>>', content, flags=re.IGNORECASE)   # v0.19.5 WR-A5: <tag />

    # Backup before any writes                          ### NEW v0.11.0 ###
    if backup and not _backup_ok(movie_name or "rating_sync", nfo_path, xml_path):   ### MODIFIED v0.19.2 B40; v0.19.4 B82 ###
        return [BACKUP_FAILED_TEXT]

    # NFO
    if nfo_path and os.path.isfile(nfo_path):
        try:
            content = _read_for_edit(nfo_path)[0]   ### MODIFIED v0.19.2 B37 — strict UTF-8, never rewritten with U+FFFD ###
            _orig = content                                           # v0.20.2 PA7
            # ### MODIFIED v0.19.2 B38 ### the legacy <rating>/<votes> are changed only
            # OUTSIDE a Kodi <ratings> block: the old whole-file replace gave every
            # source's block (imdb, themoviedb, trakt …) the chosen source's votes.
            # Inside the block only the chosen source's <rating> changes.
            m_kr = _KODI_RATINGS_RE.search(content)
            parts = [content[:m_kr.start()], content[m_kr.end():]] if m_kr else [content]
            parts = [_replace_tag(_replace_tag(p, "rating", rating), "votes", votes) for p in parts]
            content = parts[0] + content[m_kr.start():m_kr.end()] + parts[1] if m_kr else parts[0]
            if source:                                               ### NEW v0.19.5 B122 ###
                content = _set_rating_entry(content, source, rating, votes)
            else:
                content = _replace_kodi_rating(content, rating, votes)   ### NEW v0.18.4 ###
                if not _KODI_RATINGS_RE.search(content) and not re.search(r"<rating\b", content, re.I):   # WR-A5
                    content = _insert_before_root_close(content, "movie", f"<rating>{rating}</rating>")
                    if not re.search(r"<votes\b", content, re.I):
                        content = _insert_before_root_close(content, "movie", f"<votes>{votes}</votes>")
            _atomic_write_text(nfo_path, _still_valid(_orig, content))   ### MODIFIED v0.19.0 — atomic; v0.20.2 PA7 ###
        except Exception as e:
            errors.append(f"NFO write error: {e}")

    # XML
    if xml_path and os.path.isfile(xml_path):
        try:
            content = _read_for_edit(xml_path)[0]   ### MODIFIED v0.19.2 B37 — strict UTF-8, never rewritten with U+FFFD ###
            _orig = content                                           # v0.20.2 PA7
            for tag in ["IMDBrating", "Rating"]:
                content = _replace_tag(content, tag, rating)
            for tag in ["Votes", "VoteCount"]:
                content = _replace_tag(content, tag, votes)
            _rt = re.search(r"</([\w.-]+)\s*>\s*$", content)          ### NEW v0.19.5 WR-A5 — a movie.xml with no rating tags ###
            if _rt:
                if not re.search(r"<(IMDBrating|Rating)\b", content, re.I):
                    content = _insert_before_root_close(content, _rt.group(1), f"<Rating>{rating}</Rating>")
                # MODIFIED v0.20.0 KR1.4: both vote tags, as Media Center Master writes them — the MediaBrowser / Emby
                # movie.xml parser reads <VoteCount>, other readers <Votes>
                if not re.search(r"<VoteCount\b", content, re.I):
                    content = _insert_before_root_close(content, _rt.group(1), f"<VoteCount>{votes}</VoteCount>")
                if not re.search(r"<Votes\b", content, re.I):
                    content = _insert_before_root_close(content, _rt.group(1), f"<Votes>{votes}</Votes>")
            _atomic_write_text(xml_path, _still_valid(_orig, content))   ### MODIFIED v0.19.0 — atomic; v0.20.2 PA7 ###
        except Exception as e:
            errors.append(f"XML write error: {e}")

    return errors

def _still_valid(old, new):                                       ### NEW v0.20.2 PA7 (audit) ###
    """A writer that edits a file which parses must leave it parsing (ValueError: nothing is written). A file that is
    already broken is left to its own rule (Corrupt NFO / XML)."""
    try:
        _require_xml(old)
    except ValueError:
        return new
    _require_xml(new)
    return new


def _insert_before_root_close(content, root_tag, line):           ### NEW v0.19.5 WR-A5 ###
    """*line* before the last </root_tag>, by character position, in the file's line ending. Unchanged when there is no such tag."""
    ### MODIFIED v0.20.2 PA7 — found in the original text: content.lower() is longer when the text holds a Turkish "İ"
    # (two characters lowered), and the block landed inside the tag ###
    _ms = list(re.finditer(rf"</{re.escape(root_tag)}\b", content, re.I))
    if not _ms:
        return content
    at = _ms[-1].start()
    nl = "\r\n" if "\r\n" in content else "\n"
    start = content.rfind("\n", 0, at) + 1
    if content[start:at].strip():                                 # the closing tag shares its line
        return content[:at] + line + content[at:]
    return content[:start] + "  " + line + nl + content[start:]


def _set_rating_entry(content, source, rating, votes):            ### NEW v0.19.5 B122 ###
    """The value in the <rating name="source"> entry of <ratings>, which is made when missing and becomes the only default,
    last in the block. Every other entry keeps its value; a block is made when the file has none."""
    nl = "\r\n" if "\r\n" in content else "\n"
    def _entry(ind, attrs, body):
        return f'{ind}<rating{attrs}>{body}</rating>'
    m = _KODI_RATINGS_RE.search(content)
    if not m:
        block = (f'<ratings>{nl}    <rating name="{source}" max="10" default="true">{nl}      <value>{rating}</value>{nl}'
                 f'      <votes>{votes}</votes>{nl}    </rating>{nl}  </ratings>')
        return _insert_before_root_close(content, "movie", block)
    block = m.group(1)
    items = list(_KODI_RATING_RE.finditer(block))
    target = next((it for it in items if re.search(rf'name\s*=\s*"{source}"', it.group(1), re.I)), None)
    out, pos = [], 0
    for it in items:
        ls = block.rfind("\n", 0, it.start()) + 1
        own_line = not block[ls:it.start()].strip()
        start = ls if own_line else it.start()
        end = it.end()
        if own_line:                                               # the entry with its whole line, when moved
            nx = block.find("\n", end)
            if nx >= 0 and not block[end:nx].strip():
                end = nx + 1
        out.append(block[pos:start])
        if it is not target:
            attrs = re.sub(r'\s+default\s*=\s*"true"', ' default="false"', it.group(1), flags=re.I)
            out.append(block[start:it.start()] + f"<rating{attrs}>{it.group(2)}</rating>" + block[it.end():end])
        pos = end
    rest = block[pos:]
    first = items[0] if items else None
    ind = "    "
    if first is not None:
        ls = block.rfind("\n", 0, first.start()) + 1
        if not block[ls:first.start()].strip():
            ind = block[ls:first.start()]
    if target is not None:
        attrs, body = re.sub(r'\s+default\s*=\s*"[^"]*"', "", target.group(1), flags=re.I) + ' default="true"', target.group(2)
        for tag, val in (("value", rating), ("votes", votes)):
            if re.search(rf"<{tag}>[^<]*</{tag}>", body, re.I):
                body = re.sub(rf"(<{tag}>)[^<]*(</{tag}>)", rf"\g<1>{val}\2", body, count=1, flags=re.I)
            else:
                body = body.rstrip() + f"{nl}{ind}  <{tag}>{val}</{tag}>{nl}{ind}"
    else:
        attrs = f' name="{source}" max="10" default="true"'
        body = f"{nl}{ind}  <value>{rating}</value>{nl}{ind}  <votes>{votes}</votes>{nl}{ind}"
    head = "".join(out)
    if not head.endswith("\n") and not head.strip() == "":
        head += nl
    tail = rest if rest.strip() == "" and rest else nl + "  "
    new_block = head + ind + f"<rating{attrs}>{body}</rating>" + nl + (tail.lstrip("\r\n") if tail.strip() == "" else tail)
    return content[:m.start(1)] + new_block + content[m.end(1):]


def _rating_source_name(label):                                   ### NEW v0.19.5 B122 ###
    """A rating choice's label → the source's name in <ratings>; None for typed values and an average."""
    low = str(label or "").lower()
    if "average" in low or "typed" in low or "manual" in low:
        return None
    if "tmdb" in low:
        return "themoviedb"
    if "omdb" in low or "imdb" in low:
        return "imdb"
    return None


def _replace_kodi_rating(content, rating, votes):              ### NEW v0.18.4 ###
    """Update <value>/<votes> of the preferred <rating> inside a Kodi v17+
    <ratings> block (default="true", else name="imdb", else first)."""
    m = _KODI_RATINGS_RE.search(content)
    if not m:
        return content
    block = m.group(1)
    items = list(_KODI_RATING_RE.finditer(block))
    if not items:
        return content
    def _score(it):
        attrs = it.group(1)
        return (2 if 'default="true"' in attrs.lower().replace(" ", "") else 0) + \
               (1 if re.search(r'name\s*=\s*"imdb"', attrs, re.I) else 0)
    target = max(items, key=_score)
    body = target.group(2)
    body = re.sub(r'(<value>)[^<]*(</value>)', rf'\g<1>{rating}\2', body, count=1, flags=re.I)
    body = re.sub(r'(<votes>)[^<]*(</votes>)', rf'\g<1>{votes}\2',  body, count=1, flags=re.I)
    new_block = block[:target.start(2)] + body + block[target.end(2):]
    return content[:m.start(1)] + new_block + content[m.end(1):]


def get_movie_titles_from_files(nfo_path, xml_path):
    """
    Return list of unique non-empty movie titles found in NFO and XML.
    NFO: <title>, <originaltitle>
    XML: <LocalTitle>, <OriginalTitle>
    """
    titles = []

    def _extract_text(filepath, tags):
        if not filepath or not os.path.isfile(filepath): return
        try:
            root = _parse_root(filepath)                       ### MODIFIED v0.18.3 ###
            if root is None: return
            for tag in tags:
                el = root.find(tag)
                if el is not None:
                    txt = (el.text or "").strip()
                    if txt and txt not in titles:
                        titles.append(txt)
        except Exception: pass

    _extract_text(nfo_path,  ['title', 'originaltitle'])
    _extract_text(xml_path,  ['LocalTitle', 'OriginalTitle'])
    return titles


def get_primary_titles(nfo_path, xml_path):                    ### NEW v0.18.3 ###
    """
    Return (nfo_title, xml_localtitle) — the two tags that must agree for the
    title_mismatch health rule.  Either is "" when the file or tag is absent.
    Falls back to a regex read when the file does not parse as XML.
    """
    def _one(fp, tag):
        if not fp or not os.path.isfile(fp):
            return ""
        root = _parse_root(fp)
        if root is not None:
            el = root.find(tag)
            return html.unescape((el.text or "").strip()) if el is not None else ""
        m = re.search(rf"<{tag}[^>]*>([^<]+)</{tag}>", _read_text(fp) or "", re.IGNORECASE)
        return html.unescape(m.group(1).strip()) if m else ""
    return _one(nfo_path, "title"), _one(xml_path, "LocalTitle")

