def row_defaults():                                              ### NEW v0.19.4 (B22) — one row builder ###
    """Every key a movie row has, with its 'nothing found' value (fresh lists / dicts each call)."""
    defaults = {
        "video_width": None, "video_height": None, "video_quality": "—",
        "lang_ok": "—", "pt_ok": "—", "backdrop_paths": [],
        "backdrop_avg_bytes": 0,  ### NEW v0.15.0 ###
        "folder_exists": False, "folder_path": "", "folder_bytes": 0,
        "folder_size": "—", "folder_dim": None, "folder_corrupt": False,
        "folder_desc": "", "poster_desc": "", "fanart_desc": "",
        "poster_status": STATUS_MISSING, "fanart_status": STATUS_MISSING,
        "folder_status": STATUS_MISSING,
        "genres": [], "genre_display": "—", "genre_status": STATUS_ERROR,
        "movie_name": "", "movie_year": "-",
        # v0.11.0 — image quality tiers                      ### NEW v0.11.0 ###
        "poster_quality": "—", "folder_quality": "—", "fanart_quality": "—",
        # v0.12.0 — rating                                   ### NEW v0.12.0 ###
        "rating_str": "-", "rating_status": STATUS_MISSING, "rating_value": -1.0,
        "rating_votes": 0, "rating_votes_src": "", "rating_src": "",   ### NEW v0.15.0 ###
        "audio_tracks": [],                                              ### FIX v0.15.0 ###
        # v0.16.0 — votes and source                         ### NEW v0.16.0 ###
        "votes_int": 0, "votes_status": STATUS_MISSING, "votes_src": "",
        "source_imdb_val": None, "source_imdb_status": STATUS_MISSING, "source_imdb_all": [],
        "source_tmdb_val": None, "source_tmdb_status": STATUS_MISSING, "source_tmdb_all": [],
        # v0.18.2 — health engine fields                     ### ADDED_BY_CLAUDE_v18.2 ###
        "health_status": "warning", "health_reasons": [],
        "movie_title_raw": [], "movie_year_raw": None, "ffprobe_ran": False,
        # v0.18.3                                                ### NEW v0.18.3 ###
        "nfo_title": "", "xml_localtitle": "", "scan_mtime": None, "scan_sig": None,   ### scan_sig v0.19.4 B85 ###
        "video_mtime": None, "ffprobe_failed": False,           ### NEW v0.19.4 B86 / B87 ###
        "original_title": "",                                   ### NEW v0.19.3 B60 ###
        "date_added": "", "date_added_src": "",                 ### NEW v0.19.3 B63 ###
        "year_premiered_diff": "",                               ### NEW v0.19.5 B126 ###
        "xml_language": None, "nfo_language": "", "nfo_audio_lang": "", "language_src": "",   ### NEW v0.19.6 TR1 ###
        "xml_on_disk": None, "xml_used": None,                  ### NEW v0.19.6 TR1 — None: not known (a row of an older version) ###
        "nfo_on_disk": None, "nfo_used": None,                  ### NEW v0.19.6 TR1b ###
        "struct_issues": [], "struct_fixable": False,           ### NEW v0.19.3 I8 ###
        "coll_nfo": None, "coll_xml": None, "coll_xml_hint": 0,   ### NEW v0.19.4 B110a ###
        "coll_tmdb": None, "title_langs": [], "tmdb_titles": {},
        # v0.18.4                                                ### NEW v0.18.4 ###
        "health_errors": [], "health_warnings": [], "duplicate_of": [],
        # v0.19.0 — image facts (None = not probed by this version) ### NEW v0.19.0 ###
        "poster_format": None, "poster_decode_ok": None, "poster_mismatch": False, "poster_flags": {},
        "folder_format": None, "folder_decode_ok": None, "folder_mismatch": False, "folder_flags": {},
        "fanart_format": None, "fanart_decode_ok": None, "fanart_mismatch": False, "fanart_flags": {},
        "id_check": None,                                       ### NEW v0.19.0 ###
        "genre_source": "", "genre_only_in_xml": False,          ### NEW v0.19.1 ###
        "genre_only_in_nfo": False, "genre_nfo_wrong_tags": False,
    }
    # ### NEW v0.19.2 B27 ### — every other key a fresh scan row has, with the
    # "nothing found" values of the scan's stub row, so a row cached by an older
    # version (or the self-test's legacy "OldRow") never raises KeyError in the
    # table / stats code (it showed as "KeyError: 'poster_exists'" in a Tk callback).
    for _k in ("poster", "fanart"):
        defaults.update({f"{_k}_exists": False, f"{_k}_path": "", f"{_k}_bytes": 0, f"{_k}_size": "—",
                         f"{_k}_dim": None, f"{_k}_corrupt": False, f"{_k}_style": "plain", f"{_k}_tried": []})
    defaults.update({"folder_style": "plain", "folder_tried": [], "art_style": "plain", "backdrop_count": 0})
    return defaults


def _results_from_json(data):
    defaults = row_defaults()                                    # v0.19.4 (B22)
    for _k in ("nfo", "xml"):
        defaults.update({f"{_k}_exists": False, f"{_k}_path": "", f"{_k}_bytes": 0, f"{_k}_size": "—",
                         f"{_k}_status": STATUS_MISSING, f"{_k}_errors": [], f"{_k}_infos": []})
    defaults.update({
        "nfo_kodi_name": True, "language": "—",
        "video_count": 0, "video_files": [], "video_ext": "—", "video_path": None,
        "video_bytes": 0, "video_size": "—", "video_status": STATUS_MISSING,
        "subs_external": [], "subs_internal": [], "subs_hard": [], "subs_summary": "None",
        "source_imdb_empty": False, "source_tmdb_empty": False,
        "source_imdb_invalid": [], "source_tmdb_invalid": [],   # v0.20.0 RD11
        "source_id_links": {},                                   # v0.20.1 T1
        "nfo_kodi_id_missing": [], "nfo_premiered_year": None,   ### NEW v0.20.0 KR1.1 / KR1.2 ###
        "nfo_art_links": [],                                     ### NEW v0.20.0 RD9 ###
        "xml_reader_gaps": [],                                   ### NEW v0.20.0 KR1.4 ###
        # v0.19.2 F5 — naming intelligence                    ### NEW v0.19.2 F5 ###
        "nfo_all": [], "nfo_all_differ": False, "xml_notes": [], "art_notes": [], "extra_art": [], "extra_dirs": [],
        "actors_state": "", "actors_counts": {}, "actors_mismatch": [], "actors_orphans": [], "actors_dir": "",   # v0.20.1 AC1 ("" = not read yet)
        "has_extrafanart": None,                                 # v0.20.1 EA: None = not read yet (the tool looks on disk)
        "extra_art_alpha": {},                                                                       # v0.20.1 EA2
        "video_kinds": {}, "video_group": None,
        "poster_servers": None, "fanart_servers": None, "folder_servers": None,   # None = not known (no tooltip line)
        "coll_nfo": None, "coll_xml": None, "coll_xml_hint": 0, "coll_tmdb": None, "title_langs": [],   ### NEW v0.19.4 B110a ###
        "coll_xml_read": 0,                                                                         ### NEW v0.19.4 fix 6 ###
        "tmdb_titles": {},                                                                          ### NEW v0.19.4 B110f ###
        "cert_tags": {},                                                                            ### NEW v0.20.2 CR (read at the start-up re-read) ###
        "backdrop_videos": None,                                    ### NEW v0.20.2 FB1 — None = not counted yet (backdrop_videos_of) ###
    })
    _mutable = [k for k, v in defaults.items() if isinstance(v, (list, dict))]   ### NEW v0.19.2 B27 ###
    out = []
    for r in data:
        row = dict(defaults)
        row.update(r)
        if "coll_nfo" not in r:                                 ### NEW v0.19.4 B110a — cached before B110: read at the restore (fix 1) or the next scan ###
            row["coll_unread"] = True
        if "cert_tags" not in r and (r.get("nfo_exists") or r.get("xml_exists")):   ### NEW v0.20.2 CR — read at the start-up re-read ###
            row["tags_unread"] = True
        elif r.get("xml_exists") and not r.get("coll_xml_read"):  ### NEW v0.19.4 fix 6 — movie.xml collection not read yet ###
            row["coll_unread"] = True
        for _k in _mutable:                                     ### NEW v0.19.2 B27 — no list shared between rows ###
            if _k not in r:
                row[_k] = type(defaults[_k])()
        # Migrate old pt_ok → lang_ok if needed
        if "pt_ok" in row and "lang_ok" not in row:
            row["lang_ok"] = row["pt_ok"]
        row["library_root"] = _norm_lib(row.get("library_root")             ### MODIFIED v0.19.1 — normpath ###
                                        or os.path.dirname(row.get("subfolder_path") or ""))
        out.append(row)
    return out

# (v0.19.4 P9: the old SORT_OPTIONS table is gone — sort_engine.py builds every sort since v0.19.3)


### NEW v0.19.3 B63 — one typed value per sort key (None = empty, sorted last) ###
from functools import lru_cache as _lru_cache                     # v0.19.3 I4
_STATUS_RANK = {STATUS_OK: 0, STATUS_WARN: 1, STATUS_MISSING: 2, STATUS_ERROR: 3}


def _sv_text(v):
    t = str(v or "").strip()
    if t in ("", "—", "-"):
        return None
    if t.isascii():                                              # v0.19.3 I4 — the common case, 10× faster
        return t.casefold()
    return _sv_fold(t)


@_lru_cache(maxsize=1 << 16)
def _sv_fold(t):
    """Accent-free, case-free text (cached: a 10,000-row sort asks twice per row)."""
    import unicodedata
    t = unicodedata.normalize("NFKD", t)
    return "".join(c for c in t if not unicodedata.combining(c)).casefold()


def _sv_year(r):
    y = str(r.get("movie_year") or "")[:4]
    return int(y) if y.isdigit() else None


def _sv_quality(fn, field):
    def f(r, d):
        v = fn(r, field, True)
        return None if v == 9999 else v
    return f


def _sv_votes(r, d):
    v = r.get("votes_int") or 0
    return None if (not v and r.get("votes_status") in (STATUS_MISSING, None)) else int(v)


def _sv_rating(r, d):
    v = r.get("rating_value")
    if v is None or r.get("rating_status") == STATUS_MISSING or v < 0:
        return None
    return float(v)


def _sv_subs(r, d):
    has = bool(r.get("subs_internal") or r.get("subs_external") or r.get("subs_hard"))
    return (1 if has else 0, _sv_text(r.get("subs_summary")) or "")


def _sv_actors(r, d):                                            ### NEW v0.20.2 B25 — was the cell text ###
    """Actors: no info < links < local photos, then local photos, then the actors in the NFO; not read = empty."""
    st = r.get("actors_state")
    if not st:
        return None
    c = r.get("actors_counts") or {}
    return ({"none": 0, "links": 1, "local": 2}.get(st, 0), int(c.get("local") or 0), int(c.get("total") or 0))


def _sv_health(r, d):
    order = {"errors": ("error", "warning", "ok"), "warnings": ("warning", "error", "ok"),
             "ok": ("ok", "warning", "error")}.get(d, ("error", "warning", "ok"))
    st = r.get("health_status", "warning")
    return order.index(st) if st in order else 1


SORT_VALUE_FNS = {
    "movie_name": lambda r, d: _sv_text(r.get("movie_name") or r.get("subfolder")),
    "year":       lambda r, d: _sv_year(r),
    "genre":      lambda r, d: _sv_text(r.get("genre_display")),
    "rating":     _sv_rating,
    "votes":      _sv_votes,
    "source":     lambda r, d: max(_STATUS_RANK.get(r.get("source_imdb_status"), 2),
                                   _STATUS_RANK.get(r.get("source_tmdb_status"), 2)),
    "poster":     _sv_quality(_poster_quality_sort_key_missing_last, "poster_quality"),
    "folder":     _sv_quality(_poster_quality_sort_key_missing_last, "folder_quality"),
    "fanart":     _sv_quality(_fanart_quality_sort_key_missing_last, "fanart_quality"),
    "backdrops":  lambda r, d: backdrop_total(r),                    # v0.20.2 FB1: the main fanart counts
    "nfo":        lambda r, d: _STATUS_RANK.get(r.get("nfo_status"), 2),
    "xml":        lambda r, d: _STATUS_RANK.get(r.get("xml_status"), 2),
    "language":   lambda r, d: _sv_text(r.get("language")),
    "vid_ext":    lambda r, d: _sv_text(r.get("video_ext")),
    "vid_size":   lambda r, d: int(r.get("video_bytes") or 0) or None,
    "quality":    lambda r, d: (None if (r.get("video_quality") or "—") == "—" else _quality_sort_key(r.get("video_quality"))),
    "audio":      lambda r, d: _sv_text(", ".join(t.get("language", "") for t in (r.get("audio_tracks") or []))),
    "lang_ok":    lambda r, d: {"Y": 1, "N": 0}.get(r.get("lang_ok")),
    "subs":       _sv_subs,
    "library":    lambda r, d: _sv_text(r.get("library_root")),
    "collection": lambda r, d: _sv_text(collection_name(r)),           ### NEW v0.19.4 B110a ###
    "actors": _sv_actors,                                           ### NEW v0.20.1 AC1; v0.20.2 B25 ###
    "extra_art": lambda r, d: extra_info(r)["count"],                 ### NEW v0.20.1 EA4 ###
    "health":     _sv_health,
    "issues":     lambda r, d: len(r.get("health_reasons") or []),
    "date_added": lambda r, d: r.get("date_added") or None,
}


def _sort_name_key(r):
    return _sv_text(r.get("movie_name") or r.get("subfolder")) or ""


def group_order(spec):                                           ### NEW v0.19.5 B118 ###
    """What _cr.group_rows needs when the first sort level is a text column; None for any other column
    (a collection row then stays where its first movie sits, B110.10)."""
    levels = _se.clean_spec(spec)
    if not levels:
        return None
    lvl = levels[0]
    fn = SORT_VALUE_FNS.get(lvl["key"])
    if fn is None or {c[0]: c[2] for c in _se.COLUMNS}.get(lvl["key"]) != "text":
        return None
    d = lvl["dir"]
    return {"movie": lambda r: fn(r, d), "name": lambda n: _sv_text(n) or "", "reverse": d == "desc",
            "empty_first": lvl.get("empty") == "first"}


def _sort_year_key(r):
    return _sv_year(r) or 0


def sort_labels():
    """Key → label, with the Lang OK? column named after the target language."""
    lab = dict(_se.LABEL)
    lab["lang_ok"] = lang_ok_heading(SETTINGS.get("lang_ok_code", "PT"))   # v0.20.0 UI1c
    return lab


def sort_spec_from_settings(settings):                           ### NEW v0.19.3 B63 ###
    """The saved sort; on the first v0.19.3 start, the old sort_option."""
    if "b63_sort_spec" not in (settings.get("settings_migrations") or []):
        spec = _se.spec_from_old(settings.get("sort_option"))
        settings["sort_spec"] = spec
        settings["settings_migrations"] = list(settings.get("settings_migrations") or []) + ["b63_sort_spec"]
        return spec
    return _se.clean_spec(settings.get("sort_spec"))


# ══════════════════════════════════════════════════════════════════════════════
# Improvements engine
# ══════════════════════════════════════════════════════════════════════════════

def run_improvements(data_list, checks=None):
    """
    Run all enabled improvement checks on a list of row dicts.
    Returns a list of (movie_name, [issue_string, ...]) tuples.
    """
    if checks is None:
        checks = SETTINGS.get("improve_checks", _DEFAULT_SETTINGS["improve_checks"])

    max_xml_kb  = SETTINGS.get("max_xml_kb",  25)
    max_nfo_kb  = SETTINGS.get("max_nfo_kb",  50)
    min_bk      = SETTINGS.get("health_rules", {}).get("backdrop_min_count", 5)  ### MODIFIED_BY_CLAUDE_v18.2 ###
    tag_pairs   = SETTINGS.get("tag_pairs") or DEFAULT_TAG_PAIRS

    results = []
    for d in data_list:
        issues = []
        _unk = []                                               ### NEW v0.19.5 B127 — codec names not in the table ###
        name = d.get("movie_name", d["subfolder"])  ### NEW v0.10.0 — use movie_name ###

        # ── 2.1  Large XML ────────────────────────────────────────────────────
        if checks.get("large_xml", True):
            if d["xml_exists"] and d["xml_bytes"] > max_xml_kb * 1024:
                issues.append(
                    _i18n.t("uf.large_xml_movie_xml_9e6e", v=d['xml_bytes']//1024, max_xml_kb=max_xml_kb))
            if d["nfo_exists"] and d["nfo_bytes"] > max_nfo_kb * 1024:
                issues.append(
                    _i18n.t("uf.large_nfo_is_kb_99d3", nfo_path=os.path.basename(d['nfo_path']), v=d['nfo_bytes']//1024, max_nfo_kb=max_nfo_kb))

        # ── 2.2  NFO ↔ XML mismatch ───────────────────────────────────────────
        if checks.get("nfo_xml_diff", True) and d["nfo_exists"] and d["xml_exists"]:
            nfo_root = _parse_xml_to_dict(d["nfo_path"])
            xml_root = _parse_xml_to_dict(d["xml_path"])
            if nfo_root is not None and xml_root is not None:
                for nfo_path_str, xml_path_str, label, tol in tag_pairs:
                    # Special handling for id with moviedb attribute
                    if nfo_path_str.startswith("id") and "moviedb" in nfo_path_str:
                        pass  # handled below
                    # Get NFO values
                    nfo_vals = _xpath_get(nfo_root, nfo_path_str)
                    # Special: <id moviedb="imdb"> and <id moviedb="tmdb">
                    if not nfo_vals and nfo_path_str == "id":
                        nfo_vals = [v for el in nfo_root.iter('id')
                                    if not el.get('moviedb')
                                    for v in [(el.text or "").strip()] if v]
                    # Get XML values
                    xml_vals = _xpath_get(xml_root, xml_path_str)
                    if not nfo_vals or not xml_vals: continue
                    if nfo_path_str.lower().endswith("codec") or xml_path_str.lower().endswith("codec"):   ### NEW v0.19.5 B127 ###
                        _unk += unknown_codecs(nfo_vals, xml_vals)
                        if not codecs_differ(nfo_vals, xml_vals):
                            continue
                    elif not _vals_match(nfo_vals, xml_vals, tol):
                        pass
                    else:
                        continue
                    if True:
                        nv = ", ".join(nfo_vals[:3])
                        xv = ", ".join(xml_vals[:3])
                        issues.append(
                            _i18n.t("uf.nfo_xml_mismatch_nfo_01cb", label=label, nv=nv, xv=xv))

                # Check XML standalone tags vs MediaInfo block
                for standalone, mi_path, mi_label, mi_tol in XML_INTERNAL_PAIRS:
                    sa_vals = _xpath_get(xml_root, standalone)
                    mi_vals = _xpath_get(xml_root, mi_path)
                    if not sa_vals or not mi_vals: continue
                    if standalone.lower().endswith("codec"):            ### NEW v0.19.5 B127 ###
                        _unk += unknown_codecs(sa_vals, mi_vals)
                        _diff = codecs_differ(sa_vals, mi_vals)
                    else:
                        _diff = not _vals_match(sa_vals, mi_vals, mi_tol)
                    if _diff:
                        sv = ", ".join(sa_vals[:2]); mv = ", ".join(mi_vals[:2])
                        issues.append(
                            _i18n.t("uf.xml_internal_standalone_vs_2ab5", mi_label=mi_label, sv=sv, mv=mv))

        # ── 2.3  FFprobe vs NFO/XML ───────────────────────────────────────────
        if (checks.get("ffprobe_diff", True) and d.get("video_path") and
                d["video_width"] and d["video_height"] and
                _ffprobe_enabled()):
            probe = _get_ffprobe_full(d["video_path"])
            if probe:
                streams = probe.get("streams", [])
                v_streams = [s for s in streams if s.get("codec_type") == "video"
                             and (s.get("disposition") or {}).get("attached_pic") != 1]   # v0.20.0 AU16: not cover art
                a_streams = [s for s in streams if s.get("codec_type") == "audio"]
                fmt       = probe.get("format", {})

                if v_streams:
                    vst = v_streams[0]
                    fp_w = vst.get("width"); fp_h = vst.get("height")
                    fp_dur = float(fmt.get("duration", 0) or 0)
                    fp_codec = (vst.get("codec_name") or "").lower()

                    # Compare with NFO fileinfo
                    if d["nfo_exists"]:
                        nfo_root = _parse_xml_to_dict(d["nfo_path"])
                        if nfo_root is not None:
                            nfo_w = _xpath_get(nfo_root, "fileinfo.streamdetails.video.width")
                            nfo_h = _xpath_get(nfo_root, "fileinfo.streamdetails.video.height")
                            nfo_dur = _xpath_get(nfo_root, "fileinfo.streamdetails.video.durationinseconds")
                            nfo_codec = _xpath_get(nfo_root, "fileinfo.streamdetails.video.codec")
                            if fp_w and nfo_w:
                                if not _vals_match(nfo_w, [str(fp_w)], 0):
                                    issues.append(
                                        _i18n.t("uf.ffprobe_vs_nfo_video_ddcd", fp_w=fp_w, v=nfo_w[0]))
                            if fp_h and nfo_h:
                                if not _vals_match(nfo_h, [str(fp_h)], 0):
                                    issues.append(
                                        _i18n.t("uf.ffprobe_vs_nfo_video_17e8", fp_h=fp_h, v=nfo_h[0]))
                            if fp_dur and nfo_dur:
                                if not _vals_match(nfo_dur, [str(int(fp_dur))], 5):
                                    issues.append(
                                        _i18n.t("uf.ffprobe_vs_nfo_duration_ee89", fp_dur=int(fp_dur), v=nfo_dur[0]))
                            if fp_codec and nfo_codec:                  ### MODIFIED v0.19.5 B127 ###
                                _unk += unknown_codecs([fp_codec], nfo_codec)
                                if codecs_differ([fp_codec], nfo_codec):
                                    issues.append(
                                        _i18n.t("uf.ffprobe_vs_nfo_video_173a", fp_codec=fp_codec, v=nfo_codec[0]))
                            ### NEW v0.19.5 B127 ### every audio track
                            _a_nfo = _xpath_get(nfo_root, "fileinfo.streamdetails.audio.codec")
                            _a_fp = [s.get("codec_name") for s in a_streams if s.get("codec_name")]
                            if _a_nfo and _a_fp:
                                _unk += unknown_codecs(_a_fp, _a_nfo)
                                if codecs_differ(_a_fp, _a_nfo):
                                    issues.append(_i18n.t("uf.ffprobe_vs_nfo_audio_126d", join=', '.join(_a_fp[:4]), join2=', '.join(_a_nfo[:4])))

                    if d["xml_exists"] and v_streams:
                        xml_root = _parse_xml_to_dict(d["xml_path"])
                        if xml_root is not None:
                            xml_w = _xpath_get(xml_root, "VideoWidth") or _xpath_get(xml_root, "MediaInfo.Video.Width")
                            xml_h = _xpath_get(xml_root, "VideoHeight") or _xpath_get(xml_root, "MediaInfo.Video.Height")
                            xml_dur = _xpath_get(xml_root, "MediaInfo.Video.DurationSeconds") or _xpath_get(xml_root, "VideoLengthSeconds")
                            if fp_w and xml_w:
                                if not _vals_match(xml_w, [str(fp_w)], 0):
                                    issues.append(
                                        _i18n.t("uf.ffprobe_vs_xml_video_f92e", fp_w=fp_w, v=xml_w[0]))
                            if fp_h and xml_h:
                                if not _vals_match(xml_h, [str(fp_h)], 0):
                                    issues.append(
                                        _i18n.t("uf.ffprobe_vs_xml_video_d7c5", fp_h=fp_h, v=xml_h[0]))
                            if fp_dur and xml_dur:
                                if not _vals_match(xml_dur, [str(int(fp_dur))], 5):
                                    issues.append(
                                        _i18n.t("uf.ffprobe_vs_xml_duration_e332", fp_dur=int(fp_dur), v=xml_dur[0]))
                            ### NEW v0.19.5 B127 ### the XML's video codec and every audio track
                            _v_xml = _xpath_get(xml_root, "MediaInfo.Video.Codec") or _xpath_get(xml_root, "VideoCodec")
                            if fp_codec and _v_xml:
                                _unk += unknown_codecs([fp_codec], _v_xml)
                                if codecs_differ([fp_codec], _v_xml):
                                    issues.append(_i18n.t("uf.ffprobe_vs_xml_video_a38e", fp_codec=fp_codec, v=_v_xml[0]))
                            _a_xml = _xpath_get(xml_root, "MediaInfo.Audio.Codec") or _xpath_get(xml_root, "AudioCodec")
                            _a_fp = [s.get("codec_name") for s in a_streams if s.get("codec_name")]
                            if _a_fp and _a_xml:
                                _unk += unknown_codecs(_a_fp, _a_xml)
                                if codecs_differ(_a_fp, _a_xml):
                                    issues.append(_i18n.t("uf.ffprobe_vs_xml_audio_6898", join=', '.join(_a_fp[:4]), join2=', '.join(_a_xml[:4])))

        if _unk:                                                ### NEW v0.19.5 B127 — not a problem; so the table can grow ###
            issues.append(_i18n.t("uf.codec_name_not_recognized_db7e") + ", ".join(sorted(set(_unk))) + " (not compared)")

        # ── 2.4  poster.jpg vs folder.jpg different sizes ─────────────────────
        if checks.get("poster_folder", True):
            if d["poster_exists"] and d["folder_exists"]:
                pw, ph = get_image_wh(d["poster_path"])
                fw, fh = get_image_wh(d["folder_path"])
                if pw and ph and fw and fh:
                    if pw != fw or ph != fh:
                        issues.append(
                            _i18n.t("uf.image_size_poster_jpg_ad94", pw=pw, ph=ph, fw=fw, fh=fh))
                if abs(d["poster_bytes"] - d["folder_bytes"]) > 1024:
                    issues.append(
                        _i18n.t("uf.image_size_poster_jpg_6524", format_size=format_size(d['poster_bytes']), format_size2=format_size(d['folder_bytes'])))

        # ── 2.5  Proportions & file size ─────────────────────────────────────
        if checks.get("proportions", True):
            for img_type, exists, path, sz, desc in [
                ("poster",  d["poster_exists"],  d["poster_path"],  d["poster_bytes"],  d.get("poster_desc","")),
                ("folder",  d["folder_exists"],  d["folder_path"],  d["folder_bytes"],  d.get("folder_desc","")),
                ("fanart",  d["fanart_exists"],  d["fanart_path"],  d["fanart_bytes"],  d.get("fanart_desc","")),
            ]:
                if exists and desc:
                    issues.append(f"[Image Quality] {os.path.basename(path)}: {desc}")

        # ── 2.6  Minimum backdrops ────────────────────────────────────────────
        if checks.get("backdrops", True):
            bc = backdrop_total(d)                                   ### MODIFIED v0.20.2 FB1 — the main fanart counts ###
            if bc < min_bk:
                issues.append(
                    _i18n.t("uf.backdrops_only_found_minimum_9e9f", n=_n(bc, 'backdrop'), min_bk=min_bk))

        if issues:
            results.append((name, issues))

    return results

def format_improvements_report(results, error_rows=None):
    """
    Format improvements results as a readable text report.
    error_rows: list of (movie_name, [error_string, ...]) for scan errors — shown in red.
    """
    if not results and not error_rows:
        return _i18n.t("rp.ok_no_improvements_needed_9e7a")
    lines = []
    if results:
        lines.append(_i18n.t("rp.improvement_report_with_findings_c0b0", n=_n(len(results), 'movie')))
        lines.append("=" * 60 + "\n")
        for name, issues in results:
            lines.append(f"\n📁  {name}\n")
            lines.append("─" * 50 + "\n")
            for iss in issues:
                lines.append(f"  • {iss}\n")
        lines.append("\n" + "=" * 60 + "\n")
        lines.append(_i18n.t("rp.total_improvement_issues_5177", sum=sum(len(v) for _, v in results)))
    else:
        lines.append(_i18n.t("rp.ok_no_improvement_issues_cac8"))

    # Append scan errors (item 3)
    if error_rows:
        lines.append("\n" + "=" * 60 + "\n")
        lines.append(_i18n.t("rp.scan_errors_in_0cc9", n=_n(sum(len(v) for _, v in error_rows), 'error'), n2=_n(len(error_rows), 'movie')))
        lines.append("=" * 60 + "\n")
        for name, errs in error_rows:
            lines.append(f"\n📁  {name}\n")
            lines.append("─" * 50 + "\n")
            for err in errs:
                lines.append(f"  ✖ {err}\n")

    return "".join(lines)

