# Frame extraction helpers
# ══════════════════════════════════════════════════════════════════════════════

def get_video_duration(video_path, cancel=None):               ### UPDATED v0.17.0 — MP4/MKV fallback; cancel v0.19.2 B28 ###
    """
    Return video duration in seconds, or None on failure.
    Step 1: Standard JSON format probe.
    Step 2 (MP4/MKV): format=duration plain text.
    Step 3 (MP4/MKV): first video stream duration.
    Step 4 (MP4/MKV): estimate from frame count + frame rate.
    Returns (duration_float, estimated:bool).
    Callers that only need a float may use the first element.
    """
    if not _ffprobe_enabled(): return None, False

    ext = os.path.splitext(video_path)[1].lower()

    def _run(cmd, timeout=20):                                 ### MODIFIED v0.19.2 B28 — runner: priority, cancel ###
        if cancel and cancel():
            return "", -1
        status, rc, out, _err = _run_ffmpeg(cmd, timeout, cancel)
        return (out.strip(), rc) if status == FF_OK else ("", -1)

    # Step 1 — JSON format probe (all containers) — the one cached probe (v0.19.1 I5)
    _pj = _probe_json(video_path, True)
    if _pj:
        try:
            dur = float((_pj.get("format") or {}).get("duration", 0) or 0)
            if dur > 0:
                return dur, False
        except Exception:
            pass

    # Steps 2-4 only attempted for MP4 and MKV
    if ext not in (".mp4", ".mkv"):
        return None, False

    # Step 2 — plain-text format duration
    out, rc = _run([FFPROBE_PATH, "-v", "quiet",
                    "-show_entries", "format=duration",
                    "-of", "default=noprint_wrappers=1:nokey=1",
                    video_path])
    if rc == 0 and out:
        try:
            dur = float(out.split()[0])
            if dur > 0:
                return dur, False
        except Exception:
            pass

    # Step 3 — first video stream duration
    out, rc = _run([FFPROBE_PATH, "-v", "quiet",
                    "-select_streams", "v:0",
                    "-show_entries", "stream=duration",
                    "-of", "default=noprint_wrappers=1:nokey=1",
                    video_path])
    if rc == 0 and out:
        try:
            dur = float(out.split()[0])
            if dur > 0:
                return dur, False
        except Exception:
            pass

    # Step 4 — estimate from nb_frames / r_frame_rate
    out, rc = _run([FFPROBE_PATH, "-v", "quiet",
                    "-select_streams", "v:0",
                    "-show_entries", "stream=nb_frames,r_frame_rate",
                    "-of", "csv=p=0",
                    video_path])
    if rc == 0 and out:
        try:
            parts = [p.strip() for p in out.split(",") if p.strip()]
            # csv output: nb_frames,r_frame_rate  (may be on separate lines)
            if len(parts) >= 2:
                nb_frames = int(parts[0])
                fps_parts = parts[1].split("/")
                if len(fps_parts) == 2:
                    fps = float(fps_parts[0]) / float(fps_parts[1])
                else:
                    fps = float(fps_parts[0])
                if nb_frames > 0 and fps > 0:
                    return nb_frames / fps, True
        except Exception:
            pass

    # Step 5 — try NFO <runtime> or XML <RunningTime> as last resort
    try:
        sub_dir = os.path.dirname(video_path)
        sub_name = os.path.basename(sub_dir)
        nfo_path = resolve_nfo(_FolderListing(sub_dir), sub_name)[0]   ### MODIFIED v0.19.1 B23 ###
        xml_path = os.path.join(sub_dir, "movie.xml")
        runtime_min = None
        for fpath, tag in [(nfo_path, "runtime"), (xml_path, "RunningTime")]:
            if os.path.isfile(fpath):
                with open(fpath, "r", encoding="utf-8", errors="replace") as f:
                    content = f.read(65536)
                m = re.search(rf"<{tag}[^>]*>([0-9]+)</{tag}>", content, re.IGNORECASE)
                if m:
                    runtime_min = int(m.group(1))
                    break
        if runtime_min and runtime_min > 0:
            return float(runtime_min * 60), True
    except Exception:
        pass

    # All steps failed — return sentinel so caller can use a default estimate
    return None, False

# ── v0.19.2 B28: one FFmpeg / FFprobe runner ─────────────────────────────────  ### NEW v0.19.2 B28 ###
# Frame extraction could hang for minutes on a damaged file or a slow NAS, at
# normal priority with every CPU thread, and closing the dialog did not stop
# it.  Every frame / duration call now goes through _run_ffmpeg: background
# priority, a poll every 0.2 s for cancel and the deadline (kill on either),
# and a registry so every process is killed when the app closes.
FF_OK, FF_TIMEOUT, FF_CANCELLED, FF_ERROR = "ok", "timeout", "cancelled", "error"
_FF_CFLAGS = getattr(subprocess, "CREATE_NO_WINDOW", 0) | getattr(subprocess, "BELOW_NORMAL_PRIORITY_CLASS", 0)
_FF_PROCS = set()
_FF_PROCS_LOCK = threading.Lock()
_FF_TIMEOUT_TEXT = "Extraction timed out after"


def _proc_cpu_seconds(p):                                       ### NEW v0.19.3 B62 ###
    """CPU time (user + kernel, seconds) a child process has used, or None."""
    if os.name != "nt":
        return None
    try:
        import ctypes
        from ctypes import wintypes
        c, e, k, u = (wintypes.FILETIME() for _ in range(4))
        if not ctypes.windll.kernel32.GetProcessTimes(wintypes.HANDLE(int(p._handle)), ctypes.byref(c),
                                                      ctypes.byref(e), ctypes.byref(k), ctypes.byref(u)):
            return None
        val = lambda ft: (ft.dwHighDateTime << 32 | ft.dwLowDateTime) / 1e7
        return val(k) + val(u)
    except Exception:
        return None


FF_HUNG = "hung"                                                ### NEW v0.19.3 B62 ###


def _run_ffmpeg(cmd, timeout=None, cancel=None, priority=None, hung_after=None):
    """Worker threads only.  Runs *cmd*; returns (status, returncode, stdout,
    stderr) with status FF_OK / FF_TIMEOUT / FF_CANCELLED / FF_ERROR.
    *cancel* is a plain callable (no Tk) checked every 0.2 s.
    ### NEW v0.19.3 B62 ### priority="idle" runs it at IDLE priority (default
    BELOW_NORMAL); hung_after=N stops it with FF_HUNG when it used no CPU
    for N seconds (a hung process)."""
    flags = _FF_CFLAGS
    if priority == "idle":
        flags = getattr(subprocess, "CREATE_NO_WINDOW", 0) | getattr(subprocess, "IDLE_PRIORITY_CLASS", 0)
    try:
        p = subprocess.Popen(cmd, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
                             stderr=subprocess.PIPE, creationflags=flags)
    except Exception as e:
        return FF_ERROR, -1, "", str(e)
    with _FF_PROCS_LOCK:
        _FF_PROCS.add(p)
    deadline = (time.monotonic() + timeout) if timeout else None
    status = FF_OK
    cpu_last, cpu_since = None, time.monotonic()                ### v0.19.3 B62 — hung check ###
    try:
        while True:
            try:
                out, err = p.communicate(timeout=0.2)
                break
            except subprocess.TimeoutExpired:
                hung = False
                if hung_after:
                    cpu = _proc_cpu_seconds(p)
                    if cpu is not None and (cpu_last is None or cpu > cpu_last + 0.01):
                        cpu_last, cpu_since = cpu, time.monotonic()
                    hung = cpu is not None and time.monotonic() - cpu_since > hung_after
                if cancel and cancel():
                    status = FF_CANCELLED
                elif deadline is not None and time.monotonic() > deadline:
                    status = FF_TIMEOUT
                elif hung:
                    status = FF_HUNG
                else:
                    continue
                try:
                    p.kill()
                except OSError:
                    pass
                out, err = p.communicate()
                break
    finally:
        with _FF_PROCS_LOCK:
            _FF_PROCS.discard(p)
    dec = lambda b: (b or b"").decode("utf-8", "replace")
    return status, p.returncode, dec(out), dec(err)


def kill_all_ffmpeg():                                          ### NEW v0.19.2 B28 ###
    """Kill every FFmpeg / FFprobe the runner started (app close, atexit)."""
    with _FF_PROCS_LOCK:
        procs = list(_FF_PROCS)
    for p in procs:
        try:
            p.kill()
        except OSError:
            pass
    return len(procs)


atexit.register(kill_all_ffmpeg)


def _ff_frame_timeout():                                        ### NEW v0.19.2 B28 ###
    try:
        return max(5, int(SETTINGS.get("ffmpeg_frame_timeout_sec", 20)))
    except (TypeError, ValueError):
        return 20


def _ff_run_budget():                                           ### NEW v0.19.2 B28 ###
    try:
        return max(30, int(SETTINGS.get("ffmpeg_run_budget_sec", 180)))
    except (TypeError, ValueError):
        return 180


def _fmt_mmss(sec):                                             ### NEW v0.19.2 B28 ###
    sec = max(0, int(sec or 0))
    return f"{sec // 60}:{sec % 60:02d}"


def extract_single_frame(video_path, time_sec, output_path, timeout_sec=60, cancel=None, keyframes=False):
    """One frame of *video_path* at *time_sec* → *output_path* (JPEG).
    ### MODIFIED v0.19.2 B28 ### through _run_ffmpeg (background priority,
    cancel, timeout kill), 2 threads, no audio/subtitle/data decoding.
    keyframes=True (the B11 frame grid) decodes key frames only — much lighter
    on a network share; a video without a key frame near that time falls back
    to the exact frame.  Returns (ok, error_text)."""
    if not FFMPEG_PATH: return False, "FFmpeg not found"
    base = [FFMPEG_PATH, "-nostdin", "-hide_banner", "-loglevel", "error", "-y", "-threads", "2"]
    tail = ["-ss", str(time_sec), "-i", video_path, "-an", "-sn", "-dn", "-frames:v", "1"]
    attempts = []
    if keyframes:   # yuvj420p: the key-frame path hands the JPEG encoder limited-range YUV otherwise
        attempts.append(base + ["-skip_frame", "nokey"] + tail + ["-pix_fmt", "yuvj420p", "-q:v", "1", output_path])
    attempts.append(base + tail + ["-q:v", "1", output_path])
    last = ""
    for cmd in attempts:
        status, rc, _out, err = _run_ffmpeg(cmd, timeout_sec, cancel)
        if status == FF_TIMEOUT:
            return False, f"{_FF_TIMEOUT_TEXT} {timeout_sec}s"
        if status == FF_CANCELLED:
            return False, "Cancelled"
        if status == FF_ERROR:
            return False, err
        if rc == 0 and os.path.isfile(output_path) and os.path.getsize(output_path) > 0:
            return True, ""
        last = (err or "")[-300:].strip() or f"FFmpeg exit {rc}"
    return False, last

