# Dialogs
# ══════════════════════════════════════════════════════════════════════════════

# ══════════════════════════════════════════════════════════════════════════════
# Window size / position memory (v0.19.0)                      ### NEW v0.19.0 ###
# ══════════════════════════════════════════════════════════════════════════════
# SETTINGS["window_geometry"] = {window_id: {"geometry": "WxH+X+Y", "zoomed": bool}}
# One helper for the main window and every dialog: _remember_window(win, id).
# It is called AFTER the window's own sizing/centring code, so the saved
# position wins and centring is only the first-time default.  Non-resizable
# dialogs restore their position only.  <Configure> is debounced (400 ms) and
# only updates the in-memory setting; settings.json is written once when the
# window closes (through the normal _save_settings).  Restored geometry is
# clamped to the visible (virtual) screen so a removed monitor or a changed
# DPI never leaves a window off-screen.  Transient/grab behaviour untouched.

_GEOM_RE = re.compile(r"^(\d+)x(\d+)([+-]\d+)([+-]\d+)$")


def _virtual_screen(win):
    """(x, y, w, h) of the whole desktop: all monitors on Windows (ctypes),
    the Tk screen size elsewhere."""
    if os.name == "nt":
        try:
            import ctypes
            u = ctypes.windll.user32
            x, y, w, h = (u.GetSystemMetrics(76), u.GetSystemMetrics(77),
                          u.GetSystemMetrics(78), u.GetSystemMetrics(79))
            if w > 0 and h > 0:
                return x, y, w, h
        except Exception:
            pass
    try:
        return 0, 0, win.winfo_screenwidth(), win.winfo_screenheight()
    except Exception:
        return 0, 0, 1920, 1080


def _norm_lib(path):                                            ### NEW v0.19.1 ###
    """Windows-style library path (z:/film_kids → z:\\film_kids); '' stays ''."""
    path = (path or "").strip()
    return os.path.normpath(path) if path else ""


def _clamp_geometry(geom, win):
    """Return a 'WxH+X+Y' string guaranteed to be at least partly visible, or
    None when *geom* is not a geometry string."""
    m = _GEOM_RE.match(str(geom or "").strip())
    if not m:
        return None
    w, h, x, y = int(m.group(1)), int(m.group(2)), int(m.group(3)), int(m.group(4))
    vx, vy, vw, vh = _virtual_screen(win)
    w = max(100, min(w, vw))
    h = max(60,  min(h, vh))
    x = max(vx - w + 120, min(x, vx + vw - 120))     # >= 120 px of the title bar visible
    y = max(vy,           min(y, vy + vh - 60))
    return f"{w}x{h}{x:+d}{y:+d}"


### NEW v0.20.1 SN2 — every dialog breaks a text line that does not fit (the user, 2026-11-20: "If the size of the
# window is not enough to put everything in the same line, the app must break the line automatically" and "The line
# MUST BREAK RESPECTING THE SIZE OF THE WINDOW ... the text adapts to the size of the window").
# Every Label / Checkbutton / Radiobutton follows the window's width: its line breaks at the space from its left edge
# to the window's right edge (less what stands to its right: a scroll bar, a button), and it unwraps when that space
# is wide enough. This includes labels that were given a fixed wraplength in the code: that value is only used while
# the window still has its natural size (nobody resized it), so a window that sizes itself to its text can never
# shrink its text in a loop. Once the window is resized (by the user, or by a saved / set geometry), the window's
# width rules.
_AW_CLASSES = ("Label", "Checkbutton", "Radiobutton", "TLabel")
_AW_RIGHT = 16                                                   # px kept free on the right


def _aw_wanted(natural, avail, extra=0):
    """Pure: the wraplength for a text *natural* px wide in *avail* px (0 = no wrap); *extra* = a check box's width."""
    room = avail - extra
    return 0 if natural <= room else max(120, int(room))


def _aw_right_of(w, top):
    """Px taken by widgets standing to the right of *w* (or of one of its parents) on the same rows, up to *top*.
    Uses their requested widths, which do not depend on *w*'s wrap (no feedback loop)."""
    used = 0
    while w is not None and w is not top:
        parent = w.master
        if parent is None:
            break
        try:
            wx, wy, wh = w.winfo_rootx(), w.winfo_rooty(), w.winfo_height()
            for s in parent.winfo_children():
                if s is w or isinstance(s, tk.Toplevel) or not s.winfo_ismapped():
                    continue
                sy, sh = s.winfo_rooty(), s.winfo_height()
                if s.winfo_rootx() > wx and sy < wy + wh and sy + sh > wy:
                    used += s.winfo_reqwidth()
        except (tk.TclError, AttributeError):
            break
        w = parent
    return used


def auto_wrap_window(top):
    """Apply the wrap rule to every text widget of the Toplevel *top* (Tk thread)."""
    try:
        top._aw_after = None
        if not top.winfo_exists() or not top.winfo_ismapped():
            return 0
        width, tx = top.winfo_width(), top.winfo_rootx()
        natural_size = not getattr(top, "_aw_sized", False) and abs(width - top.winfo_reqwidth()) <= 1
        if not natural_size:                     # resized once = the window's width rules from now on
            top._aw_sized = True
    except (tk.TclError, AttributeError):
        return 0
    if width <= 1:
        return 0
    import tkinter.font as _tkf
    changed, stack = 0, list(top.winfo_children())
    while stack:
        c = stack.pop()
        if isinstance(c, tk.Toplevel):
            continue
        try:
            stack.extend(c.winfo_children())
            cls = c.winfo_class()
            if cls not in _AW_CLASSES or not c.winfo_ismapped():
                continue
            if not hasattr(c, "_aw_own"):
                c._aw_own = int(c.winfo_fpixels(c.cget("wraplength") or 0))   # the code's own wrap (px), 0 = none
            text = str(c.cget("text") or "")
            if not text.strip():
                continue
            if natural_size and c._aw_own:
                want = c._aw_own                    # the window follows its text: keep the code's width (no loop)
            else:
                fnt = _tkf.Font(font=c.cget("font"))
                try:
                    pad = 2 * int(c.winfo_fpixels(c.cget("padx") or 0))
                except tk.TclError:                                    # ttk: no padx
                    pad = 0
                natural = max(fnt.measure(line) for line in text.split("\n")) + pad
                extra = 24 if cls in ("Checkbutton", "Radiobutton") else 0
                avail = width - (c.winfo_rootx() - tx) - _AW_RIGHT - _aw_right_of(c, top)
                want = _aw_wanted(natural, avail, extra)
            if int(c.winfo_fpixels(c.cget("wraplength") or 0)) != want:
                c.configure(wraplength=want)
                if want and cls != "TLabel" and str(c.cget("justify")) == "center" and "w" in str(c.cget("anchor")):
                    c.configure(justify="left")
                changed += 1
        except (tk.TclError, AttributeError, ValueError):
            continue
    return changed


def _aw_on_configure(e):
    """Toplevel <Configure>: one wrap pass when the window is idle (debounced)."""
    w = e.widget
    try:
        if not isinstance(w, tk.Toplevel) or w.wm_overrideredirect() or getattr(w, "_aw_after", None):
            return
        root = w._root()
        w._aw_after = root.after_idle(lambda: auto_wrap_window(w))
    except (tk.TclError, AttributeError):
        pass


def _remember_window(win, wid, resizable=True):
    """Restore the saved geometry of window *wid* and keep SETTINGS up to date.
    Call it last in the window's __init__ (after its own geometry/centring)."""
    try:
        store = SETTINGS.get("window_geometry")
        if not isinstance(store, dict):
            store = {}
            SETTINGS["window_geometry"] = store
        saved = store.get(wid)
        saved = saved if isinstance(saved, dict) else {}
        geom = _clamp_geometry(saved.get("geometry"), win)
        win.update_idletasks()
        if geom:
            if resizable:
                win.geometry(geom)
            else:                                   # position only
                gm = _GEOM_RE.match(geom)
                win.geometry(gm.group(3) + gm.group(4))
        if saved.get("zoomed") and resizable:
            win.state("zoomed")
    except Exception as ex:
        logger.debug(f"_remember_window restore ({wid}): {ex}")

    state = {"after": None}

    def _capture():
        state["after"] = None
        try:
            if not win.winfo_exists():
                return
            st = win.state()
        except Exception:
            return
        try:
            # look the store up every time: SETTINGS["window_geometry"] may have
            # been replaced since the window was created
            store = SETTINGS.get("window_geometry")
            if not isinstance(store, dict):
                store = {}
                SETTINGS["window_geometry"] = store
            if st == "zoomed":
                entry = dict(store.get(wid) or {})
                entry["zoomed"] = True          # keep the last normal geometry too
                store[wid] = entry
                return
            if st != "normal":
                return                          # iconic / withdrawn: nothing useful
            g = win.geometry()
            m = _GEOM_RE.match(g)
            if not m or int(m.group(1)) <= 1 or int(m.group(3)) <= -30000:
                return
            store[wid] = {"geometry": g, "zoomed": False}
        except Exception:
            pass

    def _on_configure(e):
        if e.widget is not win:
            return
        if state["after"] is not None:
            try:
                win.after_cancel(state["after"])
            except Exception:
                pass
        try:
            state["after"] = win.after(400, _capture)
        except Exception:
            state["after"] = None

    def _on_destroy(e):
        if e.widget is not win:
            return
        if state["after"] is not None:
            try:
                win.tk.call("after", "cancel", state["after"])    ### MODIFIED v0.19.4 B99d — in Tcl (family rule) ###
            except Exception:
                pass
            state["after"] = None
        _capture()
        try:
            _save_settings(SETTINGS)            # one write per window close
        except Exception:
            pass

    win.bind("<Configure>", _on_configure, add="+")
    win.bind("<Destroy>",   _on_destroy,   add="+")
    win._mc_geom_capture = _capture          # used by App._on_app_close
    return _capture


# SettingsDialog lives in settings_dialog.py, which must not import this module;
# it calls this hook (if present) at the end of its __init__.
SettingsDialog._remember_window_hook = staticmethod(_remember_window)   ### NEW v0.19.0 ###


class FrameExtractionDialog(_DialogBase):
    """Progress dialog for extracting backdrop frames — smooth animation."""

    def __init__(self, parent, video_path, sub_path, timeout_sec=60):
        super().__init__(parent)
        self.title(_i18n.t("mc.extract_backdrop_s_72c6"))
        self.geometry("540x360")
        self.configure(bg=C_BG)
        self.transient(parent); _modal(self)
        self.resizable(False, False)
        self.protocol("WM_DELETE_WINDOW", self._on_cancel)

        self._video_path  = video_path
        self._sub_path    = sub_path
        self._timeout_sec = timeout_sec
        self._cancelled   = False
        self._extracted   = []
        self._pct_target  = 0       # target for smooth animation
        self._pct_current = 0       # current animated value

        tk.Label(self, text=_i18n.t("mc.extracting_backdrop_frames_abaa"),
                 font=("Helvetica", 12, "bold"), bg=C_BG, fg=C_TEXT
                 ).pack(pady=(16, 2))
        tk.Label(self, text=os.path.basename(video_path),
                 font=("Consolas", 9), bg=C_BG, fg=C_DIM).pack(pady=(0, 8))

        self.status_var = tk.StringVar(value=_i18n.t("au.preparing"))
        tk.Label(self, textvariable=self.status_var, font=("Helvetica", 10),
                 bg=C_BG, fg=C_SUBTEXT, wraplength=500).pack()

        self.eta_var = tk.StringVar(value="")
        tk.Label(self, textvariable=self.eta_var, font=("Helvetica", 9),
                 bg=C_BG, fg=C_DIM).pack()
        self._ff_state = {}                                              ### NEW v0.19.2 B28 — spinner ###
        self._ff_label = tk.Label(self, text="", font=("Consolas", 9), bg=C_BG, fg=C_ACCENT)
        self._ff_label.pack()
        self._ff_spinner = _FFSpinner(self._ff_label, self._ff_state)

        pf = tk.Frame(self, bg=C_BG); pf.pack(fill="x", padx=30, pady=(8, 4))
        self.pbar_canvas = tk.Canvas(pf, height=24, bg=C_SURFACE,
                                     highlightthickness=0, relief="flat")
        self.pbar_canvas.pack(fill="x")
        self._draw_progress(0)

        # Controls row
        ctrl = tk.Frame(self, bg=C_BG); ctrl.pack(pady=(6, 0))

        # Backdrop count spinner (item 14)
        tk.Label(ctrl, text=_i18n.t("mc.backdrops_to_extract_4557"), font=("Helvetica", 9),
                 bg=C_BG, fg=C_SUBTEXT).pack(side="left", padx=(0, 4))
        self._count_var = tk.IntVar(value=SETTINGS.get("backdrop_count", 10))
        self._spins = []                                         # v0.20.0 AU16: shown, not changeable (see _start)
        self._spins.append(tk.Spinbox(ctrl, from_=1, to=50, textvariable=self._count_var,
                   width=4, font=("Helvetica", 9),
                   bg=C_SURFACE, fg=C_TEXT, buttonbackground=C_SURFACE2,
                   relief="flat")); self._spins[-1].pack(side="left", padx=(0, 18))

        tk.Label(ctrl, text=_i18n.t("mc.per_frame_timeout_s_3287"), font=("Helvetica", 9),
                 bg=C_BG, fg=C_SUBTEXT).pack(side="left")
        self._timeout_var = tk.IntVar(value=timeout_sec)
        self._spins.append(tk.Spinbox(ctrl, from_=10, to=300, textvariable=self._timeout_var,
                   width=5, font=("Helvetica", 9),
                   bg=C_SURFACE, fg=C_TEXT, buttonbackground=C_SURFACE2,
                   relief="flat")); self._spins[-1].pack(side="left", padx=(6, 0))

        tk.Button(self, text=_i18n.t("mc.cancel_2fee"), font=("Helvetica", 10, "bold"),
                  bg=C_ERR, fg=C_BG, relief="flat", cursor="hand2",
                  command=self._on_cancel).pack(pady=(10, 16))

        self.after(150, self._start)
        self._anim_id = self.after(50, self._animate_progress)
        self.bind("<Destroy>", self._stop_anim, add="+")              ### NEW v0.19.4 B99d ###
        _remember_window(self, "FrameExtractionDialog", resizable=False)   ### NEW v0.19.0 — window memory ###

    def _draw_progress(self, pct):
        c = self.pbar_canvas; c.delete("all")
        w = c.winfo_width() or 480; h = 24
        c.create_rectangle(0, 0, w, h, fill=C_SURFACE, outline="")
        fw = int(w * pct / 100)
        if fw > 0:
            c.create_rectangle(0, 0, fw, h, fill="#2d6e3f", outline="")
        c.create_text(w//2, h//2, text=f"{int(pct)}%",
                      fill=C_TEXT, font=("Helvetica", 10, "bold"))

    def _stop_anim(self, e=None):                                ### NEW v0.19.4 B99d ###
        if e is not None and e.widget is not self:
            return
        aid, self._anim_id = getattr(self, "_anim_id", None), None
        if aid:
            try:
                self.tk.call("after", "cancel", aid)              # family rule: never after_cancel on close
            except tk.TclError:
                pass

    def _animate_progress(self):
        """Smoothly animate progress bar at ~20fps.
        ### MODIFIED v0.19.4 B99d ### stops when the window is gone."""
        try:
            if not self.winfo_exists():
                return
        except tk.TclError:
            return
        if self._pct_current < self._pct_target:
            step = max(0.5, (self._pct_target - self._pct_current) * 0.15)
            self._pct_current = min(self._pct_target, self._pct_current + step)
            self._draw_progress(self._pct_current)
        try:
            self._anim_id = self.after(50, self._animate_progress)   ### id kept: v0.19.4 B99d ###
        except Exception:
            self._anim_id = None

    def _on_cancel(self):
        self._cancelled = True                                   # the runner kills FFmpeg within 0.2 s (v0.19.2 B28)
        self.status_var.set(_i18n.t("mc.st.cancelling"))                       ### MODIFIED v0.19.2 B28 ###

    def _start(self):
        ### MODIFIED v0.19.4 B99a — the Tk variables are read HERE, on the Tk thread ###
        try:
            t = int(self._timeout_var.get())
        except (tk.TclError, ValueError):
            t = self._timeout_sec
        try:
            n = int(self._count_var.get())
        except (tk.TclError, ValueError):
            n = SETTINGS.get("backdrop_count", 10)
        ### v0.20.0 AU16 (pre-build audit) ### the run starts with these values at once: the boxes now show them
        # (greyed) instead of looking changeable — a change did nothing.  Settings → FFmpeg holds both values.
        for _sp in getattr(self, "_spins", []):
            try:
                _sp.configure(state="disabled")
            except tk.TclError:
                pass
        self._used = (max(10, t), max(1, min(50, n)))
        threading.Thread(target=self._worker, args=self._used,   # item 14: configurable count
                         daemon=True).start()

    def _worker(self, t_limit=60, n_frames=10):
        video      = self._video_path
        sub        = self._sub_path

        ui_post(lambda: self.status_var.set(_i18n.t("mc.st.reading_duration")))
        _cancel = lambda: self._cancelled                       ### NEW v0.19.2 B28 — plain flag, no Tk ###
        _t_run = time.monotonic()
        self._ff_state.update(active=True, i=0, n=n_frames, t_frame=_t_run, t_run=_t_run)
        try:
            self._worker_frames(video, sub, t_limit, n_frames, _cancel)
        finally:
            self._ff_state["active"] = False

    def _worker_frames(self, video, sub, t_limit, n_frames, _cancel):   ### v0.19.2 B28 — body of _worker ###
        dur_result = get_video_duration(video, cancel=_cancel)  ### UPDATED v0.17.0; cancel v0.19.2 B28 ###
        if self._cancelled:
            ui_post(self.destroy)
            return
        # get_video_duration now returns (float|None, estimated:bool)
        if isinstance(dur_result, tuple):
            duration, estimated = dur_result
        else:
            duration, estimated = dur_result, False            # legacy compatibility

        if not duration or duration <= 0:
            ext = os.path.splitext(video)[1].lower()
            if ext in (".mp4", ".mkv"):
                # Use a safe default estimate of 3600s and warn rather than abort
                duration  = 3600.0
                estimated = True
                ui_post(lambda: self.status_var.set(_i18n.t("mc.fx.dur_estimate")))      # v0.20.0 UI1e
            else:
                self._finish_error(_i18n.t("mc.fx.no_duration_t"), _i18n.t("mc.fx.no_duration"))   # v0.20.0 UI1e
                return

        if estimated:
            ui_post(lambda: self.status_var.set(_i18n.t("mc.fx.dur_estimated")))         # v0.20.0 UI1e

        if duration < 20:
            self._finish_error(_i18n.t("mc.fx.too_short_t"), _i18n.t("mc.fx.too_short", s=f"{duration:.0f}"))   # v0.20.0 UI1e
            return

        if duration < 120:
            start_sec = 2; end_sec = duration - 2
        elif duration < 600:
            start_sec = duration * 0.05; end_sec = duration * 0.95
        else:
            start_sec = 300; end_sec = duration - 300

        if end_sec <= start_sec:
            end_sec = duration * 0.9; start_sec = duration * 0.1

        divisor    = max(1, n_frames - 1) if n_frames > 1 else 1
        interval   = (end_sec - start_sec) / divisor if end_sec > start_sec else 1
        timestamps = [start_sec + i * interval for i in range(n_frames)]
        _new_paths = new_backdrop_paths(sub, n_frames)          ### MODIFIED v0.19.1 B23 — folder's naming style ###
        extracted  = []; failed = []
        frame_times = []
        timeouts = 0; slow_stop = False                          ### NEW v0.19.2 B28 — "slow file" breaker ###

        for i, ts in enumerate(timestamps):
            if self._cancelled: break
            if timeouts >= 2:
                slow_stop = True
                break
            self._ff_state.update(i=i + 1, t_frame=time.monotonic())   ### NEW v0.19.2 B28 ###
            out_p = _new_paths[i]                                ### MODIFIED v0.19.1 B23 ###
            fname = os.path.basename(out_p)
            mins  = int(ts // 60); secs_r = int(ts % 60)

            pct_per_frame = 100.0 / n_frames
            self._pct_target = int(i * pct_per_frame)

            ui_post(lambda i=i, m=mins, s=secs_r, fn=fname, n=n_frames:
                       self.status_var.set(_i18n.t("mc.st.frame", i=i + 1, n=n, m=m, s=f"{s:02d}", fn=fn)))

            t0 = time.time()
            ok, err_msg = extract_single_frame(video, ts, out_p, timeout_sec=t_limit, cancel=_cancel)   ### MODIFIED v0.19.2 B28 ###
            timeouts = (timeouts + 1) if (not ok and str(err_msg).startswith(_FF_TIMEOUT_TEXT)) else 0
            elapsed = time.time() - t0
            frame_times.append(elapsed)

            self._pct_target = int((i + 1) * pct_per_frame)

            if ok:
                extracted.append((fname, out_p))
            else:
                failed.append((i+1, f"{mins}:{secs_r:02d}", fname, err_msg))
                try:                                                   ### NEW v0.19.4 P3 (B18) — no partial frame left ###
                    if os.path.isfile(out_p):
                        os.remove(out_p)
                except OSError:
                    pass

            # ETA
            if frame_times:
                avg = sum(frame_times) / len(frame_times)
                remaining = avg * (n_frames - i - 1)
                if remaining > 60:
                    eta = _i18n.t("au.eta_m", m=int(remaining//60), s=int(remaining%60))
                elif remaining > 0:
                    eta = _i18n.t("au.eta_s", s=int(remaining))
                else:
                    eta = _i18n.t("au.almost")
                ui_post(lambda e=eta: self.eta_var.set(e))

        self._extracted = [p for _, p in extracted]
        self._pct_target = 100

        if self._cancelled:
            for _, p in extracted:
                try: os.remove(p)
                except OSError: pass
            ui_post(lambda: (
                self.status_var.set(_i18n.t("mc.st.cancelled")),
                messagebox.showinfo(_i18n.t("mc.cancelled_a149"),
                    _i18n.t("mc.extraction_cancelled_partial_files_a5f0"), parent=self),
                self.destroy()))
            return

        n_ok = len(extracted); n_bad = len(failed)
        if slow_stop:                                            ### NEW v0.19.2 B28 ###
            msg = B28_SLOW_TEXT.format(frames=_n(n_ok, "frame"))
            logger.warning(f"Extract Backdrop(s) stopped (slow file): {video}")
            ui_post(lambda: (messagebox.showwarning(_i18n.t("mc.stopped_c23e"), msg, parent=self), self.destroy()))
            return
        if n_bad == 0:
            ### UPDATED v0.18.0 — build file-range string correctly for all cases ###
            if n_ok == 1:
                only_fname = extracted[0][0]
                files_str = only_fname
            else:                                                ### MODIFIED v0.19.1 B23 — real names (Kodi or plain) ###
                files_str = f"{extracted[0][0]} → {extracted[-1][0]}"
            msg = (_i18n.t("mc.done_all_extracted_saved_d051", n=_n(n_frames, 'frame'), sub=sub, files_str=files_str))
            ui_post(lambda: (messagebox.showinfo(_i18n.t("mc.done_f929"), msg, parent=self), self.destroy()))
        elif n_ok == 0:
            detail = "\n".join(f"  Frame {fi} at {ts}: {em}" for fi,ts,_,em in failed[:5])
            msg = (_i18n.t("mc.no_frames_extracted_all_4ab3", n_frames=n_frames, detail=detail))
            ui_post(lambda: (messagebox.showerror(_i18n.t("mc.failed_d7c8"), msg, parent=self), self.destroy()))
        else:
            detail = "\n".join(f"  Frame {fi} at {ts}: {em}" for fi,ts,_,em in failed[:3])
            msg = (_i18n.t("mc.partial_frames_saved_failed_8c74", n_ok=n_ok, n_frames=n_frames, n_bad=n_bad, detail=detail))
            ui_post(lambda: (messagebox.showwarning(_i18n.t("mc.partial_44ff"), msg, parent=self), self.destroy()))

    def _finish_error(self, title, message):
        ui_post(lambda: (messagebox.showerror(title, message, parent=self), self.destroy()))


