        self.result_v = None   # int   | None

        movie_label = movie_name[:60] + "…" if len(movie_name) > 60 else movie_name
        tk.Label(self, text=movie_label, bg=C_BG, fg=C_ACCENT,
                 font=("Helvetica", 10, "bold"), wraplength=360).pack(padx=20, pady=(14, 4))
