# ── v0.19.2 B37: every NFO/XML writer reads through _read_for_edit ───────────
_UTF8_BOM = b"\xef\xbb\xbf"


def _xml_text(value):                                          ### NEW v0.19.2 B39 ###
    """A value as NFO/XML element text: & < > escaped.  Values stay unescaped
    in memory (readers use html.unescape / ElementTree), so this runs exactly
    once, at the point of writing."""
    return _xml_escape(str(value))


class NotUtf8Error(ValueError):                                ### NEW v0.19.2 B37 ###
    """The file is not valid UTF-8.  Rewriting it would replace every byte
    that does not decode with U+FFFD ("Am�lie"), so the writer leaves it as it is."""
    def __init__(self, path):
        super().__init__(f"{os.path.basename(path)} is not UTF-8 — not changed "
                         f"(convert it to UTF-8 first)")
        self.path = path


def _read_for_edit(path):                                      ### NEW v0.19.2 B37 ###
    """(text, bom) of an NFO/XML that is about to be changed: strict UTF-8, the
    BOM removed from the text (_atomic_write_text writes it back), newlines
    as a text-mode read gives them.  Raises NotUtf8Error for any other
    encoding, so the file is never written."""
    with open(path, "rb") as f:
        raw = f.read()
    bom = raw.startswith(_UTF8_BOM)
    try:
        text = raw[len(_UTF8_BOM):].decode("utf-8") if bom else raw.decode("utf-8")
    except UnicodeDecodeError:
        raise NotUtf8Error(path) from None
    return text.replace("\r\n", "\n").replace("\r", "\n"), bom


def _read_lines_for_edit(path):                                ### NEW v0.19.2 B37 ###
    """_read_for_edit as a list of lines (like f.readlines())."""
    return io.StringIO(_read_for_edit(path)[0]).readlines()


# ── Atomic NFO/XML writes (v0.19.0) ──────────────────────────────────────────
def _atomic_write_text(path, text, encoding="utf-8"):          ### NEW v0.19.0 ###
    """Write *text* to *path* atomically: temp file in the same folder, flush +
    fsync, then os.replace.  A crash or power loss leaves either the old or
    the new complete file, never a half-written one.  Used by every NFO/XML
    writer (ratings, genres, source IDs, Auto Repair).
    ### MODIFIED v0.19.2 B37 ### a file that starts with a UTF-8 BOM keeps it
    (_read_for_edit returns the text without the BOM)."""
    if str(path).lower().endswith(".nfo") and not nfo_in_use(library_of(os.path.dirname(str(path)))):   # v0.20.0 F3: per library
        raise RuntimeError("the NFO is not used in this health mode (movie.xml only) — not changed")   # v0.19.6 TR1b
    if os.path.basename(str(path)).lower() == "movie.xml" and not xml_in_use(library_of(os.path.dirname(str(path)))):
        raise RuntimeError("movie.xml is not used for this library (health mode / NFO only) — not changed")   # v0.20.0 F3b
    tmp = f"{path}.{threading.get_ident() % 100000}.mctmp"       # v0.20.2 PA15 (audit): one temp file per writer — two
    # writes on one movie (Auto Repair + an Apply) shared "<file>.mctmp": one could publish or delete the other's
    ### NEW v0.20.0 AU2 ### the text is written as UTF-8: a prolog that names another encoding (ISO-8859-1) would make
    # Kodi / Jellyfin read "AmÃ©lie" — the declaration follows the bytes
    if encoding.lower().replace("_", "-") in ("utf-8", "utf-8-sig"):
        text = re.sub(r"""\A(﻿?<\?xml\b[^>]*?\bencoding=)(["'])(?!utf-?8\2)[^"']*\2""",
                      lambda m: f"{m.group(1)}{m.group(2)}UTF-8{m.group(2)}", text, count=1, flags=re.I)
    try:                                                        # v0.20.0 AU2: a hidden / system NFO stays so
        _keep_attr = getattr(os.stat(path), "st_file_attributes", 0) & 0x6
    except OSError:
        _keep_attr = 0
    newline = None                                              ### NEW v0.19.3 B60 — keep the file's line endings ###
    try:
        with open(path, "rb") as f:
            head = f.read(1 << 16)
        if encoding.lower().replace("_", "-") == "utf-8" and not text.startswith("﻿") and head[:3] == _UTF8_BOM:
            encoding = "utf-8-sig"
        # a text-mode write on Windows turned every LF file into CRLF (found in
        # v0.19.3 B60: one changed tag rewrote every line ending of the file)
        newline = "\r\n" if b"\r\n" in head else ("\n" if b"\n" in head else None)
    except OSError:
        pass
    try:
        with open(tmp, "w", encoding=encoding, newline=newline) as f:
            f.write(text)
            f.flush()
            try:
                os.fsync(f.fileno())
            except OSError:
                pass
        _sc._replace_retry(tmp, path)                           # v0.19.5 WR-B1
        if _keep_attr and os.name == "nt":                      # v0.20.0 AU2
            try:
                import ctypes as _ct
                _a = getattr(os.stat(path), "st_file_attributes", 0)
                _ct.windll.kernel32.SetFileAttributesW(str(path), _a | _keep_attr)
            except Exception:
                pass
        _cache_forget(path)                                     ### NEW v0.19.3 I11 ###
    finally:
        if os.path.exists(tmp):
            try:
                os.remove(tmp)
            except OSError:
                pass


_ROOT_CLOSE_RE = re.compile(r"^\s*</([A-Za-z_][\w.:-]*)>\s*$")


def _insert_line_before_root_close(file_lines, new_line, preferred=()):   ### NEW v0.19.0 ###
    """Insert *new_line* before the closing tag of the document root.
    *preferred* names are tried first (e.g. 'Item', 'movie'); otherwise the
    LAST closing tag in the file is used (movie.xml written by Emby/Jellyfin
    uses <Title> as root, v0.18.x appended after </Title> and broke the XML).
    ### MODIFIED v0.19.5 WR-A2 ### a closing tag that shares its line is split from it (a one-line file became invalid);
    with no closing tag at all, ValueError: nothing is appended to a file that is not XML."""
    for end in preferred:
        end_re = re.compile(rf"^\s*</{re.escape(end)}>\s*$", re.IGNORECASE)
        for i, line in enumerate(file_lines):
            if end_re.match(line):
                file_lines.insert(i, new_line)
                return file_lines
    for i in range(len(file_lines) - 1, -1, -1):
        if _ROOT_CLOSE_RE.match(file_lines[i]):
            file_lines.insert(i, new_line)
            return file_lines
    for i in range(len(file_lines) - 1, -1, -1):
        ms = list(re.finditer(r"</[A-Za-z_][\w.:-]*>\s*$", file_lines[i]))
        if ms:
            at = ms[-1].start()
            head, tail = file_lines[i][:at], file_lines[i][at:]
            nl = "\r\n" if file_lines[i].endswith("\r\n") else "\n"
            if not new_line.endswith("\n"):
                new_line += nl
            file_lines[i:i + 1] = [head + nl, new_line, tail if tail.endswith("\n") else tail + nl]
            return file_lines
    raise ValueError("the file has no closing root tag; nothing written")


def _require_xml(text):                                          ### NEW v0.19.5 WR-A2, AS-A7 ###
    """A writer's result must parse: a corrupt file gets no more junk, and no fix is reported as done."""
    try:
        ### MODIFIED v0.20.0 AU2 ### a bare '&' ("Fast & Furious") is accepted, as the reader (_parse_root) and Kodi do:
        # every ID / year / title write used to refuse such an NFO that scans fine
        ET.fromstring(_AMP_FIX_RE.sub("&amp;", cut_url_tail(text.lstrip("\ufeff"))).encode("utf-8"))   # PA13
    except ET.ParseError as e:
        raise ValueError(f"the file is not valid XML ({e}); nothing written")


_XML_TOKEN_RE = re.compile(r"<!--.*?-->|<!\[CDATA\[.*?\]\]>|<[?!][^>]*>|<(/?)([A-Za-z_][\w.:-]*)[^>]*?(/?)>", re.S)


def _root_child_test(text):                                      ### NEW v0.20.0 AU2 (pre-build audit) ###
    """A function pos → True when *pos* sits directly inside the root element (depth 1), the only place the readers
    (root.find / findall) look.  The line writers used to edit the first matching tag at ANY depth: an actor's
    <tmdbid> (tinyMediaManager writes one per actor) got the movie's ID and the movie got none."""
    marks, depth = [], 0                                         # (end of tag, depth after it)
    for m in _XML_TOKEN_RE.finditer(text):
        if m.group(2) is None:
            continue                                             # comment, CDATA, <?xml?>, <!DOCTYPE>
        if m.group(1):
            depth -= 1
        elif not m.group(3):
            depth += 1
        marks.append((m.end(), depth))
    ends = [e for e, _d in marks]
    import bisect as _bisect

    def at_root(pos):
        i = _bisect.bisect_right(ends, pos) - 1
        return i >= 0 and marks[i][1] == 1
    return at_root


def _relines(lines, text):                                       # v0.20.0 AU2: the list is edited in place
    lines[:] = text.splitlines(keepends=True)


def _set_tag_in_lines(lines, tag, value, attr_pat=r"(?:\s[^>]*?)?", all_copies=False):   ### NEW v0.19.5 WR-A1, WR-A4 ###
    """The first <tag> gets *value*, in place: plain text, CDATA or the empty form <tag />. Attributes stay. True when found.
    (The readers take the first tag, so a second tag added at the end was never read.)
    ### MODIFIED v0.20.0 AU2 ### only a tag directly inside the root (an <actor>'s <tmdbid> is never touched), and a
    value on its own line(s) is replaced too (it used to be skipped: the old value stayed and was still read)."""
    pair = re.compile(rf"(<{tag}{attr_pat}>)(?:\s*<!\[CDATA\[.*?\]\]>\s*|[^<]*)(</\s*{tag}\s*>)", re.IGNORECASE | re.S)
    single = re.compile(rf"<({tag})({attr_pat})\s*/>", re.IGNORECASE)
    text = "".join(lines)
    at_root = _root_child_test(text)
    hits = [(m.start(), "p", m) for m in pair.finditer(text) if at_root(m.start())]
    hits += [(m.start(), "s", m) for m in single.finditer(text) if at_root(m.start())]
    if not hits:
        return False
    ### MODIFIED v0.20.1 L8 — all_copies: every root-level copy gets the value (a second <imdbid> kept the wrong ID) ###
    chosen = sorted(hits, key=lambda h: h[0], reverse=True) if all_copies else [min(hits, key=lambda h: h[0])]   # last first
    for _pos, kind, m in chosen:
        if kind == "p":
            new = m.group(1) + str(value) + m.group(2)
        else:
            new = f"<{m.group(1)}{m.group(2).rstrip()}>{value}</{m.group(1)}>"
        text = text[:m.start()] + new + text[m.end():]
    _relines(lines, text)
    return True


def _write_tag_in_files(nfo_path, xml_path, nfo_tag, xml_tag, value):   ### NEW v0.19.0 ###
    """Set <nfo_tag> in the NFO and/or <xml_tag> in the XML to *value*
    (first occurrence replaced, otherwise inserted before the root's closing
    tag, indentation copied from the file).  Pass None to skip a file.
    Returns (ok, error_str)."""
    errors = []
    value = _xml_text(value)                                    ### NEW v0.19.2 B39 — escaped once, here ###
    for path, tag in ((nfo_path, nfo_tag), (xml_path, xml_tag)):
        if not path or not tag or not os.path.isfile(path):
            continue
        try:
            lines = _read_lines_for_edit(path)   ### MODIFIED v0.19.2 B37 — strict UTF-8, never rewritten with U+FFFD ###
            found = _set_tag_in_lines(lines, re.escape(tag), value)   ### MODIFIED v0.19.5 WR-A1 ###
            if not found:
                indent = "  "
                for line in lines:
                    m = re.match(r"^([ \t]+)<", line)
                    if m:
                        indent = m.group(1); break
                lines = _insert_line_before_root_close(lines, f"{indent}<{tag}>{value}</{tag}>\n",
                                                       preferred=("movie", "Item", "Title"))
            _require_xml("".join(lines))                         ### NEW v0.19.5 AS-A7 ###
            _atomic_write_text(path, "".join(lines))
        except Exception as e:
            errors.append(f"{os.path.basename(path)}: {e}")
    return (not errors), "; ".join(errors)


def _plain_id_first(lines):                                      ### NEW v0.19.5 B125 ###
    """Kodi takes the first <id>: the plain one (IMDb) goes before <id moviedb=…>."""
    plain = next((i for i, l in enumerate(lines) if re.search(r"<id\s*>", l, re.I)), None)
    other = next((i for i, l in enumerate(lines) if re.search(r"<id\s[^>]*>", l, re.I)), None)
    if plain is not None and other is not None and other < plain and len(re.findall(r"<", lines[plain])) <= 2:
        lines.insert(other, lines.pop(plain))
    return lines


def _update_uniqueid_lines(lines, id_type, value):               ### NEW v0.19.1 B19 ###
    """Set every EXISTING Kodi <uniqueid type="imdb"> (id_type "IMDB") or
    <uniqueid type="tmdb"|"themoviedb"> ("TMDB") to *value* — also the
    self-closing form.  Other attributes (default="true") are kept.
    ### MODIFIED v0.19.5 B125 (D11) ### the caller adds one when this type has none: Kodi reads uniqueid, not imdbid or tmdbid."""
    types = "imdb" if id_type == "IMDB" else "(?:tmdb|themoviedb)"
    pair = re.compile(rf'(<uniqueid\b[^>]*\btype=["\']?{types}["\']?[^>/]*>)[^<]*(</\s*uniqueid\s*>)', re.IGNORECASE)
    single = re.compile(rf'<uniqueid\b([^>]*\btype=["\']?{types}["\']?[^>]*?)\s*/>', re.IGNORECASE)
    ### MODIFIED v0.20.0 AU2 ### on the whole text (a value on its own line was never updated) and only directly
    # inside the root
    text = "".join(lines)
    at_root = _root_child_test(text)
    text = pair.sub(lambda m: f"{m.group(1)}{value}{m.group(2)}" if at_root(m.start()) else m.group(0), text)
    at_root = _root_child_test(text)
    text = single.sub(lambda m: f"<uniqueid{m.group(1)}>{value}</uniqueid>" if at_root(m.start()) else m.group(0), text)
    return text.splitlines(keepends=True)


def nfo_id_tags_kodi_only(settings=None):                      ### NEW v0.20.0 RD12 ###
    """True when Settings → Health Rules → NFO "ID tags written in the NFO" is "<uniqueid> only": the ID writers then
    add no <imdbid> / <tmdbid> / <id> / <id moviedb> tag (the ones the NFO has are still corrected) and no empty
    placeholder tag in the NFO.  Kodi, Jellyfin and Emby read <uniqueid>.  movie.xml is not affected."""
    s = settings if settings is not None else SETTINGS
    return (s.get("health_rules") or {}).get("nfo_id_tags", "kodi") == "kodi"   # v0.20.1: the default (user, 2026-11-19)


def add_kodi_uniqueids(nfo_path, ids):                           ### NEW v0.20.1 BF2 ###
    """Add one <uniqueid type="imdb|tmdb"> line for each (kind, value) in *ids* whose type the NFO has no <uniqueid>
    for yet — and nothing else: the user's other tags stay as they are (no placeholder tags, no <id> forms; line
    endings and BOM kept by _atomic_write_text). default="true" goes to the TMDB one (else the IMDb one), only when
    no <uniqueid> of the NFO has it. Returns the kinds added; raises on a read / write problem."""
    from xml.sax.saxutils import escape as _xesc
    text, _bom = _read_for_edit(nfo_path)
    at_root = _root_child_test(text)
    have, has_default = set(), False
    # checkup: an empty <uniqueid type="tmdb"></uniqueid> / <uniqueid … /> is removed first (it counted as present:
    # nothing was added and the warning stayed)
    text = re.sub(r"""[ \t]*<uniqueid\b[^>]*\btype\s*=\s*["']?(?:imdb|tmdb|themoviedb)["']?[^>]*(?:/>|>\s*</uniqueid\s*>)[ \t]*\r?\n?""",
                  lambda m: "" if at_root(m.start()) else m.group(0), text, flags=re.IGNORECASE)
    at_root = _root_child_test(text)
    for m in re.finditer(r"<uniqueid\b([^>]*)>", text, re.IGNORECASE):
        if not at_root(m.start()):
            continue
        t = re.search(r"""\btype\s*=\s*["']?([\w]+)""", m.group(1), re.IGNORECASE)
        if t:
            have.add({"themoviedb": "tmdb"}.get(t.group(1).lower(), t.group(1).lower()))
        if re.search(r"""\bdefault\s*=\s*["']?true""", m.group(1), re.IGNORECASE):
            has_default = True
    add = [(k, str(v).strip()) for k, v in ids if k in ("imdb", "tmdb") and v and str(v).strip() and k not in have]
    if not add:
        return []
    default_kind = None if has_default else ("tmdb" if any(k == "tmdb" for k, _v in add) else add[0][0])
    ind = re.search(r"\n([ \t]+)<\w", text)
    indent = ind.group(1) if ind else "  "
    lines = text.splitlines(keepends=True)
    for k, v in add:
        dflt = ' default="true"' if k == default_kind else ""
        lines = _insert_line_before_root_close(lines, f'{indent}<uniqueid type="{k}"{dflt}>{_xesc(v)}</uniqueid>\n',
                                               preferred=("movie",))
    new = "".join(lines)
    _require_xml(new)
    _atomic_write_text(nfo_path, new)
    return [k for k, _v in add]


def _write_source_id_to_files(nfo_path, xml_path, id_type, chosen_id):  ### FIXED v0.16.0 ###
    """
    Write chosen_id to ALL relevant tags for id_type in both NFO and XML.

    XML IMDB tags:  <IMDB>, <IMDbId>, <IMDB_ID>          (all three written/inserted)
    XML TMDB tags:  <TMDB>, <TMDbId>, <TMDB_ID>          (all three written/inserted)
    NFO IMDB tags:  <imdbid>, <id moviedb="imdb">         (both written/inserted)
    NFO TMDB tags:  <tmdbid>, <id moviedb="tmdb">         (both written/inserted)

    Returns (ok: bool, error_str: str).
    """
    errors = []
    chosen_id = str(chosen_id).strip().rstrip("\\/ ")           ### NEW v0.19.5 WR-A4 — junk copied from a damaged tag ###

    def _detect_indent(file_lines):
        for line in file_lines:
            m = re.match(r'^([ \t]+)<', line)
            if m:
                return m.group(1)
        return "  "

    def _replace_tag_in_lines(file_lines, tag, value):
        """Replace <tag>…</tag> in place, also the empty and CDATA forms (WR-A1). Returns (lines, found)."""
        return file_lines, _set_tag_in_lines(file_lines, re.escape(tag), value, all_copies=True)   # v0.20.1 L8

    def _insert_tag_before_close(file_lines, tag, value, end_tags):
        """Insert <tag>value</tag> before the root's closing tag (end_tags are
        tried first, then the last closing tag in the file).
        ### FIXED v0.19.0 — movie.xml with a <Title> root got the new tag
        appended AFTER </Title>, which made the file invalid ###"""
        indent = _detect_indent(file_lines)
        new_line = f"{indent}<{tag}>{value}</{tag}>\n"
        return _insert_line_before_root_close(file_lines, new_line, preferred=tuple(end_tags))

    def _replace_attr_tag(file_lines, attr_val, value):
        """Replace <id moviedb="attr_val">…</id> in place, also <id moviedb="…" />. Returns (lines, found)."""
        attr = rf"""\s[^>]*moviedb=["']?{re.escape(attr_val)}["']?[^>/]*?"""
        return file_lines, _set_tag_in_lines(file_lines, "id", value, attr, all_copies=True)   # v0.20.1 L8

    # ── Write to XML ──────────────────────────────────────────────────────────
    if xml_path and os.path.isfile(xml_path):
        try:
            lines = _read_lines_for_edit(xml_path)   ### MODIFIED v0.19.2 B37 — strict UTF-8, never rewritten with U+FFFD ###

            if id_type == "IMDB":
                xml_tags = ["IMDB", "IMDbId", "IMDB_ID"]
            else:
                xml_tags = ["TMDB", "TMDbId", "TMDB_ID"]

            for tag in xml_tags:
                lines, found = _replace_tag_in_lines(lines, tag, chosen_id)
                if not found:
                    lines = _insert_tag_before_close(lines, tag, chosen_id, ["Item"])

            _require_xml("".join(lines))                             ### NEW v0.19.5 AS-A7 ###
            _atomic_write_text(xml_path, "".join(lines))             ### MODIFIED v0.19.0 — atomic ###
        except Exception as e:
            errors.append(f"XML: {e}")

    # ── Write to NFO ──────────────────────────────────────────────────────────
    if nfo_path and os.path.isfile(nfo_path):
        try:
            lines = _read_lines_for_edit(nfo_path)   ### MODIFIED v0.19.2 B37 — strict UTF-8, never rewritten with U+FFFD ###

            lines = _update_uniqueid_lines(lines, id_type, chosen_id)   ### NEW v0.19.1 B19 ###
            _ko = nfo_id_tags_kodi_only()                            ### NEW v0.20.0 RD12 — correct, never add ###
            if id_type == "IMDB":
                # Write <imdbid>
                lines, found = _replace_tag_in_lines(lines, "imdbid", chosen_id)
                if not found and not _ko:
                    lines = _insert_tag_before_close(lines, "imdbid", chosen_id, ["movie"])
                # Write <id moviedb="imdb">
                lines, found = _replace_attr_tag(lines, "imdb", chosen_id)
                if not found and not _ko:
                    indent = _detect_indent(lines)
                    new_line = f'{indent}<id moviedb="imdb">{chosen_id}</id>\n'
                    lines = _insert_line_before_root_close(lines, new_line, preferred=("movie",))   ### FIXED v0.19.0 ###
                # Write bare <id>ttXXXXXXX</id> (KODI plain IMDB tag)
                # Use [^<]* instead of tt\d+ so corrupt values like
                # "tt33384756/" are fully replaced.  ### FIX v0.17.0-bug1 ###
                bare_found = _set_tag_in_lines(lines, "id", chosen_id, r"\s*")   # MODIFIED v0.19.5 WR-A1
                if not bare_found and not _ko:                 ### FIX v0.17.0 — insert if missing ###
                    indent = _detect_indent(lines)
                    bare_line = f"{indent}<id>{chosen_id}</id>\n"
                    lines = _insert_line_before_root_close(lines, bare_line, preferred=("movie",))   ### FIXED v0.19.0 ###
            else:
                # Write <tmdbid>
                lines, found = _replace_tag_in_lines(lines, "tmdbid", chosen_id)
                if not found and not _ko:
                    lines = _insert_tag_before_close(lines, "tmdbid", chosen_id, ["movie"])
                # Write <id moviedb="tmdb"> or <id moviedb="themoviedb">
                lines, found_t  = _replace_attr_tag(lines, "tmdb", chosen_id)
                lines, found_t2 = _replace_attr_tag(lines, "themoviedb", chosen_id)
                if not found_t and not found_t2 and not _ko:
                    indent   = _detect_indent(lines)
                    new_line = f'{indent}<id moviedb="tmdb">{chosen_id}</id>\n'
                    lines = _insert_line_before_root_close(lines, new_line, preferred=("movie",))   ### FIXED v0.19.0 ###

            ### NEW v0.19.5 B125 (D11) ### what Kodi reads: a uniqueid of this type when there is none; TMDB's is the default
            ### unless the file already names one
            _ut = "imdb" if id_type == "IMDB" else "(?:tmdb|themoviedb)"
            _all = "".join(lines)
            if not re.search(rf"""<uniqueid\b[^>]*\btype=["']?{_ut}["']?""", _all, re.I):
                _dflt = ' default="true"' if id_type == "TMDB" and not re.search(r"""<uniqueid\b[^>]*\bdefault=["']?true""", _all, re.I) else ""
                _un = "imdb" if id_type == "IMDB" else "tmdb"
                lines = _insert_line_before_root_close(lines, f'{_detect_indent(lines)}<uniqueid type="{_un}"{_dflt}>{chosen_id}</uniqueid>\n', preferred=("movie",))
            lines = _plain_id_first(lines)
            _require_xml("".join(lines))                             ### NEW v0.19.5 AS-A7 ###
            _atomic_write_text(nfo_path, "".join(lines))             ### MODIFIED v0.19.0 — atomic ###
        except Exception as e:
            errors.append(f"NFO: {e}")

    if errors:
        return False, "; ".join(errors)
    # ### NEW v0.19.1 B13 ### the other source gets empty placeholder tags when
    # it has no value anywhere, so the user can fill it in by hand.
    # (v0.20.1: the RD12 setting "<uniqueid> only" leaves them out — the user's choice decides, D-0201-51)
    return _write_empty_source_tags(nfo_path, xml_path, "TMDB" if id_type == "IMDB" else "IMDB")


_EMPTY_ID_TAGS = {                                             ### NEW v0.19.1 B13 ###
    # (file kind, line to insert, regex that detects an existing tag — any value)
    "IMDB": [("xml", "<IMDB></IMDB>",       r"<IMDB(\s[^>]*)?/?>"),
             ("xml", "<IMDbId></IMDbId>",   r"<IMDbId(\s[^>]*)?/?>"),
             ("xml", "<IMDB_ID></IMDB_ID>", r"<IMDB_ID(\s[^>]*)?/?>"),
             ("nfo", "<imdbid></imdbid>",   r"<imdbid(\s[^>]*)?/?>"),
             ("nfo", '<id moviedb="imdb"></id>', r"""<id\s[^>]*moviedb=["']?imdb["']?"""),
             ("nfo", "<id></id>",           r"<id\s*/?>")],
    "TMDB": [("xml", "<TMDB></TMDB>",       r"<TMDB(\s[^>]*)?/?>"),
             ("xml", "<TMDbId></TMDbId>",   r"<TMDbId(\s[^>]*)?/?>"),
             ("xml", "<TMDB_ID></TMDB_ID>", r"<TMDB_ID(\s[^>]*)?/?>"),
             ("nfo", "<tmdbid></tmdbid>",   r"<tmdbid(\s[^>]*)?/?>"),
             ("nfo", '<id moviedb="tmdb"></id>', r"""<id\s[^>]*moviedb=["']?(?:tmdb|themoviedb)["']?""")],
}


def _write_empty_source_tags(nfo_path, xml_path, id_type, dry_run=False):    ### NEW v0.19.1 B13; dry_run v0.19.4 B83 ###
    """Insert EMPTY tags for id_type ("IMDB"/"TMDB") inside the root of both
    files — placeholders the user can fill in by hand.  Only when that source
    has no value in any tag of either file (a value elsewhere is a "partial"
    ID, which Normalize Sources copies instead).  Existing tags, empty or not,
    are never touched; an unparseable file is left alone; a file is written
    (atomically) only when a tag was added.  Returns (ok, error_str).
    ### v0.19.4 B83 ### dry_run=True writes nothing and returns (would_add, "")."""
    src = extract_source_ids_from_files(nfo_path, xml_path)
    if src[f"{id_type.lower()}_all_vals"]:
        return (False, "") if dry_run else (True, "")
    errors = []
    for kind, path, roots in (("xml", xml_path, ("Item",)), ("nfo", nfo_path, ("movie",))):
        if not (path and os.path.isfile(path)) or _parse_root(path) is None:
            continue
        if kind == "nfo" and nfo_id_tags_kodi_only():              # v0.20.0 RD12: no empty tags in a trimmed NFO
            continue
        try:
            lines = _read_lines_for_edit(path)   ### MODIFIED v0.19.2 B37 — strict UTF-8, never rewritten with U+FFFD ###
            text = "".join(lines)
            indent = next((m.group(1) for m in (re.match(r'^([ \t]+)<', ln) for ln in lines) if m), "  ")
            added = False
            _at_root = _root_child_test(text)                       # v0.20.0 AU2: an actor's <tmdbid> does not count
            for k, new_tag, rx in _EMPTY_ID_TAGS[id_type]:
                if k != kind or any(_at_root(m.start()) for m in re.finditer(rx, text, re.IGNORECASE)):
                    continue
                if dry_run:                                      ### NEW v0.19.4 B83 ###
                    return True, ""
                lines = _insert_line_before_root_close(lines, f"{indent}{new_tag}\n", preferred=roots)
                added = True
            if added:
                _atomic_write_text(path, "".join(lines))
        except Exception as e:
            errors.append(f"{kind.upper()}: {e}")
    if errors:
        return False, "; ".join(errors)
    return (False, "") if dry_run else (True, "")


_EMPTY_TAGS_UNCHANGED = object()                                ### NEW v0.19.4 B83 ###


def empty_id_tags_needed(nfo_path, xml_path):                    ### NEW v0.19.4 B83 ###
    """True when "Write empty ID tags" would add a tag to this movie (only
    those movies are backed up, written and counted)."""
    return any(_write_empty_source_tags(nfo_path, xml_path, t, dry_run=True)[0] for t in ("TMDB", "IMDB"))


def _write_both_source_ids(nfo_path, xml_path, imdb_id, tmdb_id):  ### NEW v0.16.0 ###
    """
    Write both IMDB and TMDB IDs to NFO and XML in one call.
    The CALLER backs the files up before calling this. Returns (ok, error_str).
    Skips whichever ID is None/empty — since v0.19.1 (B13) the missing source
    gets empty placeholder tags (written by _write_source_id_to_files).
    """
    errors = []
    if imdb_id:
        ok, err = _write_source_id_to_files(nfo_path, xml_path, "IMDB", imdb_id)
        if not ok: errors.append(err)
    if tmdb_id:
        ok, err = _write_source_id_to_files(nfo_path, xml_path, "TMDB", tmdb_id)
        if not ok: errors.append(err)
    if errors:
        return False, "; ".join(e for e in errors if e)
    return True, ""

# ══════════════════════════════════════════════════════════════════════════════
# NEW v0.19.1 B15 — hard-coded (burned-in) subtitles, marked by the user
# ══════════════════════════════════════════════════════════════════════════════
# Burned-in subtitles are part of the picture, so FFprobe cannot see them and
# there is no reliable automatic detection (OCR would be slow and often wrong).
# The user marks them; the mark is a standard user tag that Kodi and
# Emby/Jellyfin keep:  NFO <tag>Hardsub POR</tag>,  XML <Tags><Tag>Hardsub POR</Tag></Tags>.
_HARDSUB_RE = re.compile(r"^\s*hardsub\s+([a-z]{3})\s*$", re.IGNORECASE)


def get_hardsub_langs(nfo_path, xml_path):
    """Sorted ISO 639-2 codes marked as hard-coded subtitles in the NFO or XML."""
    codes = set()
    for p, find in ((nfo_path, lambda r: r.findall("tag")),
                    (xml_path, lambda r: (r.find("Tags").findall("Tag") if r.find("Tags") is not None else []))):
        if p and os.path.isfile(p):
            root = _parse_root(p)
            if root is None:
                continue
            for el in find(root):
                m = _HARDSUB_RE.match(el.text or "")
                if m:
                    codes.add(m.group(1).upper())
    return sorted(codes)


def _write_hardsub_tags(nfo_path, xml_path, langs):
    """Make the files hold EXACTLY the Hardsub tags of *langs* (ISO 639-2
    codes): existing 'Hardsub XXX' tags are removed, one tag per language is
    added; every other <tag>/<Tag> is kept.  NFO tags go before </movie>;
    XML tags go into <Tags> (created before the root's end when absent; an
    emptied <Tags> block is removed).  Atomic writes; a file whose result
    would not parse is left untouched.  Returns (ok, error_str)."""
    langs = sorted({(c or "").strip().upper() for c in langs if re.fullmatch(r"[A-Za-z]{3}", (c or "").strip())})
    errors = []

    def _indent_of(lines, default="\t"):
        return next((m.group(1) for m in (re.match(r'^([ \t]+)<', ln) for ln in lines) if m), default)

    def _check_and_write(path, before, after):
        if after == before:
            return
        if _parse_root(path) is not None:            # only guard files that parsed before
            try:
                ET.fromstring(_AMP_FIX_RE.sub("&amp;", after))
            except Exception as ex:
                raise ValueError(f"result would not be valid XML ({ex})")
        _atomic_write_text(path, after)

    if nfo_path and os.path.isfile(nfo_path):
        try:
            text = _read_for_edit(nfo_path)[0]   ### MODIFIED v0.19.2 B37 — strict UTF-8, never rewritten with U+FFFD ###
            new = re.sub(r"[ \t]*<tag>\s*hardsub\s+[a-z]{3}\s*</tag>[ \t]*\r?\n?", "", text, flags=re.IGNORECASE)
            lines = new.splitlines(keepends=True)
            ind = _indent_of(lines)
            for c in langs:
                lines = _insert_line_before_root_close(lines, f"{ind}<tag>Hardsub {c}</tag>\n", preferred=("movie",))
            _check_and_write(nfo_path, text, "".join(lines))
        except Exception as e:
            errors.append(f"NFO: {e}")

    if xml_path and os.path.isfile(xml_path):
        try:
            text = _read_for_edit(xml_path)[0]   ### MODIFIED v0.19.2 B37 — strict UTF-8, never rewritten with U+FFFD ###
            new = re.sub(r"[ \t]*<Tag>\s*hardsub\s+[a-z]{3}\s*</Tag>[ \t]*\r?\n?", "", text, flags=re.IGNORECASE)
            removed = new != text
            lines = new.splitlines(keepends=True)
            ind = _indent_of(lines)
            new_tags = "".join(f"{ind}{ind}<Tag>Hardsub {c}</Tag>\n" for c in langs)
            if langs:
                if re.search(r"<Tags\s*/>", new):
                    new = re.sub(r"<Tags\s*/>", lambda m: "<Tags>\n" + new_tags + f"{ind}</Tags>", new, count=1)
                elif re.search(r"</Tags\s*>", new):
                    m = re.search(r"^([ \t]*)</Tags\s*>", new, re.MULTILINE)
                    if m:                                   # </Tags> on its own line
                        new = new[:m.start()] + new_tags + new[m.start():]
                    else:                                   # one-line <Tags>…</Tags>
                        inline = "".join(f"<Tag>Hardsub {c}</Tag>" for c in langs)
                        new = re.sub(r"</Tags\s*>", lambda mm: inline + "</Tags>", new, count=1)
                else:
                    lines = new.splitlines(keepends=True)
                    lines = _insert_line_before_root_close(lines, f"{ind}<Tags>\n{new_tags}{ind}</Tags>\n",
                                                           preferred=("Item",))
                    new = "".join(lines)
            elif removed:
                new = re.sub(r"[ \t]*<Tags>\s*</Tags>[ \t]*\r?\n?", "", new)
            _check_and_write(xml_path, text, new)
        except Exception as e:
            errors.append(f"XML: {e}")

    if errors:
        return False, "; ".join(errors)
    return True, ""


