GENRES_TMDB_ACTION = "Check Genres Against TMDB"                  # backup label (Backup History / Undo)
GENRES_TMDB_LABEL = _label_const("GENRES_TMDB_LABEL", "🎬", "act.genres_tmdb")
GENRES_TMDB_ALL_LABEL = _label_const("GENRES_TMDB_ALL_LABEL", "🎬", "act.genres_tmdb_all")


def genres_tmdb_candidates(rows):
    """Movies that have genres and an IMDb or TMDB ID (a movie without genres is Normalize Genres' job)."""
    return [r for r in rows if r.get("genres") and ((r.get("source_tmdb_val") or "").strip() or (r.get("source_imdb_val") or "").strip())]


def genres_tmdb_compare(rows, api_key, lang="en-US", fetch=None, progress=None, cancelled=None):
    """Worker: [(row, file genres, TMDB genres)] for the movies whose genres differ from TMDB's (both normalized, order
    and case ignored), and the errors.  Nothing is written."""
    items, errors = [], []
    for i, r in enumerate(rows):
        if cancelled and cancelled():
            break
        try:
            tid = (r.get("source_tmdb_val") or "").strip()
            if not tid and (r.get("source_imdb_val") or "").strip():
                found = _tmdb_find_imdb(r["source_imdb_val"].strip(), api_key, fetch)
                tid = str(found[0].get("id") or "") if found else ""
            if tid:
                data = _tmdb_movie_full(tid, api_key, lang, fetch) or {}
                names = [g.get("name") for g in (data.get("genres") or []) if g.get("name")]
                if names:
                    new = list(normalize_genre_list(names)[0])
                    cur = list(r.get("genres") or [])
                    if {g.lower() for g in new} != {g.lower() for g in normalize_genre_list(cur)[0]}:
                        items.append((r, cur, new))
        except Exception as ex:
            errors.append(f"{r.get('movie_name') or r.get('subfolder', '?')}: {ex}")
        if progress:
            progress(i + 1)
    return items, errors


class GenresTmdbDialog(_DialogBase):                              ### NEW v0.20.0 I36 ###
    """The movies whose genres differ from TMDB: file → TMDB per movie, nothing ticked (the file keeps its genres
    unless the user ticks the movie).  Click or Space ticks a row."""
    _BG = C_BG; _FG = C_TEXT

    def __init__(self, app, items, checked):
        super().__init__(app)
        self._items = list(items)
        self.ticks = [False] * len(self._items)
        self.result = False
        self.title(shown_action(GENRES_TMDB_ACTION))
        self.configure(bg=self._BG)
        self.transient(app); _modal(self)
        self.resizable(True, True)
        tk.Label(self, text=_i18n.t("i36.head", n=len(self._items), m=checked), bg=self._BG, fg=C_ACCENT,
                 font=("Helvetica", 11, "bold"), justify="left").pack(anchor="w", padx=16, pady=(14, 2))
        tk.Label(self, text=_i18n.t("i36.note"), bg=self._BG, fg=C_SUBTEXT, font=("Helvetica", 9), justify="left",
                 wraplength=720).pack(anchor="w", padx=16, pady=(0, 8))
        fr = tk.Frame(self, bg=self._BG); fr.pack(fill="both", expand=True, padx=16)
        cols = (("tick", "", 34), ("movie", _i18n.t("i36.col_movie"), 260), ("file", _i18n.t("i36.col_file"), 220),
                ("tmdb", _i18n.t("i36.col_tmdb"), 220))
        self._tv = ttk.Treeview(fr, columns=[c for c, _l, _w in cols], show="headings", height=14, selectmode="browse")
        for c, l, w in cols:
            self._tv.heading(c, text=l); self._tv.column(c, width=w, anchor="center" if c == "tick" else "w", stretch=c != "tick")
        self._tv.pack(side="left", fill="both", expand=True)
        sb = ttk.Scrollbar(fr, orient="vertical", command=self._tv.yview); sb.pack(side="right", fill="y")
        self._tv.configure(yscrollcommand=sb.set)
        for i, (r, cur, new) in enumerate(self._items):
            name = r.get("movie_name") or r.get("subfolder", "")
            y = r.get("movie_year")
            self._tv.insert("", "end", iid=str(i), values=("☐", f"{name} ({y})" if y and y != "-" else name,
                                                           " / ".join(cur), " / ".join(new)))
        self._tv.bind("<ButtonRelease-1>", self._click)
        self._tv.bind("<space>", lambda e: self._toggle(self._tv.focus()))
        bf = tk.Frame(self, bg=self._BG); bf.pack(fill="x", padx=16, pady=(10, 14))
        kw = dict(relief="flat", cursor="hand2", font=("Helvetica", 10))
        tk.Button(bf, text=_i18n.t("i36.all"), bg=C_SURFACE2, fg=self._FG, command=lambda: self._set_all(True), **kw).pack(side="left")
        tk.Button(bf, text=_i18n.t("i36.none"), bg=C_SURFACE2, fg=self._FG, command=lambda: self._set_all(False), **kw).pack(side="left", padx=(6, 0))
        tk.Button(bf, text=_i18n.t("mc.cancel_2fee"), bg=C_SURFACE2, fg=self._FG, command=self.destroy, **kw).pack(side="right")
        self.write_btn = tk.Button(bf, text=_i18n.t("i36.write"), bg=C_WARN, fg=C_BG, command=self._ok,
                                   relief="flat", cursor="hand2", font=("Helvetica", 10, "bold"))
        self.write_btn.pack(side="right", padx=(0, 8))
        self.bind("<Escape>", lambda e: self.destroy())
        self._sync()
        _remember_window(self, "GenresTmdbDialog", resizable=True)

    def _click(self, e):
        iid = self._tv.identify_row(e.y)
        if iid:
            self._toggle(iid)

    def _toggle(self, iid):
        if iid == "" or iid is None:
            return
        i = int(iid)
        self.ticks[i] = not self.ticks[i]
        self._tv.set(iid, "tick", "☑" if self.ticks[i] else "☐")
        self._sync()

    def _set_all(self, value):
        for i in range(len(self.ticks)):
            self.ticks[i] = value
            self._tv.set(str(i), "tick", "☑" if value else "☐")
        self._sync()

    def _sync(self):
        n = sum(self.ticks)
        self.write_btn.configure(text=_i18n.t("i36.write_n", n=n), state="normal" if n else "disabled")

    def _ok(self):
        if any(self.ticks):
            self.result = True
            self.destroy()


def _tmdb_candidate_titles(data):
    """Every title TMDb knows for a movie: title, original title, all
    translations and all alternative titles (so a Portuguese library title
    matches without a per-language query)."""
    out = []
    def _add(t):
        t = (t or "").strip()
        if t and t not in out:
            out.append(t)
    if not isinstance(data, dict):
        return out
    _add(data.get("title")); _add(data.get("original_title")); _add(data.get("name"))
    for tr in (data.get("translations") or {}).get("translations") or []:
        d = tr.get("data") or {}
        _add(d.get("title")); _add(d.get("name"))
    for at in (data.get("alternative_titles") or {}).get("titles") or []:
        _add(at.get("title"))
    return out


def _is_http_404(exc):
    import urllib.error as _ue
    return isinstance(exc, _ue.HTTPError) and exc.code == 404


_ROMAN_NUMS = {"ii": "2", "iii": "3", "iv": "4", "v": "5", "vi": "6", "vii": "7", "viii": "8", "ix": "9", "x": "10",
               "one": "1", "two": "2", "three": "3", "four": "4", "five": "5"}   ### NEW v0.19.5 CO-D6 ###


def _title_numbers(t):
    """The part numbers of a title: {'1'} from 'Vol. 1', {'2'} from 'Part II'."""
    return {_ROMAN_NUMS.get(w, w.lstrip("0") or "0") for w in re.findall(r"[^\W_]+", str(t or "").lower(), re.UNICODE)
            if w.isdigit() or w in _ROMAN_NUMS}


def _titles_match(candidates, local_titles, threshold=0.85):
    """Accent-insensitive comparison (via _norm_title_key + difflib).
    Returns (matched, best_ratio, best_candidate).
    ### MODIFIED v0.19.5 CO-D6 ### titles that differ in a number are not a match: Vol. 1 and Vol. 2 scored 0.93."""
    best = (0.0, "")
    locals_n = [(_norm_title_key(t), _title_numbers(t)) for t in local_titles if t]
    for c in candidates:
        cn = _norm_title_key(c)
        if not cn:
            continue
        cnum = _title_numbers(c)
        for ln, lnum in locals_n:
            if not ln:
                continue
            if cn == ln:
                return True, 1.0, c
            if cnum != lnum:
                continue
            r = difflib.SequenceMatcher(None, cn, ln).ratio()
            if r > best[0]:
                best = (r, c)
    return best[0] >= threshold, best[0], best[1]


def _year_close(a, b, tol=1):
    """True when both years are known and differ by at most *tol*, or when
    either year is unknown (an unknown year never fails a verification)."""
    try:
        ya, yb = int(str(a)[:4]), int(str(b)[:4])
    except (TypeError, ValueError):
        return True
    return abs(ya - yb) <= tol


ID_OK        = "OK"
ID_DIFFERENT = "IMDb and TMDB point to different films"
ID_OTHER     = "ID belongs to another film"
ID_NOT_FOUND = "ID does not exist"
ID_DISAGREE  = "NFO and XML disagree"
ID_NONE      = "no IDs"
ID_IMDB_ONLY = "OK (IMDb only — not on TMDB)"                  ### NEW v0.19.1 B14 — confirmed by the user ###
ID_INVALID   = "a field holds a wrong ID"                       ### NEW v0.20.1 T4 — never "OK" while a tag is wrong ###
ID_RESULTS   = (ID_OK, ID_DIFFERENT, ID_OTHER, ID_NOT_FOUND, ID_DISAGREE, ID_NONE, ID_IMDB_ONLY, ID_INVALID)
_ID_RESULT_KEYS = {ID_OK: "ok", ID_DIFFERENT: "different", ID_OTHER: "other", ID_NOT_FOUND: "not_found",
                   ID_DISAGREE: "disagree", ID_NONE: "none", ID_IMDB_ONLY: "imdb_only", ID_INVALID: "invalid"}


def id_result_text(res):                                         ### NEW v0.20.1 R9 / U18 — shown translated, stored English ###
    k = _ID_RESULT_KEYS.get(res)
    return _i18n.t("idres." + k) if k else (res or "?")
ID_GOOD      = (ID_OK, ID_IMDB_ONLY)                            ### NEW v0.19.1 B14 ###


_ID_CHECK_TEXT = dict({                                          # v0.20.1 R8 (the rule _hr_id_check is next to _hr_missing_ids)
    ID_OTHER: "Verify IMDb/TMDB IDs: the ID belongs to another film — Search Sources finds the right one",
    ID_DIFFERENT: "Verify IMDb/TMDB IDs: the IMDb and TMDB IDs point to different films — Search Sources finds the right one",
    ID_NOT_FOUND: "Verify IMDb/TMDB IDs: an ID does not exist on TMDB — Search Sources finds the right one"})


def _source_missing(row, k):                                   ### NEW v0.19.1 B24 ###
    """True when the movie has no value for source k ("imdb"/"tmdb")."""
    st = row.get(f"source_{k}_status", STATUS_MISSING)
    vals = [v for v in (row.get(f"source_{k}_all") or []) if v]
    return st == STATUS_MISSING or (st == STATUS_ERROR and not vals)


def source_missing_level(row, rules):                          ### NEW v0.19.1 B24 ###
    """'error' | 'warning' | 'off' for the missing-ID reasons of this movie:
    health_rules.single_source_level when one of IMDb/TMDb is missing,
    health_rules.no_source_level when both are.  None when nothing is missing."""
    n = sum(1 for k in ("imdb", "tmdb") if _source_missing(row, k))
    if n == 0:
        return None
    lvl = rules.get("no_source_level" if n == 2 else "single_source_level", "error")
    return lvl if lvl in ("error", "warning", "off") else "error"


def _imdb_only_check(imdb_id, title="", year="", detail=None):  ### NEW v0.19.1 B14 ###
    """The id_check stored when the user confirms an IMDb-only film."""
    return {"result": ID_IMDB_ONLY,
            "detail": detail or "Confirmed by you: this film is not on TMDB",
            "imdb_id": imdb_id, "tmdb_id": None, "tmdb_title": title or "", "tmdb_year": year or "",
            "find_tmdb_id": None, "ratio": 0.0,
            "when": datetime.datetime.now().strftime("%Y-%m-%d %H:%M")}


def _local_titles_for(row):
    """All titles the movie is known by locally: NFO/XML title tags and the
    folder name without the '(year)' and '[tags]' parts."""
    titles = list(row.get("movie_title_raw") or [])
    for t in (row.get("nfo_title"), row.get("xml_localtitle"), row.get("movie_name")):
        if t and t not in titles:
            titles.append(t)
    folder = row.get("subfolder") or ""
    folder = re.sub(r"\[[^\]]*\]", " ", folder)
    folder = re.sub(r"\(\d{4}\)", " ", folder)
    folder = " ".join(folder.split())
    if folder and folder not in titles:
        titles.append(folder)
    return titles


def verify_movie_ids(row, api_key, lang="en-US", fetch=None):
    """
    Check that the IMDb and TMDb IDs of one movie belong to the movie.
    Pure apart from *fetch* (url → dict; defaults to the rate-limited TMDb
    fetch).  Network errors other than HTTP 404 propagate to the caller.

    Returns a dict:
      result     one of ID_RESULTS
      detail     human-readable explanation
      imdb_id, tmdb_id        the IDs that were checked
      tmdb_title, tmdb_year   what TMDb says the TMDb ID is (when known)
      find_tmdb_id            TMDb id that the IMDb id resolves to (when known)
      ratio                   best title similarity (0..1)
      when                    ISO timestamp
    """
    fetch = fetch or _tmdb_rate_limited_fetch
    nfo_path = row.get("nfo_path") if row.get("nfo_exists") else None
    xml_path = row.get("xml_path") if row.get("xml_exists") else None
    res = {"result": ID_NONE, "detail": "", "imdb_id": None, "tmdb_id": None,
           "tmdb_title": "", "tmdb_year": "", "find_tmdb_id": None, "ratio": 0.0,
           "when": datetime.datetime.now().strftime("%Y-%m-%d %H:%M")}

    src = extract_source_ids_from_files(nfo_path, xml_path)
    # v0.20.0 AU22: junk around an ID ('tt0133093/') is the same ID, not a disagreement (struct_fix cleans it)
    imdb_all = [_id_fixed("imdb", v) or v for v in (src.get("imdb_all_vals") or []) if v]
    tmdb_all = [_id_fixed("tmdb", v) or v for v in (src.get("tmdb_all_vals") or []) if v]
    imdb_id, tmdb_id = get_movie_ids_robust(nfo_path, xml_path)
    imdb_id = (imdb_id or "").strip() or None
    tmdb_id = (str(tmdb_id) if tmdb_id else "").strip() or None
    res["imdb_id"], res["tmdb_id"] = imdb_id, tmdb_id

    if len(set(imdb_all)) > 1 or len(set(tmdb_all)) > 1:
        parts = []
        if len(set(imdb_all)) > 1: parts.append("IMDb " + " / ".join(sorted(set(imdb_all))))
        if len(set(tmdb_all)) > 1: parts.append("TMDB " + " / ".join(sorted(set(tmdb_all))))
        res["result"] = ID_DISAGREE
        res["detail"] = "Different IDs in the NFO/XML tags: " + "; ".join(parts)
        return res
    if not imdb_id and not tmdb_id:
        _odd = list(src.get("imdb_invalid_vals") or []) + list(src.get("tmdb_invalid_vals") or [])   # v0.20.0 AU3
        if _odd:                                                  # only values that are not IDs: said so (CO-D8)
            res["result"] = ID_NOT_FOUND
            res["detail"] = "Not a valid ID: " + ", ".join(repr(x) for x in _odd)
            return res
        res["result"] = ID_NONE
        res["detail"] = "No IMDb or TMDB ID in the NFO or XML"
        return res
    ### NEW v0.19.5 CO-D8 — an odd ID is this movie's result; it used to stop the whole run ###
    _bad = [x for x, ok in ((imdb_id, not imdb_id or re.fullmatch(r"tt\d+", imdb_id)), (tmdb_id, not tmdb_id or re.fullmatch(r"[0-9]+", tmdb_id))) if not ok]
    if _bad:
        res["result"] = ID_NOT_FOUND
        res["detail"] = "Not a valid ID: " + ", ".join(repr(x) for x in _bad)
        return res

    local_titles = _local_titles_for(row)
    local_year   = row.get("movie_year_raw") or row.get("movie_year")

    tmdb_data = None; tmdb_missing = False
    if tmdb_id:
        try:
            tmdb_data = _tmdb_movie_full(tmdb_id, api_key, lang, fetch)
            if not isinstance(tmdb_data, dict) or not tmdb_data.get("id"):
                tmdb_missing = True
        except Exception as ex:
            if _is_http_404(ex):
                tmdb_missing = True
            else:
                raise
    find_results = None; imdb_missing = False
    if imdb_id:
        try:
            find_results = _tmdb_find_imdb(imdb_id, api_key, fetch)
            if not find_results:
                imdb_missing = True
        except Exception as ex:
            if _is_http_404(ex):
                imdb_missing = True
            else:
                raise

    if tmdb_data:
        res["tmdb_title"] = (tmdb_data.get("title") or tmdb_data.get("original_title") or "").strip()
        res["tmdb_year"]  = (tmdb_data.get("release_date") or "")[:4]
        res["coll_tmdb"] = _cr.coll_from_movie(tmdb_data, lang, time.time())     ### NEW v0.19.4 B110b — no extra request ###
        res["title_langs"] = _cr.title_langs_from(tmdb_data, [_cr.local_title(row)])   ### MODIFIED v0.19.4 fix 9 ###
        if isinstance(res["coll_tmdb"], dict):
            res["coll_tmdb"]["tl"] = _cr.loose_title(_cr.local_title(row))
        res["tmdb_titles"] = _cr.titles_by_lang(tmdb_data)              ### NEW v0.19.4 B110f ###
    if find_results:
        res["find_tmdb_id"] = str(find_results[0].get("id") or "")

    # ### NEW v0.19.1 B14 ### an IMDb-only film the user confirmed stays OK as
    # long as TMDb still does not know the IMDb ID and no TMDb ID was added
    _prev = row.get("id_check") or {}
    if (imdb_missing and not tmdb_id and _prev.get("result") == ID_IMDB_ONLY
            and _prev.get("imdb_id") == imdb_id):
        keep = dict(_prev); keep["when"] = res["when"]
        keep["detail"] = "IMDb only — still not on TMDB (confirmed by you)"
        return keep

    _no_link = ""                                                 ### NEW v0.19.4 P4 (C9) ###
    if (imdb_missing and not tmdb_missing and tmdb_data
            and not ((tmdb_data.get("external_ids") or {}).get("imdb_id") or "").strip()):
        imdb_missing = False                                      # TMDB simply has no IMDb link: the title check decides
        _no_link = f" — TMDB has no IMDb link (IMDb {imdb_id} not checked)"
    if tmdb_missing or imdb_missing:
        which = []
        if tmdb_missing: which.append(f"TMDB {tmdb_id}")
        if imdb_missing: which.append(f"IMDb {imdb_id}")
        res["result"] = ID_NOT_FOUND
        res["detail"] = "Not found on TMDB: " + ", ".join(which)
        return res

    # Both IDs known: do they name the same film?
    if tmdb_data and find_results:
        find_id = str(find_results[0].get("id") or "")
        ext_imdb = ((tmdb_data.get("external_ids") or {}).get("imdb_id") or "").strip()
        if find_id != str(tmdb_id) and ext_imdb != imdb_id:
            ft = find_results[0].get("title") or find_results[0].get("original_title") or ""
            fy = (find_results[0].get("release_date") or "")[:4]
            res["result"] = ID_DIFFERENT
            res["detail"] = (f"IMDb {imdb_id} is TMDB {find_id} '{ft}' ({fy}); "
                             f"TMDB {tmdb_id} is '{res['tmdb_title']}' ({res['tmdb_year']})")
            return res

    # Title + year check against everything TMDb knows about the film
    ref = tmdb_data if tmdb_data else {
        "title": find_results[0].get("title"), "original_title": find_results[0].get("original_title"),
        "release_date": find_results[0].get("release_date")}
    if not tmdb_data:
        res["tmdb_title"] = (ref.get("title") or ref.get("original_title") or "").strip()
        res["tmdb_year"]  = (ref.get("release_date") or "")[:4]
    cands = _tmdb_candidate_titles(ref)
    matched, ratio, best = _titles_match(cands, local_titles)
    if not matched and not tmdb_data and res.get("find_tmdb_id"):  ### NEW v0.19.5 CO-D7 — an IMDb ID alone: ask for the translations too ###
        try:
            _full = _tmdb_movie_full(res["find_tmdb_id"], api_key, lang, fetch)
            if isinstance(_full, dict) and _full.get("id"):
                matched, ratio, best = _titles_match(_tmdb_candidate_titles(_full), local_titles)
        except Exception as ex:
            if not _is_http_404(ex):
                raise
    res["ratio"] = round(ratio, 3)
    year_ok = _year_close(local_year, res["tmdb_year"])
    if matched and year_ok:
        ### NEW v0.20.1 T4 — the film is right, but a tag holds a wrong value: say it, name the right ID, Fix writes it ###
        _wrong = id_wrong_findings_src(src)
        if _wrong:
            f = _wrong[0]
            good = f["suggest"]
            if not good and f["kind"] == "imdb" and tmdb_data:
                good = ((tmdb_data.get("external_ids") or {}).get("imdb_id") or "").strip()
            if not good and f["kind"] == "tmdb" and res.get("find_tmdb_id"):
                good = res["find_tmdb_id"]
            good = good if _idr.valid(f["kind"], good) else ""
            res["result"] = ID_INVALID
            res["fix_ids"] = [dict(x, suggest=(good if x is f else x["suggest"])) for x in _wrong]
            res["detail"] = (id_wrong_text(dict(f, suggest=good))
                             + f"; TMDB {res.get('tmdb_id') or res.get('find_tmdb_id') or '?'} is '{res['tmdb_title']}' ({res['tmdb_year']})")
            return res
        res["result"] = ID_OK
        res["detail"] = f"Matched '{best}' ({res['tmdb_year']})" + _no_link   # P4 (C9)
    else:
        res["result"] = ID_OTHER
        why = []
        if not matched:
            why.append(f"best title similarity {ratio:.2f} ('{best}')")
        if not year_ok:
            why.append(f"year {local_year} vs TMDB {res['tmdb_year']}")
        res["detail"] = (f"TMDB says '{res['tmdb_title']}' ({res['tmdb_year']}); "
                         f"local '{local_titles[0] if local_titles else '?'}' ({local_year or '?'}): "
                         + "; ".join(why))
    return res


def format_id_verify_report(rows):
    """Plain-text version of the verification results (for Save)."""
    L = [_i18n.t("rp.imdb_tmdb_id_verification_66f8", n=_n(len(rows), 'movie')),
         _i18n.t("rp.generated_8af8", strftime=datetime.datetime.now().strftime('%Y-%m-%d %H:%M')), "=" * 60, ""]
    cnt = collections.Counter((r.get("id_check") or {}).get("result", "?") for r in rows)
    for k in ID_RESULTS:
        if cnt.get(k):
            L.append(f"  {cnt[k]:5d}  {k}")
    L.append("")
    for r in sorted(rows, key=lambda x: (x.get("movie_name") or x.get("subfolder") or "").lower()):
        c = r.get("id_check") or {}
        L.append(f"{r.get('movie_name') or r.get('subfolder')}  [{r.get('movie_year', '-')}]  "
                 f"IMDb {c.get('imdb_id') or '—'}  TMDB {c.get('tmdb_id') or '—'}  →  {c.get('result', '?')}")
        if c.get("detail"):
            L.append(f"    {c['detail']}")
    return "\n".join(L)


class _SourceDisagreementDialog(_DialogBase):              ### UPDATED v0.16.0 ###
    """
    Case B popup: ID tags disagree — let user pick which ID is correct.
    Looks up title + year for each candidate ID via TMDB API and
    shows them alongside the ID so the user can identify the right one
    without opening a browser.
    """
    def __init__(self, parent, movie_name, id_type, values):
        super().__init__(parent)
        self.bind("<Escape>", lambda e: self.destroy())   ### NEW v0.19.2 B45 — Esc closes (nothing written) ###
        self.result_id = None
        self.cancelled = True
        self.title(_i18n.t("mc.normalize_id_conflict_5986", id_type=id_type))
        self.configure(bg=C_BG)
        self.resizable(True, False)
        self.transient(parent)
        self.minsize(520, 200)

        # ── Header ────────────────────────────────────────────────────────────
        tk.Label(self,
                 text=movie_name,
                 font=("Helvetica", 11, "bold"),
                 bg=C_BG, fg=C_TEXT).pack(padx=20, pady=(14, 2))
        tk.Label(self,
                 text=_i18n.t("mc.ids_disagree_across_tags_64ab", id_type=id_type),
                 bg=C_BG, fg=C_SUBTEXT,
                 font=("Helvetica", 9)).pack(padx=20, pady=(0, 8))

        # ── Radio frame with ID + title/year lookup ───────────────────────────
        rf = tk.Frame(self, bg=C_SURFACE); rf.pack(fill="x", padx=16, pady=4)
        self._var = tk.StringVar(value=values[0])
        color = "#f5c518" if id_type == "IMDB" else "#01d277"

        # Placeholder labels — filled in after async lookup
        self._row_labels = {}   # id_val → tk.Label for title/year

        for v in values:
            row = tk.Frame(rf, bg=C_SURFACE); row.pack(fill="x", padx=4, pady=3)
            tk.Radiobutton(row, text=v,
                           variable=self._var, value=v,
                           bg=C_SURFACE, fg=color, selectcolor=C_BG,
                           activebackground=C_SURFACE,
                           font=("Consolas", 10, "bold"),
                           width=14, anchor="w").pack(side="left", padx=(6, 4))
            lbl = tk.Label(row,
                           text=_i18n.t("mc.looking_up_402b"),
                           bg=C_SURFACE, fg=C_DIM,
                           font=("Helvetica", 9, "italic"), anchor="w")
            lbl.pack(side="left", fill="x", expand=True, padx=4)
            self._row_labels[v] = lbl

        # ── Buttons ───────────────────────────────────────────────────────────
        def _open_sites():
            for v in values:
                if id_type == "IMDB":
                    open_url_with_browser(f"https://www.imdb.com/title/{v}")
                else:
                    open_url_with_browser(f"https://www.themoviedb.org/movie/{v}")

        sep = tk.Frame(self, bg=C_SURFACE2, height=1)
        sep.pack(fill="x", padx=16, pady=(8,0))

        bf = tk.Frame(self, bg=C_BG); bf.pack(pady=(8, 14))
        tk.Button(bf, text=_i18n.t("mc.open_website_s_5cc9"),
                  bg=C_SURFACE2, fg=C_TEXT, relief="flat", cursor="hand2",
                  font=("Helvetica", 9), padx=8, pady=4,
                  command=_open_sites).pack(side="left", padx=6)
        tk.Button(bf, text="  OK  ",
                  bg=C_OK, fg=C_BG, relief="flat", cursor="hand2",
                  font=("Helvetica", 9, "bold"), padx=12, pady=4,
                  command=self._ok).pack(side="left", padx=6)
        tk.Button(bf, text=_i18n.t("mc.skip_1908"),
                  bg=C_SURFACE2, fg=C_TEXT, relief="flat", cursor="hand2",
                  font=("Helvetica", 9), padx=8, pady=4,
                  command=self.destroy).pack(side="left", padx=6)

        self.update_idletasks()
        x = parent.winfo_rootx() + (parent.winfo_width()  - self.winfo_width())  // 2
        y = parent.winfo_rooty() + (parent.winfo_height() - self.winfo_height()) // 2
        self.geometry(f"+{x}+{y}")

        # Kick off async lookups for each ID
        threading.Thread(
            target=self._lookup_all, args=(id_type, list(values)),
            daemon=True).start()
        _remember_window(self, "_SourceDisagreementDialog", resizable=True)   ### NEW v0.19.0 — window memory ###

    def _lookup_all(self, id_type, values):
        for v in values:
            title, year, err = _lookup_id_info_ex(id_type, v)          ### MODIFIED v0.19.1 B22 ###
            if title:
                text = f"{title}  ({year})" if year else title
            elif err:
                text = _i18n.t("mc.lookup_failed_tmdb_did_839b", err=err)
            elif not SETTINGS.get("tmdb_api_key", "").strip():         # C15
                text = _i18n.t("mc.not_checked_no_tmdb_1938")
            elif str(id_type).upper() == "IMDB":
                text = _i18n.t("mc.not_on_tmdb_may_6a3b")
            else:
                text = _i18n.t("mc.tmdb_has_no_movie_2341")
            _bad = bool(err) and not title                       # v0.20.0 AU23: the lookup failed
            def _update(lbl=self._row_labels.get(v), t=text, _bad=_bad):
                if lbl and lbl.winfo_exists():
                    lbl.configure(
                        text=t,
                        fg=C_ERR if _bad else C_TEXT,                       # v0.20.0 AU23: not by English words
                        font=("Helvetica", 9, "italic" if _bad else "normal"))
                    # Resize dialog to fit new content
                    self.update_idletasks()
            ui_post(_update)

    def _ok(self):
        self.result_id = self._var.get()
        self.cancelled = False
        self.destroy()


class _SourceManualEntryDialog(_DialogBase):               ### NEW v0.16.0 ###
    """Case C popup: all tags missing — ask user to type an ID."""
    def __init__(self, parent, movie_name, id_type, show_skip_all=False):  ### MODIFIED v0.19.0 ###
        self._id_type = id_type                                     # P3 (C8)
        super().__init__(parent)
        self.result_id = None
        self.cancelled = True
        self.skip_all  = False                                  ### NEW v0.19.0 ###
        self.title(_i18n.t("mc.enter_id_27d1", id_type=id_type))
        self.configure(bg=C_BG)
        self.resizable(False, False)
        self.transient(parent)

        pad = dict(padx=20, pady=6)
        tk.Label(self, text=f"{movie_name}",
                 font=("Helvetica", 11, "bold"),
                 bg=C_BG, fg=C_TEXT).pack(**pad)
        if id_type == "IMDB":
            example = _i18n.t("uf.e_g_tt_the_8b24")
            hint = _i18n.t("mc.imdb_ids_start_with_d4c0")
        else:
            example = _i18n.t("au.tmdb_example")
            hint = _i18n.t("mc.tmdb_ids_are_numeric_798d")
        tk.Label(self,
                 text=_i18n.t("mc.no_id_found_a0da", id_type=id_type, hint=hint, example=example),
                 bg=C_BG, fg=C_SUBTEXT,
                 font=("Helvetica", 10), justify="left").pack(**pad)

        self._entry_var = tk.StringVar()
        tk.Entry(self, textvariable=self._entry_var,
                 bg=C_SURFACE, fg=C_TEXT, insertbackground=C_TEXT,
                 font=("Consolas", 11), width=24, relief="flat").pack(**pad)

        bf = tk.Frame(self, bg=C_BG); bf.pack(pady=(4, 16))
        tk.Button(bf, text="  OK  ", bg=C_OK, fg=C_BG,
                  relief="flat", cursor="hand2",
                  command=self._ok).pack(side="left", padx=6)
        tk.Button(bf, text=_i18n.t("mc.skip_1908"), bg=C_SURFACE2, fg=C_TEXT,
                  relief="flat", cursor="hand2",
                  command=self.destroy).pack(side="left", padx=6)
        if show_skip_all:                                       ### NEW v0.19.0 ###
            tk.Button(bf, text=_i18n.t("mc.skip_all_remaining_868f"), bg=C_SURFACE2, fg=C_ERR,
                      relief="flat", cursor="hand2",
                      command=self._skip_all).pack(side="left", padx=6)
        self.bind("<Return>", lambda e: self._ok())
        self.bind("<Escape>", lambda e: self.destroy())             # P3 (C22)

        self.update_idletasks()
        x = parent.winfo_rootx() + (parent.winfo_width() - self.winfo_width()) // 2
        y = parent.winfo_rooty() + (parent.winfo_height() - self.winfo_height()) // 2
        self.geometry(f"+{x}+{y}")
        _remember_window(self, "_SourceManualEntryDialog", resizable=False)   ### NEW v0.19.0 — window memory ###

    def _skip_all(self):                                        ### NEW v0.19.0 ###
        self.skip_all = True
        self.destroy()

    def _ok(self):
        v = self._entry_var.get().strip()
        if v:
            clean, why = clean_typed_id(self._id_type, v)           ### NEW v0.19.4 P3 (C8) — checked like Enter ID ###
            if not clean:
                messagebox.showwarning(_i18n.t("mc.not_an_id_b740"), why, parent=self)
                return
            self.result_id = clean
            self.cancelled = False
        self.destroy()


