### NEW v0.20.1 SN3 — the activity indicator (the user, 2026-11-20: "something that is missing is an indication of
# activity ... the user might think it did not solve the problem"; "this shall be applied to ALL disk writing /
# refresh activities of the app so collection and movies"). Every background write or re-read is registered here
# (any thread); the Tk thread shows it: a turning ring on the panel's poster when the shown movie / collection is
# involved, a thin moving bar above the table and a status-bar line for anything, then ✓ Done or ! Not done.
class _ActivityRegistry:
    """Thread-safe: what is being written / re-read right now, and what just ended (for ✓ / !)."""

    def __init__(self):
        self._lock = threading.Lock()
        self._next = 0
        self._live = {}
        self._ended = []
        self._eseq = 0                                            # each end gets the next number (the ticker's cursor)
        self.waker = None                                         # set by the App: wakes its Tk ticker

    def begin(self, text="", paths=(), keys=()):
        with self._lock:
            self._next += 1
            tok = self._next
            self._live[tok] = {"text": text or "", "paths": {_pkey(p) for p in (paths or ()) if p},
                               "keys": set(keys or ()), "t": time.monotonic()}
        self._wake()
        return tok

    def end(self, tok, error=None):
        with self._lock:
            e = self._live.pop(tok, None)
            if e is None:
                return
            now = time.monotonic()
            self._eseq += 1
            e.update(end=now, error=(str(error) if error else None), eseq=self._eseq)
            self._ended = [x for x in self._ended if now - x["end"] < 60] + [e]
        self._wake()

    def live(self):
        with self._lock:
            return [dict(e) for e in self._live.values()]

    def ended_after(self, eseq):
        """The entries that ended after the cursor *eseq* (a job can start and end between two ticks)."""
        with self._lock:
            return [dict(e) for e in self._ended if e["eseq"] > eseq]

    def last_eseq(self):
        with self._lock:
            return self._eseq

    def _wake(self):
        w = self.waker
        if w is not None:
            try:
                ui_post(w)
            except (RuntimeError, tk.TclError):
                pass


_ACT = _ActivityRegistry()


class _activity:                                                  ### NEW v0.20.1 SN3 ###
    """with _activity(text, paths, keys): one registered write / re-read (any thread); an exception = "Not done"."""

    def __init__(self, text="", paths=(), keys=()):
        self.text, self.paths, self.keys, self.error = text, paths, keys, None

    def __enter__(self):
        self.tok = _ACT.begin(self.text, self.paths, self.keys)
        return self

    def __exit__(self, et, ev, tb):
        _ACT.end(self.tok, ev if ev is not None else self.error)
        return False


def act_targets(items, depth=0):                                  ### NEW v0.20.1 SN3 ###
    """Pure: (movie folders, collection keys) found in a job's items — rows, (row, …) tuples, (key, name, rows, …)
    groups, collection names. A movie also marks its collection (the collection panel shows its movies)."""
    paths, keys = set(), set()
    if depth > 3:
        return paths, keys
    for it in items or ():
        if isinstance(it, dict):
            if it.get("subfolder_path"):
                paths.add(it["subfolder_path"])
                k = _cr.group_key(it)
                if k:
                    keys.add(k)
        elif isinstance(it, (list, tuple, set)):
            p, k = act_targets(it, depth + 1)
            paths |= p; keys |= k
        elif isinstance(it, str) and it.strip() and depth == 0:
            if os.path.isabs(it):
                paths.add(it)
            else:
                keys.add(_cr.norm_name(it))
    return paths, keys


def act_label(label):                                             ### NEW v0.20.1 SN3 ###
    """A menu label / backup label → the short name shown while it works ("🗂  Fix Collection…" → "Fix Collection")."""
    s = shown_action(label) if label else ""
    s = str(s).split("  ", 1)[-1].strip()
    return s.rstrip("…").rstrip(".").strip()


ACT_SHOW_AFTER, ACT_MIN_SHOW, ACT_SETTLE, ACT_LINGER = 0.3, 0.6, 0.45, 1.6   # seconds (visual only)


def act_visual(busy, now, st, job=False):                         ### NEW v0.20.1 SN3 ###
    """Pure: the indicator's state for one target. *st* (a dict kept between ticks) holds since / shown / last_busy /
    until / result / err / job. Returns "idle", "wait" (busy, not shown yet: no flash of the ring), "busy", "done" or
    "error". A short gap between chained jobs (names → folder read → set.nfo → refresh) does not end it (ACT_SETTLE).
    *job*: an action the user started takes part — it always ends with ✓ / !, even when it was quick; a background
    re-read alone shows nothing unless it lasts (no ✓ blinking after every scan)."""
    if busy:
        st["last_busy"] = now
        if st.get("since") is None:
            st.update(since=now, shown=None, until=None, result=None, err=None, _job=False)
        if job:
            st["_job"] = True
        if st.get("shown") is None and now - st["since"] >= ACT_SHOW_AFTER:
            st["shown"] = now
        return "busy" if st.get("shown") is not None else "wait"
    if st.get("since") is not None:
        shown = st.get("shown")
        if now - st.get("last_busy", now) < ACT_SETTLE or (shown is not None and now - shown < ACT_MIN_SHOW):
            return "busy" if shown is not None else "wait"
        st["since"] = None
        if shown is None and not st.get("_job") and not st.get("err"):
            st.update(shown=None, until=None, result=None)
            return "idle"
        st.update(shown=None, until=now + ACT_LINGER, result="error" if st.get("err") else "done")
    if st.get("until") is not None and now < st["until"]:
        return st["result"]
    st.update(until=None, result=None, err=None)
    return "idle"


_NET_DRIVES = {}


def is_network_path(p):                                           ### NEW v0.20.1 SN3 ###
    """True for a UNC path or a mapped network drive (Windows); cached per drive."""
    p = str(p or "")
    if p.startswith("\\\\") or p.startswith("//"):
        return True
    if len(p) < 2 or p[1] != ":":
        return False
    d = p[0].upper()
    if d not in _NET_DRIVES:
        try:
            import ctypes
            _NET_DRIVES[d] = ctypes.windll.kernel32.GetDriveTypeW(f"{d}:\\") == 4   # DRIVE_REMOTE
        except Exception:
            _NET_DRIVES[d] = False
    return _NET_DRIVES[d]


_ACT_CACHE = {}
_ACT_IMG_N = __import__("itertools").count(1)                    # never reused, also after _ACT_CACHE.clear()


_ACT_FONTS = {}


def _act_font(size):
    """A PIL font for the poster's lines (loaded once per size)."""
    f = _ACT_FONTS.get(size)
    if f is not None:
        return f
    from PIL import ImageFont
    for name in ("segoeui.ttf", "arial.ttf", "DejaVuSans.ttf"):
        try:
            f = ImageFont.truetype(name, size)
            break
        except Exception:
            continue
    else:
        f = ImageFont.load_default()
    _ACT_FONTS[size] = f
    return f


def act_poster_frame(base, state, angle, lines, scale=1.0):        ### NEW v0.20.1 SN3 ###
    """PIL: the poster *base* darkened, with the turning ring (state "busy", *angle* in degrees), a ✓ ("done") or
    a ! ("error"), and up to 2 short lines below. Drawn 4× and scaled down: smooth edges."""
    from PIL import Image, ImageDraw
    w, h = base.size
    r = max(12, int(round(min(w, h) * 0.15)))
    cx, cy = w // 2, int(h * 0.42)
    S = 4
    lines = tuple(x for x in (lines or ()) if x)[:2]
    if "_act_n" not in base.info:                                # a number of its own (an id() can be reused)
        base.info["_act_n"] = next(_ACT_IMG_N)
    key = ("bg", base.info["_act_n"], w, h, lines, scale)        # the darkened poster with its text: drawn once
    im = _ACT_CACHE.get(key)
    if im is None:
        if len(_ACT_CACHE) > 200:
            _ACT_CACHE.clear()
        im = Image.blend(base.convert("RGB"), Image.new("RGB", (w, h), (17, 17, 27)), 0.62)
        if lines:
            d = ImageDraw.Draw(im)
            f1, f2 = _act_font(max(10, int(round(12 * scale)))), _act_font(max(9, int(round(11 * scale))))
            y = cy + r + int(10 * scale)
            for i, ln in enumerate(lines):
                f = f1 if i == 0 else f2
                words, cur, out = str(ln).split(), "", []
                for wd in words:                                  # break a line that is wider than the poster
                    t = (cur + " " + wd).strip()
                    if cur and d.textlength(t, font=f) > w - 12:
                        out.append(cur); cur = wd
                    else:
                        cur = t
                if cur:
                    out.append(cur)
                for o in out[:2]:
                    d.text((w // 2, y), o, fill=(235, 235, 245) if i == 0 else (180, 184, 205), font=f, anchor="mt")
                    y += int((16 if i == 0 else 15) * scale)
        _ACT_CACHE[key] = im
    im = im.copy()
    lkey = ("mark", state, int(angle) if state == "busy" else 0, r)
    mark = _ACT_CACHE.get(lkey)
    if mark is None:
        big = Image.new("RGBA", ((2 * r + 4) * S, (2 * r + 4) * S), (0, 0, 0, 0))
        d = ImageDraw.Draw(big)
        c, rr, th = (r + 2) * S, r * S, max(3, int(round(r * 0.18))) * S
        box = [c - rr, c - rr, c + rr, c + rr]
        dark_ink = (17, 17, 27, 255)
        if state == "busy":
            acc = tuple(int(C_ACCENT.lstrip("#")[i:i + 2], 16) for i in (0, 2, 4)) + (255,)
            d.ellipse(box, outline=(255, 255, 255, 46), width=th)
            d.arc(box, angle, angle + 100, fill=acc, width=th)
            for a in (angle, angle + 100):                        # round ends
                ex, ey = c + (rr - th / 2) * math.cos(math.radians(a)), c + (rr - th / 2) * math.sin(math.radians(a))
                d.ellipse([ex - th / 2, ey - th / 2, ex + th / 2, ey + th / 2], fill=acc)
        else:
            col = C_OK if state == "done" else C_ERR
            d.ellipse(box, fill=tuple(int(col.lstrip("#")[i:i + 2], 16) for i in (0, 2, 4)) + (255,))
            u = rr / 22.0
            if state == "done":
                d.line([(c - 10 * u, c + 1 * u), (c - 3 * u, c + 8 * u), (c + 11 * u, c - 8 * u)], fill=dark_ink,
                       width=max(S, int(4 * u)), joint="curve")
            else:
                d.line([(c, c - 11 * u), (c, c + 3 * u)], fill=dark_ink, width=max(S, int(4 * u)))
                d.ellipse([c - 2.5 * u, c + 7 * u, c + 2.5 * u, c + 12 * u], fill=dark_ink)
        mark = big.resize((2 * r + 4, 2 * r + 4), Image.LANCZOS)
        _ACT_CACHE[lkey] = mark
    im.paste(mark, (cx - r - 2, cy - r - 2), mark)
    return im


def _wait_off_tk(app, fn):                                        ### NEW v0.20.2 PB14 (audit) ###
    """Run *fn* (a backup + a write into a movie folder, perhaps on a sleeping NAS) in a tracked job thread while the
    window keeps drawing — Tk's wait_variable, the local event loop of a modal dialog — and give its result back here
    on the Tk thread, so the caller keeps its plain return value.  An exception in *fn* is raised here."""
    box, var = {}, tk.BooleanVar(master=app, value=False)

    def work():
        try:
            box["r"] = fn()
        except BaseException as e:                               # raised again on the Tk thread
            box["e"] = e
        finally:
            try:
                ui_post(lambda: var.set(True))
            except (RuntimeError, tk.TclError):
                pass
    _AppJobThread(app, target=work).start()
    try:
        app.wait_variable(var)
    except tk.TclError:                                          # the window was closed meanwhile
        pass
    if "e" in box:
        raise box["e"]
    return box.get("r")


def _alive_or(win, other):                                       ### NEW v0.20.2 PB14 (code check 1) ###
    """*win* when it still exists, else *other*: a dialog closed (Esc, X) during _wait_off_tk gets its message on
    the main window instead of a TclError."""
    try:
        return win if win.winfo_exists() else other
    except tk.TclError:
        return other


class _AppJobThread(threading.Thread):                           ### NEW v0.19.4 P2 (E15) ###
    """A long background action: counted in app._bg_running while it runs, so a Full / Quick Scan waits for it
    (a scan replaces every row the action is about to update).
    ### v0.20.1 SN3 ### also registered in _ACT (act_text / act_paths / act_keys: what the indicator shows)."""

    def __init__(self, app, *a, act_text=None, act_paths=(), act_keys=(), **k):
        k.setdefault("daemon", True)
        super().__init__(*a, **k)
        self._app = app
        self._act = (act_text, act_paths, act_keys)
        self._act_tok = None
        self.act_error = None

    def start(self):
        self._app._bg_running = getattr(self._app, "_bg_running", 0) + 1
        try:
            self._act_tok = _ACT.begin(self._act[0] or _i18n.t("sn3.working"), self._act[1], self._act[2])
        except Exception:
            self._act_tok = None
        super().start()

    def run(self):
        try:
            super().run()
        except BaseException as ex:
            self.act_error = self.act_error or str(ex) or type(ex).__name__
            raise
        finally:
            if self._act_tok is not None:
                _ACT.end(self._act_tok, self.act_error)
            try:
                ui_post(self._app._bg_done)
            except (RuntimeError, tk.TclError):
                pass


class _BatchJob:                                                 ### NEW v0.19.3 I7 ###
    """The skeleton every batch worker repeated, in one place: the progress
    window (from _PROGRESS_MIN items), Cancel, one backup folder for the run
    (I1 label), the error list, the changed folders → ONE _schedule_refresh,
    and the final message on the Tk thread.

        job = _BatchJob(app, items, "Label", progress_title="Doing…")
        job.run(step, finish)      # step(job, item) → True when changed; finish(job) on the Tk thread

    A step raises to report an error ("<name_of(item)>: <error>"), calls
    job.backup(name, *paths) before its first write, and appends the changed
    movie folder to job.changed."""

    def __init__(self, app, items, label, progress_title=None, prog=None, name_of=None, pausable=False):
        self.app, self.items, self.label = app, list(items), label
        if prog is None and progress_title and len(self.items) >= _PROGRESS_MIN:
            prog = _BatchProgressDialog(app, progress_title, total=len(self.items), pausable=pausable)   # v0.20.1 RV13
        self.prog = prog
        self.name_of = name_of or (lambda it: it.get("movie_name") or it.get("subfolder", ""))
        self.ref, self.done, self.errors, self.changed = [None], 0, [], []
        self.processed, self.was_cancelled = 0, False            ### NEW v0.19.4 B83 ###
        ### NEW v0.20.1 RV13 ### the loop runs in bulk_engine.run_steps; a step may raise _bulk.Skip(reason) (counted
        # in self.skipped, listed in self.skipped_items); checkpoint(job) every checkpoint_every items ("save as it goes")
        self.skipped, self.skipped_items = collections.Counter(), []
        self.checkpoint, self.checkpoint_every = None, 0

    def cancel_note(self):                                      ### NEW v0.19.4 B83 ###
        """For the result message: "" or "Cancelled after k of n …"."""
        ### MODIFIED v0.20.1 B20 ### also the lines of a service that stopped answering in this run (once, at the end)
        svc = getattr(self, "service_notes", None) or []
        tail = ("\n\n" + "\n".join(svc)) if svc else ""
        if not self.was_cancelled:
            return tail
        n = len(self.items)
        return (_i18n.t("uf.cancelled_after_of_left_cf3d", processed=self.processed, n=n, v=n - self.processed)) + tail

    def backup(self, name, *paths):
        return _batch_backup_ok(name, self.ref, *paths)

    def cancelled(self):
        # v0.20.1 T9: closing stops a batch; B20: so does Cancel in the "service is not answering" dialog (same thread)
        return bool(self.prog and self.prog.cancelled) or APP_CLOSING.is_set() or _service_run_cancelled()

    def paused(self):                                           ### NEW v0.20.1 RV13 ###
        return bool(self.prog and getattr(self.prog, "paused", False))

    def _work(self, step, finish):
        _ro0 = _sc.read_only_mark()                             ### NEW v0.20.0 RD1 ###
        ### MODIFIED v0.20.1 RV13 ### the loop is bulk_engine.run_steps (same order, Cancel, errors "<name>: <error>",
        # progress after every item); new: Pause, Skip reasons, checkpoints
        res = _bulk.run_steps(
            self.items, lambda item: step(self, item), name_of=self.name_of,
            control=_bulk.BulkControl(cancelled=self.cancelled, paused=self.paused),
            on_progress=(lambda k, n: self.prog.advance(k)) if self.prog else None,
            checkpoint=(lambda r: self.checkpoint(self)) if self.checkpoint else None,
            checkpoint_every=self.checkpoint_every)
        self.done, self.processed, self.was_cancelled = res.done, res.processed, res.cancelled
        self.errors.extend(res.errors)
        self.skipped, self.skipped_items = res.skipped, res.skipped_items
        self.service_notes = _service_run_summary()               # v0.20.1 B20: read before the service run ends
        if getattr(self, "after_steps", None):                   ### NEW v0.19.4 fix 15 — same worker, same backup run ###
            try:
                self.after_steps(self)
            except Exception as ex:
                self.errors.append(f"{self.label}: {ex}")
        if self.prog:
            self.prog.close()
        if self.errors and getattr(self, "_thread", None) is not None:   ### NEW v0.20.1 SN3 — "! Not done" ###
            self._thread.act_error = str(self.errors[0])
        self.app._schedule_refresh(list(dict.fromkeys(self.changed)), need_ffprobe=False)
        self.read_only = _sc.read_only_since(_ro0)              ### NEW v0.20.0 RD1 ###
        ui_post(lambda: (finish(self), self.offer_clear_read_only()))

    def offer_clear_read_only(self):                            ### NEW v0.20.0 RD1 ###
        """After the batch's own message: one question for every read-only file it met (Tk thread)."""
        ro = list(getattr(self, "read_only", None) or [])
        if not ro:
            return None
        n = len(ro)
        shown = "\n".join(ro[:8]) + (_i18n.t("m3.and_more", n=n - 8) if n > 8 else "")
        if not messagebox.askyesno(shown_action(self.label), _i18n.tn("m3.ro_ask", n, shown=shown, label=shown_action(self.label)),
                                   parent=self.app):
            return 0
        ok = sum(1 for p in ro if _sc.clear_read_only(p))
        bad = n - ok
        messagebox.showinfo(shown_action(self.label), _i18n.tn("m3.ro_done", n, ok=ok)
                            + (_i18n.t("m3.ro_bad", bad=bad) if bad else "")
                            + _i18n.tn("m3.ro_again", n, label=shown_action(self.label)), parent=self.app)
        return ok

    def run(self, step, finish):
        _go = lambda: _with_backup_action(self.label, self._work, step, finish)
        _around = getattr(self, "around", None)                   ### NEW v0.20.1 BF3 — e.g. a service run for online steps ###
        try:                                                      ### NEW v0.20.1 SN3 — what the indicator shows ###
            _ap, _ak = act_targets(self.items)
        except Exception:
            _ap, _ak = set(), set()
        self._thread = _AppJobThread(self.app, target=(lambda: _around(_go)) if _around else _go,
                                     act_text=act_label(self.label), act_paths=_ap, act_keys=_ak)
        self._thread.start()                                      # P2
        return self


class BackupHistoryDialog(_DialogBase):                          ### NEW v0.19.1 I1 ###
    """Tools → Backup History / Undo…: every backup run (newest first) with its
    files; "Restore this run" puts the files back (current files are backed
    up first, files changed since the run are listed and can be skipped)."""
    _COLS = (("created", "Date", 150), ("action", "Action", 230), ("movies", "Movies", 70),
             ("files", "Files", 60), ("state", "Restore", 260))           ### MODIFIED v0.19.4 B75 — was 170 ###

    def __init__(self, parent):
        super().__init__(parent)
        self._app = parent
        self._runs = []
        self.title(_i18n.t("mc.backup_history_undo_53dc"))
        self.configure(bg=C_BG)
        self.transient(parent)
        self.geometry("880x560"); self.minsize(700, 420)
        tk.Label(self, text=_i18n.t("mc.each_line_is_one_302a"),
                 bg=C_BG, fg=C_SUBTEXT, font=("Helvetica", 9)).pack(anchor="w", padx=14, pady=(10, 4))
        top = tk.Frame(self, bg=C_BG); top.pack(fill="both", expand=True, padx=12)
        self._tree = ttk.Treeview(top, columns=[c for c, _l, _w in self._COLS], show="headings", height=10)
        for c, l, w in self._COLS:
            self._tree.heading(c, text=_i18n.t("hd.bh." + c)); self._tree.column(c, width=w, anchor="w")   # v0.20.0 UI1e
        self._tree.pack(fill="both", expand=True)
        self._tree.bind("<<TreeviewSelect>>", lambda e: self._show_files())
        tk.Label(self, text=_i18n.t("mc.files_of_the_selected_dcff"), bg=C_BG, fg=C_TEXT,
                 font=("Helvetica", 9, "bold")).pack(anchor="w", padx=14, pady=(8, 2))
        self._files = tk.Text(self, height=8, bg=C_ROW_ALT, fg=C_TEXT, font=("Consolas", 9), wrap="char")   # v0.20.1 SN2: was "none"
        self._files.pack(fill="both", expand=False, padx=12)
        self._status = tk.Label(self, text=_i18n.t("mc.loading_5f02"), bg=C_BG, fg=C_SUBTEXT, font=("Helvetica", 9))
        self._status.pack(anchor="w", padx=14, pady=(4, 0))
        bf = tk.Frame(self, bg=C_BG); bf.pack(pady=(6, 12))
        self._restore_btn = tk.Button(bf, text=_i18n.t("mc.restore_this_run_fe79"), bg=C_PEACH, fg=C_BG,
                                      relief="flat", cursor="hand2", font=("Helvetica", 10, "bold"),
                                      state="disabled", command=self._restore)
        self._restore_btn.pack(side="left", padx=4)
        tk.Button(bf, text=_i18n.t("mc.open_folder_93ac"), bg=C_SURFACE2, fg=C_TEXT, relief="flat", cursor="hand2",
                  font=("Helvetica", 10), command=self._open_folder).pack(side="left", padx=4)
        tk.Button(bf, text=_i18n.t("mc.close_cbdd"), bg=C_SURFACE2, fg=C_TEXT, relief="flat", cursor="hand2",
                  font=("Helvetica", 10), command=self.destroy).pack(side="left", padx=4)
        self.bind("<Escape>", lambda e: self.destroy())
        _remember_window(self, "BackupHistoryDialog", resizable=True)
        self.load()

    # listing (worker thread — many folders on a network share)
    def load(self, sync=False):
        def _work():
            runs = _sc.list_backup_runs(_BACKUP_ROOT)
            for r in runs:                                       # v0.20.2 PA5: a file under a folder renamed later is followed
                _mv = lambda r=r, c={}: c.setdefault("m", _sc.moved_folders_after(_BACKUP_ROOT, r.get("created", ""),
                                                                                  exclude=r.get("folder")))
                r["changed"] = [f["original"] for f in r["files"] if _sc.file_changed_since_run(f, _mv)]
            def _ui():
                try:
                    if self.winfo_exists():
                        self._fill(runs)
                except tk.TclError:
                    pass
            if sync:
                _ui()
            else:
                ui_post(_ui)
        if sync:
            _work()
        else:
            threading.Thread(target=_work, daemon=True).start()

    def _fill(self, runs):
        self._runs = runs
        self._tree.delete(*self._tree.get_children())
        for i, r in enumerate(runs):
            if r.get("removed"):                                        ### NEW v0.19.4 B75 ###
                vals = (r["created"], r["action"], r.get("movies") or "—", r.get("n_files") or "—",
                        _i18n.t("uf.removed_by_the_size_946b", removed=r['removed']))
            elif r["legacy"]:
                vals = (r["created"], _i18n.t("au.bh.legacy"), "—", r.get("n_files", "—"), _i18n.t("uf.legacy_manual_restore_only_e290"))
            else:
                st = _i18n.t("au.bh.changed", n=len(r['changed'])) if r["changed"] else _i18n.t("au.bh.ready")
                vals = (r["created"], r["action"], r["movies"], len(r["files"]), st)
            self._tree.insert("", "end", iid=str(i), values=vals)
        self._status.configure(text=_i18n.t("mc.in_a552", n=_n(len(runs), 'backup run'), backup_root=_BACKUP_ROOT))   # v0.19.4 B105
        if runs:
            self._tree.selection_set("0")

    def selected_run(self):
        sel = self._tree.selection()
        return self._runs[int(sel[0])] if sel else None

    def _show_files(self):
        r = self.selected_run()
        self._files.delete("1.0", "end")
        if not r:
            self._restore_btn.configure(state="disabled"); return
        if r.get("removed"):                                            ### NEW v0.19.4 B75 ###
            self._files.insert("end", _i18n.t("uf.the_automatic_size_cleanup_3ad8", removed=r['removed']))
            self._restore_btn.configure(state="disabled"); return
        if r["legacy"]:
            self._files.insert("end", _i18n.t("uf.this_backup_was_made_c189"))
            self._restore_btn.configure(state="disabled"); return
        for f in r["files"]:
            mark = _i18n.t("uf.changed_since_the_run_be16") if f["original"] in r["changed"] else ""
            if f.get("moved_to"):                                ### NEW v0.20.2 RN — a rename only (nothing copied) ###
                self._files.insert("end", f"{f['moved_to']}   ({_i18n.t('rn.bh.was', name=os.path.basename(f['original']))}){mark}\n")
                continue
            self._files.insert("end", f"{f['original']}   ({f['backup']}){mark}\n")
        self._restore_btn.configure(state="disabled" if getattr(self, "_restoring", False) else "normal")   # v0.20.0 AU12

    def _open_folder(self):
        r = self.selected_run()
        if r and r.get("folder"):                                       ### MODIFIED v0.19.4 B75 — a removed run has none ###
            os_open(r["folder"])

    def ask_skip_changed(self, changed):
        """UI: files changed since the run → which to skip.  Returns a set, or
        None to cancel (tests replace this)."""
        ans = messagebox.askyesnocancel(
            _i18n.t("mc.restore_files_changed_since_ed96"),
            _i18n.tn("m3.changed_after", len(changed), files=_n(len(changed), "file"))
            + "\n".join(os.path.basename(x) for x in changed[:12])
            + ("\n…" if len(changed) > 12 else "")
            + _i18n.t("m3.cd_restore_choice"), parent=self)
        if ans is None:
            return None
        return set() if ans else set(changed)

    def _restore(self, sync=False):
        r = self.selected_run()
        if (not r or r["legacy"] or r.get("removed") or getattr(self, "_restoring", False)   ### MODIFIED v0.19.4 B75 ###
                or getattr(self._app, "_restoring", False)):    # v0.20.2 PA8: one restore at a time in the APP (two windows)
            return                                              # v0.20.0 AU12: one restore at a time
        _rv = getattr(self._app, "_review_win", None)            ### NEW v0.20.1 A29 — the review's own run is still open ###
        try:
            _rv_open = _rv is not None and bool(_rv.winfo_exists())
        except tk.TclError:
            _rv_open = False
        if _rv_open:
            messagebox.showinfo(_i18n.t("mc.restore_this_run_e863"), _i18n.t("bh.review_open"), parent=self)
            return
        skip = set()
        if r["changed"]:
            skip = self.ask_skip_changed(r["changed"])
            if skip is None:
                return
        elif not sync and not messagebox.askyesno(
                _i18n.t("mc.restore_this_run_e863"), _i18n.t("mc.put_back_as_they_1ccd", n=_n(len(r['files']), 'file'), action=r['action'], created=r['created']), parent=self):
            return
        self._restore_btn.configure(state="disabled", text=_i18n.t("mc.restoring_b0d2"))
        self._restoring = True                                   # v0.20.0 AU12: picking another run re-enabled the button
        self._app._restoring = True                              # v0.20.2 PA8
        def _work():
            try:
                restored, errors, safety = _sc.restore_backup_run(_BACKUP_ROOT, r["folder"], skip, logger=logger)
            except Exception as ex:                              # v0.20.0 AU12: never stuck at "Restoring…"
                logger.error(f"Restore failed: {ex}")
                restored, errors, safety = [], [str(ex)], None
            try:                                                 # v0.20.2 code check 2: a failure here never leaves
                movie_dirs = sorted({os.path.dirname(x) for x in restored})   # "one restore at a time" stuck on
                ### NEW v0.20.2 RN — a folder renamed back: its row follows first (the same queue as the refresh) ###
                _rs = {os.path.normcase(x) for x in restored}
                _back = [(f["moved_to"], f["original"]) for f in reversed(r["files"])
                         if f.get("moved_to") and os.path.normcase(f["original"]) in _rs]
                if _back:
                    ui_post(lambda st=_back: self._app._rn_repath(st))
                    movie_dirs += [b for a, b in _back if os.path.isdir(b)]
                self._app._schedule_refresh(movie_dirs, need_ffprobe=False)
            except Exception as ex:
                logger.error(f"Restore: the table was not refreshed: {ex}")
                errors = list(errors) + [str(ex)]
            def _ui():
                self.last_result = (restored, errors, safety)
                self._restoring = False
                self._app._restoring = False                     # v0.20.2 PA8
                try:
                    if self.winfo_exists():
                        self._restore_btn.configure(text=_i18n.t("mc.restore_this_run_fe79"))
                        self.load()
                except tk.TclError:
                    pass
                msg = _i18n.t("mc.restored_b4ac", n=_n(len(restored), 'file'))
                if skip:
                    msg += _i18n.t("mc.skipped_c4b6", n=_n(len(skip), 'changed file'))   # v0.19.4 B105
                if safety:
                    msg += _i18n.t("mc.the_files_as_they_e084", safety=safety)
                if errors:
                    msg += _i18n.t("mc.errors_83c4", join="\n".join(errors[:8]))
                messagebox.showinfo(_i18n.t("mc.restore_2bd3"), msg, parent=self._app)
            if sync:
                _ui()
            else:
                ui_post(_ui)
        if sync:
            _work()
        else:
            _AppJobThread(self._app, target=_work).start()       # v0.20.2 PA8: close asks and waits; a scan waits


class _PauseAskDialog(_DialogBase):                              ### NEW v0.19.1 B22 ###
    """A paused service is needed: message + advice, [Try anyway] [Cancel]."""
    def __init__(self, parent, service, entry):
        super().__init__(parent)
        self.result = False
        label = _SERVICE_LABEL.get(service, service)
        try:
            until = datetime.datetime.fromisoformat(entry["until"]).strftime("%H:%M")
        except Exception:
            until = "?"
        self.text = (_i18n.t("au.paused_until", label=label, until=until) + "\n\n"
                     f"{api_failure_message(service, entry.get('kind')) if entry.get('kind') else entry.get('message') or ''}")
        self.title(_i18n.t("mc.online_service_paused_593b"))
        self.configure(bg=C_BG); self.transient(parent); self.resizable(False, False)
        tk.Label(self, text=self.text, bg=C_BG, fg=C_WARN, font=("Helvetica", 10),
                 justify="left", wraplength=440).pack(padx=18, pady=(16, 10))
        bf = tk.Frame(self, bg=C_BG); bf.pack(pady=(0, 14))
        tk.Button(bf, text=_i18n.t("mc.try_anyway_3bc4"), bg=C_PEACH, fg=C_BG, relief="flat", cursor="hand2",
                  font=("Helvetica", 10, "bold"), command=self._try).pack(side="left", padx=4)
        tk.Button(bf, text=_i18n.t("mc.cancel_2fee"), bg=C_SURFACE2, fg=C_TEXT, relief="flat", cursor="hand2",
                  font=("Helvetica", 10), command=self.destroy).pack(side="left", padx=4)
        self.bind("<Escape>", lambda e: self.destroy())
        _remember_window(self, "_PauseAskDialog", resizable=False)

    def _try(self):
        self.result = True
        self.destroy()


class _ServiceFailureDialog(_DialogBase):                        ### NEW v0.19.1 B22 ###
    """First failure of a service in a batch run: message + advice and
    [Pause this run] [Continue with the other source / without <service>] [Cancel]."""
    def __init__(self, parent, service, kind, other_label=None):
        super().__init__(parent)
        self.result = "continue"
        label = _SERVICE_LABEL.get(service, service)
        self.text = api_failure_message(service, kind)
        self.title(_i18n.t("mc.not_available_409c", label=label))
        self.configure(bg=C_BG); self.transient(parent); self.resizable(False, False)
        _modal(self)                                             ### NEW v0.19.4 B98 — its buttons answer; the grab goes back ###
        tk.Label(self, text=self.text, bg=C_BG, fg=C_WARN, font=("Helvetica", 10),
                 justify="left", wraplength=460).pack(padx=18, pady=(16, 6))
        tk.Label(self, text=_i18n.t("mc.this_is_asked_once_269e"), bg=C_BG, fg=C_DIM,
                 font=("Helvetica", 8)).pack(padx=18)
        bf = tk.Frame(self, bg=C_BG); bf.pack(pady=(10, 14))
        self.buttons = {}
        secs = API_PAUSE_SECONDS.get(kind)
        if secs:
            until = (datetime.datetime.now() + datetime.timedelta(seconds=secs)).strftime("%H:%M")
            self.buttons["pause"] = tk.Button(bf, text=_i18n.t("mc.pause_this_run_until_135e", until=until),
                                              bg=C_PEACH, fg=C_BG, relief="flat", cursor="hand2",
                                              font=("Helvetica", 9, "bold"), command=lambda: self._go("pause"))
        cont = "  " + (_i18n.t("uf.m.continue_with", other=other_label) if other_label   # v0.20.0 UI1f
                       else _i18n.t("uf.m.continue_without", service=label)) + "  "
        self.buttons["continue"] = tk.Button(bf, text=cont, bg=C_OK, fg=C_BG, relief="flat",
                                             cursor="hand2", font=("Helvetica", 9, "bold"),
                                             command=lambda: self._go("continue"))
        self.buttons["cancel"] = tk.Button(bf, text=_i18n.t("mc.cancel_2fee"), bg=C_SURFACE2, fg=C_TEXT, relief="flat",
                                           cursor="hand2", font=("Helvetica", 9), command=lambda: self._go("cancel"))
        for b in self.buttons.values():
            b.pack(side="left", padx=4)
        self.protocol("WM_DELETE_WINDOW", lambda: self._go("continue"))
        _remember_window(self, "_ServiceFailureDialog", resizable=False)

    def _go(self, what):
        self.result = what
        self.destroy()


class _HardsubDialog(_DialogBase):                              ### NEW v0.19.1 B15 ###
    """Right-click → Hard-coded subtitles…: the user ticks the language(s)
    burned into the picture (common list + "Other…" ISO 639-2 codes).
    on_done(sorted codes) is called on Apply; Cancel / [X] calls nothing."""
    def __init__(self, parent, movie_names, current=(), on_done=None):
        super().__init__(parent)
        self.result = None
        self._on_done = on_done
        n = len(movie_names)
        self.title(_i18n.t("mc.hard_coded_subtitles_034f"))
        self.configure(bg=C_BG)
        self.transient(parent); self.resizable(False, False)
        head = movie_names[0] if n == 1 else f"{_n(n, 'movie')}"
        tk.Label(self, text=head, bg=C_BG, fg=C_ACCENT, font=("Helvetica", 11, "bold"),
                 wraplength=460).pack(padx=18, pady=(14, 2))
        tk.Label(self, text=_i18n.t("mc.tick_the_subtitle_language_fe64"),
                 bg=C_BG, fg=C_SUBTEXT, font=("Helvetica", 9), justify="center").pack(padx=18, pady=(0, 8))
        cur = {c.upper() for c in current}
        known = [c for c, _lang_name in SUBTITLE_LANGUAGES]   # v0.19.4 B105: _n is the plurals helper
        g = tk.Frame(self, bg=C_BG); g.pack(padx=18)
        self._vars = {}
        for i, (code, name) in enumerate(SUBTITLE_LANGUAGES):
            v = tk.BooleanVar(value=code in cur); self._vars[code] = v
            tk.Checkbutton(g, text=f"{code}  {name}", variable=v, bg=C_BG, fg=C_TEXT,
                           selectcolor=C_SURFACE, activebackground=C_BG, activeforeground=C_TEXT,
                           font=("Helvetica", 9), anchor="w", width=20).grid(row=i // 3, column=i % 3, sticky="w")
        of = tk.Frame(self, bg=C_BG); of.pack(padx=18, pady=(8, 0), fill="x")
        tk.Label(of, text=_i18n.t("mc.other_iso_e_g_e3e7"), bg=C_BG, fg=C_TEXT,
                 font=("Helvetica", 9)).pack(side="left")
        self._other_var = tk.StringVar(value=", ".join(sorted(c for c in cur if c not in known)))
        tk.Entry(of, textvariable=self._other_var, width=18, font=("Consolas", 10), bg=C_SURFACE, fg=C_TEXT,
                 insertbackground=C_TEXT, relief="flat").pack(side="left", padx=6)
        self._msg = tk.Label(self, text="", bg=C_BG, fg=C_ERR, font=("Helvetica", 9))
        self._msg.pack(padx=18, pady=(4, 0))
        if n > 1:
            tk.Label(self, text=_i18n.t("mc.each_selected_movie_gets_4e89"),
                     bg=C_BG, fg=C_WARN, font=("Helvetica", 9, "italic")).pack(padx=18)
        tk.Label(self, text=_i18n.t("mc.hs.written"),                       # v0.20.0 UI1e
                 bg=C_BG, fg=C_DIM, font=("Helvetica", 8)).pack(padx=18, pady=(4, 0))
        bf = tk.Frame(self, bg=C_BG); bf.pack(pady=(10, 14))
        for txt, bg, fg, cmd in ((_i18n.t("mc.hs.apply"), C_OK, C_BG, self._apply),       # v0.20.0 UI1e
                                 (_i18n.t("mc.hs.none"), C_PEACH, C_BG, self._none),
                                 (_i18n.t("mc.hs.cancel"), C_SURFACE2, C_TEXT, self.destroy)):
            tk.Button(bf, text="  " + txt + "  ", bg=bg, fg=fg, relief="flat", cursor="hand2",
                      font=("Helvetica", 10, "bold"), command=cmd).pack(side="left", padx=4)
        self.bind("<Escape>", lambda e: self.destroy())
        self.update_idletasks()
        try:
            x = parent.winfo_rootx() + (parent.winfo_width() - self.winfo_width()) // 2
            y = parent.winfo_rooty() + (parent.winfo_height() - self.winfo_height()) // 2
            self.geometry(f"+{max(0, x)}+{max(0, y)}")
        except Exception:
            pass
        _remember_window(self, "_HardsubDialog", resizable=False)

    def selected(self):
        """Ticked codes + the 'Other…' codes, or None when an Other code is invalid."""
        codes = {c for c, v in self._vars.items() if v.get()}
        for tok in re.split(r"[\s,;]+", self._other_var.get().strip()):
            if not tok:
                continue
            if not re.fullmatch(r"[A-Za-z]{3}", tok):
                self._msg.configure(text=_i18n.t("mc.is_not_a_letter_449b", tok=tok))
                return None
            codes.add(tok.upper())
        return sorted(codes)

    def _none(self):
        for v in self._vars.values():
            v.set(False)
        self._other_var.set("")

    def _apply(self):
        codes = self.selected()
        if codes is None:
            return
        self.result = codes
        self.destroy()
        if self._on_done:
            self._on_done(codes)


def backdrop_count_message(local_n, online_n, source="TMDB", n=None):   ### NEW v0.19.1 B17; n v0.19.3 B61 ###
    """(text, button label, warn) for the Replace All Backdrops confirmation.
    ### v0.19.3 B61 ### with *n* (the number the user chose) the text says
    how many will be downloaded: the n with the highest resolution."""
    if n is not None:
        n = max(0, min(int(n), online_n))
        best = _i18n.t("rp.the_best_one_874d") if n == 1 else _i18n.t("rp.the_with_the_highest_2183", n=n)
        head = _i18n.t("mc.you_have_offers_523c", n=_n(local_n, 'backdrop'), source=source, online_n=online_n)
        if n < local_n:
            return _i18n.t("rp.you_will_get_fewer_fc0f", head=head, n=n, best=best, v=local_n - n), _i18n.t("rp.replace_anyway_b193"), True
        gain = n - local_n
        return (head + _i18n.t("uf.you_will_get_88b8", n=n, best=best) + (_i18n.t("au.gain", n=gain) if gain else _i18n.t("uf.the_same_number_da6b")),
                _i18n.t("rp.replace_0ebe"), False)
    if online_n < local_n:
        return (_i18n.t("rp.you_have_offers_replacing_13ba", n=_n(local_n, 'backdrop'), source=source, online_n=online_n, online_n2=online_n, v=local_n - online_n),
                _i18n.t("rp.replace_anyway_b193"), True)
    gain = online_n - local_n
    extra = _i18n.t("rp.more_7c5d", gain=gain) if gain else _i18n.t("rp.the_same_number_77ca")
    return (_i18n.t("rp.you_have_offers_replacing_4645", n=_n(local_n, 'backdrop'), source=source, online_n=online_n, online_n2=online_n, extra=extra), _i18n.t("rp.replace_0ebe"), False)


### NEW v0.19.3 I6 — preview texts (pure) ###
def sources_preview_text(rows):
    """Normalize Sources — All: what happens to each movie's IMDb / TMDB IDs."""
    L = [_i18n.t("rp.normalize_sources_27f0", n=_n(len(rows), 'movie')), "=" * 60, ""]
    for r in rows:
        L.append(f"\U0001f4c1  {r.get('movie_name') or r.get('subfolder', '?')}")
        for k, lbl in (("imdb", "IMDb"), ("tmdb", "TMDB")):
            st = r.get(f"source_{k}_status")
            vals = [v for v in (r.get(f"source_{k}_all") or []) if v]
            if st == STATUS_OK:
                continue
            if st == STATUS_MISSING or not vals:
                L.append(_i18n.t("rp.no_id_you_will_c16f", lbl=lbl))
            elif len(set(vals)) == 1:
                L.append(_i18n.t("rp.copied_to_the_tags_29e5", lbl=lbl, v=vals[0]))
            else:
                L.append(_i18n.t("rp.the_ids_differ_you_1265", lbl=lbl, join=' / '.join(dict.fromkeys(vals))))
        L.append("")
    return "\n".join(L)


def copy_poster_preview_text(rows):
    """Copy poster → folder: every folder.jpg that will be overwritten (or created)."""
    L = [_i18n.t("rp.copy_poster_jpg_folder_340d", n=_n(len(rows), 'movie')), _i18n.t("rp.every_folder_jpg_is_8a9e"), "=" * 60, ""]
    for r in rows:
        name = r.get("movie_name") or r.get("subfolder", "?")
        new = f"{os.path.basename(r.get('poster_path') or 'poster.jpg')} ({r.get('poster_size', '—')})"
        if r.get("folder_exists"):
            L.append(f"  {name}:  folder.jpg ({r.get('folder_size', '—')}) ← {new}")
        else:
            L.append(_i18n.t("rp.no_folder_jpg_created_87c6", name=name, new=new))
    return "\n".join(L)


def genres_preview_text(rows):
    """Normalize Genres — All, the part decided without going online."""
    changes, same = [], 0
    for r in rows:
        cur = list(r.get("genres") or [])
        if not cur:
            continue
        try:
            new, _c = normalize_genre_list(cur)
        except Exception:
            continue
        if list(new) != cur or r.get("genre_only_in_xml") or r.get("genre_only_in_nfo") or r.get("genre_nfo_wrong_tags"):
            changes.append(f"  {r.get('movie_name') or r.get('subfolder', '?')}:  {' / '.join(cur)}  →  {' / '.join(new)}")
        else:
            same += 1
    n_none = sum(1 for r in rows if not r.get("genres"))
    L = [_i18n.t("rp.normalize_genres_41b5", n=_n(len(rows), 'movie')), "=" * 60, "",
         _i18n.t("rp.will_be_changed_nfo_29e6", n=_n(len(changes), 'movie')), ""]
    L += changes or ["  (none)"]
    L += ["", f"{_n(same, 'movie')} {'is' if same == 1 else 'are'} already normalized."]
    if n_none:
        L.append(f"{_n(n_none, 'movie')} {'has' if n_none == 1 else 'have'} no genres: they are looked up online (with a TMDB key) and shown in a second preview.")
    return "\n".join(L)


def ratings_preview_text(pending):
    """Sync Ratings — All: [(row, name, nfo, xml, (rating, votes, source)), …] current → new."""
    L = [_i18n.t("rp.sync_ratings_will_be_077b", n=_n(len(pending), 'movie')), "=" * 60, ""]
    for d, name, _nfo_, _x, ch in pending:                    # v0.19.4 B105: _n is the plurals helper
        L.append(_i18n.t("rp.votes_votes_7b03", name=name, get=d.get('rating_str', '-'), v=d.get('votes_int') or '-', v2=ch[0], v3=ch[1], v4=ch[2]))
    return "\n".join(L)


def _ask_preview(app, title, text, file_stem, run_label):
    """Tk thread: show the preview and wait; True = Run."""
    pv = _PreviewRunDialog(app, title, text, file_stem=file_stem, run_label=run_label)
    app._last_preview = pv
    app.wait_window(pv)
    return bool(pv.run)


def view_rows(results, view):                                    ### NEW v0.19.3 I4 — pure (worker-safe) ###
    """The table rows for *view* = (sort spec, filter text, health filter,
    library filter): sorted (B63: up to 3 levels, empty last, tie-break
    never reversed) and filtered (view-only; *results* is never modified)."""
    spec, term, hf, lf = view
    sorted_results = _se.sort_rows(results, spec, SORT_VALUE_FNS, _sort_name_key, _sort_year_key)
    def _hf_ok(r):
        st = r.get("health_status", "warning")
        if hf == "problems": return st != "ok"
        if hf in ("error", "warning"): return st == hf
        return True
    lfk = _pkey(lf) if lf else None
    def _lib_ok(r):
        return lfk is None or _pkey(r.get("library_root") or os.path.dirname(r.get("subfolder_path") or "")) == lfk
    return [r for r in sorted_results if _hf_ok(r) and _lib_ok(r) and _matches_filter(r, term)]


