### NEW v0.20.0 UI1a — the fix of a health reason by the code of its rule (one meaning per rule; "" = no fix).
# Rules that give reasons with different fixes (images, IDs, collections, file content …) are not listed: their
# reasons still go through the text checks below until UI1c gives each reason its own code.
_FIX_KEY_BY_CODE = {
    "title_mismatch": "title", "duplicate_movie": "dup", "video_quality_minimum": "video", "nfo_name_not_kodi": "nfo_name",
    "id_not_kodi": "uniqueid",                                   # v0.20.1 BF2: its own tool (was "auto", KR1.1)
    "id_wrong": "ids_wrong", "id_check": "ids_search",           # v0.20.1 T2 / R8
    "cert_settings": "cert",                                     # v0.20.2 CR
    "xml_tags_old_readers": "auto",                              # v0.20.0 KR1.4: Auto Repair adds the tags
    # v0.20.1 R7: no_actor_info is mapped by its text (only "links" has a fix: Download Actor Photos)
    "lang_not_ok": "audio", "required_audio_language": "audio_none",                  # v0.20.1 R7
    "required_subtitle_language": ("subs_find", "subs"),
    "missing_nfo": "xml2nfo",                                                          # v0.20.1 L1
    "genre_warning": "genres", "genre_only_in_xml": "genres", "genre_only_in_nfo": "genres", "genre_nfo_wrong_tags": "genres",
    "genre_missing": "genres_fill", "missing_movie_year": "year_fill",
    "profile_names_unread": "media_rename",                      # v0.20.0 F3c / F3c2: the renamer
    "nfo_online_art_links": "art_links",                         # v0.20.0 RD9
    "missing_fanart": "fanart", "insufficient_backdrops": "backdrops", "backdrop_too_small": "backdrops",   # no_audio_tracks: by text (L1)
    "poster_folder_identical": "copy",
    "rating_conflict": "ratings", "votes_conflict": "ratings", "missing_rating": "ratings", "rating_warning": "ratings",
    "suspicious_rating": "ratings", "missing_votes": "ratings", "votes_warning": "ratings",
}


def _fix_issue_keys(row, settings=None):
    """Pure: the issue keys of one row, from its health reasons and errors."""
    keys = set()
    for r in (row.get("health_reasons") or []):
        _k = _FIX_KEY_BY_CODE.get(reason_code(r), None)          ### NEW v0.20.0 UI1a — the rule's code first ###
        if _k is not None:
            if _k:
                keys.update(_k if isinstance(_k, tuple) else (_k,))   # v0.20.1 R7: a reason may have two entries
            if _k == "xml2nfo" and not row.get("xml_exists"):         # v0.20.1 L1: only with a movie.xml to convert
                keys.discard("xml2nfo")
            continue
        lo = r.lower()
        ### NEW v0.20.1 R7 / L1 — reasons whose fix depends on their text ###
        if r.startswith("Actor photos only as web links"):
            keys.add("actors")
            continue
        if r.startswith(("No actor information", "The actors in the NFO have no photos")):   # nothing to download: no fix entry
            continue
        if r == FFPROBE_FAILED_TEXT:
            keys.add("ffprobe")
            continue
        if "is not a year" in r or "is out of range (1888" in r:
            keys.add("year_fill")
            continue
        if r == "Missing folder image" and row.get("poster_exists"):
            keys.add("copy")                                        # offline: the poster becomes folder.jpg
        if r.startswith("Poster/folder quality below minimum") and row.get("poster_exists"):
            keys.add("replace_posters")
        # v0.20.1: the same keys for a reason without a code (UI1a: a cached row gives the same fixes)
        if r.startswith(("IMDb field holds", "TMDB field holds")):
            keys.add("ids_wrong"); continue
        if r.startswith("Verify IMDb/TMDB IDs:"):
            keys.add("ids_search"); continue
        if r == "Missing genre information":
            keys.add("genres_fill"); continue
        if r.startswith(("Genre issues detected", "NFO has no <genre>", "XML has no <Genre>", "NFO uses non-Kodi genre tags")):
            keys.add("genres"); continue
        if r.startswith("Missing movie year"):
            keys.add("year_fill"); continue
        if r == "Missing NFO file":
            if row.get("xml_exists"):
                keys.add("xml2nfo")
            continue
        if r.startswith("Required audio language"):
            keys.add("audio_none"); continue
        if r.startswith("Required subtitle language"):
            keys.update(("subs_find", "subs")); continue
        if "only in <imdbid> / <tmdbid> — Kodi reads <uniqueid>" in r:   ### MODIFIED v0.20.1 BF2 — its own tool ###
            keys.add("uniqueid")
        elif "only in movie.xml tags the old programs ignore" in r:
            keys.add("auto")                                    # v0.20.0 KR1.4: first ("votes", "ID" are in the text)
        elif r.startswith("Collection folder:"):              ### NEW v0.19.4 fix 15 ###
            keys.add("collection_old")
        elif r.startswith("Collection artwork:"):             ### NEW v0.19.4 B110g ###
            keys.add("collection_art")
        elif r.startswith("Collection: movie.xml"):          ### NEW v0.19.4 fix 6 ###
            keys.add("collection_xml")
        elif r.startswith("Collection:") and ("no longer exists on TMDB" in r or "is not listed by TMDB" in r):   ### NEW v0.19.4 fix 3c ###
            keys.add("collection_gone")
        elif r.startswith("Collection:"):                     ### NEW v0.19.4 B110c ###
            keys.add("collection")
        elif r.startswith("Title mismatch"):                  ### NEW v0.19.3 B60 — first: the titles may hold any word ###
            keys.add("title")
        elif r.startswith("Possible duplicate"):              ### NEW v0.19.3 B64 ###
            keys.add("dup")
        elif r.startswith("Video quality below minimum"):     ### NEW v0.19.3 B71 — was listed as an IMAGE problem ###
            keys.add("video")
        elif r.startswith("NFO named after the folder"):      ### NEW v0.19.3 B73 ###
            keys.add("nfo_name")
        elif r in ("Missing poster", "Missing folder image") or r.startswith(("Corrupt poster image", "Corrupt folder image",
                                                                                "Missing poster (only folder")):   # P4 (C18)
            keys.add("poster")
        elif r.startswith("Corrupt fanart image"):                 # P4 (C18)
            keys.add("fanart")
        elif r == "No audio tracks detected":                      # P4 (C18): no Fix for it (not Subtitles…)
            pass
        elif r == "Missing fanart":
            keys.add("fanart")
        elif "backdrop" in lo:
            keys.add("backdrops")
        elif "proportions" in lo or "quality below minimum" in lo or "below minimum size" in lo:
            keys.add("images")
        elif r.startswith("Poster and folder image are different"):
            keys.add("copy")
        elif ("imdb id" in lo or "tmdb id" in lo) and "missing" in lo:
            keys.add("ids_search")
        elif ("imdb id" in lo or "tmdb id" in lo) and ("one file only" in lo or "empty in others" in lo or "conflict" in lo):
            keys.add("ids_norm")
        # v0.20.1 R3: no text branch to Verify (it only checks; a wrong value has its own reason and fix, ids_wrong;
        # a bad Verify result is the id_check reason → Search Sources; junk around an ID → Auto Repair's struct_fix)
        elif "rating" in lo or "votes" in lo:
            keys.add("ratings")
        elif "audio" in lo:
            keys.add("audio")
        elif "subtitle" in lo:
            keys.add("subs")
    if row.get("nfo_errors"):
        keys.add("nfo_err")
    if row.get("xml_errors"):
        keys.add("xml_err")
    try:
        if _auto_repair_plan(row, settings):
            keys.add("auto")
    except Exception:
        pass
    return keys


### NEW v0.20.1 AR2 — the Auto Repair line says what it really does (the user, 2026-11-20: with one problem only (no
# uniqueid) the panel showed that fix AND "Auto Repair can fix more"; both did the same single fix, so "more" was wrong).
# Each Auto Repair step → the Fix line that does the same job (None: only Auto Repair does it).
AR_STEP_FIX_KEY = {"ids_wrong": "ids_wrong", "ids_resolve": "ids_norm", "ids_search": "ids_search", "ids_partial": "ids_norm",
                   "ids_kodi": "uniqueid", "ratings": "ratings", "genres": "genres", "genres_tmdb": "genres_fill",
                   "year_tmdb": "year_fill", "title_copy": "title", "title_sync": "title", "collection": "collection",
                   "nfo_name": "nfo_name", "xml_tags": None, "struct_fix": None, "amp_fix": None}


def auto_repair_summary(rows, keys_of, settings=None):
    """Pure: the Auto Repair line for *rows* — {"show", "first", "label", "tip", "rows"}. *keys_of(row)* = the row's
    Fix-line keys. One unit per Fix line Auto Repair would do (two steps of the same line count once) plus one per
    step no other line does. Hidden when everything it does is ONE line already listed; with one row it says how many
    of the movie's fixes it does ("Fix all 3 at once" / "Fix 3 of 5 at once"), with several rows "N fixes on M movies"."""
    T = _i18n.t
    per, codes_all = [], []
    for r in rows:
        try:
            plan = [c for c, _l in _auto_repair_plan(r, settings)]
        except Exception:
            plan = []
        if not plan:
            continue
        keys = set(keys_of(r)) - {"auto"}
        units, seen = [], set()
        for c in plan:
            k = AR_STEP_FIX_KEY.get(c)
            u = ("line", k) if k and k in keys else ("step", c)
            if u not in seen:
                seen.add(u); units.append((u, c))
        per.append((r, keys, units, plan))
        codes_all.extend(plan)
    out = {"show": False, "first": False, "label": "", "tip": "", "rows": [p[0] for p in per]}
    if not per:
        return out
    if all(len(u) == 1 and u[0][0][0] == "line" for _r, _k, u, _p in per) and len({u[0][0] for _r, _k, u, _p in per}) == 1:
        return out                                                # it would only repeat the one line above it
    short = lambda c: T("ar.short." + c)
    if len(per) == 1:
        _r, keys, units, plan = per[0]
        n = len(units)
        m = len(keys) + sum(1 for u, _c in units if u[0] == "step")
        names = [short(c) for _u, c in units]
        shown = ", ".join(names[:4]) + (f" +{len(names) - 4}" if len(names) > 4 else "")
        if n == 1:
            out["label"] = T("fix.auto_one", what=names[0])
        elif n >= m:
            out["label"] = T("fix.auto_all", n=n, names=shown)
        else:
            out["label"] = T("fix.auto_some", n=n, m=m, names=shown)
        out["tip"] = "\n".join("• " + _AR_LABELS.get(c, c) for c in plan)
        out["first"] = n >= 2
    else:
        total = sum(len(u) for _r, _k, u, _p in per)
        out["label"] = T("fix.auto_multi", fixes=_n(total, "fix"), movies=_n(len(per), "movie", ","))
        cnt = collections.Counter(codes_all)
        out["tip"] = "\n".join(f"• {_AR_LABELS.get(c, c)} — {_n(cnt[c], 'movie', ',')}" for c in AR_STEP_ORDER if c in cnt)
        out["first"] = True
    out["show"] = True
    return out


def ctx_fix_issues(rows, settings=None):                        ### NEW v0.19.2 B57 ###
    """[(key, label, rows_with_that_problem)] in a fixed order, for the menu.
    ### v0.20.1 AR2 ### the Auto Repair line: hidden when it only repeats one line, else first, with what it does."""
    by, keys_by = {}, {}
    for r in rows:
        ks = _fix_issue_keys(r, settings)
        keys_by[id(r)] = ks
        for k in ks:
            by.setdefault(k, []).append(r)
    out = [(k, _FIX_ISSUE_LABELS[k], by[k]) for k in _FIX_ISSUE_ORDER if k in by and k != "auto"]
    if "auto" in by:
        s = auto_repair_summary(by["auto"], lambda r: keys_by.get(id(r), ()), settings)
        if s["show"]:
            item = ("auto", s["label"], s["rows"] or by["auto"])
            out = [item] + out if s["first"] else out + [item]
    return out


def ctx_fix_tip(rows, settings=None):                            ### NEW v0.20.1 AR2 ###
    """The tooltip of the Auto Repair line: each step it runs (and on how many movies)."""
    keys_by = {id(r): _fix_issue_keys(r, settings) for r in rows}
    return auto_repair_summary(rows, lambda r: keys_by.get(id(r), ()), settings)["tip"]


