    # ── Column header double-click (auto-size) ────────────────────────────────
    def _on_header_dblclick_guard(self, col_id):
        ### FIX v0.17.2-bug3 — skip auto-size if a resize drag just finished ###
        if self._col_resize_just_ended:
            self._col_resize_just_ended = False
            return
        now = time.time()
        last = self._hdr_click_time.get(col_id, 0)
        job = getattr(self, "_hdr_sort_job", None)               ### NEW v0.19.3 B63 ###
        if now - last < 0.35:
            if job:                                            # a double-click: no sort, only auto-size
                try:
                    self.tk.call("after", "cancel", job)
                except tk.TclError:
                    pass
                self._hdr_sort_job = None
            self._auto_size_col(col_id)
        else:
            shift = bool(getattr(self, "_hdr_shift", False))
            self._hdr_sort_job = self.after(360, lambda c=col_id, sh=shift: self._heading_sort(c, sh))
        self._hdr_click_time[col_id] = now

    # ── v0.19.3 B63: the sort builder ──────────────────────────────────────────
    def _heading_sort(self, col_id, shift=False):                 ### NEW v0.19.3 B63 ###
        self._hdr_sort_job = None
        self._apply_sort(_se.click_heading(self._sort_spec, col_id, shift))

    def _apply_sort(self, spec, refresh=True):                    ### NEW v0.19.3 B63 ###
        self._sort_spec = _se.clean_spec(spec)
        SETTINGS["sort_spec"] = [dict(l) for l in self._sort_spec]
        SETTINGS["sort_option"] = _se.old_text_for(self._sort_spec)   # older versions still read it
        try:
            self.sort_var.set(_se.describe(self._sort_spec, sort_labels()))
            self._render_sort_row()
        except tk.TclError:
            pass
        if refresh:
            self._refresh_table()

    def _render_sort_row(self):                                   ### NEW v0.19.3 B63 ###
        fr = self._sort_levels_fr
        for w in fr.winfo_children():
            w.destroy()
        lab = sort_labels()
        keys = list(_se.MENU_KEYS)                                ### MODIFIED v0.19.3 B69 — Health first ###
        labels = [lab[k] for k in keys]
        btn = dict(font=("Helvetica", 9, "bold"), relief="flat", cursor="hand2")
        for i, lvl in enumerate(self._sort_spec):
            tk.Label(fr, text=_i18n.t("sort.by") if i == 0 else _i18n.t("sort.then_by"), font=("Helvetica", 10), bg=C_BG,
                     fg=C_SUBTEXT).pack(side="left", padx=(0 if i == 0 else 10, 4))
            cb = ttk.Combobox(fr, values=labels, state="readonly", width=_sort_combo_width(labels), font=("Helvetica", 10))   # v0.20.0 UI1c
            cb.set(lab[lvl["key"]])
            cb.pack(side="left")
            cb.bind("<<ComboboxSelected>>", lambda e, i=i, c=cb: self._sort_set_key(i, keys[labels.index(c.get())]))
            tk.Button(fr, text=f" {_se.dir_label(lvl['key'], lvl['dir'])}  ⇅ ", bg=C_SURFACE2, fg=C_WARN,
                      command=lambda i=i: self._sort_toggle(i), **btn).pack(side="left", padx=(4, 0))
            if i > 0:
                tk.Button(fr, text=" ✕ ", bg=C_BG, fg=C_SUBTEXT, command=lambda i=i: self._sort_remove(i),
                          **btn).pack(side="left", padx=(2, 0))
        if len(self._sort_spec) < _se.MAX_LEVELS:
            tk.Button(fr, text=f" {_i18n.t('sort.add_then')} ", bg=C_BG, fg=C_ACCENT, command=self._sort_add,
                      **btn).pack(side="left", padx=(10, 0))
        ### NEW v0.19.3 B72 — "Update View" back (v0.19.2 "Update Sort"), after the last level ###
        self._update_view_btn = tk.Button(fr, text=f" {_i18n.t('sort.update_view')} ", bg=C_SURFACE2, fg=C_TEXT,
                                          command=self._refresh_table, **btn)
        self._update_view_btn.pack(side="left", padx=(10, 0))
        _add_btn_tooltip(self._update_view_btn, _i18n.t("sort.update_view.tip"))

    def _sort_set_key(self, i, key):                              ### NEW v0.19.3 B63 ###
        spec = [dict(l) for l in self._sort_spec]
        ### MODIFIED v0.20.0 AU10 (pre-build audit) ### a level removed BEFORE i shifts i: A, B, C with B set to A gave
        # [B, A] (C lost, B kept) instead of [A, C]
        if not 0 <= i < len(spec):
            return
        new, ni = [], 0
        for j, l in enumerate(spec):
            if j == i:
                ni = len(new); new.append(l)                     # the level being set
            elif l["key"] != key:
                new.append(l)                                    # a level using *key* elsewhere moves here
        spec = new
        spec[ni] = {"key": key, "dir": _se.default_dir(key)}
        self._apply_sort(spec)

    def _sort_toggle(self, i):                                    ### NEW v0.19.3 B63 ###
        spec = [dict(l) for l in self._sort_spec]
        spec[i]["dir"] = _se.next_dir(spec[i]["key"], spec[i]["dir"])
        spec[i].pop("empty", None)
        self._apply_sort(spec)

    def _sort_remove(self, i):                                    ### NEW v0.19.3 B63 ###
        if 0 < i < len(self._sort_spec):
            self._apply_sort([l for j, l in enumerate(self._sort_spec) if j != i])

    def _sort_add(self):                                          ### NEW v0.19.3 B63 ###
        used = {l["key"] for l in self._sort_spec}
        key = next((k for k, _l, _kd in _se.ALL_KEYS if k not in used), None)
        if key and len(self._sort_spec) < _se.MAX_LEVELS:
            self._apply_sort(self._sort_spec + [{"key": key, "dir": _se.default_dir(key)}])

    def _all_presets(self):                                       ### NEW v0.19.3 B63 ###
        user = [p for p in (SETTINGS.get("sort_presets") or []) if isinstance(p, dict) and p.get("name")]
        return list(_se.BUILTIN_PRESETS) + user

    def _apply_preset_index(self, n):                             ### NEW v0.19.3 B63 ###
        if getattr(self, "_part", None) not in (None, "movies"):   # v0.20.0 AU17: the Movies part only (as Ctrl+A, I14)
            return
        presets = self._all_presets()
        if 0 <= n < len(presets):
            self._apply_sort(presets[n]["levels"])
            try:
                self.stats_var.set(_i18n.t("sort.preset_status", name=presets[n]["name"]))
            except Exception:
                pass
        return "break"

    def _build_presets_menu(self):                                ### NEW v0.19.3 B63 ###
        m = tk.Menu(self, tearoff=0, bg=C_SURFACE, fg=C_TEXT, activebackground=C_HOVER,
                    activeforeground=C_TEXT)
        presets = self._all_presets()
        n_b = len(_se.BUILTIN_PRESETS)
        m.add_command(label=_i18n.t("sort.menu.builtin"), state="disabled")
        for i, p in enumerate(presets):
            if i == n_b:
                m.add_separator()
                m.add_command(label=_i18n.t("sort.menu.mine"), state="disabled")
            m.add_command(label=f"{p['name']}   —   {_se.describe(p['levels'], sort_labels(), prefix=False)}",
                          accelerator=f"Ctrl+{i + 1}" if i < 9 else "", command=lambda i=i: self._apply_preset_index(i))
        m.add_separator()
        m.add_command(label=_i18n.t("sort.menu.save"), command=lambda: SortPresetDialog(self, "save"))
        m.add_command(label=_i18n.t("sort.menu.manage"), command=lambda: SortPresetDialog(self, "manage"),
                      state="normal" if len(presets) > n_b else "disabled")
        m.add_command(label=_i18n.t("sort.menu.back", level=f"{_se.LABEL['movie_name']} ({_se.dir_label('movie_name', 'asc')})"),
                      command=self._apply_default_sort)
        self._presets_menu = m
        return m

    def _post_presets_menu(self):                                 ### NEW v0.19.3 B63 ###
        m, b = self._build_presets_menu(), self._presets_btn
        try:
            m.tk_popup(b.winfo_rootx(), b.winfo_rooty() + b.winfo_height())
        finally:
            try:
                m.grab_release()
            except tk.TclError:
                pass

    def _update_heading_marks(self):                              ### NEW v0.19.3 B63 ###
        marks = _se.heading_marks(self._sort_spec)
        iso = SETTINGS.get("lang_ok_code", "PT")
        for col in COLUMN_MODEL:
            base = lang_ok_heading(iso) if col["label"] == "LANG_OK_LABEL" else col["label"]   # v0.20.0 UI1c
            mk = marks.get(col["id"])
            try:
                self.tree.heading(col["id"], text=f"{base}  {mk}" if mk else base)
            except tk.TclError:
                pass

    AUTO_SIZE_MEASURE_MAX = 40   ### NEW v0.20.0 RD2 — the longest texts measured per column ###

    def _auto_size_fit(self, col_ids):                            ### NEW v0.20.0 RD2 ###
        """Auto-size *col_ids* in one pass over the visible rows.  v0.19.6 measured every cell of every column on
        the Tk thread (a new Font per column, one Tcl measure per cell): on 1,706 movies "Auto Size Columns" froze the
        window (Reddit tester, 2026-11-14).  Now each row is read once, each column keeps its distinct first lines,
        and only the AUTO_SIZE_MEASURE_MAX longest (by characters) are measured: the same widths on a small table,
        a time that no longer grows with the number of measured cells."""
        font_obj = getattr(self, "_auto_size_font", None)
        if font_obj is None:
            font_obj = self._auto_size_font = tk_font.Font(root=self, font=("Helvetica", 10))
        cols = list(self.tree["columns"])
        want = [(c, cols.index(c)) for c in col_ids if c in cols]
        texts = {c: set() for c, _i in want}
        for iid in self._visible_iids():                         ### v0.19.4 B110h ###
            vals = self.tree.item(iid, "values")
            for c, idx in want:
                if idx < len(vals):
                    texts[c].add(str(vals[idx]).split("\n")[0])
        for c, _i in want:
            maxw = font_obj.measure(self.tree.heading(c)["text"]) + 24
            longest = sorted(texts[c], key=len, reverse=True)[:self.AUTO_SIZE_MEASURE_MAX]
            for cell in longest:
                w = font_obj.measure(cell) + 24
                if w > maxw:
                    maxw = w
            self.tree.column(c, width=min(maxw, 800))

    def _auto_size_col(self, col_id):
        self._auto_size_fit([col_id])

    def _auto_size_all(self):
        self._auto_size_fit(list(self.tree["columns"]))         # MODIFIED v0.20.0 RD2 — one pass, not one per column

    def _fit_heading(self, col_id, w):                          ### NEW v0.19.6 TR8 ###
        """*w*, or wider when the heading would be cut off. The model widths fit Windows' heading
        font (B120); Linux draws "Helvetica" with a wider font, so "Backdrops" or "Video Size" were cut."""
        try:
            f = tk_font.Font(root=self, font=ttk.Style(self).lookup("Treeview.Heading", "font"))
            lab = str(self.tree.heading(col_id, "text")).split("  ")[0]
            return max(int(w), f.measure(lab) + 12)   # the B120 margin
        except (tk.TclError, ValueError):
            return w

    def _default_col_widths(self):                              ### NEW v0.19.4 fix 2c ###
        """↺ Default Widths: every column back to its model width (the grouped view keeps the Year span visible)."""
        for col in COLUMN_MODEL:
            try:
                self.tree.column(col["id"], width=self._fit_heading(col["id"], px(col["width"])))   # v0.19.6 TR8
            except tk.TclError:
                pass
        if self._grouped():
            self._year_w_ungrouped = px(COLUMN_MODEL[COL_YEAR]["width"])
            self._year_fit()

    # ── v0.19.4 fix 2a: the Year column in the grouped view ──
    def _year_fit_width(self):
        f = tk_font.Font(font=("Helvetica", 10))                 # the font _auto_size_col measures with
        return max(f.measure("8888–8888"), f.measure(str(self.tree.heading("year")["text"]))) + 24

    def _year_fit(self):
        try:
            base = getattr(self, "_year_w_ungrouped", None) or int(self.tree.column("year", "width"))
            self.tree.column("year", width=max(int(base), self._year_fit_width()))
        except (tk.TclError, ValueError, TypeError):
            pass

    def _year_on_group(self, grouped):
        """Grouping on: remember the user's Year width and widen it for "1979–1986"; off: the width back."""
        prev = getattr(self, "_last_grouped", None)
        if grouped == prev:
            return
        self._last_grouped = grouped
        try:
            if grouped:
                if getattr(self, "_year_w_ungrouped", None) is None:
                    self._year_w_ungrouped = int(self.tree.column("year", "width"))
                self._year_fit()
            elif prev and getattr(self, "_year_w_ungrouped", None):
                self.tree.column("year", width=int(self._year_w_ungrouped))
                self._year_w_ungrouped = None
        except (tk.TclError, ValueError, TypeError):
            pass

    # ── Keyboard navigation ───────────────────────────────────────────────────
    def _safe_index(self, children, iid):                          ### NEW v0.19.4 (D7) ###
        """The position of *iid* among the visible rows; a movie hidden in a closed collection counts as its
        collection row (or the first row) — it used to raise an error."""
        children = list(children)
        if iid in children:
            return children.index(iid)
        try:
            p = self.tree.parent(iid)
            if p in children:
                return children.index(p)
        except tk.TclError:
            pass
        return 0

    def _kb_navigate(self, event):
        children = self._visible_iids()                          ### v0.19.4 B110h ###
        if not children: return
        sel = self._sel_iids()
        if not sel:
            first = children[0]
            self.tree.selection_set(first); self.tree.see(first); return
        cur_idx = self._safe_index(children, sel[-1])            # D7
        key = event.keysym
        if key == "Prior":  new_idx = max(0, cur_idx - self._page_rows())                ### MODIFIED v0.19.1 ###
        elif key == "Next": new_idx = min(len(children)-1, cur_idx + self._page_rows())
        elif key == "Home": new_idx = 0
        elif key == "End":  new_idx = len(children)-1
        else: return
        target = children[new_idx]
        self.tree.selection_set(target); self.tree.see(target)
        self._sel_anchor = None; self._sel_active_idx = None   ### v0.19.1 — next Shift starts here ###
        return "break"

    ### NEW v0.13.1 — Jump-to-letter / digit on the Movie Name column ###
    @staticmethod
    def _strip_diacritics(s):
        """ASCII-fold a string for case-insensitive prefix matching.
        'Ångström' -> 'Angstrom', 'Abril Despedaçado' -> 'Abril Despedacado'.
        """
        if not s:
            return ""
        nfkd = unicodedata.normalize("NFKD", s)
        return "".join(c for c in nfkd if not unicodedata.combining(c))

    ### NEW v0.17.2 — Jump-to-Letter Final Fix ###
    def _update_sel_count(self):                                  ### NEW v0.19.1 B21 ###
        """Status bar: "N selected" when more than one row is selected."""
        try:
            n = len(self._selected_movie_iids())                 ### v0.19.4 B110h — a collection row = its movies ###
            self._sb_sel.configure(text="  " + _i18n.t("sb.selected", n=_i18n.num(n)) if n > 1 else "")
        except tk.TclError:
            pass

    def _select_all_visible(self, event=None):                    ### NEW v0.19.1 B21 ###
        """Ctrl+A: select every visible (filtered) row.  Not while a text box
        (Filter box, any Entry/Text/Spinbox/Combobox) has the focus — there
        Ctrl+A keeps working on the text."""
        try:
            fw = self.focus_get()
        except Exception:
            fw = None
        if fw is not None and isinstance(fw, (tk.Entry, tk.Text, tk.Spinbox, ttk.Entry, ttk.Combobox)):
            return None
        kids = self._view_movie_iids()                           ### v0.19.4 B110h — also inside closed collections ###
        if not kids:
            return "break"
        self.tree.selection_set(kids)
        self.tree.focus(kids[0])
        self._reset_sel_anchor()
        self._update_sel_count()
        return "break"

    def _kb_jump_to_letter(self, event):
        """Jump selection to the next row whose movie name starts with the
        pressed key (A–Z, a–z, 0–9).  Cycles per-character on repeat press.

        Strategy (v0.17.2):
        - Bound to BOTH self.tree and self (App root) to cover all focus cases.
        - Guard: skip if any text-input widget (Entry/Text/Combobox/Spinbox) has focus.
        - Use event.keysym as primary char source (works even when event.char is empty).
        - Per-character index dict for cycling (spec-compliant state management).
        """
        if getattr(self, "_part", None) not in (None, "movies"):   # v0.20.0 AU17: the Movies part only (as Ctrl+A, I14)
            return
        # ── Guard 1: skip if fired from a text-input widget ───────────────────
        # This preserves normal typing in search boxes, spinboxes, etc.
        try:
            focused = self.focus_get()
            if focused is not None:
                cls = focused.__class__.__name__
                if cls in ("Entry", "Text", "Spinbox") or \
                        isinstance(focused, (tk.Entry, tk.Text, tk.Spinbox)):
                    return
                # Also skip ttk Entry/Combobox
                try:
                    import tkinter.ttk as _ttk
                    if isinstance(focused, (_ttk.Entry, _ttk.Combobox, _ttk.Spinbox)):
                        return
                except Exception:
                    pass
        except Exception:
            pass

        # ── Guard 2: skip modifier combos (Ctrl, Alt, Cmd) ───────────────────
        # Do NOT include 0x8 — on Windows this is NumLock/Mod1 and is set
        # on plain letter keypresses, blocking all jump-to-letter input.  ### FIX v0.17.3 ###
        modifier_mask = 0x4 | 0x20000  # Ctrl | Alt only
        if event.state & modifier_mask:
            return

        # ── Guard 3: skip if no data is loaded ───────────────────────────────
        if not self._results:
            return

        # ── Resolve the character ─────────────────────────────────────────────
        # Use keysym first (always populated), fall back to event.char
        # keysym for letters: "a".."z", "A".."Z", digits: "0".."9"
        ch = ""
        ks = event.keysym or ""
        if len(ks) == 1 and (ks.isalpha() or ks.isdigit()):
            ch = ks
        elif event.char and len(event.char) == 1 and \
                (event.char.isalpha() or event.char.isdigit()):
            ch = event.char

        if not ch:
            return

        target = self._strip_diacritics(ch).upper()
        if not target or not (target.isalpha() or target.isdigit()):
            return

        # ── Build match list ──────────────────────────────────────────────────
        children = self._visible_iids()                          ### v0.19.4 B110h ###
        if not children:
            return "break"

        matches = []
        for iid in children:
            d = self._item_map.get(iid)
            if not d:
                if iid not in self._coll_map:                       # D13: a collection row by its name
                    continue
                name = str(self._coll_map[iid][1] or "").lstrip()
            else:
                name = (d.get("movie_name") or d.get("subfolder") or "").lstrip()
            folded = self._strip_diacritics(name).upper().lstrip()
            if folded and folded[0] == target:
                matches.append(iid)

        if not matches:
            return "break"

        # ── Per-char cycling index ────────────────────────────────────────────
        if target != self._jump_last_char:
            # Different key pressed → reset this char's index
            self._jump_index[target] = 0
            self._jump_last_char = target
        else:
            # Same key → advance
            cur = self._jump_index.get(target, 0)
            self._jump_index[target] = (cur + 1) % len(matches)

        idx = self._jump_index.get(target, 0)
        if idx >= len(matches):
            idx = 0
            self._jump_index[target] = 0
        next_iid = matches[idx]

        # ── Apply ─────────────────────────────────────────────────────────────
        self.tree.selection_set(next_iid)
        self.tree.focus(next_iid)
        self.tree.see(next_iid)
        self._jump_last_iid = next_iid
        return "break"
    ### END v0.17.2 — Jump-to-Letter Final Fix ###

    def _shift_up(self, event):                                ### REWRITTEN v0.17.0 ###
        """Shift+Up: shrink bottom of selection toward anchor, or extend above anchor."""
        children = self._visible_movie_iids()                    ### v0.19.4 B110h — skips collection rows ###
        if not children: return "break"
        sel = [i for i in self._sel_iids() if i in self._item_map]
        if not sel: return "break"

        # Initialise anchor on first Shift press — anchor stays at the clicked row
        self._sel_check(children, sel)                           # v0.20.0 AU10
        if self._sel_anchor is None:
            self._sel_anchor = self._safe_index(children, sel[0])   # D7
        if self._sel_active_idx is None:
            self._sel_active_idx = self._safe_index(children, sel[-1])   # D7

        anchor = self._sel_anchor
        new_active = max(0, self._sel_active_idx - 1)
        self._sel_active_idx = new_active

        # Continuous range between anchor and new active end
        lo = min(anchor, new_active)
        hi = max(anchor, new_active)
        self.tree.selection_set(children[lo:hi + 1])
        self._sel_last = (tuple(children[lo:hi + 1]), tuple(children))   # v0.20.0 AU10
        self.tree.see(children[new_active])
        return "break"

    def _shift_down(self, event):                              ### REWRITTEN v0.17.0 ###
        """Shift+Down: extend bottom of selection downward from anchor."""
        children = self._visible_movie_iids()                    ### v0.19.4 B110h — skips collection rows ###
        if not children: return "break"
        sel = [i for i in self._sel_iids() if i in self._item_map]
        if not sel: return "break"

        self._sel_check(children, sel)                           # v0.20.0 AU10
        if self._sel_anchor is None:
            self._sel_anchor = self._safe_index(children, sel[0])   # D7
        if self._sel_active_idx is None:
            self._sel_active_idx = self._safe_index(children, sel[-1])   # D7

        anchor = self._sel_anchor
        new_active = min(len(children) - 1, self._sel_active_idx + 1)
        self._sel_active_idx = new_active

        lo = min(anchor, new_active)
        hi = max(anchor, new_active)
        self.tree.selection_set(children[lo:hi + 1])
        self._sel_last = (tuple(children[lo:hi + 1]), tuple(children))   # v0.20.0 AU10
        self.tree.see(children[new_active])
        return "break"

    def _page_rows(self):                                      ### NEW v0.19.1 ###
        """Rows visible in the table (page size for PageUp/PageDown)."""
        try:
            rh = int(ttk.Style(self).lookup("Treeview", "rowheight") or 26)
            return max(1, self.tree.winfo_height() // max(rh, 1) - 1)
        except Exception:
            return 20

    def _shift_page(self, event):                              ### NEW v0.19.1 ###
        """Shift+PageUp/PageDown/Home/End: extend the selection from the anchor
        by one page or to the first/last row (same anchor logic as Shift+Up/Down)."""
        children = self._visible_movie_iids()                    ### v0.19.4 B110h — skips collection rows ###
        if not children: return "break"
        sel = [i for i in self._sel_iids() if i in self._item_map]
        if not sel:
            self.tree.selection_set(children[0]); return "break"
        self._sel_check(children, sel)                           # v0.20.0 AU10
        if self._sel_anchor is None:
            self._sel_anchor = self._safe_index(children, sel[0])   # D7
        if self._sel_active_idx is None:
            self._sel_active_idx = self._safe_index(children, sel[-1])   # D7
        page = self._page_rows()
        k = event.keysym
        if k == "Prior":  new_active = max(0, self._sel_active_idx - page)
        elif k == "Next": new_active = min(len(children) - 1, self._sel_active_idx + page)
        elif k == "Home": new_active = 0
        elif k == "End":  new_active = len(children) - 1
        else: return None
        self._sel_active_idx = new_active
        lo, hi = min(self._sel_anchor, new_active), max(self._sel_anchor, new_active)
        self.tree.selection_set(children[lo:hi + 1])
        self._sel_last = (tuple(children[lo:hi + 1]), tuple(children))   # v0.20.0 AU10
        self.tree.see(children[new_active])
        return "break"

    def _sel_check(self, children, sel):                         ### NEW v0.20.0 AU10 (pre-build audit) ###
        """The Shift anchor is a list position: it is only valid while the selection and the row order are the ones
        the last Shift key left.  A letter jump, plain Up / Down or a re-sort / filter used to leave it stale, and the
        next Shift+Down selected rows the user never picked (and a right-click action then ran on them)."""
        if getattr(self, "_sel_last", None) != (tuple(sel), tuple(children)):
            self._sel_anchor = None
            self._sel_active_idx = None

    def _reset_sel_anchor(self, event=None):                   ### NEW v0.16.1 ###
        """Reset anchor on plain single click so next Shift starts fresh."""
        self._sel_anchor     = None
        self._sel_active_idx = None                            ### NEW v0.17.0 ###

    # ── Custom column resize ──────────────────────────────────────────────────
    def _col_resize_start(self, event):                        ### FIX v0.17.0-bug3 ###
        """On Button-1 on a separator: snapshot ALL column widths as baseline."""
        region = self.tree.identify_region(event.x, event.y)
        if region != "separator":
            self._col_resize_state = {}
            return
        col_id = self.tree.identify_column(event.x)
        if not col_id or col_id == "#0":                          ### v0.19.4 fix 2b — the grouped view's tree column ###
            self._col_resize_state = {}
            return
        try:
            col_idx  = self._model_col_index(int(col_id.lstrip("#")) - 1)   ### v0.18.4 ###
            all_cols = self.tree.cget("columns")
            col_name = all_cols[col_idx]
        except Exception:
            self._col_resize_state = {}
            return
        # Snapshot widths BEFORE built-in handler runs
        snapshot = {c: self.tree.column(c, "width") for c in all_cols}
        self._col_resize_state = {
            "col":      col_name,
            "start_x":  event.x,
            "start_w":  snapshot[col_name],
            "snapshot": snapshot,
            "all_cols": all_cols,
        }

    def _col_resize_drag(self, event):                         ### FIX v0.17.0-bug3 ###
        """On every B1-Motion: built-in has just modified adjacent columns.
        Restore all OTHER columns to their pre-drag widths so only the
        target column changes size."""
        st = self._col_resize_state
        if not st:
            return
        col      = st["col"]
        dx       = event.x - st["start_x"]
        new_w    = max(30, st["start_w"] + dx)
        snapshot = st["snapshot"]
        # Restore every column EXCEPT the target to its pre-drag width
        for c, w in snapshot.items():
            if c != col:
                try:
                    self.tree.column(c, width=w)
                except Exception:
                    pass
        # Set the target column to the dragged width
        self.tree.column(col, width=new_w)
        ### v0.19.4 fix 2b — this binding runs BEFORE the Treeview class binding (widget tag first): without
        ### "break" Tk's own resize then moved the neighbour column on every motion (jumpy) ###
        return "break"

    def _col_resize_end(self, event):                          ### FIX v0.17.0-bug3 ###
        """On mouse-up: apply the final width, clear state."""
        st = self._col_resize_state
        self._col_resize_state = {}
        if not st:
            return
        # v0.19.4 fix 2b: "break" below keeps the class binding (and so the heading command) from running,
        # so _col_resize_just_ended (FIX v0.17.2-bug3) is no longer set here
        col   = st["col"]
        dx    = event.x - st["start_x"]
        new_w = max(30, st["start_w"] + dx)
        snapshot = st["snapshot"]
        # Final correction: restore all others, set target
        for c, w in snapshot.items():
            if c != col:
                try:
                    self.tree.column(c, width=w)
                except Exception:
                    pass
        self.tree.column(col, width=new_w)
        return "break"                                           ### v0.19.4 fix 2b ###

    # ── FFmpeg status bar ──────────────────────────────────────────────────────
    def _async_test_ffmpeg(self):                              ### FIX v0.16.0 ###
        """Run FFmpeg test off the main thread, then update the status widget."""
        ff_ok, fp_ok, ff_msg, fp_msg = _test_ffmpeg(FFMPEG_PATH, FFPROBE_PATH)
        self._ffmpeg_status = (ff_ok, fp_ok)
        try:                                                   ### FIX v0.19.2 — window closed before the test ended ###
            ui_post(lambda: self._build_ffmpeg_status(self._ff_frame))
        except (RuntimeError, tk.TclError):
            pass

    def _build_ffmpeg_status(self, parent):
        for w in parent.winfo_children(): w.destroy()
        _bg = parent.cget("bg")                                    # v0.19.3 B70 — the chip colour
        # FIX v0.16.0 — never call _test_ffmpeg on the main thread.
        # Use cached result; show "Checking…" placeholder until it arrives.
        if self._ffmpeg_status is None:
            tk.Label(parent, text="FFmpeg…", font=("Helvetica",9,"bold"),
                     bg=_bg, fg=C_DIM).pack(side="left")
            return
        ff_ok, fp_ok = self._ffmpeg_status
        if ff_ok and fp_ok:
            lbl = tk.Label(parent, text="FFmpeg ✓", font=("Helvetica",9,"bold"),
                           bg=_bg, fg=C_OK, cursor="hand2")
            lbl.pack(side="left")
            self._ff_tip = None
            ff_dir = os.path.dirname(FFMPEG_PATH) if FFMPEG_PATH else ""
            def _show(e):
                self._ff_tip = tw = tk.Toplevel(parent); tw.wm_overrideredirect(True)
                tw.wm_geometry(f"+{e.x_root+10}+{e.y_root+15}"); tw.configure(bg=C_SURFACE2)
                tk.Label(tw, text=_i18n.t("ff.tip", path=ff_dir),
                         bg=C_SURFACE2, fg=C_TEXT, font=("Consolas",9), padx=8, pady=4).pack()
            def _hide(e):
                if self._ff_tip: self._ff_tip.destroy(); self._ff_tip = None
            lbl.bind("<Enter>", _show); lbl.bind("<Leave>", _hide)
            lbl.bind("<Button-1>", lambda e: SettingsDialog(self))
        else:
            if not ff_ok and not fp_ok:
                status_text = "FFmpeg ✗"; fg = C_ERR
            elif not ff_ok:
                status_text = "ffmpeg ✗"; fg = C_PEACH
            else:
                status_text = "ffprobe ✗"; fg = C_PEACH
            tk.Label(parent, text=status_text, font=("Helvetica",9,"bold"),
                     bg=_bg, fg=fg).pack(side="left", padx=(0,4))
            tk.Button(parent, text=_i18n.t("ff.set_path"), font=("Helvetica",8),
                      bg=C_SURFACE2, fg=C_TEXT, relief="flat", cursor="hand2",
                      command=lambda: SettingsDialog(self)).pack(side="left", padx=(0,4))
            tk.Button(parent, text=_i18n.t("ff.download"), font=("Helvetica",8),
                      bg=C_SURFACE2, fg=C_ACCENT, relief="flat", cursor="hand2",
                      command=lambda: open_url_with_browser("https://ffmpeg.org/download.html")
                      ).pack(side="left", padx=(0,4))

    def _on_ffprobe_toggle(self):
        SETTINGS["use_ffprobe"] = self._use_ffprobe.get()
        _save_settings(SETTINGS)

    def _toggle_ffprobe_switch(self):                              ### NEW v0.19.3 B70 ###
        """The header switch: same variable and setting as the old tickbox."""
        self._use_ffprobe.set(not self._use_ffprobe.get())
        self._on_ffprobe_toggle()

    def _draw_ffprobe_switch(self):                                ### NEW v0.19.3 B70 ###
        try:
            on = bool(self._use_ffprobe.get())
            c = self._fp_switch
            c.delete("all")
            fill = C_OK if on else C_HOVER
            c.create_oval(1, 1, 17, 17, fill=fill, outline=fill)
            c.create_oval(17, 1, 33, 17, fill=fill, outline=fill)
            c.create_rectangle(9, 1, 25, 17, fill=fill, outline=fill)
            x = 18 if on else 2
            c.create_oval(x, 2, x + 14, 16, fill=C_BG, outline=C_BG)
            self._fp_state.configure(text=_i18n.t("fp.on") if on else _i18n.t("fp.off"), fg=C_OK if on else C_SUBTEXT)
        except (tk.TclError, AttributeError):
            pass

