    def _on_settings_changed(self):
        """Called by SettingsDialog on save — fully non-blocking.
        ### NEW v0.13.0 — UI freeze fix ###

        - Skip _build_ffmpeg_status() entirely on post-save refresh.
          That call ran two `subprocess.run(timeout=10)` ffprobe/ffmpeg version
          checks on the main thread, freezing the UI for up to 20 seconds.
          FFmpeg status is only refreshed when the user clicks "Test FFmpeg"
          inside the Settings dialog.
        - Skip the per-movie compute_lang_ok() loop unless the target language
          code actually changed.  That loop calls ffprobe per movie
          (timeout=20s each) and could freeze the UI for minutes on a
          large library.
        - Heavy work (per-movie quality reclassification, refresh_table)
          is scheduled with ui_post(...) so it runs AFTER the Settings
          dialog has fully destroyed.  This guarantees the dialog never
          appears stuck and the UI stays responsive.
        """
        iso = SETTINGS.get("lang_ok_code", "PT")
        self.tree.heading("lang_ok", text=lang_ok_heading(iso))          # v0.20.0 UI1c
        if PLEX_NFO_ASK_AUTO:                                   # v0.20.0 6h — only Plex just ticked
            self.after(300, self._maybe_ask_plex_nfo)
        self._apply_title_bars()                               ### NEW v0.19.2 B51 ###
        if hasattr(self, "_group_var") and bool(self._group_var.get()) != bool(SETTINGS.get("group_by_collection")):   ### NEW v0.19.4 B110h ###
            self._group_var.set(bool(SETTINGS.get("group_by_collection")))
            self._refresh_soon()                                   # D11: one rebuild per save
        if (SETTINGS.get("collection_folder") or "") != getattr(self, "_last_coll_folder", None):   ### NEW v0.19.4 B110g ###
            self._last_coll_folder = SETTINGS.get("collection_folder") or ""
            ui_post(self._read_collection_folders)

        # FIX v0.16.0 — invalidate cached FFmpeg status and re-test off-thread  ### FIX v0.16.0 ###
        # This handles the case where the user changed the FFmpeg path in Settings.
        self._ffmpeg_status = None
        self._build_ffmpeg_status(self._ff_frame)   # shows "FFmpeg…" placeholder
        threading.Thread(target=self._async_test_ffmpeg, daemon=True).start()

        # Capture whether the language code actually changed so we only
        # run the (potentially heavy) compute_lang_ok loop when needed.
        prev_iso = getattr(self, "_last_lang_iso", iso)
        lang_changed = (prev_iso != iso)
        self._last_lang_iso = iso

        # ── Deferred heavy work — runs after the Settings dialog is gone ──
        def _post_save_refresh():
            # 1. Re-evaluate lang_ok ONLY if the target language changed.
            #    compute_lang_ok() calls ffprobe per row (timeout=20s each),
            #    which would freeze the UI on a large library if always run.
            if lang_changed:                                    ### MODIFIED v0.19.4 B100 — in a worker; the table follows ###
                _rows = list(self._results)
                self._lang_gen = getattr(self, "_lang_gen", 0) + 1     # v0.20.2 PB9: a newer change wins
                _gen = self._lang_gen

                def _lang_work():
                    vals = []
                    for r in _rows:
                        try:
                            lo = compute_lang_ok(
                                r.get("video_path"), r.get("subs_internal", []),
                                r.get("subs_external", []),
                                r.get("nfo_path") if r.get("nfo_exists") else None,
                                r.get("xml_path") if r.get("xml_exists") else None,
                                iso_code=iso, subs_hard=r.get("subs_hard"))   ### v0.19.1 B15 ###
                            if r.get("video_path") and lang_in_stored_streams(r, iso):   # NEW v0.19.5 AS-A13: the stored audio, FFprobe off too
                                lo = "Y"
                            vals.append((r, lo))
                        except Exception:
                            pass

                    def _apply():
                        if _gen != getattr(self, "_lang_gen", 0):       # v0.20.2 PB9: an older language — dropped
                            return
                        for r, lo in vals:
                            r["lang_ok"] = lo
                            _apply_health(r)                       # NEW v0.19.5 AS-A13: the warning follows the column
                        self._refresh_soon()                       # D11
                        self._update_stats()
                    try:
                        ui_post(_apply)
                    except (RuntimeError, tk.TclError):
                        pass
                threading.Thread(target=_lang_work, name="lang-recompute", daemon=True).start()

            # 2. Recompute image quality tiers using CACHED dims — zero disk I/O
            for r in self._results:
                if r.get("poster_exists"):
                    pw, ph = self._parse_dim_str(r.get("poster_dim"))
                    r["poster_quality"] = classify_image_quality(pw, ph, "poster")
                if r.get("folder_exists"):
                    flw, flh = self._parse_dim_str(r.get("folder_dim"))
                    r["folder_quality"] = classify_image_quality(flw, flh, "folder")
                if r.get("fanart_exists"):
                    fw, fh = self._parse_dim_str(r.get("fanart_dim"))
                    r["fanart_quality"] = classify_image_quality(fw, fh, "fanart")

            ttk.Style(self).configure(                                     ### NEW v0.18.3 ###
                "Treeview", rowheight=px(20 if SETTINGS.get("compact_mode", False) else 26))
            self._refresh_soon()                                   # D11
            self._update_stats()

        # Schedule deferred refresh — runs AFTER the Settings dialog destroys
        ui_post(_post_save_refresh)

    def _refresh_soon(self):                                       ### NEW v0.19.4 (D11) — several requests, one rebuild ###
        if getattr(self, "_rs_after", None) is not None:
            try:
                self.tk.call("after", "cancel", self._rs_after)
            except tk.TclError:
                pass
        self._rs_after = self.after(80, self._refresh_soon_run)

    def _refresh_soon_run(self):
        self._rs_after = None
        self._refresh_table()

    def _apply_health_rules_inplace(self):               ### ADDED_BY_CLAUDE_v18.2 ###
        """
        Re-evaluate health_rules for every loaded movie using current SETTINGS.
        Runs on the main thread — no I/O, no re-scan. ~5ms for 500 movies.
        Called after Save & Apply in the Settings dialog when health rules changed (v0.18.4),
        and by Tools → Recompute Health Status.
        """
        if not self._results:
            return
        finalize_results(self._results)                        ### MODIFIED v0.18.4 — duplicates + health ###
        self._refresh_table()                                  ### MODIFIED v0.19.4 P1 — the collection rows too ###
        self._update_stats()
        self._reread_stale()                                   ### NEW v0.20.0 XB1 ###

    def _reread_stale(self):                                   ### NEW v0.20.0 XB1 ###
        """Read again, in the background, the folders whose movie.xml / NFO the current health mode uses but the
        last scan did not read (it ran in another mode).  Nothing to do while a scan runs: it reads them."""
        if self._scanning or not self._results:
            return 0
        paths = [r["subfolder_path"] for r in self._results if r.get("subfolder_path") and row_needs_reread(r)]
        if len(paths) > REREAD_QUICK_SCAN_AT:                  # many folders (a NAS library): a Quick Scan reads them
            logger.info(f"Health mode: {len(paths)} folder(s) to read again (movie.xml / NFO not read by the last scan) "
                        "— Quick Scan")
            flash_status(self, _i18n.t("t8.quick_scan", n=_n(len(paths), "movie")))   # v0.20.1 T8: said before it starts
            self.after(0, self._update_scan)                   # parallel, with its progress; row_needs_reread → re-read
            return len(paths)
        if paths:
            logger.info(f"Health mode: reading {len(paths)} folder(s) again (movie.xml / NFO not read by the last scan)")
            self._rf_stale_keys = getattr(self, "_rf_stale_keys", set()) | {_pkey(p) for p in paths}
            _was = getattr(self, "_rf_noted", False)
            self._rf_noted = True                              # a re-read changes no file: nothing to note for Undo
            self._rf_in_stale = True
            try:
                self._schedule_refresh(paths, need_ffprobe=False)
            finally:
                self._rf_noted = _was
                self._rf_in_stale = False
        return len(paths)

    # ── Column header tooltips — derived from COLUMN_MODEL (Phase B) ──────────
    # Tips are no longer a class-level dict literal. They are derived from
    # COLUMN_MODEL so that adding a column in one place updates tips automatically.
    @property
    def _COL_HEADER_TIPS(self):
        """Return header tip dict built from COLUMN_MODEL at access time."""
        return {col["id"]: col["header_tip"] for col in COLUMN_MODEL}

    def _add_header_tooltips(self):
        """Bind Motion events on column headings to show tooltip text."""
        self._hdr_tip_win = None
        self._hdr_tip_col = None

        def _on_header_motion(event):
            col_id = self.tree.identify_column(event.x)
            region = self.tree.identify_region(event.x, event.y)
            if region != "heading":
                _hide_header_tip()
                return
            if col_id:
                idx = self._model_col_index(int(col_id.lstrip("#")) - 1)   ### v0.18.4 ###
                cols = self.tree["columns"]
                if 0 <= idx < len(cols):
                    cname = cols[idx]
                    tip_text = self._COL_HEADER_TIPS.get(cname)
                    if tip_text and cname != self._hdr_tip_col \
                            and SETTINGS.get("show_header_tips", True):  # v0.10.5
                        _hide_header_tip()
                        self._hdr_tip_col = cname
                        tw = tk.Toplevel(self.tree)
                        tw.wm_overrideredirect(True)
                        tw.wm_geometry(f"+{event.x_root+14}+{event.y_root+20}")
                        tw.configure(bg=C_MANTLE)
                        tk.Label(tw, text=tip_text, bg=C_MANTLE, fg=C_TEXT,
                                 font=("Consolas", 9), padx=10, pady=6,
                                 wraplength=420, justify="left").pack()
                        self._hdr_tip_win = tw
                    return
            _hide_header_tip()

        def _hide_header_tip(event=None):
            if self._hdr_tip_win:
                self._hdr_tip_win.destroy()
                self._hdr_tip_win = None
            self._hdr_tip_col = None

        self.tree.bind("<Motion>", _on_header_motion, add=True)
        self.tree.bind("<Leave>",  _hide_header_tip,  add=True)

    # ── Cell tooltips (item 19) ────────────────────────────────────────────────
    def _tooltip(self, iid, ci):
        ci = self._model_col_index(ci)                         ### NEW v0.18.4 — hidden columns ###
        d = self._item_map.get(iid)
        if not d: return None
        fn = _TOOLTIP_METHODS.get(ci)                           ### MODIFIED v0.19.3 I7 — a dispatch table ###
        return getattr(self, fn)(d, iid, ci) if fn else None

