    def _tip_extra_art(self, d, iid, ci):                          ### NEW v0.20.1 EA4 / EA1 / EA2 / EA5 ###
        info = extra_info(d)
        lines = [_i18n.t("ea.tip.head")]
        for n in sorted(d.get("extra_art") or []):
            lines.append("  ✓ " + n)
        if info["missing"]:
            lines.append(_i18n.t("ea.tip.missing", kinds=", ".join(info["missing"])))
