    # ══════════════════════════════════════════════════════════════════════════
    # NEW v0.19.1 — rows whose movie folder was deleted
    # ══════════════════════════════════════════════════════════════════════════
    def _folder_gone(self, d):
        """'present' | 'deleted' | 'offline' for the movie folder of row *d*.
        A missing folder under a REACHABLE library root was deleted; when the
        root itself is unreachable the library is offline and nothing is lost."""
        sp = d.get("subfolder_path") or ""
        if sp and os.path.isdir(sp):
            return "present"
        root = d.get("library_root") or os.path.dirname(sp)
        if root and os.path.isdir(root):
            return "deleted"
        return "offline"

    def _remove_rows(self, rows, why="no longer exists"):
        """Drop *rows* from the results, the table and the cache; recompute the
        duplicate groups so their twins lose the duplicate warning."""
        keys = {_pkey(r.get("subfolder_path") or "") for r in rows if r}
        if not keys:
            return 0
        before = len(self._results)
        self._results = [r for r in self._results if _pkey(r.get("subfolder_path") or "") not in keys]
        n = before - len(self._results)
        if not n:
            return 0
        finalize_results(self._results)
        self._refresh_table()
        self._update_stats()
        self._incremental_save(self._results)
        names = ", ".join((r.get("movie_name") or r.get("subfolder") or "?") for r in rows[:3])
        more = f" (+{len(rows) - 3} more)" if len(rows) > 3 else ""
        txt = f"Removed {_n(n, 'movie')} whose folder {why}: {names}{more}"
        try:
            self._sb_action.configure(text=f"  {txt}")
        except Exception:
            pass
        logger.info(txt)
        return n

    def _handle_missing_folder(self, d, state=None):
        """Called when an action finds the folder of *d* missing.  Returns True
        when the caller must stop (row removed or library offline).
        ### v0.20.0 AU20 ### *state*: the answer of _folder_gone already got in a worker (no disk check here)."""
        st = state or self._folder_gone(d)
        if st == "present":
            return False
        if st == "deleted":
            self._remove_rows([d])
        else:
            root = d.get("library_root") or os.path.dirname(d.get("subfolder_path") or "")
            self._note_offline([root])
            messagebox.showinfo(_i18n.t("mc.library_offline_74a2"),
                                _i18n.t("mc.the_library_folder_is_6320", root=root), parent=self)
        return True

    def _remove_from_list(self, data_list):
        """Right-click → Remove from list (files are not touched)."""
        self._remove_rows(list(data_list), why="was removed from the list")

    ### NEW v0.10.0 — _reval_no_ffmpeg: re-validate without FFMPEG ###
    def _reval_no_ffmpeg(self, iid, data):
        """Re-validate all columns that do not require FFMPEG.
        v0.11.0: FFprobe fields (video_width, video_height, video_quality,
        subs_internal, subs_external, subs_summary, lang_ok) are preserved
        from the previous scan — they are NOT cleared.        ### NEW v0.11.0 ###
        """
        sp, sn = data["subfolder_path"], data["subfolder"]
        ### MODIFIED v0.20.0 AU20 (recommendation 2 of the audit) ### the folder check and the rescan run in a worker:
        # on a sleeping NAS share they froze the window (the several-movies Update already ran in the background).
        # _reval_running counts the open updates (the self-test waits for 0).
        if self._busy():                                          # v0.20.0 RV3: not during a scan
            return
        _busy_paths = self.__dict__.setdefault("_reval_paths", set())
        if _pkey(sp) in _busy_paths:                              # v0.20.0 RV3: Ctrl+R twice = one update
            return
        _busy_paths.add(_pkey(sp))
        self._reval_running = getattr(self, "_reval_running", 0) + 1

        def _work():
            try:
                if not os.path.isdir(sp):
                    st, r, _kept = self._folder_gone(data), None, True
                else:
                    st = "present"
                    r, _kept = rescan_or_keep(data, use_ffprobe=False)   ### MODIFIED v0.19.5 AS-A8 ###
                    if not _kept:
                        carry_after_rescan(r, data)                    ### MODIFIED v0.19.4 P4 — one rule (same video, same IDs) ###
                    _apply_health(r)
            except Exception as ex:
                logger.error(f"Update (no FFprobe) failed for {sn}: {ex}")
                st, r = "error", None
            ui_post(lambda: self._reval_no_ffmpeg_done(iid, data, st, r))
        _AppJobThread(self, target=_work, name="update-one", act_text=act_label(_i18n.t("act.update_no_ff")),
                      act_paths=(data.get("subfolder_path"),)).start()   # v0.20.0 RV3: a scan / close waits for it; SN3

    def _reval_no_ffmpeg_done(self, iid, data, st, r):            ### NEW v0.20.0 AU20 — Tk thread ###
        try:
            sp, sn = data["subfolder_path"], data["subfolder"]
            if st != "present":
                if st != "error":
                    self._handle_missing_folder(data, state=st)
                return
            for i, o in enumerate(self._results):
                if o["subfolder_path"] == sp: self._results[i] = r; break
            self._row_replaced(self._iid_for_path(sp, iid), r)         ### MODIFIED v0.19.4 P1 ###
            self._regroup_if_moved(data, r)                            ### NEW v0.19.4 fix 3a ###
            self._update_stats()
            logger.info(f"Re-validated (no FFMPEG): {sn}")
            self._incremental_save(self._results)                  ### NEW v0.18.0 — persist updated row ###
        finally:
            self._reval_running = max(0, getattr(self, "_reval_running", 1) - 1)
            self.__dict__.setdefault("_reval_paths", set()).discard(_pkey(data.get("subfolder_path") or ""))
    ### NEW v0.10.0 — Refresh Icons developer tool ###
    def _refresh_icons(self):
        """Force redraw of all emoji icons in the table."""
        if self._busy():                                       ### NEW v0.19.4 B91 ###
            return
        for iid in self._view_movie_iids():                      ### v0.19.4 B110h ###
            d = self._item_map.get(iid)
            if d:
                self.tree.item(iid, values=self._rv_at(iid, d), tags=self._tags(d, self._row_tag(iid, d)))   # P1; FB3
        logger.info("Icons refreshed")
    def _reval_ffmpeg(self, iid, data):
        """Re-validate (with FFprobe) — full column revalidation, always runs FFprobe.
        ### NEW v0.12.0 — full revalidation (all columns), force_ffprobe=True,
                          does NOT depend on global use_ffprobe setting. ###
        """
        sp, sn = data["subfolder_path"], data["subfolder"]
        if not os.path.isdir(sp) and self._handle_missing_folder(data): return   ### MODIFIED v0.19.1 ###

        def _worker():
            try:
                with _activity(UPDATE_FF_TEXT, (sp,)):           # v0.20.1 SN3
                    r = self._rescan_row(data, force_ffprobe=True)   ### MODIFIED v0.18.4 ###
                def _apply():
                    for i, o in enumerate(self._results):
                        if o["subfolder_path"] == sp:
                            self._results[i] = r; break
                    self._row_replaced(self._iid_for_path(sp, iid), r)   ### MODIFIED v0.19.4 P1 ###
                    self._regroup_if_moved(data, r)
                    self._update_stats()
                    name_disp = r.get("movie_name", r.get("subfolder", "?"))
                    ### MODIFIED v0.19.4 B106 — a status-bar line, no pop-up ###
                    try:
                        self._sb_action.configure(text=_i18n.t("mc.quality_lang_ok_60a9", update_ff_text=UPDATE_FF_TEXT, name_disp=name_disp, get=r.get('video_quality','—'), get2=r.get('lang_ok','—')))
                    except tk.TclError:
                        pass
                    logger.info(f"Re-validated (with FFprobe): {sn}")
                    self._incremental_save(self._results)      ### NEW v0.18.0 ###
                ui_post(_apply)
            except Exception as e:
                logger.error(f"Re-validate (with FFprobe) error for {sn}: {e}")
                _msg = f"{UPDATE_FF_TEXT} failed for {sn}:\n{e}"   ### FIXED v0.18.3; wording v0.19.4 B106 ###
                ui_post(lambda m=_msg: messagebox.showerror(UPDATE_FF_TEXT, m))

        threading.Thread(target=_worker, daemon=True).start()

    def _reval_multi_ffmpeg(self, iids, data_list):
        """Re-validate multiple rows with FFprobe — full revalidation. ### NEW v0.12.0 ###
        ### MODIFIED v0.19.4 B106 ### the batch progress window with Cancel;
        the result says how many were updated (and where a cancel stopped)."""
        prog = _BatchProgressDialog(self, f"{UPDATE_FF_TEXT}…", total=len(data_list))
        self._reval_prog = prog                                  # read by the self-test

        def _worker():
            done = 0; gone = []; seen = 0                        ### v0.19.1; seen v0.19.4 B106 ###
            for iid, data in zip(iids, data_list):
                if prog.cancelled:                               ### NEW v0.19.4 B106 ###
                    break
                seen += 1
                sp, sn = data["subfolder_path"], data["subfolder"]
                if not os.path.isdir(sp):
                    if self._folder_gone(data) == "deleted":
                        gone.append(data)
                    continue
                try:
                    r = self._rescan_row(data, force_ffprobe=True)   ### MODIFIED v0.18.4 ###
                    def _apply(i=iid, d=r, o0=data):
                        for idx, o in enumerate(self._results):
                            if o["subfolder_path"] == d["subfolder_path"]:
                                self._results[idx] = d; break
                        self._row_replaced(self._iid_for_path(d["subfolder_path"], i), d)   ### MODIFIED v0.19.4 P1 ###
                        self._regroup_if_moved(o0, d)
                    ui_post(_apply)
                    done += 1
                except Exception as e:
                    logger.error(f"FFprobe batch error for {sn}: {e}")
                prog.advance(seen)                                ### NEW v0.19.4 B106 ###
            cancelled = prog.cancelled and seen < len(data_list)
            prog.close()

            def _finish(n=done):
                if gone:                                         ### NEW v0.19.1 ###
                    self._remove_rows(gone)
                self._update_stats()
                self._incremental_save(self._results)          ### NEW v0.18.0 ###
                msg = _i18n.t("mc.of_updated_with_ffprobe_beb3", n=_n(n, 'movie'), n2=len(data_list))   ### MODIFIED v0.19.4 B106 — one wording ###
                if cancelled:
                    msg += (_i18n.t("mc.cancelled_after_of_left_a60d", seen=seen, n=len(data_list), v=len(data_list) - seen))
                messagebox.showinfo(UPDATE_FF_TEXT, msg, parent=self)
                logger.info(f"Batch update (with FFprobe): {n}/{len(data_list)} done" + (" — cancelled" if cancelled else ""))
            ui_post(_finish)
        threading.Thread(target=_worker, daemon=True).start()

    ### NEW v0.12.0 — Custom genre helpers ###
    def _collect_custom_genres(self, data_list):
        """Return sorted list of unique custom genres across all selected rows."""
        valid = _get_valid_genres()
        custom = set()
        for d in data_list:
            for g in d.get("genres", []):
                lower = g.lower()
                canonical = _GENRE_SYNONYMS.get(lower)
                if canonical:
                    continue  # synonym — normalizable, not truly custom
                normalized = normalize_genre(g)
                in_valid = (g in valid or
                            g.title() in valid or
                            normalized in valid or
                            normalized.lower() in {v.lower() for v in valid})
                if not in_valid:
                    custom.add(g)
        return sorted(custom)

    def _add_custom_genres(self, custom_genres, data_list):
        """Add custom genres to the settings genre list and refresh affected rows."""
        existing = SETTINGS.get("genre_list", _DEFAULT_SETTINGS["genre_list"])
        existing_set = {g.strip() for g in existing.splitlines() if g.strip()}
        new_genres = [g for g in custom_genres if g not in existing_set]
        if not new_genres:
            messagebox.showinfo(_i18n.t("mc.add_custom_genres_9c78"), _i18n.t("mc.all_custom_genres_are_2c93"), parent=self)
            return
        updated = existing.rstrip() + "\n" + "\n".join(new_genres)
        SETTINGS["genre_list"] = "\n".join(g.strip() for g in updated.splitlines() if g.strip())
        _save_settings(SETTINGS)
        logger.info(f"Added custom genres to settings: {', '.join(new_genres)}")
        # ### MODIFIED v0.19.4 P1 (D8) ### every movie with these genres is re-classified AND re-checked
        for d in self._results:
            d["genre_display"], d["genre_status"] = classify_genres(d.get("genres", []))
        self._apply_health_rules_inplace()
        messagebox.showinfo(_i18n.t("mc.add_custom_genres_9c78"),
                            _i18n.t("mc.added_to_settings_d45c", n=_n(len(new_genres), 'genre'), join=", ".join(new_genres)), parent=self)

    def _open_opensubtitles(self, d):
        """Item 16 — Open movie page on OpenSubtitles.org."""
        titles = get_movie_titles_from_files(
            d.get("nfo_path") if d.get("nfo_exists") else None,
            d.get("xml_path") if d.get("xml_exists") else None)
        title = titles[0] if titles else None
        year  = get_movie_year_from_files(
            d.get("nfo_path") if d.get("nfo_exists") else None,
            d.get("xml_path") if d.get("xml_exists") else None)

        if not title:
            messagebox.showwarning(_i18n.t("mc.opensubtitles_b5f4"),
                                   _i18n.t("mc.could_not_find_movie_637a"))
            return

        url = build_opensubtitles_url(title, year)
        if url:
            open_url_with_browser(url)
        else:
            messagebox.showerror(_i18n.t("mc.opensubtitles_b5f4"), _i18n.t("mc.failed_to_build_url_64d5"), parent=self)

    # ── Extract frames ─────────────────────────────────────────────────────────
    # ── Online Ratings Sync (item 2) ───────────────────────────────────────────
    def _sync_ratings(self, data_list, preview=False):          ### preview v0.19.3 I6 ###
        """Launch ratings sync for one or more movies in a background thread."""
        if not self._confirm_services(("tmdb", "omdb")):          ### NEW v0.19.1 B22 — paused service: Try anyway? ###
            return
        tmdb_key = SETTINGS.get("tmdb_api_key", "").strip()
        omdb_key = SETTINGS.get("omdb_api_key", "").strip()
        if not tmdb_key and not omdb_key:
            messagebox.showwarning(_i18n.t("mc.no_api_keys_c066"),
                _i18n.t("mc.no_tmdb_or_omdb_8d9b"))
            return
        # Show progress dialog immediately for ≥10 movies          ### NEW v0.17.0 ###
        prog = None
        if len(data_list) >= _PROGRESS_MIN:                     ### MODIFIED v0.19.1 — was 10 ###
            prog = _BatchProgressDialog(self, _i18n.t("uf.processing_movies_ratings_sync_d0ad"),
                                        total=len(data_list))
        _AppJobThread(self, target=self._sync_ratings_worker, act_paths=act_targets(data_list)[0],   # v0.20.1 SN3
                         args=(data_list, tmdb_key, omdb_key, prog, preview), daemon=True).start()

    # ── Worker-thread dialog helper (v0.19.0) ─────────────────────────────────
    def _ask_on_ui(self, make_dialog, read_result, timeout=600):     ### NEW v0.19.0 ###
        """Build a dialog on the UI thread, wait for it to close and return
        read_result(dlg).  Call from a worker thread only; waits on an Event
        instead of a sleep/poll loop.  Returns None after *timeout* seconds."""
        box = {}; ev = threading.Event()
        def _run():
            if box.get("gave_up"):                              ### NEW v0.19.5 I22 — too late: nobody waits for the answer ###
                return
            try:
                dlg = make_dialog()
                box["dlg"] = dlg                                ### NEW v0.19.4 B99e ###
                self.wait_window(dlg)
                box["r"] = read_result(dlg)
            except Exception as ex:
                logger.error(f"_ask_on_ui: {ex}")
                box["r"] = None
            finally:
                ev.set()
        ui_post(_run)
        if not ev.wait(timeout):                                ### MODIFIED v0.19.4 B99e — no answer: the dialog goes too ###
            box["gave_up"] = True
            def _close():
                d = box.get("dlg")
                try:
                    if d is not None and d.winfo_exists():
                        d.destroy()
                except tk.TclError:
                    pass
            try:
                ui_post(_close)
            except (RuntimeError, tk.TclError):
                pass
            logger.warning(f"_ask_on_ui: no answer within {timeout} s — the question was closed")
            return None
        return box.get("r")

    def _ask_ratings_dialog(self, movie_name, tmdb_r, tmdb_v, omdb_r, omdb_v,
                            show_checkboxes, fallback_mode=False):    ### NEW v0.19.0 ###
        """Show RatingsCompareDialog from the worker and return a plain dict
        (tests replace this method with a scripted one)."""
        def_apply = SETTINGS.get("rating_apply_all_movies", False) and not fallback_mode
        def_votes = SETTINGS.get("rating_use_more_votes",   False) and not fallback_mode
        res = self._ask_on_ui(
            lambda: RatingsCompareDialog(self, movie_name, tmdb_r, tmdb_v, omdb_r, omdb_v,
                                         default_apply_all=def_apply,
                                         default_use_more_votes=def_votes,
                                         show_checkboxes=show_checkboxes,
                                         fallback_mode=fallback_mode),
            lambda dlg: {"choice": dlg.choice, "apply_all": dlg.apply_all,
                         "use_more_votes": dlg.use_more_votes,
                         "manual_r": dlg.manual_r, "manual_v": dlg.manual_v,
                         "apply_fallback": dlg.apply_fallback})
        return res or {"choice": "cancel", "apply_all": False, "use_more_votes": False,
                       "manual_r": None, "manual_v": None, "apply_fallback": False}

    @staticmethod
    def _rating_valid(r, v):                                        ### NEW v0.19.0 ###
        """A source is valid only with a non-zero rating AND a non-zero vote
        count (TMDb/OMDb return "0.0" / "0" for unrated titles)."""
        if r is None:
            return False
        try:
            if float(str(r).replace(",", ".")) == 0.0:
                return False
            return int(str(v or "0").replace(",", "").replace(".", "")) > 0
        except (TypeError, ValueError):
            return False

    @staticmethod
    def _auto_by_votes(tr, tv, or_, ov):                            ### MOVED v0.19.0 (was nested) ###
        """Pick the source with more votes among two VALID sources (average on a tie)."""
        try:
            tv_int = int(str(tv).replace(",", "")) if tv else 0
            ov_int = int(str(ov).replace(",", "")) if ov else 0
            if tv_int > ov_int:
                return tr, tv, "TMDB"
            if ov_int > tv_int:
                return or_, ov, "OMDb/IMDb"
            avg_r = (float(tr) + float(or_)) / 2
            return f"{avg_r:.1f}", str(max(tv_int, ov_int)), "TMDB+OMDb average"
        except Exception:
            return tr, tv, "TMDB"

    def _sync_ratings_worker(self, data_list, tmdb_key, omdb_key, prog=None, preview=False):   ### NEW v0.19.1 B20; preview v0.19.3 I6 ###
        """Runs _sync_ratings_worker_run inside a service run (B20): a service that refuses
        (daily limit / invalid key) is not asked again until the run ends."""
        _service_run_begin(**self._service_run_args(prog, {"omdb": "TMDB", "tmdb": _i18n.t("uf.omdb_imdb_data_5eaf")}))   ### B22 ###
        try:
            with _sc.backup_action("Ratings Sync"):                     ### NEW v0.19.1 I1 ###
                return self._sync_ratings_worker_run(data_list, tmdb_key, omdb_key, prog, preview)
        finally:
            _service_run_end()

    def _sync_ratings_worker_run(self, data_list, tmdb_key, omdb_key, prog=None, preview=False):  ### REWRITTEN v0.19.0; preview v0.19.3 I6 ###
        """
        Background worker for ratings sync.

        Two run-local memories, both reset when the run ends:
          primary  — the choice remembered from the first dialog ("Apply this
                     choice to all remaining movies" / "Use the source with
                     more votes" / typed values).  It wins wherever at least one
                     source is valid; when the chosen source is invalid for a
                     movie the other valid source is used.  Typed values apply
                     to every remaining movie.
          fallback — remembered from the zero-votes dialog ("Apply this choice
                     to all remaining movies with zero votes and no rating"):
                     typed values or skip.  Used only when BOTH sources are
                     invalid (rating 0 or votes 0).
        Nothing is ever written with rating 0.0 / votes 0.
        """
        primary  = None    # ("source", "tmdb"|"omdb") | ("manual", r, v) | ("votes",)
        fallback = None    # ("manual", r, v) | ("skip",)
        multi = len(data_list) > 1
        written = 0
        changed_paths = []                                      ### v0.19.0 — one refresh at the end ###
        unreachable = []                                        ### NEW v0.19.1 — sources that could not be asked ###
        write_failed = []                                       ### NEW v0.19.2 B41 — files that could not be written ###
        pending = []                                            ### NEW v0.19.3 I6 — preview: collected, written on Run ###
        bk_ref = [None]                                         ### NEW v0.19.4 B82 — one backup folder for the run ###
        no_id, no_answer = [], []                               ### NEW v0.19.6 TR2 — skipped, with the reason ###

        def _write(d, name, nfo_path, xml_path, chosen):
            nonlocal written
            if not _batch_backup_ok(d.get("movie_name", name), bk_ref, nfo_path, xml_path):   ### NEW v0.19.4 B82 ###
                write_failed.append(f"{name}: {BACKUP_FAILED_TEXT}")
                logger.warning(f"Ratings not written: {name}: {BACKUP_FAILED_TEXT}")
                return
            errors = write_rating_to_files(nfo_path, xml_path, chosen[0], chosen[1],
                                           movie_name=d.get("movie_name", name), backup=False,   ### MODIFIED v0.19.4 B82 ###
                                           source=_rating_source_name(chosen[2] if len(chosen) > 2 else None))   # v0.19.5 B122
            if errors:                                         ### MODIFIED v0.19.2 B41 — into the summary, no pop-up per movie ###
                write_failed.append(f"{name}: " + "; ".join(errors))
                logger.warning(f"Ratings not written: {name}: {'; '.join(errors)}")
                changed_paths.append(d["subfolder_path"])       # one file may have been written: refresh the row
            else:
                written += 1
                logger.info(f"Ratings written ({chosen[2]}): {name} → {chosen[0]} / {chosen[1]}")
                changed_paths.append(d["subfolder_path"])

        def _from_primary(pr, tr, tv, tok, or_, ov, ook):
            kind = pr[0]
            if kind == "manual":
                return pr[1], pr[2], "manual"
            if kind == "votes":
                if tok and ook:
                    return self._auto_by_votes(tr, tv, or_, ov)
                return (tr, tv, "TMDB") if tok else (or_, ov, "OMDb/IMDb")
            want = pr[1]
            if want == "tmdb":
                return (tr, tv, "TMDB") if tok else (or_, ov, "OMDb/IMDb")
            return (or_, ov, "OMDb/IMDb") if ook else (tr, tv, "TMDB")

        for _idx, d in enumerate(data_list):
            if (prog and prog.cancelled) or _service_run_cancelled():   # B22
                break
            name = d.get("movie_name") or d["subfolder"]
            nfo_path = _metadata_targets(d)[0]   # v0.20.0 F3b
            xml_path = _metadata_targets(d)[1]   # v0.20.0 F3b
            imdb_id, tmdb_id = get_movie_ids_robust(nfo_path, xml_path)

            _take_fetch_errors()
            ### NEW v0.19.1 B20 — a service that refused earlier in this run is not asked;
            ### the other source is used, or the movie is skipped when neither is left
            _use_t = bool(tmdb_key) and not _service_blocked("tmdb")
            _use_o = bool(omdb_key) and not _service_blocked("omdb")
            if (tmdb_key or omdb_key) and not (_use_t or _use_o):
                unreachable.append(f"{name}: " + "; ".join(
                    str(ServiceUnavailable(s, k)) for s, k in (("tmdb", _service_blocked("tmdb")),
                                                              ("omdb", _service_blocked("omdb"))) if k))
                if prog:
                    prog.advance(_idx + 1)
                continue
            _why = ratings_skip_reason(imdb_id, tmdb_id, _use_t, _use_o)   ### NEW v0.19.6 TR2 ###
            if _why:
                no_id.append(f"{name}: {_why}")
                if prog:
                    prog.advance(_idx + 1)
                continue
            if not _use_t:
                tmdb_r, tmdb_v = None, None
            elif tmdb_id:
                tmdb_r, tmdb_v = _fetch_tmdb_rating(tmdb_id, tmdb_key)
            else:                                               # v0.19.6 TR2: only an IMDb ID
                tmdb_r, tmdb_v = _fetch_tmdb_rating_by_imdb(imdb_id, tmdb_key)
            if (prog and prog.cancelled) or _service_run_cancelled():   # B22                         ### NEW v0.19.1 — cancel between calls ###
                break
            omdb_r, omdb_v = _fetch_omdb_rating(imdb_id, omdb_key) if (_use_o and imdb_id) else (None, None)
            tok = self._rating_valid(tmdb_r, tmdb_v)
            ook = self._rating_valid(omdb_r, omdb_v)
            _errs = _take_fetch_errors()                      ### NEW v0.19.1 ###
            if _errs:
                # a source could not be asked (network / rate limit / key):
                # never treat that as "no rating" and never write a partial choice
                unreachable.append(f"{name}: {_errs[0]}")
                if prog:
                    prog.advance(_idx + 1)
                continue
            _noans = None                                       ### NEW v0.19.6 TR2 — asked, and no answer: named if skipped ###
            if tmdb_r is None and omdb_r is None:
                _asked = [s for s, on in (("TMDB", _use_t), ("OMDb", _use_o and imdb_id)) if on]
                _noans = (f"{name}: {' and '.join(_asked)} have no rating for "
                          + " / ".join(x for x in (imdb_id, f'TMDB {tmdb_id}' if tmdb_id else '') if x))

            chosen = None   # (rating_str, votes_str, source_label)

            if tok or ook:
                # ── at least one valid source: the primary choice decides ──
                if primary is not None:
                    chosen = _from_primary(primary, tmdb_r, tmdb_v, tok, omdb_r, omdb_v, ook)
                else:
                    res = self._ask_ratings_dialog(
                        name, tmdb_r if tok else None, tmdb_v if tok else None,
                        omdb_r if ook else None, omdb_v if ook else None,
                        show_checkboxes=multi)
                    choice = res.get("choice")
                    if choice in (None, "cancel"):
                        if prog: prog.advance(_idx + 1)
                        continue
                    if choice == "manual":
                        if res.get("manual_r") is None:
                            if prog: prog.advance(_idx + 1)
                            continue
                        chosen = (str(res["manual_r"]), str(res["manual_v"]), "manual")
                        if multi and res.get("apply_all"):
                            primary = ("manual", str(res["manual_r"]), str(res["manual_v"]))
                    else:
                        if multi and res.get("apply_all"):
                            primary = ("source", choice)
                        elif multi and res.get("use_more_votes"):
                            primary = ("votes",)
                        if res.get("use_more_votes") and tok and ook:
                            chosen = self._auto_by_votes(tmdb_r, tmdb_v, omdb_r, omdb_v)
                        elif choice == "tmdb":
                            chosen = (tmdb_r, tmdb_v, "TMDB") if tok else (omdb_r, omdb_v, "OMDb/IMDb")
                        else:
                            chosen = (omdb_r, omdb_v, "OMDb/IMDb") if ook else (tmdb_r, tmdb_v, "TMDB")
            else:
                # ── both sources invalid (rating 0 or votes 0): fallback ────
                if primary is not None and primary[0] == "manual":
                    chosen = (primary[1], primary[2], "manual")     # typed values apply everywhere
                elif fallback is not None:
                    if fallback[0] == "manual":
                        chosen = (fallback[1], fallback[2], "manual")
                    else:
                        if _noans: no_answer.append(_noans)         # v0.19.6 TR2
                        if prog: prog.advance(_idx + 1)
                        continue                                    # remembered skip
                else:
                    res = self._ask_ratings_dialog(name, None, None, None, None,
                                                   show_checkboxes=multi, fallback_mode=True)
                    if res.get("choice") == "manual" and res.get("manual_r") is not None:
                        chosen = (str(res["manual_r"]), str(res["manual_v"]), "manual")
                        if multi and res.get("apply_fallback"):
                            fallback = ("manual", str(res["manual_r"]), str(res["manual_v"]))
                    else:
                        if multi and res.get("apply_fallback"):
                            fallback = ("skip",)
                        if _noans: no_answer.append(_noans)         # v0.19.6 TR2
                        if prog: prog.advance(_idx + 1)
                        continue

            if chosen and chosen[0] is not None and chosen[1] is not None \
                    and self._rating_valid(chosen[0], chosen[1]):
                if preview:                                     ### v0.19.3 I6 ###
                    pending.append((d, name, nfo_path, xml_path, chosen))
                else:
                    _write(d, name, nfo_path, xml_path, chosen)

            if prog:
                prog.advance(_idx + 1)

        if prog:
            prog.close()
        _closed = False
        if preview and pending:                                 ### NEW v0.19.3 I6 — current → new, then write ###
            run = self._ask_on_ui(lambda: _PreviewRunDialog(self, _i18n.t("uf.sync_ratings_all_movies_38c3"),
                                                            ratings_preview_text(pending), file_stem="ratings_preview",
                                                            run_label=_i18n.t("mc.write_ratings_85a5")),
                                  lambda dlg: dlg.run)
            if run:
                for p in pending:
                    _write(*p)
            else:
                _closed = True
        self._schedule_refresh(changed_paths, need_ffprobe=False)   ### v0.19.0 ###
        _msg = _i18n.t("uf.ratings_sync_finished_for_c270", n=_n(len(data_list), 'movie'), written=written)
        if written:                                              ### NEW v0.19.4 B109e ###
            _msg += "\n" + UNDO_HINT
        if _closed:
            _msg += _i18n.tn("uf.m.preview_closed", len(pending), movies=_n(len(pending), 'movie'))   # v0.20.0 UI1f
        if write_failed:                                         ### NEW v0.19.2 B41 ###
            _msg += (_i18n.t("uf.could_not_be_written_5fa5", n=len(write_failed))
                     + "\n".join(write_failed[:8]) + ("\n…" if len(write_failed) > 8 else ""))
        for _lst, _head in ((no_id, _i18n.t("uf.skipped_no_id_the_de84")),          ### NEW v0.19.6 TR2 ###
                            (no_answer, _i18n.t("uf.skipped_the_sources_have_4902"))):
            if _lst:
                _msg += (f"\n\n{_n(len(_lst), 'movie')} {_head}:\n" + "\n".join(_lst[:8])
                         + (_i18n.t("uf.and_more_logs_app_0bd4", v=len(_lst) - 8) if len(_lst) > 8 else ""))
                for _x in _lst:
                    logger.info(f"Ratings sync skipped {_x}")
        if unreachable:                                          ### NEW v0.19.1 ###
            _msg += (_i18n.t("uf.skipped_because_tmdb_omdb_700d", n=_n(len(unreachable), 'movie'))
                     + "\n".join(unreachable[:8]) + ("\n…" if len(unreachable) > 8 else ""))
        _svc = _service_run_summary()                            ### NEW v0.19.1 B20 — said once ###
        if _svc:
            _msg += "\n\n" + "\n".join(_svc)
        ui_post(lambda m=_msg: messagebox.showinfo(_i18n.t("mc.ratings_sync_complete_ff80"), m))


    def _reval_by_path(self, d, no_ffprobe=False):               ### MODIFIED v0.19.0 — wrapper ###
        """Compatibility wrapper: every caller is a metadata/artwork change, so
        it refreshes WITHOUT FFprobe through the central mechanism (v0.18.4
        ran a full _reval that followed the global FFprobe setting)."""
        if d and d.get("subfolder_path"):
            self._schedule_refresh([d["subfolder_path"]], need_ffprobe=False)

    # ══════════════════════════════════════════════════════════════════════════
    # NEW v0.19.0 — central automatic refresh after any change
    # ══════════════════════════════════════════════════════════════════════════
    _RF_DELAY_MS = 300

    def _schedule_refresh(self, paths, need_ffprobe=False):       ### NEW v0.19.0 ###
        """Ask for the rows of *paths* to be rescanned and redrawn.

        - safe from any thread (re-posts itself to the UI thread);
        - coalesces: requests within 300 ms (or arriving while a refresh runs)
          are merged into ONE background batch;
        - a request made while a batch runs is queued and starts after it;
        - need_ffprobe=True only for changes to video/audio/embedded subtitles;
          everything else keeps the FFprobe data of the previous scan;
        - after each batch: stats/counters updated and the results cache
          saved once."""
        if not getattr(self, "_rf_noted", False):                    ### NEW v0.19.1 I1 — run result for Undo ###
            try:
                _sc.note_written(list(paths or []))
            except Exception:
                pass
        if threading.current_thread() is not threading.main_thread():
            with _RF_POST_LOCK:                                      # on its way through the queue: not idle yet
                self._rf_posted = getattr(self, "_rf_posted", 0) + 1

            def _arrived(p=list(paths), f=need_ffprobe):
                with _RF_POST_LOCK:
                    self._rf_posted -= 1
                self._schedule_refresh(p, f)
            ui_post(_arrived)
            return
        for pth in paths or []:
            if not pth:
                continue
            k = _pkey(pth)
            if not getattr(self, "_rf_in_stale", False):           # v0.20.0 XB1: a real change is never dropped
                getattr(self, "_rf_stale_keys", set()).discard(k)
            self._rf_pending[k] = bool(self._rf_pending.get(k)) or bool(need_ffprobe)
        if self._rf_pending and self._rf_timer is None and not self._rf_running:
            self._rf_timer = self.after(self._RF_DELAY_MS, self._run_refresh)
        if self._rf_pending:
            self._act_wake()                                       # v0.20.1 SN3

    def _refresh_idle(self):                                       ### NEW v0.19.0 ###
        return not getattr(self, "_rf_posted", 0) and not self._rf_pending and self._rf_timer is None and not self._rf_running

    def _run_refresh(self):                                        ### NEW v0.19.0 ###
        self._rf_timer = None
        if not self._rf_pending:
            return
        if self._scanning:                      # a scan will rebuild the rows; retry after it
            self._rf_timer = self.after(500, self._run_refresh)
            return
        batch = dict(self._rf_pending); self._rf_pending.clear()
        rows = {_pkey(r.get("subfolder_path", "")): r for r in self._results}
        ### NEW v0.20.0 XB1 — a re-read asked only because of the health mode is dropped when a scan read the folder meanwhile
        _stale = getattr(self, "_rf_stale_keys", set())
        batch = {k: ff for k, ff in batch.items() if not (k in _stale and k in rows and not ff and not row_needs_reread(rows[k]))}
        self._rf_stale_keys = set()
        jobs = [(rows[k], ff) for k, ff in batch.items() if k in rows]
        if not jobs:
            return
        self._rf_running = True
        self._rf_batch_keys = {_pkey(d.get("subfolder_path", "")) for d, _ff in jobs}   # v0.20.1 SN3: the indicator
        self._act_wake()

        def _worker():
            out = []; gone = []                                  ### v0.19.1 ###
            for d, ff in jobs:
                try:
                    if not os.path.isdir(d["subfolder_path"]):
                        if self._folder_gone(d) == "deleted":
                            gone.append(d)
                        continue
                    r = self._rescan_row(d, force_ffprobe=True) if ff else self._rescan_row_no_probe(d)
                    out.append(r)
                except Exception as ex:
                    logger.warning(f"refresh failed for {d.get('subfolder')}: {ex}")
            def _apply():
                try:
                    self._apply_rescanned_rows(out)                  ### MODIFIED v0.19.4 P6 (E11) ###
                    ### NEW v0.20.1 SN1 — a movie now in a collection whose folder was never read (a fix renamed it):
                    # read the collection folders again, so the panel and the "⚠ set.nfo" mark show the new state ###
                    try:
                        if _coll_root() and any(_cr.group_key(r) and _cr.group_key(r) not in COLL_FOLDERS for r in out):
                            self._read_collection_folders()
                    except Exception as _ex:
                        logger.warning(f"collection folders not re-read after the refresh: {_ex}")
                    if gone:                                     ### NEW v0.19.1 ###
                        self._remove_rows(gone)
                    self._update_stats()
                    self._incremental_save(self._results)
                    logger.info(f"Auto-refresh: {len(out)} row(s)"
                                + (" (with FFprobe)" if any(ff for _d, ff in jobs) else " (no FFprobe)"))
                finally:
                    self._rf_running = False
                    self._rf_batch_keys = set()                  # v0.20.1 SN3
                    self._rf_runs += 1
                    if self._rf_pending and self._rf_timer is None:
                        self._rf_timer = self.after(self._RF_DELAY_MS, self._run_refresh)
            _ffprobe_cache_flush()                              ### NEW v0.19.1 I5 ###
            ui_post(_apply)
        threading.Thread(target=_worker, daemon=True).start()

