    # ── v0.19.3 B62: UI watchdog — a stall > 5 s is logged with every thread's stack ──
    _WD_LIMIT = 5.0

    def _start_ui_watchdog(self):                                  ### NEW v0.19.3 B62 ###
        self._wd_beat = time.monotonic()
        self._wd_stop = False
        try:
            _wd_hwnd = self.winfo_id()                             ### NEW v0.19.5 B112 ###
        except tk.TclError:
            _wd_hwnd = None

        def beat():
            if self._wd_stop:
                return
            self._wd_beat = time.monotonic()
            try:
                self.after(500, beat)
            except (RuntimeError, tk.TclError):
                pass

        def watch():                                           # never touches Tk
            logged = None
            woken = False
            while not self._wd_stop:
                time.sleep(1.0)
                gap = time.monotonic() - self._wd_beat
                ### NEW v0.19.5 B112 — Tk's timers can stop after another program's PrintWindow (also in bare Tk) until the next
                ### window message; a mouse move revives them. With nobody at the mouse, this message does it. Harmless if Tk is just busy.
                if gap > 2.0 and not woken and _wd_hwnd and sys.platform == "win32":
                    woken = True
                    try:
                        import ctypes
                        ctypes.windll.user32.PostMessageW(ctypes.c_void_p(_wd_hwnd), 0, None, None)   # WM_NULL
                    except (OSError, AttributeError, ValueError, TypeError):   # never stops the watchdog
                        pass
                elif gap <= 2.0:
                    woken = False
                if gap > self._WD_LIMIT and logged is None:
                    logged = gap
                    logger.warning(f"UI busy for {gap:.0f} s — the window did not respond. Threads:\n"
                                   + format_thread_stacks())
                elif gap <= self._WD_LIMIT and logged is not None:
                    logger.info(f"UI responsive again (it was busy for more than {logged:.0f} s)")
                    logged = None
        beat()
        threading.Thread(target=watch, name="ui-watchdog", daemon=True).start()

    def destroy(self):                                             ### NEW v0.19.2 B27 ###
        """Cancel every pending after() timer of this interpreter first, so no
        callback fires on a destroyed window (bgerror 'invalid command name').
        Cancelled in Tcl, not with after_cancel (CLAUDE.md: that deletes the
        Tcl command during close); Misc.destroy deletes the commands itself."""
        self._wd_stop = True                                    ### v0.19.3 B62 ###
        try:
            for aid in self.tk.splitlist(self.tk.call("after", "info")):
                try:
                    self.tk.call("after", "cancel", aid)
                except tk.TclError:
                    pass
        except tk.TclError:
            pass
        super().destroy()

    def _refresh_pause_indicator(self):                            ### NEW v0.19.1 B22 ###
        """Status bar: '⚠ OMDb (IMDb data) paused — daily limit (retry after about 23:40)';
        empty when nothing is paused.  Re-checks every 30 s while a pause is active."""
        try:
            act = api_pauses_active()
            parts = []
            for svc, e in act.items():
                try:
                    hhmm = datetime.datetime.fromisoformat(e["until"]).strftime("%H:%M")
                except Exception:
                    hhmm = "?"
                _svc = _i18n.t("api.omdb") if svc == "omdb" else _SERVICE_LABEL.get(svc, svc)   # v0.20.0 UI1c (logs stay English)
                _why = _i18n.t("api.refusal." + e.get("kind")) if _i18n.has("api.refusal." + str(e.get("kind"))) else e.get("kind")
                parts.append(_i18n.t("sb.paused", service=_svc, why=_why, time=hhmm))
            self._sb_pause.configure(text="   ".join(parts))
            if act:
                aid = getattr(self, "_pause_after_id", None)
                if aid:
                    try: self.after_cancel(aid)
                    except Exception: pass
                self._pause_after_id = self.after(30000, self._refresh_pause_indicator)
        except tk.TclError:
            pass

    def _show_pause_info(self):                                    ### NEW v0.19.1 B22 ###
        act = api_pauses_active()
        if not act:
            self._refresh_pause_indicator(); return
        lines = []
        for svc, e in act.items():
            lines.append(f"{_SERVICE_LABEL.get(svc, svc)} — paused until {e['until'].replace('T', ' ')}\n"
                         f"{api_failure_message(svc, e.get('kind')) if e.get('kind') else e.get('message') or ''}")
        if messagebox.askyesno(_i18n.t("mc.online_services_paused_4645"),
                _i18n.t("mc.end_the_pause_now_6197", join="\n\n".join(lines)),
                parent=self):
            for svc in list(act):
                api_pause_end(svc)
        self._refresh_pause_indicator()

    def _ask_try_anyway(self, service, entry):                     ### NEW v0.19.1 B22 ###
        """UI thread: a paused service is needed — True = try anyway (tests replace this)."""
        dlg = _PauseAskDialog(self, service, entry)
        self.wait_window(dlg)
        return bool(dlg.result)

    def _confirm_services(self, services):                         ### NEW v0.19.1 B22 ###
        """UI thread, before an action that needs *services*: for each paused
        one show the message + advice with [Try anyway] [Cancel].  Try anyway
        ends the pause (a new failure starts it again).  False = do not start."""
        for svc in services:
            e = api_pause_get(svc)
            if not e:
                continue
            if not self._ask_try_anyway(svc, e):
                return False
            api_pause_end(svc)
        return True

    def _ask_service_failure(self, service, kind, other_label):    ### NEW v0.19.1 B22 ###
        """Worker thread, first failure of *service* in a batch run (asked once):
        "pause" | "continue" | "cancel"."""
        res = self._ask_on_ui(lambda: _ServiceFailureDialog(self, service, kind, other_label),
                              lambda dlg: dlg.result)
        return res or "continue"

    def _service_run_args(self, prog, alternatives):              ### NEW v0.19.1 B22 ###
        return dict(on_failure=self._ask_service_failure, alternatives=alternatives,
                    cancel_check=(lambda: bool(prog and prog.cancelled)))

    # ── v0.19.1 B15: hard-coded (burned-in) subtitles ────────────────────────
    def _hardsubs_for(self, data_list):                            ### NEW v0.19.1 B15 ###
        """Right-click → Hard-coded subtitles… (one movie or a selection)."""
        rows = [d for d in data_list if d.get("nfo_exists") or d.get("xml_exists")]
        if not rows:
            messagebox.showinfo(_i18n.t("mc.hard_coded_subtitles_034f"), _i18n.t("mc.no_nfo_or_xml_6a49"), parent=self)
            return
        sets = [set(d.get("subs_hard") or []) for d in rows]
        current = sorted(set.intersection(*sets)) if sets else []
        names = [d.get("movie_name") or d["subfolder"] for d in rows]
        return _HardsubDialog(self, names, current,
                              on_done=lambda codes, rr=rows: self._hardsubs_apply(rr, codes))

    def _hardsubs_apply(self, rows, codes, confirm=True):         ### NEW v0.19.1 B15 ###
        """UI thread: confirm a selection, then write in a worker."""
        if confirm and len(rows) > 1:
            names = [d.get("movie_name") or d["subfolder"] for d in rows]
            more = f"\n… and {len(names) - 15} more" if len(names) > 15 else ""
            what = ", ".join(codes) if codes else _i18n.t("uf.none_remove_all_marks_2847")
            if not messagebox.askyesno(_i18n.t("mc.hard_coded_subtitles_034f"),
                    _i18n.t("mc.set_hard_coded_subtitles_d130", what=what, n=_n(len(rows), 'movie'), join="\n".join(names[:15]), more=more), parent=self):
                return
        prog = _BatchProgressDialog(self, _i18n.t("uf.hard_coded_subtitles_5e0e"), total=len(rows)) \
               if len(rows) >= _PROGRESS_MIN else None
        _AppJobThread(self, target=self._hardsubs_worker, args=(list(rows), list(codes), prog),
                         act_paths=act_targets(rows)[0], daemon=True).start()   # v0.20.1 SN3

    @_labelled_backups("Hard-coded subtitles")                               ### NEW v0.19.1 I1 ###
    def _hardsubs_worker(self, rows, codes, prog=None):           ### NEW v0.19.1 B15 ###
        """Worker thread: backup + write the Hardsub tags, then refresh the rows."""
        backup_ref = [None]; changed_paths = []; errors = []
        for i, d in enumerate(rows):
            if prog and prog.cancelled:
                break
            nfo = _metadata_targets(d)[0]   # v0.20.0 F3b
            xml = _metadata_targets(d)[1]   # v0.20.0 F3b
            name = d.get("movie_name") or d["subfolder"]
            if get_hardsub_langs(nfo, xml) != sorted(codes):
                if not _batch_backup_ok(name, backup_ref, nfo, xml):    ### MODIFIED v0.19.2 B40 ###
                    ok, err = False, BACKUP_FAILED_TEXT
                else:
                    ok, err = _write_hardsub_tags(nfo, xml, codes)
                changed_paths.append(d["subfolder_path"])           # MODIFIED v0.19.5 WR-B2 — also a failure: one file may have changed
                if not ok:
                    errors.append(f"{name}: {err}")
            if prog:
                prog.advance(i + 1)
        if prog:
            prog.close()
        if changed_paths:
            self._schedule_refresh(changed_paths)
        what = ", ".join(codes) if codes else "none"
        def _done():
            try:
                self._sb_action.configure(text=_i18n.t("mc.hard_coded_subtitles_written_8146", what=what, n=_n(len(changed_paths), 'movie')))
            except Exception:
                pass
            if errors:
                messagebox.showerror(_i18n.t("mc.hard_coded_subtitles_034f"), "\n".join(errors[:20]), parent=self)
        ui_post(_done)

    # ── v0.19.1 B5: genres from TMDb / OMDb ──────────────────────────────────
    def _ask_genre_preview(self, text):                           ### NEW v0.19.1 ###
        """Worker thread: show the genres that would be written; True = write."""
        res = self._ask_on_ui(
            lambda: _PreviewRunDialog(self, _i18n.t("uf.normalize_genres_genres_found_9172"), text,
                                      "genres_online", run_label=_i18n.t("mc.write_genres_a5f6")),
            lambda dlg: bool(dlg.run))
        return bool(res)

    def _fetch_online_genres(self, d, nfo_path, xml_path, tmdb_key, omdb_key):   ### NEW v0.19.1 ###
        """(genres, source) for a movie without genres: TMDb (by TMDb ID, or the
        IMDb ID through /find), then OMDb.  ([], reason) when nothing is usable.
        Never used when Verify IDs said the ID belongs to another film."""
        chk = (d.get("id_check") or {}).get("result")
        if chk in (ID_OTHER, ID_DIFFERENT, ID_NOT_FOUND):
            return [], _i18n.t("uf.skipped_verify_ids_says_9d92", chk=chk)
        imdb_id, tmdb_id = get_movie_ids_robust(nfo_path, xml_path)
        if not imdb_id and not tmdb_id:
            return [], _i18n.t("uf.no_imdb_tmdb_id_a567")
        names, src = [], ""
        if tmdb_key:
            tid = tmdb_id
            if not tid and imdb_id:
                fr = _tmdb_find_imdb(imdb_id, tmdb_key)
                tid = str(fr[0].get("id")) if fr else None
            if tid:
                try:
                    data = _tmdb_rate_limited_fetch(
                        f"https://api.themoviedb.org/3/movie/{tid}?api_key={tmdb_key}&language=en-US", timeout=10)
                    names = [g.get("name") for g in (data.get("genres") or []) if g.get("name")]
                    src = "TMDB"
                except Exception as ex:
                    if not _is_http_404(ex):
                        raise
        if not names and omdb_key and imdb_id:
            data = _http_get_json("omdb", f"https://www.omdbapi.com/?apikey={omdb_key}&i={imdb_id}&type=movie", timeout=10)
            if data.get("Response") == "True" and data.get("Genre") and data.get("Genre") != "N/A":
                names = [x.strip() for x in data["Genre"].split(",") if x.strip()]
                src = "OMDb"
        if not names:
            return [], _i18n.t("uf.no_genres_on_tmdb_b241")
        normalized, _c = normalize_genre_list(names)
        return normalized, src

    def _normalize_genres_worker(self, data_list, prog=None):        ### NEW v0.19.1 B20 — one service run ###
        """Runs _normalize_genres_worker_run inside a service run (B20): a service that refuses
        (daily limit / invalid key) is not asked again until the run ends."""
        _service_run_begin(**self._service_run_args(prog, {"tmdb": _i18n.t("uf.omdb_imdb_data_5eaf"), "omdb": "TMDB"}))   ### B22 ###
        try:
            with _sc.backup_action("Normalize Genres"):                     ### NEW v0.19.1 I1 ###
                return self._normalize_genres_worker_run(data_list, prog)
        finally:
            _service_run_end()

    def _normalize_genres_worker_run(self, data_list, prog=None):   ### UPDATED v0.17.0 ###
        """Worker thread: normalizes genres per movie, shows custom-genre dialog per movie."""
        changed = 0
        errors  = []
        backup_ref = [None]
        remembered_delete = None     # v0.19.0: "Apply this choice to all remaining movies"
        multi = len(data_list) > 1
        changed_paths = []                                       ### v0.19.0 ###
        pending_online = []          # v0.19.1 B5: (row, nfo, xml, genres, source) fetched online
        online_skipped = []
        _tk = SETTINGS.get("tmdb_api_key", "").strip(); _ok = SETTINGS.get("omdb_api_key", "").strip()

        for _idx, d in enumerate(data_list):                  ### UPDATED v0.17.0 ###
            if (prog and prog.cancelled) or _service_run_cancelled():   # B22                       ### NEW v0.17.0 ###
                break
            # Each movie gets its OWN fresh genre read — no shared state ### NEW v0.15.0 ###
            nfo_path = _metadata_targets(d)[0]   # v0.20.0 F3b
            xml_path = _metadata_targets(d)[1]   # v0.20.0 F3b

            _ginfo = resolve_movie_genres(nfo_path, xml_path)   ### MODIFIED v0.19.1 — NFO + XML ###
            movie_genres = _ginfo["genres"]
            needs_sync = bool(_ginfo["only_in_xml"] or _ginfo["only_in_nfo"] or _ginfo["nfo_wrong"])
            if not movie_genres:
                # v0.19.1 B5 — no genres in either file: ask TMDb, then OMDb
                if (_tk or _ok) and (nfo_path or xml_path):
                    _name = d.get("movie_name") or d.get("subfolder", "?")
                    try:
                        fetched, why = self._fetch_online_genres(d, nfo_path, xml_path, _tk, _ok)
                    except Exception as ex:
                        fetched, why = [], _i18n.t("uf.could_not_reach_tmdb_0889", v=_tmdb_error_message(ex).splitlines()[0])
                    if fetched:
                        pending_online.append((d, nfo_path, xml_path, fetched, why))
                    else:
                        online_skipped.append(f"{_name}: {why}")
                if prog:
                    prog.advance(_idx + 1)
                continue

            valid_genres = _get_valid_genres()
            def _is_splittable(g, valid):                          ### FIX v0.15.0 ###
                """Return True if g is made up entirely of valid genres joined by /|\\,;"""  ### FIX v0.15.0 ###
                parts = [p.strip() for p in re.split(r'[/|,;]', g) if p.strip()]
                if len(parts) < 2: return False
                vl = {v.lower() for v in valid}
                return all(
                    p in valid or p.title() in valid
                    or normalize_genre(p) in valid
                    or normalize_genre(p).lower() in vl
                    for p in parts)
            custom = [g for g in movie_genres
                      if g not in valid_genres
                      and g.title() not in valid_genres
                      and normalize_genre(g) not in valid_genres
                      and normalize_genre(g).lower() not in {v.lower() for v in valid_genres}
                      and not _is_splittable(g, valid_genres)]  ### FIX v0.15.0 — splittable genres are not custom ###

            delete_custom = False
            if custom and remembered_delete is not None:          ### NEW v0.19.0 ###
                delete_custom = remembered_delete
            elif custom:
                movie_name = d.get("movie_name", d.get("subfolder", "?"))
                res = self._ask_on_ui(                            ### MODIFIED v0.19.0 — Event wait, apply-all ###
                    lambda mn=movie_name, cg=list(custom): CustomGenreDialog(self, mn, cg, show_apply_all=multi),
                    lambda dlg: (bool(dlg.delete_custom), bool(dlg.apply_all)))
                delete_custom, _apply_all = res if res else (False, False)
                if multi and _apply_all:
                    remembered_delete = delete_custom

            if delete_custom:
                # Keep only standard genres from this movie's list
                filtered = [g for g in movie_genres if g not in custom]
            else:
                filtered = list(movie_genres)

            normalized, did_change = normalize_genre_list(filtered)
            # Always write if custom genres were deleted, even if normalized list unchanged
            # v0.19.1: also when the NFO and XML genres are out of sync / non-Kodi tags
            if not did_change and not (delete_custom and custom) and not needs_sync:
                continue

            movie_name_b = d.get("movie_name", d.get("subfolder", "unknown"))
            if not _batch_backup_ok(movie_name_b, backup_ref, nfo_path, xml_path):   ### MODIFIED v0.19.2 B40 ###
                errors.append(f"{d['subfolder']}: {BACKUP_FAILED_TEXT}")
                if prog:
                    prog.advance(_idx + 1)
                continue
            ok_nfo, err_nfo = write_genres_to_nfo(nfo_path, normalized) if nfo_path else (False, "")
            ok_xml, err_xml = write_genres_to_xml(xml_path, normalized) if xml_path else (False, "")
            if ok_nfo or ok_xml:
                changed += 1
                changed_paths.append(d["subfolder_path"])            ### v0.19.0 ###
                d["genres"]        = normalized
                d["genre_display"] = "/".join(normalized)
                d["genre_status"]  = classify_genres(normalized)[1]
            if err_nfo: errors.append(f"{d['subfolder']}: {err_nfo}")
            if err_xml: errors.append(f"{d['subfolder']}: {err_xml}")
            if prog:                                           ### NEW v0.17.0 ###
                prog.advance(_idx + 1)

        # v0.19.1 B5 — genres fetched online: one preview, then write   ### NEW v0.19.1 ###
        n_online = 0
        if pending_online and not (prog and prog.cancelled):
            lines = [_i18n.t("uf.genres_found_online_for_e476", n=_n(len(pending_online), 'movie')), ""]
            for d, _nfo_, _x, g, src in pending_online:     # v0.19.4 B105: _n is the plurals helper
                lines.append(f"  {d.get('movie_name') or d.get('subfolder')}  →  {'/'.join(g)}   ({src})")
            if online_skipped:
                lines += ["", _i18n.t("uf.not_found_skipped_1b1f", n=len(online_skipped))] + [f"  {x}" for x in online_skipped]
            lines += ["", _i18n.t("uf.write_these_genres_to_24b7")]
            if self._ask_genre_preview("\n".join(lines)):
                for d, nfo_p, xml_p, g, src in pending_online:
                    nm = d.get("movie_name", d.get("subfolder", "unknown"))
                    if not _batch_backup_ok(nm, backup_ref, nfo_p, xml_p):   ### MODIFIED v0.19.2 B40 ###
                        errors.append(f"{d['subfolder']}: {BACKUP_FAILED_TEXT}")
                        continue
                    okn, en = write_genres_to_nfo(nfo_p, g) if nfo_p else (False, "")
                    okx, ex_ = write_genres_to_xml(xml_p, g) if xml_p else (False, "")
                    if okn or okx:
                        n_online += 1; changed += 1
                        changed_paths.append(d["subfolder_path"])
                        logger.info(f"Genres from {src} written: {nm} → {'/'.join(g)}")
                    if en: errors.append(f"{d['subfolder']}: {en}")
                    if ex_: errors.append(f"{d['subfolder']}: {ex_}")

        if prog:
            prog.close()                                      ### NEW v0.17.0 ###
        _svc = _service_run_summary()                          ### NEW v0.19.1 B20 ###
        def _done():
            self._schedule_refresh(changed_paths, need_ffprobe=False)   ### MODIFIED v0.19.0 — rescan, not just redraw ###
            msg = _i18n.t("mc.normalized_genres_in_59bb", n=_n(changed, 'movie'), v=f"\n{UNDO_HINT}" if changed else "")   # B109e
            if _svc:
                msg += "\n\n" + "\n".join(_svc)
            if n_online:
                msg += _i18n.t("mc.of_them_got_their_7a86", n_online=n_online)
            if online_skipped and not pending_online:
                msg += (_i18n.t("mc.no_genres_found_online_2b7c", n=_n(len(online_skipped), 'movie'), join="\n".join(online_skipped[:6]), v="\n…" if len(online_skipped) > 6 else ""))
            if errors:
                msg += _i18n.t("mc.errors_83c4", join="\n".join(errors[:5]))
            messagebox.showinfo(_i18n.t("mc.normalize_genres_acad"), msg, parent=self)
        ui_post(_done)

