    def _normalize_sources_for(self, data_list):               ### NEW v0.16.0 ###
        """Launch Normalize Sources for given data_list in a background thread."""
        if not self._confirm_services(("tmdb",)):          ### NEW v0.19.1 B22 — paused service: Try anyway? ###
            return
        if not data_list:
            return
        prog = None                                            ### NEW v0.17.0 ###
        if len(data_list) >= _PROGRESS_MIN:                     ### MODIFIED v0.19.1 — was 10 ###
            prog = _BatchProgressDialog(self, _i18n.t("uf.processing_movies_normalize_sources_f1bb"),
                                        total=len(data_list))
        _AppJobThread(
            self, target=self._normalize_sources_worker, act_paths=act_targets(data_list)[0],   # v0.20.1 SN3
            args=(list(data_list), prog),                     ### NEW v0.17.0 ###
            daemon=True).start()

    def _normalize_sources_all(self):                          ### NEW v0.16.0 ###
        """Normalize Sources for all movies with ◐ or ○ in Source column."""
        if self._busy():                                       ### NEW v0.19.4 B91 ###
            return
        if self._no_scan("No data"):                ### MODIFIED v0.19.4 I17 ###
            return
        targets = [r for r in self._results
                   if r.get("source_imdb_status") in (STATUS_WARN, STATUS_MISSING, STATUS_ERROR)   # P4 (E2)
                   or r.get("source_tmdb_status") in (STATUS_WARN, STATUS_MISSING, STATUS_ERROR)]
        if not targets:
            messagebox.showinfo(_i18n.t("mc.normalize_sources_all_movies_5eda"),
                                _i18n.t("mc.no_movies_with_missing_ae8b")); return
        ### MODIFIED v0.19.3 I6 — a preview instead of the yes/no question ###
        if not _ask_preview(self, _i18n.t("uf.normalize_sources_all_movies_c084"), sources_preview_text(targets),
                            "normalize_sources_preview", "  ▶ Normalize Sources  "):
            return
        self._normalize_sources_for(targets)

    @_labelled_backups("Normalize Sources")                               ### NEW v0.19.1 I1 ###
    def _normalize_sources_worker(self, data_list, prog=None):  ### UPDATED v0.17.0 ###
        """
        Worker thread: normalize IMDB/TMDB source tags for each movie.
        Case A: tags present but some missing, all agree → auto-fill silently.
        Case B: tags disagree → popup to pick correct ID.
        Case C: all tags missing → popup to type an ID.
        Skips movie on cancel or window-close.
        """
        import time as _time
        changed = 0; errors = []
        backup_ref = [None]
        skip_missing_all = False     # v0.19.0: "Skip all remaining" in the type-an-ID dialog
        multi = len(data_list) > 1
        changed_paths = []                                       ### v0.19.0 ###

        for _idx, d in enumerate(data_list):                  ### UPDATED v0.17.0 ###
            if prog and prog.cancelled:                       ### NEW v0.17.0 ###
                break
            nfo_path   = _metadata_targets(d)[0]   # v0.20.0 F3b
            xml_path   = _metadata_targets(d)[1]   # v0.20.0 F3b
            movie_name = d.get("movie_name", d.get("subfolder", "?"))

            src      = extract_source_ids_from_files(nfo_path, xml_path)
            imdb_all = src["imdb_all_vals"]
            tmdb_all = src["tmdb_all_vals"]

            for id_type, all_vals, status in [
                ("IMDB", imdb_all, src["imdb_status"]),
                ("TMDB", tmdb_all, src["tmdb_status"]),
            ]:
                chosen_id = None

                if status == STATUS_OK:
                    continue

                elif status == STATUS_MISSING or (status == STATUS_ERROR and not any(all_vals)
                                                  and src.get(f"{id_type.lower()}_invalid_vals")):
                    # Case C — ask user to type ID ("Skip all remaining" remembered per run)
                    # ### v0.20.0 RD11b ### also when the tags hold only a value that is not an ID ('7840' in the IMDb
                    # tag): it used to be skipped silently; the typed ID replaces the bad value in every tag
                    if skip_missing_all:                              ### NEW v0.19.0 ###
                        continue
                    res = self._ask_on_ui(                            ### MODIFIED v0.19.0 — Event wait ###
                        lambda mn=movie_name, it=id_type: _SourceManualEntryDialog(self, mn, it, show_skip_all=multi),
                        lambda dlg: (dlg.result_id, dlg.skip_all))
                    rid, _skip_all = res if res else (None, False)
                    if _skip_all:
                        skip_missing_all = True
                    if not rid:
                        continue
                    chosen_id = rid.strip()

                elif status in (STATUS_WARN, STATUS_ERROR) and len({v for v in all_vals if v}) > 1:
                    # Case B — show disagreement popup  ### MODIFIED v0.19.4 P4 (E18) — the shared helper, no time limit ###
                    rid = self._ask_on_ui(
                        lambda mn=movie_name, it=id_type, vals=[v for v in all_vals if v]: _SourceDisagreementDialog(self, mn, it, vals),
                        lambda dlg: dlg.result_id)
                    if not rid:
                        continue
                    chosen_id = rid.strip()

                elif status in (STATUS_WARN, STATUS_ERROR) and len({v for v in all_vals if v}) == 1:
                    # Case A — auto-fill silently  ### P4 (E2): also empty tags next to the value ###
                    chosen_id = next(v for v in all_vals if v)

                if not chosen_id:
                    continue

                if not _batch_backup_ok(movie_name, backup_ref, nfo_path, xml_path):   ### MODIFIED v0.19.2 B40 ###
                    ok, err = False, BACKUP_FAILED_TEXT
                else:
                    ok, err = _write_source_id_to_files(
                        nfo_path, xml_path, id_type, chosen_id)
                if ok:
                    changed += 1
                    if d["subfolder_path"] not in changed_paths:
                        changed_paths.append(d["subfolder_path"])   ### v0.19.0 ###
                elif err:
                    errors.append(f"{movie_name} ({id_type}): {err}")
                    if d["subfolder_path"] not in changed_paths:       ### NEW v0.19.5 WR-B2 — one file may have changed ###
                        changed_paths.append(d["subfolder_path"])

            if prog:                                           ### NEW v0.17.0 ###
                prog.advance(_idx + 1)

        if prog:
            prog.close()                                      ### NEW v0.17.0 ###
        def _done():
            self._schedule_refresh(changed_paths, need_ffprobe=False)   ### MODIFIED v0.19.0 ###
            msg = _i18n.t("mc.normalize_sources_updated_9182", n=_n(changed, 'ID'), v=f"\n{UNDO_HINT}" if changed else "")   # B109e
            if errors:
                msg += _i18n.t("mc.errors_83c4", join="\n".join(errors[:5]))
            messagebox.showinfo(_i18n.t("mc.normalize_sources_af3c"), msg, parent=self)
        ui_post(_done)

