    # ── v0.19.4 B110b: Check Collections Online ──
    def _check_collections_all(self):                              ### NEW v0.19.4 B110b ###
        if self._busy():
            return
        if self._no_scan("No data"):
            return
        self._check_collections(list(self._results), ask=True)

    def _check_collections(self, rows, ask=False, fetch=None):    ### NEW v0.19.4 B110b ###
        """One movie, the selection or all: TMDB's collection of each movie (one request per movie, two per
        collection), for movies whose data is missing or older than 30 days."""
        title = CHECK_COLL_LABEL.split("  ", 1)[-1].rstrip("…")
        if self._busy() or not rows:
            return
        if not self._confirm_services(("tmdb",)):
            return
        key = SETTINGS.get("tmdb_api_key", "").strip()
        if not key:
            messagebox.showwarning(title, _i18n.t("mc.no_tmdb_api_key_6e12"), parent=self)
            return
        now = time.time()
        todo, skipped = [], {}
        for r in rows:
            ok, why = collection_check_ready(r)
            if not ok:
                skipped[why] = skipped.get(why, 0) + 1
            elif _cr.needs_check(r, now) or _coll_lacks_english(r):   ### fix 10 ###
                todo.append(r)
        fresh = len(rows) - len(todo) - sum(skipped.values())
        if not todo and fresh > 0:                                 ### NEW v0.19.4 fix 12 — offer to check again ###
            if not messagebox.askyesno(title, collection_check_summary(0, 0, skipped, fresh)
                                       + _i18n.tn("m3.check_again", fresh), icon="question", parent=self):
                return
            todo = [r for r in rows if collection_check_ready(r)[0]]
            ask, fresh = False, 0                                  # P2 (E16): they are asked now
        if not todo:
            messagebox.showinfo(title, collection_check_summary(0, 0, skipped, fresh), parent=self)
            return
        if ask and not messagebox.askyesno(title,
                _i18n.t("mc.ask_tmdb_for_the_e7ee", n=_n(len(todo), 'movie'), v="\n\n" + all_movies_note(self) if all_movies_note(self) else ""),
                icon="question", parent=self):
            return
        prog = _BatchProgressDialog(self, _i18n.t("au.prog.check_coll"), total=len(todo)) if len(todo) >= _PROGRESS_MIN else None
        lang = _tmdb_lang_for(SETTINGS.get("lang_ok_code", "EN"))
        _AppJobThread(self, target=self._check_collections_worker, args=(todo, key, lang, prog, skipped, fresh, fetch),
                         name="check-collections", daemon=True).start()

    # ── v0.19.4 B110e: the collection fix, Set / Remove ──
    def _lib_lang(self):
        return _tmdb_lang_for(SETTINGS.get("lang_ok_code", "EN"))

    def _fix_collections_all(self):                                ### NEW v0.19.4 B110e ###
        if self._busy():
            return None
        if self._no_scan("No data"):
            return None
        return self._fix_collections_for(list(self._results))

    def _fix_collections_for(self, rows, preview=True):           ### NEW v0.19.4 B110e ###
        title = FIX_COLL_LABEL.split("  ", 1)[-1].rstrip("…")
        if self._busy():
            return None
        rows = collection_siblings(list(rows), self._results)     ### NEW v0.19.4 fix 5 — the whole collection, one name ###
        items, skipped = collection_fix_items(rows, None, self._lib_lang())
        ### NEW v0.20.1 SN1 — Fix Collection also fixes the collection's set.nfo (the user, 2026-11-20: the panel showed
        # "no set.nfo", Fix Collection wrote only the names, and a second Fix said "Nothing to change"). The set.nfo
        # step runs after the names are written and the collection folder is read again (a rename moves the folder).
        targets = collection_fix_targets(rows, items)
        if not items:
            nothing = _i18n.t("mc.nothing_to_change_6e7b", join="\n".join(f"{_n(k, 'movie')} — {why}" for why, k in sorted(skipped.items())))
            return self._coll_set_nfo_fix(targets, nothing_msg=(title, nothing))
        if preview and (len(items) > 1 or skipped):
            pv = _PreviewRunDialog(self, FIX_COLL_LABEL.rstrip("…") + " — " + _i18n.t("f3r.preview"),
                                   collection_fix_text(items, skipped) + "\n\n" + _i18n.t("sn1.preview_note"),
                                   file_stem="collection_fix_preview", run_label=_i18n.t("mc.write_collections_87e1"))
            self._coll_fix_preview = pv
            self.wait_window(pv)
            if not pv.run:
                return None
        return self._write_collections(items, title, then=lambda job: self._coll_set_nfo_fix(targets))

    def _coll_set_nfo_fix(self, targets, nothing_msg=None):        ### NEW v0.20.1 SN1 ###
        """Read the collection folders again (with the names just written), then write / complete the set.nfo of each
        target collection that has a mistake. A text that differs asks first (the CF2 choice "Use TMDB's").
        *nothing_msg* = (title, text) shown when neither the names nor any set.nfo needed a change."""
        self._cf_extra_names = {nm for _k, nm, _rs in targets}

        def _then():
            groups = []
            for key, name, rs in targets:
                f = collection_set_nfo_findings(key, name, rs)
                if f is not None and f["mistakes"]:
                    groups.append((key, name, rs, f))
            self._coll_set_nfo_groups = groups                    # read by the self-test
            if not groups:
                if nothing_msg:
                    messagebox.showinfo(nothing_msg[0], nothing_msg[1], parent=self)
                return None
            use = set()
            if any({"title_differs", "other_language"} & set(g[3]["mistakes"]) for g in groups):
                dlg = _SetNfoDialog(self, groups)
                self.wait_window(dlg)
                if dlg.result is None:
                    return None
                use = dlg.result
            return self._set_nfo_run(groups, use)
        self._read_collection_folders(then=_then)
        return None

    # ── v0.19.4 B110g: the collection folder ──
    def _read_collection_folders(self, then=None):                 ### NEW v0.19.4 B110g ###
        """Worker: list the set folders; Tk thread: health + table.  Nothing while the setting is empty."""
        root = _coll_root()                                       ### v0.19.4 fix 2e ###
        ### MODIFIED v0.20.1 SN1 — also the names a fix just wrote (the rows are re-read later, in the background) ###
        _extra, self._cf_extra_names = set(getattr(self, "_cf_extra_names", None) or ()), set()
        names = sorted({collection_name(r) for r in self._results if collection_name(r)} | {n for n in _extra if n})
        aliases = collection_aliases(self._results)              ### NEW v0.19.4 fix 15 ###
        if not root:
            if COLL_FOLDERS:                                        ### MODIFIED v0.19.4 P1 (B15) — re-check the rows ###
                COLL_FOLDERS.clear()
                finalize_results(self._results)
                self._refresh_table(); self._update_stats()
            if then:
                then()
            return

        ### MODIFIED v0.19.4 P2 (E5) — each read hands its own result to its callback; only the newest read is
        ### applied (an older one finishing later on the share can't overwrite it), then every waiting "then" ###
        self._cf_gen = gen = getattr(self, "_cf_gen", 0) + 1
        self._cf_thens = list(getattr(self, "_cf_thens", None) or []) + ([then] if then else [])
        _tok = _ACT.begin(_i18n.t("sn3.reading_coll"), (root,), ("*",))   # v0.20.1 SN3: every collection panel

        def work():
            try:
                res = read_collection_folders(root, names, aliases)
            except Exception as ex:
                logger.warning(f"Collection folder not read: {ex}")
                res = None
            try:
                ui_post(lambda r=res: apply(r))
            except (RuntimeError, tk.TclError):
                _ACT.end(_tok)

        def apply(res):
            try:
                _apply_cf(res)
            finally:
                _ACT.end(_tok)                                 # after the panel shows the new state

        def _apply_cf(res):
            if gen != self._cf_gen:                            # a newer read is on its way
                return
            thens, self._cf_thens = self._cf_thens, []
            same = dict(COLL_FOLDERS) == (res or {})                   # P6 (E13): nothing new → no rebuild
            COLL_FOLDERS.clear()
            if res:
                COLL_FOLDERS.update(res)
            if not same:
                finalize_results(self._results)
                self._refresh_table(); self._update_stats()
            self._coll_folders_read = True                     # read by the self-test
            for t in thens:
                t()
            try:                                               ### NEW v0.19.4 fix 17 — the panel shows the new state ###
                if self._panel_shown():
                    self._panel_refresh()
            except Exception:
                pass
        self._coll_folders_read = False
        threading.Thread(target=work, name="collection-folders", daemon=True).start()

    def _set_nfo_all(self):                                        ### NEW v0.20.1 CF2 ###
        """Tools → Collections → Check / Write set.nfo…: every collection the check applies to; missing files and empty
        tags are written / filled; for a text that differs the user ticks "Use TMDB's" per collection; backup, Undo."""
        if self._busy(SET_NFO_ACTION) or self._no_scan("No data"):
            return None
        groups = collection_set_nfo_groups(self._results)
        if not groups:
            messagebox.showinfo(shown_action(SET_NFO_ACTION), _i18n.t("cf2.none"), parent=self)
            return None
        dlg = _SetNfoDialog(self, groups)
        self.wait_window(dlg)
        if dlg.result is None:
            return None
        return self._set_nfo_run(groups, dlg.result)

    def _refresh_collection(self, rows):                           ### NEW v0.20.1 SN1 — the user, 2026-11-20 ###
        """Refresh a collection: its folder (artwork, set.nfo) is read again, and its movies are re-read in the
        background (no FFprobe), like Update on a movie. The panel and the table follow."""
        if self._busy():
            return None
        rows = [r for r in rows if r]
        self._cf_extra_names = {collection_name(r) for r in rows if collection_name(r)}
        self._read_collection_folders()
        paths = [r.get("subfolder_path") for r in rows if r.get("subfolder_path")]
        if paths:
            self._schedule_refresh(paths, need_ffprobe=False)
            try:
                self._sb_action.configure(text=_i18n.t("mc.updating_in_the_background_88de", n=_n(len(paths), 'movie')))
            except (AttributeError, tk.TclError):
                pass
        self._coll_refreshed = len(paths)                          # read by the self-test
        return None

    def _set_nfo_for(self, key, name, rows):                       ### NEW v0.20.1 L4 — one collection (its panel) ###
        if self._busy(SET_NFO_ACTION):
            return None
        f = collection_set_nfo_findings(key, name, rows)
        if f is None:
            messagebox.showinfo(shown_action(SET_NFO_ACTION), _i18n.t("cf2.none"), parent=self)
            return None
        groups = [(key, name, rows, f)]
        dlg = _SetNfoDialog(self, groups)
        self.wait_window(dlg)
        if dlg.result is None:
            return None
        return self._set_nfo_run(groups, dlg.result)

    def _set_nfo_run(self, groups, use_tmdb):                     ### NEW v0.20.1 CF2 ###
        """Write / fill set.nfo for *groups*; *use_tmdb* = the keys whose differing text takes TMDB's / the NFO name."""
        todo = [g for g in groups if g[3]["mistakes"] or g[0] in use_tmdb]

        def _step(job, g):
            key, name, rows, f = g
            path = f["path"]
            if f["existing"] is None and not os.path.exists(path):   # v0.20.1 SN1: a file made meanwhile is filled, never overwritten
                write_set_nfo(path, _sn.build(name, f["want_overview"]))
                _sc.note_created(_BACKUP_ROOT, name, job.ref, path, None, logger=logger)
                return True
            old = _read_for_edit(path)[0]                          # v0.20.1 B16: strict — not UTF-8 → listed, not written
            new = _sn.fill(old, name, f["want_overview"])
            if key in use_tmdb:
                if "title_differs" in f["mistakes"]:
                    new = _sn.replace_tag(new, "title", name)
                if f["want_overview"] and ({"other_language"} & set(f["mistakes"]) or "overview_differs" in f["notes"]):
                    new = _sn.replace_tag(new, "overview", f["want_overview"])
            if new == old:
                raise _bulk.Skip("nothing")
            if not job.backup(name, path):
                raise BackupFailed()
            write_set_nfo(path, new)
            return True

        def _finish(job):
            ### NEW v0.20.1 SN1 — the result is checked on disk: a set.nfo that is still not there is an error, never "done" ###
            for _g in todo:
                if not os.path.isfile(_g[3]["path"]) and not any(_g[1] in e for e in job.errors):
                    job.errors.append(f"{_g[1]}: {_i18n.t('sn1.not_on_disk', p=_g[3]['path'])}")
            msg = _i18n.t("cf2.done", n=_n(job.done, "collection"))
            if job.errors:
                msg += _i18n.t("bf.failed", join="\n".join(job.errors[:8]))
            msg += ("\n\n" + UNDO_HINT) if job.done else ""
            self._last_set_nfo = (job.done, list(job.errors))                 # read by the self-test
            (messagebox.showwarning if job.errors else messagebox.showinfo)(shown_action(SET_NFO_ACTION), msg, parent=self)
            ### MODIFIED v0.20.1 SN1 — the folders of the collections just written are read too (their movies may still
            # carry the old name until the background re-read; without this the panel lost the folder: "not checked") ###
            self._cf_extra_names = set(getattr(self, "_cf_extra_names", None) or ()) | {g[1] for g in todo}
            self._read_collection_folders()

        job = _BatchJob(self, todo, SET_NFO_ACTION, progress_title=_i18n.t("cf2.progress"), name_of=lambda g: g[1])
        return job.run(_step, _finish)

    # ── v0.20.2 SE: the set.nfo editor (one collection) ──
    def _set_nfo_edit_for(self, key, name, rows, _reread=True):    ### NEW v0.20.2 SE ###
        """Create / edit the set.nfo of one collection (panel, right-click, Tools → Collections). Kodi 22+; Kodi ticked;
        the collection folder set (asked once) and read first; the file is read in a worker, strictly as UTF-8."""
        T = _i18n.t
        title = shown_action(SET_NFO_EDIT_ACTION)
        if self._busy(title):
            return None
        rows = [r for r in rows if r]                              # the collection's own rows (one name = one Kodi set)
        if set_nfo_editor_state(key, name, rows) is None:
            messagebox.showinfo(title, T("se.no_kodi"), parent=self)
            return None
        root = self._ask_coll_root(title)
        if not root:
            return None
        if key not in COLL_FOLDERS:
            if _reread:                                            # read the collection folders first, then come back
                self._cf_extra_names = set(getattr(self, "_cf_extra_names", None) or ()) | {name}
                self._read_collection_folders(then=lambda: self._set_nfo_edit_for(key, name, rows, _reread=False))
                return None
            messagebox.showwarning(title, T("se.root_unreachable", root=root), parent=self)   # never a folder made there
            return None
        st = set_nfo_editor_state(key, name, rows)
        if not st["mode"]:
            messagebox.showinfo(title, T("se.not_own", name=name), parent=self)
            return None
        if st["mode"] == "create":
            return self._set_nfo_edit_open(key, name, rows, st, None, None)
        path = st["path"]

        def work():
            try:
                txt, err = _read_for_edit(path)[0], None
            except NotUtf8Error:
                txt, err = None, T("se.not_utf8", p=path)
            except OSError as ex:
                txt, err = None, f"{path}: {ex}"
            try:
                ui_post(lambda: self._set_nfo_edit_open(key, name, rows, st, txt, err))
            except (RuntimeError, tk.TclError):
                pass
        threading.Thread(target=work, name="set-nfo-read", daemon=True).start()
        return None

    def _set_nfo_edit_open(self, key, name, rows, st, text, err):  ### NEW v0.20.2 SE ###
        T = _i18n.t
        title = shown_action(SET_NFO_EDIT_ACTION)
        if err:
            messagebox.showwarning(title, err, parent=self)
            return None
        vals = None
        if st["mode"] == "edit":
            vals = _sn.values(text)
            if vals is None:
                messagebox.showwarning(title, T("se.not_set", p=st["path"]), parent=self)
                return None
        dlg = _SetNfoEditDialog(self, name, st, vals)
        self._set_nfo_edit_dlg = dlg                               # read by the self-test
        self.wait_window(dlg)
        if dlg.result is None:
            return None
        return self._set_nfo_edit_run(key, name, st, text, dlg.result)

    def _set_nfo_edit_run(self, key, name, st, text_at_open, fields):   ### NEW v0.20.2 SE ###
        """Write the editor's fields: a new folder (Undo removes it) and file, or the file edited after a backup.
        A file that appeared / changed since the editor opened is left alone (an error: open the editor again)."""
        T = _i18n.t
        root = _coll_root()
        item = {"name": name, "dir": st["dir"], "path": st["path"], "mode": st["mode"]}

        def _step(job, it):
            if not root or not os.path.isdir(root):
                raise RuntimeError(T("se.root_unreachable", root=root or "—"))
            path = it["path"]
            if it["mode"] == "create":
                if os.path.exists(path):
                    raise RuntimeError(T("se.changed_meanwhile"))
                if not os.path.isdir(it["dir"]):
                    os.makedirs(it["dir"])
                    _sc.note_created(_BACKUP_ROOT, name, job.ref, it["dir"], it["dir"], logger=logger)
                write_set_nfo(path, _sn.build(name, fields["overview"], fields["originaltitle"]))
                _sc.note_created(_BACKUP_ROOT, name, job.ref, path, None, logger=logger)
                return True
            old = _read_for_edit(path)[0]
            if old != text_at_open:
                raise RuntimeError(T("se.changed_meanwhile"))
            new = _sn.edit(old, name, fields["originaltitle"], fields["overview"])
            if new == old:
                raise _bulk.Skip("nothing")
            if not job.backup(name, path):
                raise BackupFailed()
            write_set_nfo(path, new)
            return True

        def _finish(job):
            if job.errors:
                msg = T("se.failed", join="\n".join(job.errors[:4]))
            elif job.done:
                msg = T("se.done", p=item["path"]) + "\n\n" + UNDO_HINT
            else:
                msg = T("se.nothing")
            self._last_set_nfo_edit = (job.done, list(job.errors), job.ref[0])    # read by the self-test
            (messagebox.showwarning if job.errors else messagebox.showinfo)(shown_action(SET_NFO_EDIT_ACTION), msg, parent=self)
            self._cf_extra_names = set(getattr(self, "_cf_extra_names", None) or ()) | {name}
            self._read_collection_folders()

        job = _BatchJob(self, [item], SET_NFO_EDIT_ACTION, name_of=lambda it: it["name"])
        return job.run(_step, _finish)

    def _set_nfo_edit_all(self, _reread=True):                     ### NEW v0.20.2 SE — Tools → Collections ###
        """Choose one collection (those with a set.nfo, and the own ones without), then its editor."""
        T = _i18n.t
        title = shown_action(SET_NFO_EDIT_ACTION)
        if self._busy(title) or self._no_scan("No data"):
            return None
        by = {}
        for r in self._results:
            k = _cr.group_key(r)
            if k:
                by.setdefault(k, (collection_name(r), []))[1].append(r)
        cand = {k: v for k, v in by.items() if set_nfo_editor_state(k, v[0], v[1]) is not None}
        if not cand:
            messagebox.showinfo(title, T("se.no_kodi"), parent=self)
            return None
        root = self._ask_coll_root(title)
        if not root:
            return None
        if any(k not in COLL_FOLDERS for k in cand):
            if _reread:
                self._read_collection_folders(then=lambda: self._set_nfo_edit_all(_reread=False))
                return None
            if not COLL_FOLDERS:
                messagebox.showwarning(title, T("se.root_unreachable", root=root), parent=self)
                return None
        items = []
        for k, (nm, rs) in sorted(cand.items(), key=lambda kv: kv[1][0].lower()):
            st = set_nfo_editor_state(k, nm, rs)
            if st and st["mode"]:
                items.append((k, nm, st["mode"]))
        if not items:
            messagebox.showinfo(title, T("se.pick_none"), parent=self)
            return None
        dlg = _SetNfoPickDialog(self, items)
        self._set_nfo_pick_dlg = dlg                               # read by the self-test
        self.wait_window(dlg)
        if dlg.result is None:
            return None
        nm, rs = cand[dlg.result]
        return self._set_nfo_edit_for(dlg.result, nm, rs)

    # ── v0.20.2 CG: Collection Gaps ──
    def _cg_selected_rows(self, iid, rows):                         ### NEW v0.20.2 CG ###
        """The right-clicked collection, plus the other collection rows selected with it."""
        sel = [i for i in self.tree.selection() if i in getattr(self, "_coll_map", {})]   # B110h helper (collection rows)
        if iid not in sel or len(sel) < 2:
            return list(rows)
        out, seen = [], set()
        for i in sel:
            for r in self._coll_rows(i):
                if id(r) not in seen:
                    seen.add(id(r)); out.append(r)
        return out

    def _cg_library(self):
        return list(self._results) + list(getattr(self, "_inactive_rows", None) or [])

    def _collection_gaps(self, rows=None):                         ### NEW v0.20.2 CG ###
        """Collection Gaps for *rows* (None = every collection): movies never checked online are checked first, then
        the collections' movie lists are read (missing, stale, another language); then the report window. Without a
        TMDB key, after Cancel or an error the report still opens (the rest is "not checked")."""
        T = _i18n.t
        title = T("cg.title")
        if self._busy(title) or self._no_scan("No data"):
            return None
        rows = list(self._results) if rows is None else [r for r in rows if r]
        if not any(_cr.group_key(r) for r in rows):
            messagebox.showinfo(title, T("cg.none"), parent=self)
            return None
        key = SETTINGS.get("tmdb_api_key", "").strip()
        lang = self._lib_lang()
        notes = [] if key else [T("cg.no_key_note")]
        if key and not self._confirm_services(("tmdb",)):
            key, notes = "", [T("cg.cancelled_note")]
        movies = [r for r in rows if key and _cr.group_key(r) and r.get("coll_tmdb") is None and collection_check_ready(r)[0]]
        self._cg_done = None                                       # read by the self-test
        if not movies:
            return self._cg_phase2(rows, key, lang, notes)
        prog = _BatchProgressDialog(self, T("cg.prog_movies"), total=len(movies)) if len(movies) >= _PROGRESS_MIN else None

        def work(fetch=None):
            fetch = fetch or _tmdb_rate_limited_fetch
            got, err, stopped = [], None, False
            for i, r in enumerate(movies):
                if prog and prog.cancelled:
                    stopped = True
                    break
                try:
                    data = _tmdb_movie_full(r["source_tmdb_val"].strip(), key, lang, fetch)
                    ct = _cr.coll_from_movie(data, lang, time.time())
                    if isinstance(ct, dict):
                        ct["tl"] = _cr.loose_title(_cr.local_title(r))
                        got.append((r, ct, _cr.title_langs_from(data, [_cr.local_title(r)]), _cr.titles_by_lang(data)))
                except Exception as ex:
                    if _is_http_404(ex):
                        continue
                    err = _tmdb_error_message(ex)
                    logger.error(f"Collection Gaps: online check stopped at '{r.get('movie_name')}': {err}")
                    break
                if prog:
                    prog.advance(i + 1)
            if prog:
                prog.close()
            ui_post(lambda: _apply(got, err, stopped))

        def _apply(got, err, stopped):
            by_path = {r.get("subfolder_path"): r for r in self._results}
            for r, ct, tl, tt in got:
                r = by_path.get(r.get("subfolder_path"), r)
                r["coll_tmdb"], r["title_langs"], r["tmdb_titles"] = ct, tl, tt
            if got:
                finalize_results(self._results)
                self._refresh_table(); self._update_stats()
                self._incremental_save(self._results)
            if err:
                notes.append(T("cg.stopped_note", e=err))
            elif stopped:
                notes.append(T("cg.cancelled_note"))
            cur = {r.get("subfolder_path"): r for r in self._results}
            self._cg_phase2([cur.get(r.get("subfolder_path"), r) for r in rows], "" if (err or stopped) else key, lang, notes)
        _AppJobThread(self, target=lambda: work(getattr(self, "_cg_fetch", None)), name="collection-gaps-movies",
                      daemon=True).start()
        return None

    def _cg_phase2(self, rows, key, lang, notes):                  ### NEW v0.20.2 CG ###
        """The movie lists of the TMDB collections whose cache entry is missing / stale / in another language."""
        T = _i18n.t
        groups, _sk = collection_gap_groups(rows)
        now = time.time()
        cids = [str(g["cid"]) for g in groups if _cr.gaps_entry_stale(COLL_CACHE.get(str(g["cid"])), lang, now)]
        if not (key and cids):
            return self._cg_show(rows, notes, ())
        prog = _BatchProgressDialog(self, T("cg.prog_colls"), total=len(cids)) if len(cids) >= _PROGRESS_MIN else None

        def work(fetch=None):
            fetch = fetch or _tmdb_rate_limited_fetch
            got, gone, err, stopped = {}, set(), None, False
            for i, cid in enumerate(cids):
                if prog and prog.cancelled:
                    stopped = True
                    break
                base = f"https://api.themoviedb.org/3/collection/{cid}"
                try:
                    main = fetch(f"{base}?api_key={key}&language={lang}")
                    trs = fetch(f"{base}/translations?api_key={key}")
                    ent = _cr.coll_cache_entry(main, trs, lang, time.time())
                    if not ent["names"].get("en"):                 # as Check Collections Online (fix 10)
                        en = fetch(f"{base}?api_key={key}&language=en-US") or {}
                        if (en.get("name") or "").strip():
                            ent["names"]["en"] = en["name"].strip()
                        if (en.get("overview") or "").strip():
                            ent["overviews"].setdefault("en", en["overview"].strip())
                    got[cid] = ent
                except Exception as ex:
                    if _is_http_404(ex):
                        gone.add(cid)
                        continue
                    err = _tmdb_error_message(ex)
                    logger.error(f"Collection Gaps: collection {cid} not read: {err}")
                    break
                if prog:
                    prog.advance(i + 1)
            if prog:
                prog.close()
            ui_post(lambda: _apply(got, gone, err, stopped))

        def _apply(got, gone, err, stopped):
            for cid, ent in got.items():
                old = COLL_CACHE.get(cid) or {}
                for k in ("names", "overviews"):                   # names TMDB gave in other runs stay
                    ent[k] = dict(old.get(k) or {}, **ent[k])
                COLL_CACHE[cid] = ent
            for cid in gone:
                COLL_CACHE.pop(cid, None)
            if got or gone:
                _sc.save_collections_cache(dict(COLL_CACHE))
            if err:
                notes.append(T("cg.stopped_note", e=err))
            elif stopped:
                notes.append(T("cg.cancelled_note"))
            self._cg_show(rows, notes, gone)
        _AppJobThread(self, target=lambda: work(getattr(self, "_cg_fetch", None)), name="collection-gaps-collections",
                      daemon=True).start()
        return None

    def _cg_compute(self, rows, gone=()):                          ### NEW v0.20.2 CG ###
        groups, skipped = collection_gap_groups(rows)
        res, sk2 = collection_gaps_results(groups, self._cg_library(), _sc.load_gaps_ignored(logger),
                                           _cg.today_iso(getattr(self, "_cg_today", None)), gone)
        return res, skipped + sk2

    def _cg_show(self, rows, notes, gone):                         ### NEW v0.20.2 CG ###
        paths = {r.get("subfolder_path") for r in rows}
        scope = lambda: [r for r in self._results if r.get("subfolder_path") in paths]
        res, skipped = self._cg_compute(scope(), gone)
        libs = sorted({_lib_root_of(r) for r in self._cg_library() if _lib_root_of(r)}, key=str.casefold)
        missing = self._libs_not_loaded()
        if missing:
            notes = list(notes) + [_i18n.t("cg.libs_missing", libs=", ".join(missing))]
        old = getattr(self, "_cg_dlg", None)
        try:
            if old is not None and old.winfo_exists():
                old.destroy()
        except tk.TclError:
            pass
        dlg = _CollectionGapsDialog(self, res, skipped, libs, len(self._cg_library()), notes,
                                    _cg.today_iso(getattr(self, "_cg_today", None)),
                                    recompute=lambda: self._cg_compute(scope(), gone))
        self._cg_dlg = dlg                                         # read by the self-test
        self._cg_done = (len(res), len(skipped))
        return dlg

    def _cg_row_now(self, row):
        p = (row or {}).get("subfolder_path")
        return next((r for r in self._results if r.get("subfolder_path") == p), row)

    def _cg_fix(self, dlg, res, item):                             ### NEW v0.20.2 CG — the fix of one missing movie ###
        T = _i18n.t
        title = T("cg.title")
        if self._busy(title):
            return None
        row = self._cg_row_now(item["row"])
        cid, name, part = res["cid"], res["name"], item["part"]
        done = lambda job=None: dlg.mark_fixed(cid, part["id"])
        if item["status"] in (_cg.NO_TAG, _cg.OTHER):
            if item["status"] == _cg.OTHER and not messagebox.askyesno(
                    title, T("cg.move_ask", m=row.get("movie_name") or "?", a=item.get("other") or "?", b=name),
                    icon="question", parent=dlg):
                return None
            return self._write_collections([(row, (name, cid, None))], title, then=done, label=CG_ACTION, migrate=False)
        if item["status"] != _cg.TITLE:
            return None
        key = SETTINGS.get("tmdb_api_key", "").strip()
        if not key:
            messagebox.showwarning(title, T("mc.no_tmdb_api_key_6e12"), parent=dlg)
            return None
        if not self._confirm_services(("tmdb",)):
            return None

        def work(fetch=None):                                      # the IMDb ID first, so the question shows it
            imdb, err = None, None
            try:
                data = _tmdb_movie_full(str(part["id"]), key, self._lib_lang(), fetch or _tmdb_rate_limited_fetch) or {}
                imdb = ((data.get("external_ids") or {}).get("imdb_id") or data.get("imdb_id") or "").strip() or None
            except Exception as ex:
                err = _tmdb_error_message(ex)
            ui_post(lambda: self._cg_title_confirm(dlg, res, item, row, imdb, err))
        threading.Thread(target=lambda: work(getattr(self, "_cg_fetch", None)), name="collection-gaps-ids",
                         daemon=True).start()
        return None

    def _cg_title_confirm(self, dlg, res, item, row, imdb, err):   ### NEW v0.20.2 CG — fix (b), after the user's OK ###
        T = _i18n.t
        title = T("cg.title")
        if err:
            messagebox.showwarning(title, T("cg.fetch_failed", e=err), parent=dlg)
            return None
        cid, name, part = res["cid"], res["name"], item["part"]
        yr = row.get("movie_year")
        mine = (row.get("movie_name") or "?") + (f" ({yr})" if yr and yr != "-" else "")
        text = T("cg.title_ask", m=mine, rid=(row.get("source_tmdb_val") or "").strip() or "—",
                 rimdb=(row.get("source_imdb_val") or "").strip() or "—",
                 p=f"{_cg.shown_title(part)} ({part.get('date') or T('cg.no_date')})", pid=part["id"],
                 pimdb=imdb or "—", c=name)
        if not imdb:
            text += "\n\n" + T("cg.title_no_imdb")
        self._cg_last_question = text                              # read by the self-test
        if _ChoiceDialog.ask(dlg, title, text, [("ok", T("cg.write"), "ok"), (None, T("mc.cancel_2fee"), "")]) != "ok":
            return None
        if self._busy(title):
            return None

        def _step(job, r):
            nfo, xml = _metadata_targets(r)[:2]
            if not nfo:
                raise RuntimeError("no NFO in use")
            if not job.backup(r.get("movie_name") or r.get("subfolder", ""), nfo, xml):
                raise BackupFailed()
            ok, e = _write_both_source_ids(nfo, xml, imdb, str(part["id"]))
            if not ok:
                raise RuntimeError(e)
            ok, e = write_collection_to_nfo(nfo, name, cid)
            if not ok:
                raise RuntimeError(e)
            if xml:
                ok, e = write_collection_to_xml(xml, name, cid)
                if not ok:
                    raise RuntimeError(e)
            job.changed.append(r["subfolder_path"])
            return True

        def _finish(job):
            if job.done:
                no_collection_set([row], False)
                dlg.mark_fixed(cid, part["id"])
            msg = T("cg.done_one", m=mine) + ("\n\n" + UNDO_HINT if job.done else "")
            if job.errors:
                msg = T("cg.failed", e="\n".join(job.errors[:4]))
            self._cg_fix_done = (job.done, list(job.errors), job.ref[0])   # read by the self-test
            (messagebox.showwarning if job.errors else messagebox.showinfo)(title, msg, parent=dlg)
        job = _BatchJob(self, [row], CG_ACTION, name_of=lambda r: r.get("movie_name") or r.get("subfolder", ""))
        return job.run(_step, _finish)

    def _cg_ignore(self, dlg, cid, pid, on):                       ### NEW v0.20.2 CG — "I don't want this one" / undo ###
        data = _sc.load_gaps_ignored(logger)
        data = _cg.ignore(data, cid, pid) if on else _cg.unignore(data, cid, pid)
        if not _sc.save_gaps_ignored(data):
            messagebox.showerror(_i18n.t("cg.title"), _i18n.t("cg.ignore_not_saved"), parent=dlg)
            return False
        dlg.refresh()
        return True

    def _create_collection_folders_all(self):                      ### NEW v0.19.4 B110g ###
        if self._busy():
            return None
        if self._no_scan("No data"):
            return None
        return self._create_collection_folders_for(list(self._results))

    def _create_collection_folders_for(self, rows, preview=True, root=None, replace=False):   ### NEW v0.19.4 B110g; replace: B117 ###
        title = CREATE_COLL_LABEL.split("  ", 1)[-1].rstrip("…")
        if self._busy():
            return None
        root = os.path.normpath(root) if root else self._ask_coll_root(title)   ### v0.19.4 fix 2e ###
        if not root:
            return None
        if not os.path.isdir(root):
            messagebox.showwarning(title, _i18n.t("mc.the_collection_folder_is_aba1", root=root), parent=self)
            return None
        if not COLL_FOLDERS and not getattr(self, "_cf_tried", False):   ### NEW v0.19.4 P3 (B3) — read them first ###
            self._cf_tried = True
            self._read_collection_folders(then=lambda: self._create_collection_folders_for(rows, preview, root, replace))
            return None
        items = collection_folder_items(rows, root, complete=preview or replace)   # B117: the preview can offer Replace
        if not items:
            messagebox.showinfo(title, _i18n.t("mc.every_collection_of_the_d660"), parent=self)
            return None
        if preview:
            pv = _PreviewRunDialog(self, CREATE_COLL_LABEL.rstrip("…") + " — " + _i18n.t("f3r.preview"), collection_folder_text(items),
                                   file_stem="collection_folder_preview", run_label=_i18n.t("mc.create_82da"))
            self._coll_folder_preview = pv
            _rv = tk.BooleanVar(value=False)                     ### NEW v0.19.5 B117 — default off ###
            pv._replace_var = _rv
            pv.bind("<Destroy>", lambda e, p=pv: setattr(p, "replace_chosen", bool(_rv.get())) if e.widget is p else None, add="+")
            _rcb = tk.Checkbutton(pv._btn_row, text=_i18n.t("mc.replace_the_existing_poster_3968"), variable=_rv, bg=C_BG, fg=C_TEXT,
                                  selectcolor=C_SURFACE, activebackground=C_BG, activeforeground=C_TEXT)
            _rcb.pack(side="left", padx=(12, 0))
            self.wait_window(pv)
            if not pv.run:
                return None
            replace = bool(pv.replace_chosen) if hasattr(pv, "replace_chosen") else bool(_rv.get())
            if not replace:
                items = [it for it in items if it["make"] or it["need"]]
                if not items:
                    messagebox.showinfo(title, _i18n.t("mc.nothing_was_changed_every_54ad"), parent=self)
                    return None
        key = SETTINGS.get("tmdb_api_key", "").strip()
        lang = self._lib_lang()

        def _step(job, it):
            made = None
            if not os.path.isdir(it["dir"]):
                os.makedirs(it["dir"])
                _sc.note_created(_BACKUP_ROOT, it["name"], job.ref, it["dir"], it["dir"], logger=logger)   # P3 (B17): Undo removes it
                ### NEW v0.20.1 CF2 — a new collection folder gets its set.nfo (title + overview in the app's TMDB language) ###
                _sp = os.path.join(it["dir"], _sn.FILE_NAME)
                if not os.path.exists(_sp):
                    write_set_nfo(_sp, _sn.build(it["name"], set_nfo_overview(it.get("tmdb"))))
                    _sc.note_created(_BACKUP_ROOT, it["name"], job.ref, _sp, None, logger=logger)
            try:                                                   ### NEW v0.19.4 P3 (B3) — what the folder has now ###
                _have = _cr.art_types(os.listdir(it["dir"]))
            except OSError:
                _have = {}
            old_art = dict(_have) if replace and it["tmdb"] else {}    ### NEW v0.19.5 B117 ###
            it = dict(it, need=[t for t in ("poster", "fanart") if t in old_art or t in it["need"] and t not in _have])
            if it["need"] and not key:                             ### v0.19.4 fix 2f — never a silent "folder only" ###
                raise RuntimeError("no TMDB API key (Settings) — the folder is there, the images were not downloaded")
            missing = []
            if it["need"]:
                imgs = _tmdb_rate_limited_fetch(f"https://api.themoviedb.org/3/collection/{it['tmdb']}/images?api_key={key}"
                                                f"&include_image_language={lang.split('-')[0]},null,en")
                for t in it["need"]:
                    pick = _cr.pick_image((imgs or {}).get("posters" if t == "poster" else "backdrops"), t, lang)
                    if not pick:
                        missing.append(t)
                        continue
                    dest = os.path.join(it["dir"], t + (".png" if pick["file_path"].lower().endswith(".png") else ".jpg"))
                    if t in old_art:                             ### NEW v0.19.5 B117 — the new image first, then the old one aside ###
                        old = os.path.join(it["dir"], old_art[t])
                        tmp = dest + ".mcnew"
                        ok, err = _save_image_from("https://image.tmdb.org/t/p/original" + pick["file_path"], tmp)
                        if not ok:
                            raise RuntimeError(f"{t}: {err}")
                        try:
                            if not job.backup(it["name"], old):
                                raise RuntimeError(f"{t}: {BACKUP_FAILED_TEXT}")
                            rep_dir = os.path.join(it["dir"], "replaced")
                            rep_made = rep_dir if not os.path.isdir(rep_dir) else None
                            os.makedirs(rep_dir, exist_ok=True)
                            aside = os.path.join(rep_dir, os.path.basename(old))
                            shutil.copy2(old, aside)
                            _sc.note_created(_BACKUP_ROOT, it["name"], job.ref, aside, rep_made, logger=logger)
                            if os.path.normcase(old) != os.path.normcase(dest):
                                os.remove(old)
                            _sc._replace_retry(tmp, dest)                            # v0.19.5 WR-B1
                        finally:
                            if os.path.exists(tmp):
                                os.remove(tmp)
                        _sc.note_created(_BACKUP_ROOT, it["name"], job.ref, dest, None, logger=logger)   # no-op when the name is the old one
                        continue
                    if os.path.exists(dest):                     # never replaced
                        continue
                    ok, err = _save_image_from("https://image.tmdb.org/t/p/original" + pick["file_path"], dest)
                    if not ok:
                        raise RuntimeError(f"{t}: {err}")
                    _sc.note_created(_BACKUP_ROOT, it["name"], job.ref, dest, made, logger=logger)
            # P3 (B17): the movie folders did not change — the folder list is read again in _finish
            if missing:                                          ### v0.19.4 fix 2f ###
                raise RuntimeError(f"TMDB has no {' / '.join(missing)} for this collection — choose one with Collection Artwork…")
            return True

        def _finish(job):
            msg = _i18n.t("mc.done_b4a9", n=_n(job.done, 'collection folder'))
            if job.errors:
                msg += _i18n.t("mc.not_done_8624", join="\n".join(job.errors[:8]))
            msg += job.cancel_note()
            msg += ("\n\n" + UNDO_HINT) if job.done else ""
            self._coll_create_done = (job.done, list(job.errors))   # read by the self-test
            self._read_collection_folders()
            messagebox.showinfo(title, msg, parent=self)

        return _BatchJob(self, items, title, progress_title=_i18n.t("uf.creating_collection_folders_b2ef"),
                         name_of=lambda it: it["name"]).run(_step, _finish)

    def _ask_coll_root(self, title):                               ### NEW v0.19.4 fix 2e / g — one place ###
        """The collection folder; asked once (and saved, normalised) when it is not set.  None = cancelled."""
        root = _coll_root()
        if root:
            return root
        if not messagebox.askyesno(title, _i18n.t("mc.kodi_reads_collection_artwork_1ce8"),
                                   parent=self):
            return None
        root = filedialog.askdirectory(parent=self, title=_i18n.t("mc.collection_folder_kodi_s_3636"))
        if not root:
            return None
        root = os.path.normpath(root)
        SETTINGS["collection_folder"] = root
        _save_settings(SETTINGS)
        return root

    def _collection_art_for(self, key, name, rows=None, tmdb_id=None):   ### NEW v0.19.4 fix 2g; tmdb_id fix 3d ###
        """Collection Artwork…: choose the poster and the fanart of one collection (the window is modal)."""
        title = COLL_ART_LABEL.split("  ", 1)[-1].rstrip("…")
        if self._busy():
            return None
        root = self._ask_coll_root(title)
        if not root:
            return None
        if not os.path.isdir(root):
            messagebox.showwarning(title, _i18n.t("mc.the_collection_folder_is_aba1", root=root), parent=self)
            return None
        rows = [r for r in self._results if _cr.group_key(r) == key] or list(rows or [])
        st = COLL_FOLDERS.get(key) or {}
        cdir = st.get("dir") or os.path.join(root, _cr.kodi_legal_name(name))
        dlg = _CollectionArtDialog(self, key, name, cdir, rows, tmdb_id or collection_tmdb_id(rows),
                                   SETTINGS.get("tmdb_api_key", "").strip(), self._lib_lang())
        self._coll_art_dialog = dlg                                # read by the self-test
        return dlg

    def _write_collections(self, items, title, remove=False, then=None, label=None, migrate=True):   ### NEW v0.19.4 B110e; then fix 3d ###
        # v0.20.2 CG: *label* = the backup label when *title* is a shown (translated) text; migrate=False = one movie
        # joins another collection: its old collection's folder is never moved (fix 15 is for renames)
        def _step(job, item):
            r, target = item
            rm = remove or target is None                               # P7 (E19): a None target = clean
            nfo = _metadata_targets(r)[0]    # v0.19.6 TR1b: only an NFO in use
            if not nfo:
                raise RuntimeError("no NFO in use — the collection is kept in the NFO")
            if target and target[0] == "title":                      ### NEW v0.19.4 B110f — the local titles ###
                xml = _metadata_targets(r)[1]   # v0.20.0 F3b
                if not job.backup(r.get("movie_name") or r.get("subfolder", ""), nfo, xml):
                    raise BackupFailed("backup failed — not changed")
                ok, err = _write_local_title(r, target[1], ("nfo", "xml"))
                if not ok:
                    raise RuntimeError(err)
                job.changed.append(r["subfolder_path"])
                return True
            xml = _metadata_targets(r)[1]   ### v0.19.4 fix 6 — movie.xml too ###
            if not job.backup(r.get("movie_name") or r.get("subfolder", ""), nfo, xml):
                raise BackupFailed("backup failed — not changed")
            ok, err = remove_collection_from_nfo(nfo) if rm else write_collection_to_nfo(nfo, *target)
            if not ok:
                raise RuntimeError(err)
            job.changed.append(r["subfolder_path"])                      ### MODIFIED v0.19.4 P3 (B1) — the NFO changed ###
            if remove:                                                  # v0.20.0 AU22: marked in _finish
                job.__dict__.setdefault("rm_ok", []).append(r)
            if not rm and target:                                       ### NEW v0.19.4 fix 15 ###
                job.renames.append((r, collection_name(r), target[0]))
            if xml:
                ok, err = write_collection_to_xml(xml, None, None) if rm else write_collection_to_xml(xml, target[0], target[1])
                if not ok:
                    raise RuntimeError(f"the NFO was changed, movie.xml not: {err} (Sync Collection can copy it later)")
            return True

        def _finish(job):
            if not remove and job.renames:                              ### NEW v0.19.4 P3 (E23) — only the written ones ###
                no_collection_set([x[0] for x in job.renames], False)
            if remove and getattr(job, "rm_ok", None):                  # v0.20.0 AU22: only the NFOs that lost the <set>
                if not no_collection_set(job.rm_ok, True):
                    logger.warning("no_collection.json could not be written")
            what = _i18n.t("uf.removed_from_their_collection_5353") if remove else _i18n.t("uf.got_their_collection_1059")
            msg = f"{_n(job.done, 'movie')} {what}."
            if job.errors:
                msg += _i18n.t("mc.not_changed_2fc6", join="\n".join(job.errors[:8]))
            msg += job.cancel_note()
            if job.notes:                                               ### NEW v0.19.4 fix 15 ###
                msg += _i18n.t("mc.collection_folders_0de9", join="\n".join("  " + x for x in job.notes))
            msg += ("\n\n" + UNDO_HINT) if job.done else ""
            self._coll_write_done = (job.done, list(job.errors))       # read by the self-test
            self._coll_write_ref = job.ref[0]                           # v0.20.2 CG (read by the self-test)
            messagebox.showinfo(title, msg, parent=self)
            if job.notes:
                self._read_collection_folders()

        if then is not None:                                     ### NEW v0.19.4 fix 3d — after the result message ###
            _fin0 = _finish

            def _finish(job):
                _fin0(job)
                if job.done:
                    then(job)
        job = _BatchJob(self, items, label or title, progress_title=_i18n.t("au.prog.write_coll"),
                        name_of=lambda it: it[0].get("movie_name") or it[0].get("subfolder", ""))
        job.renames, job.notes = [], []                                  ### NEW v0.19.4 fix 15 ###
        if migrate:
            job.after_steps = lambda j: j.notes.extend(self._migrate_coll_folders(j.renames, j.ref))
        return job.run(_step, _finish)

    def _migrate_coll_folders(self, renames, ref):                   ### NEW v0.19.4 fix 15 ###
        """Worker: after collection renames [(row, old name, new name)], move each old collection folder into the
        new one — only when no other movie still uses the old name (user decision 2).  Returns notes."""
        root = _coll_root()
        if not renames or not root or not os.path.isdir(root):
            return []
        written = {id(r) for r, _o, _n2 in renames}
        results = list(self._results)
        missing = self._libs_not_loaded(results)                   ### NEW v0.19.4 P3 (B7, user decision 5) ###
        if missing:
            olds = sorted({_cr.kodi_legal_name(o) for _r, o, n2 in renames
                           if o and n2 and _cr.kodi_legal_name(o).casefold() != _cr.kodi_legal_name(n2).casefold()
                           and os.path.isdir(os.path.join(root, _cr.kodi_legal_name(o)))})
            return [_i18n.t("uf.not_moved_the_library_8ded", o=o, v=missing[0]) for o in olds]
        pairs = []
        for _r, old, new in renames:
            if (old and new and _cr.kodi_legal_name(old).casefold() != _cr.kodi_legal_name(new).casefold()
                    and (old, new) not in pairs):
                pairs.append((old, new))
        notes = []
        for old, new in pairs:
            if not os.path.isdir(os.path.join(root, _cr.kodi_legal_name(old))):
                continue
            still = [x for x in results if id(x) not in written and _cr.group_key(x) == _cr.norm_name(old)]
            if still:
                notes.append(_i18n.tn("uf.m.kept_still_uses", len(still), folder=_cr.kodi_legal_name(old),   # v0.20.0 UI1f
                                      others=_n(len(still), 'other movie'), old=old))
                continue
            try:
                note = migrate_collection_folder(root, old, new, ref)
            except Exception as ex:
                note = _i18n.t("mc.not_moved_c673", kodi_legal_name=_cr.kodi_legal_name(old), ex=ex)
            if note:
                notes.append(note)
        return notes

    def _libs_not_loaded(self, results=None):                     ### NEW v0.19.4 P3 (B7) ###
        """The configured libraries with no movie in the table (never scanned, or empty).  A collection folder is
        shared by every library, so it is not moved while one of them is unknown (user decision 5)."""
        have = {_pkey(r.get("library_root") or os.path.dirname(r.get("subfolder_path") or ""))
                for r in (results if results is not None else list(self._results)) + list(self._inactive_rows)}   # 5j
        return [l for l in self._all_libraries() if _pkey(l) not in have]

    def _import_old_coll_folder_for(self, rows, ask=True):          ### NEW v0.19.4 fix 15 ###
        """Fix "Collection folder: images left in …": move the old folder's files into the collection's folder."""
        title = _i18n.t("au.move_coll")
        _miss = self._libs_not_loaded()                               ### NEW v0.19.4 P3 (B7) ###
        if _miss:
            messagebox.showinfo(title, _i18n.t("mc.not_moved_the_library_80da", join="\n".join(_miss[:5])), parent=self)
            return None
        root = _coll_root()
        items, seen = [], set()
        for r in rows:
            k = _cr.group_key(r)
            st = COLL_FOLDERS.get(k) if k else None
            if k and k not in seen and st and st.get("old_dir"):
                seen.add(k)
                items.append((st["old_name"], collection_name(r)))
        if not items or not root:
            messagebox.showinfo(title, _i18n.t("mc.no_images_are_left_b83c"), parent=self)
            return None
        lines = "\n".join(f"  {o}  →  {_cr.kodi_legal_name(n)}" for o, n in items)
        if ask and not messagebox.askyesno(
                title, _i18n.t("mc.move_the_files_of_4bd1", n=_n(len(items), 'old collection folder'), lines=lines, undo_hint=UNDO_HINT), icon="question", parent=self):
            return None

        def _step(job, it):
            note = migrate_collection_folder(root, it[0], it[1], job.ref)
            if note:
                job.notes.append(note)
            return bool(note)

        def _finish(job):
            msg = "\n".join(job.notes) or _i18n.t("uf.nothing_was_moved_c6c6")
            if job.errors:
                msg += _i18n.t("mc.not_moved_65bc", join="\n".join(job.errors[:8]))
            self._coll_move_done = (job.done, list(job.errors))         # read by the self-test
            messagebox.showinfo(title, msg + ("\n\n" + UNDO_HINT if job.done else ""), parent=self)
            self._read_collection_folders()
        job = _BatchJob(self, items, title, progress_title=_i18n.t("uf.moving_collection_folders_ce83"), name_of=lambda it: it[0])
        job.notes = []
        return job.run(_step, _finish)

    def _set_collection_for(self, rows, name=None, tmdb_id=None, folder=False):   ### NEW v0.19.4 B110e; TMDB + folder fix 3d ###
        """Put the movies in a collection: one in use, your own name, or a TMDB collection found by name (its id
        and name).  Clears their "not in a collection" mark.  With *folder*: then the collection folder is made
        and Collection Artwork… opens."""
        title = SET_COLL_LABEL.split("  ", 1)[-1].rstrip("…")
        rows = [r for r in rows if r.get("nfo_exists")]
        if not rows:
            messagebox.showinfo(title, _i18n.t("mc.the_selected_movie_s_9506"), parent=self)
            return None
        tname = None
        if name is None:
            used = sorted({collection_name(r) for r in self._results if collection_name(r)}, key=str.casefold)
            dlg = _SetCollectionDialog(self, used, collection_name(rows[0]) or "",
                                       api_key=SETTINGS.get("tmdb_api_key", "").strip(), lang=self._lib_lang(),
                                       n_movies=len(rows))
            self._set_coll_dlg = dlg
            self.wait_window(dlg)
            if not dlg.result:
                return None
            name, tmdb_id, tname, folder = dlg.result
        name = (name or "").strip()
        if not name:
            return None
        if tmdb_id:                                              ### fix 3d — the TMDB collection the user chose ###
            cid = int(tmdb_id)
            ent = COLL_CACHE.setdefault(str(cid), {"names": {}, "overviews": {}})
            nms = ent.setdefault("names", {})
            if tname and not any(_cr.norm_name(v) == _cr.norm_name(tname) for v in nms.values()):
                nms.setdefault("en", tname)                      # fix 13: the search is in English
            _sc.save_collections_cache(dict(COLL_CACHE))
            name = set_collection_name(name, tname, cid, rows, self._results, self._lib_lang())   ### fix 13 ###
        else:
            ids = {(r.get("coll_tmdb") or {}).get("id") for r in rows}
            cid = next(iter(ids)) if len(ids) == 1 and None not in ids else None
            if cid:
                names = (COLL_CACHE.get(str(cid)) or {}).get("names") or {}
                if not any(_cr.norm_name(v) == _cr.norm_name(name) for v in names.values()):
                    cid = None
            ### NEW v0.19.4 fix 5 — Join: a collection in use gives its TMDB id (the one most of its movies carry) ###
            mine = {id(r) for r in rows}
            others = [r for r in self._results if id(r) not in mine and _cr.group_key(r) == _cr.norm_name(name)]
            oids = [str((r.get("coll_nfo") or {}).get("tmdbcolid") or (r.get("coll_tmdb") or {}).get("id") or "") for r in others]
            oids = [x for x in oids if x]
            if oids:
                cid = int(max(sorted(set(oids)), key=oids.count))
        # P3 (E23): the "not in a collection" mark is cleared by _write_collections, for the movies it wrote
        then = (lambda job, n=name, c=cid, rr=list(rows): self._after_set_collection(n, c, rr)) if folder else None
        return self._write_collections([(r, (name, cid, None)) for r in rows], title, then=then)

    def _sync_collection_xml_for(self, rows, preview=True):       ### NEW v0.19.4 fix 6 ###
        """movie.xml and the NFO say the same collection: the NFO's goes to movie.xml; an NFO without one takes
        movie.xml's; a movie marked "not in a collection" gets movie.xml cleaned."""
        title = SYNC_COLL_XML_LABEL.split("  ", 1)[-1].rstrip("…")
        writes, removes, lines = [], [], []
        for r in rows:
            if not (r.get("nfo_exists") and r.get("xml_exists") and _cr.xml_reasons(r)):
                continue
            nfo, x = r.get("coll_nfo") or {}, r.get("coll_xml") or {}
            who = r.get("movie_name") or r.get("subfolder", "")
            if nfo.get("name"):
                writes.append((r, (nfo["name"], nfo.get("tmdbcolid"), None)))
                lines.append(f"  {who}:  movie.xml ← NFO  '{nfo['name']}'")
            elif r.get("coll_none") or not x.get("name"):
                removes.append(r)
                lines.append(_i18n.t("uf.movie_xml_cleaned_not_1b17", who=who))
            else:
                writes.append((r, (x["name"], x.get("tmdbcolid"), None)))
                lines.append(f"  {who}:  NFO ← movie.xml  '{x['name']}'")
        if not writes and not removes:
            messagebox.showinfo(title, _i18n.t("mc.movie_xml_and_the_727e"), parent=self)
            return None
        if preview and len(lines) > 1:
            pv = _PreviewRunDialog(self, title + " — " + _i18n.t("f3r.preview"), f"{_n(len(lines), 'movie')}:\n\n" + "\n".join(lines)
                                   + _i18n.t("uf.each_nfo_and_movie_aebd"),
                                   file_stem="collection_xml_preview", run_label=_i18n.t("mc.sync_698b"))
            self._coll_sync_preview = pv
            self.wait_window(pv)
            if not pv.run:
                return None
        return self._write_collections([(r, None) for r in removes] + writes, title)   ### MODIFIED v0.19.4 P7 (E19) — one run ###

    def _after_set_collection(self, name, cid, rows):             ### NEW v0.19.4 fix 3d ###
        """Set Collection… with the tick: the collection folder (made now), then Collection Artwork…."""
        title = SET_COLL_LABEL.split("  ", 1)[-1].rstrip("…")
        root = self._ask_coll_root(title)
        if not root:
            return None
        if not os.path.isdir(root):
            messagebox.showwarning(title, _i18n.t("mc.the_collection_folder_is_aba1", root=root), parent=self)
            return None
        d = os.path.join(root, _cr.kodi_legal_name(name))
        try:
            os.makedirs(d, exist_ok=True)
        except OSError as ex:
            messagebox.showwarning(title, _i18n.t("mc.the_folder_could_not_60e4", d=d, ex=ex), parent=self)
            return None
        logger.info(f"Set Collection: folder {d}")
        key = _cr.norm_name(name)
        rows2 = [dict(r, coll_nfo={"name": name, "tmdbcolid": cid}) for r in rows]
        self._read_collection_folders(then=lambda: self._collection_art_for(key, name, rows2, tmdb_id=cid))
        return d

    def _remove_collection_for(self, rows, ask=True):             ### NEW v0.19.4 B110e; fix 3b — "not in a collection" ###
        """The movies are not in a collection: the <set> leaves their NFO (where there is one, after a backup) and
        MediaClinic remembers them (no_collection.json), so TMDB's collection is no longer suggested."""
        title = REMOVE_COLL_LABEL.split("  ", 1)[-1].rstrip("…")
        rows = [r for r in rows if r.get("nfo_exists") and (r.get("coll_nfo") or (r.get("coll_tmdb") or {}).get("id"))]
        if not rows:
            messagebox.showinfo(title, _i18n.t("mc.the_selected_movie_s_6426"),
                                parent=self)                       # P7 (E20)
            return None
        writes = [r for r in rows if r.get("coll_nfo")]
        if ask and not messagebox.askyesno(
                title, _i18n.t("m3.coll_none", movies=_n(len(rows), "movie"))
                + (_i18n.t("m3.coll_removed", movies=_n(len(writes), "movie")) if writes else "")
                + _i18n.t("m3.coll_remember"), parent=self):
            return None
        ### MODIFIED v0.20.0 AU22 (audit point 4) ### only the movies without a <set> to remove are marked now; the
        # others when their NFO really lost it (_write_collections → job.rm_ok): a failed backup / locked NFO used to
        # leave the <set> while the movie was already marked "not in a collection"
        _now = [r for r in rows if not r.get("coll_nfo")]
        if _now and not no_collection_set(_now, True):
            logger.warning("no_collection.json could not be written")
        if not writes:
            finalize_results(self._results)
            self._refresh_table(); self._update_stats()
            self._incremental_save(self._results)
            self._coll_write_done = (0, [])                       # read by the self-test
            messagebox.showinfo(title, _i18n.t("mc.marked_as_not_in_fc68", n=_n(len(rows), 'movie')), parent=self)
            return None
        return self._write_collections([(r, None) for r in writes], title, remove=True)

    def _check_collections_worker(self, todo, key, lang, prog, skipped, fresh, fetch=None):   ### NEW v0.19.4 B110b ###
        """Background: TMDB requests only; the rows are changed on the Tk thread (_finish)."""
        fetch = fetch or _tmdb_rate_limited_fetch
        cache = dict(COLL_CACHE) or _sc.load_collections_cache()
        got, asked, error, gone = [], set(), None, set()        # gone: v0.19.4 fix 3c
        for i, r in enumerate(todo):
            if prog and prog.cancelled:
                break
            try:
                data = _tmdb_movie_full(r["source_tmdb_val"].strip(), key, lang, fetch)
                ct = _cr.coll_from_movie(data, lang, time.time())
                tl = _cr.title_langs_from(data, [_cr.local_title(r)])     ### MODIFIED v0.19.4 fix 9 — the local title only ###
                if isinstance(ct, dict):
                    ct["tl"] = _cr.loose_title(_cr.local_title(r))
                tt = _cr.titles_by_lang(data)                         ### NEW v0.19.4 B110f ###
                cid = str((ct or {}).get("id") or "")
                if cid and cid not in asked:
                    asked.add(cid)
                    base = f"https://api.themoviedb.org/3/collection/{cid}"
                    try:
                        main = fetch(f"{base}?api_key={key}&language={lang}")
                        trs = fetch(f"{base}/translations?api_key={key}")
                        cache[cid] = _cr.coll_cache_entry(main, trs, lang, time.time())
                        if not cache[cid]["names"].get("en"):        ### NEW v0.19.4 fix 10 — the English name ###
                            en = fetch(f"{base}?api_key={key}&language=en-US") or {}
                            if (en.get("name") or "").strip():
                                cache[cid]["names"]["en"] = en["name"].strip()
                            if (en.get("overview") or "").strip():
                                cache[cid]["overviews"].setdefault("en", en["overview"].strip())
                    except Exception as cex:                         ### v0.19.4 fix 3c — the COLLECTION is gone, not the movie ###
                        if not _is_http_404(cex):
                            raise
                        gone.add(cid)
                        cache.pop(cid, None)
                if cid and cid in gone:
                    ct = {"id": None, "when": ct.get("when") or time.time(), "gone": int(cid), "gone_name": ct.get("name")}
                    skipped["collection no longer on TMDB"] = skipped.get("collection no longer on TMDB", 0) + 1
                if ct is not None:
                    got.append((r, ct, tl, tt))
            except Exception as ex:
                if _is_http_404(ex):
                    skipped["not on TMDB"] = skipped.get("not on TMDB", 0) + 1
                    continue
                error = _tmdb_error_message(ex)
                logger.error(f"Check collections stopped at '{r.get('movie_name')}': {error}")
                break
            if prog:
                prog.advance(i + 1)
        if prog:
            prog.close()
        def _finish():
            ### MODIFIED v0.19.4 P2 (E7) — only the collections this run fetched (or found gone) change the cache;
            ### a Set Collection done meanwhile stays; saved here, on the Tk thread ###
            for cid in asked:
                if cid in cache:
                    COLL_CACHE[cid] = cache[cid]
            for cid in gone:
                COLL_CACHE.pop(cid, None)
            if asked:
                _sc.save_collections_cache(dict(COLL_CACHE))
            by_path = {r.get("subfolder_path"): r for r in self._results}     # P2 (E1): the row now, not an old copy
            for r, ct, tl, tt in got:
                r = by_path.get(r.get("subfolder_path"), r)
                r["coll_tmdb"], r["title_langs"], r["tmdb_titles"] = ct, tl, tt
            if got:
                finalize_results(self._results)
                self._refresh_table(); self._update_stats()
                self._incremental_save(self._results)
            self._coll_check_done = (len(got), len(asked), dict(skipped), error)   # read by the self-test
            title = CHECK_COLL_LABEL.split("  ", 1)[-1].rstrip("…")
            text = collection_check_summary(len(got), len(asked), skipped, fresh)
            if error:
                messagebox.showerror(_i18n.t("mc.stopped_5432", title=title), _i18n.t("mc.what_was_fetched_is_6b1d", error=error, text=text), parent=self)
            else:
                messagebox.showinfo(title, text, parent=self)
        try:
            ui_post(_finish)
        except (RuntimeError, tk.TclError):
            pass

    def _verify_ids_all(self):                                     ### NEW v0.19.0 ###
        if self._busy():                                       ### NEW v0.19.4 B91 ###
            return
        if self._no_scan("No data"):                ### MODIFIED v0.19.4 I17 ###
            return
        tmdb_key = SETTINGS.get("tmdb_api_key", "").strip()
