    def _rescan_row_no_probe(self, d):                             ### NEW v0.19.0 ###
        """Thread-safe: rescan one movie without FFprobe and merge the FFprobe
        data of the previous row (same rules as Update (no FFprobe))."""
        r, _kept = rescan_or_keep(d, use_ffprobe=False)            ### MODIFIED v0.19.5 AS-A8 ###
        if _kept:
            return r
        carry_after_rescan(r, d)                                   ### MODIFIED v0.19.4 P4 — one rule (same video, same IDs) ###
        _apply_health(r)
        return r

    def _apply_rescanned_rows(self, rows):                         ### NEW v0.19.4 P6 (E11) — one map, not one search per row ###
        idx = {o.get("subfolder_path"): i for i, o in enumerate(self._results)}
        iids = {rd.get("subfolder_path"): i for i, rd in self._item_map.items()}
        for r in rows:
            sp = r.get("subfolder_path")
            i = idx.get(sp)
            old = self._results[i] if i is not None else None
            if i is not None:
                self._results[i] = r
            self._regroup_if_moved(old, r)
            if not self._row_replaced(iids.get(sp), r) and getattr(self, "_tbl_filling", False):
                self._fill_swaps[sp] = r

    def _apply_rescanned_row(self, r):                             ### NEW v0.19.0 ###
        """UI thread: replace the row with the same folder in the results, the
        item map and the table."""
        sp = r.get("subfolder_path")
        old = None
        for i, o in enumerate(self._results):
            if o.get("subfolder_path") == sp:
                old = o
                self._results[i] = r
                break
        self._regroup_if_moved(old, r)                             ### NEW v0.19.4 fix 3a ###
        if not self._row_replaced(self._iid_for_path(sp), r) and getattr(self, "_tbl_filling", False):   ### MODIFIED v0.19.4 P1 ###
            self._fill_swaps[sp] = r                                # not inserted yet: the fill uses the new row

    def _regroup_if_moved(self, old, new):                         ### NEW v0.19.4 fix 3a ###
        """A row whose collection changed: the grouped table is rebuilt (one debounced refresh for a batch);
        the collection rules (spellings, artwork) follow through finalize_results."""
        o, n = old or {}, new or {}
        _dk = lambda r: (r.get("source_imdb_val"), r.get("source_tmdb_val"), r.get("movie_name"), r.get("movie_year"))
        if old and new and _dk(o) != _dk(n):                       ### NEW v0.19.5 AS-A9 — the duplicate warning follows a changed ID ###
            if getattr(self, "_dup_after", None) is not None:
                try:
                    self.tk.call("after", "cancel", self._dup_after)
                except tk.TclError:
                    pass
            self._dup_after = self.after(150, self._recheck_duplicates)
        if (o.get("coll_nfo") == n.get("coll_nfo") and o.get("coll_none") == n.get("coll_none")   # fix 5: any change
                and o.get("coll_tmdb") == n.get("coll_tmdb") and o.get("coll_xml") == n.get("coll_xml")):   # fix 6
            return
        if getattr(self, "_regroup_after", None) is not None:
            try:
                self.tk.call("after", "cancel", self._regroup_after)
            except tk.TclError:
                pass
        self._regroup_after = self.after(150, self._regroup_now)

    def _regroup_now(self):
        self._regroup_after = None
        finalize_results(self._results)
        self._refresh_table(); self._update_stats()
        self._regrouped = getattr(self, "_regrouped", 0) + 1      # read by the self-test
        ### NEW v0.19.4 fix 17 — a collection name the folder list does not know yet (a rename, Set, Join, a hand
        ### edit + Update): read the collection folders again, so the panel and the artwork rule see its folder ###
        if _coll_root():
            names = {collection_name(r) for r in self._results if collection_name(r)}
            if any(_cr.norm_name(n) not in COLL_FOLDERS for n in names):
                self._read_collection_folders()

    def _ask_id_chooser(self, movie_name, year, candidates, show_apply_all=False, preselect=None):
        """Worker thread: show _IdChooserDialog and return (candidate|None, skip_all)."""
        res = self._ask_on_ui(
            lambda: _IdChooserDialog(self, movie_name, year, candidates, show_apply_all, preselect),
            lambda dlg: (dlg.result, dlg.skip_all))
        return res if res else (None, False)

    def _auto_repair(self, data_list, all_movies=False):           ### NEW v0.19.0 ###
        if self._busy("Auto Repair"):                            ### NEW v0.19.4 B91 — first ###
            return
        if not self._confirm_services(("tmdb", "omdb")):          ### NEW v0.19.1 B22 — paused service: Try anyway? ###
            return
        if self._busy("Auto Repair"):                ### MODIFIED v0.19.4 B91 — one message ###
            return
        if not data_list:
            messagebox.showinfo(_i18n.t("mc.auto_repair_917e"), _i18n.t("mc.no_movies_selected_3bde"), parent=self); return
        tmdb_key = SETTINGS.get("tmdb_api_key", "").strip()
        omdb_key = SETTINGS.get("omdb_api_key", "").strip()
        if not tmdb_key:
            messagebox.showwarning(_i18n.t("mc.auto_repair_917e"),
                _i18n.t("mc.no_tmdb_api_key_23b4"), parent=self)
        ### MODIFIED v0.20.1 BF4 — the planned steps with counts, each with a tick box; the dry run offered for a
        # selection too (ticked by default for All Movies, as before)
        _steps4 = [(c, _AR_LABELS[c], len(rs)) for c, rs in auto_repair_step_counts(data_list, SETTINGS)]
        dlg = _AutoRepairOptionsDialog(self, len(data_list), offer_dry_run=True, dry_default=all_movies,
                                       has_rating_keys=bool(tmdb_key or omdb_key), steps=_steps4)
        self.wait_window(dlg)
        if not dlg.result:
            return
        opts = {"tmdb_key": tmdb_key, "omdb_key": omdb_key,
                "lang": _tmdb_lang_for(SETTINGS.get("lang_ok_code", "EN")),
                "rating_pref": dlg.result["rating_pref"], "dry_run": False,
                "multi": len(data_list) > 1, "steps": dlg.result.get("steps")}
        if dlg.result.get("dry_run"):
            _ch4 = dlg.result.get("steps")
            entries = [{"name": d.get("movie_name") or d["subfolder"],
                        "planned": [lbl for _c, lbl in _auto_repair_plan(d, SETTINGS) if _ch4 is None or _c in _ch4]}
                       for d in data_list]
            pv = _PreviewRunDialog(self, _i18n.t("uf.auto_repair_preview_dry_5e4b"),
                                   format_auto_repair_summary(entries, dry_run=True))
            self.wait_window(pv)
            if not pv.run:
                return
        prog = _BatchProgressDialog(self, _i18n.t("au.prog.auto_repair"), total=len(data_list)) if len(data_list) >= 3 else None
        _AppJobThread(self, target=self._auto_repair_worker, args=(list(data_list), opts, prog),
                      act_paths=act_targets(data_list)[0]).start()   # v0.20.1 SN3

    def _auto_repair_all(self):                                    ### NEW v0.19.0 ###
        if self._busy("Auto Repair"):                            ### NEW v0.19.4 B91 — first ###
            return
        if self._no_scan("No data"):                ### MODIFIED v0.19.4 I17 ###
            return
        self._auto_repair(list(self._results), all_movies=True)

    # ── v0.20.1 BF2 / BF3: one Auto Repair step on many movies (bulk_engine: one backup run, Pause, Cancel) ──
    _AR_STEP_METHODS = {                                         ### NEW v0.20.1 BF3 — code → step (worker thread) ###
        "ids_wrong":   lambda self, c: self._ar_ids_wrong(c),        # v0.20.1 T2
        "ids_resolve": lambda self, c: self._ar_fix_ids(c, "resolve"),
        "ids_search":  lambda self, c: self._ar_fix_ids(c, "search"),
        "ids_partial": lambda self, c: self._ar_fix_ids(c, "partial"),
        "ids_kodi":    lambda self, c: self._ar_ids_kodi(c),
        "xml_tags":    lambda self, c: self._ar_xml_tags(c),
        "ratings":     lambda self, c: self._ar_ratings(c),
        "genres":      lambda self, c: self._ar_genres(c),
        "genres_tmdb": lambda self, c: self._ar_genres_tmdb(c),
        "year_tmdb":   lambda self, c: self._ar_year_tmdb(c),
        "title_copy":  lambda self, c: self._ar_title_copy(c),
        "title_sync":  lambda self, c: self._ar_title_sync(c),
        "struct_fix":  lambda self, c: self._ar_struct_fix(c),
        "nfo_name":    lambda self, c: self._ar_nfo_name(c),
        "collection":  lambda self, c: self._ar_collection(c),
        "amp_fix":     lambda self, c: self._ar_amp_fix(c),
    }

    def _ar_run_step(self, code, ctx):
        """(status, message) of one Auto Repair step; status is "fixed" / "skipped" / "failed"."""
        fn = self._AR_STEP_METHODS.get(code)
        return fn(self, ctx) if fn else ("skipped", f"unknown action {code}")

