    # ── v0.20.1 T2 / T5: Fix Wrong IDs (a tester) ─────────────────────────────────────────────────────────────
    def _fix_wrong_ids_all(self):
        if self._busy(_i18n.t("idw.title")) or self._no_scan("No data"):
            return None
        return self._fix_wrong_ids_for(list(self._results), all_movies=True)

    def _fix_wrong_ids_for(self, rows, all_movies=False, confirm=True):
        """A wrong value in an IMDb / TMDB tag → the right ID (from the same file, else TMDB), written into the ID tags
        the files already have; no tag added; preview, one backup run (Undo), Pause / Cancel."""
        if self._busy(_i18n.t("idw.title")):
            return None
        todo = [r for r in rows if id_wrong_findings(r)]
        if not todo:
            messagebox.showinfo(_i18n.t("idw.title"), _i18n.t("idw.nothing"), parent=self)
            return None

        def _detail(r):
            return "; ".join(f"{'IMDb' if f['kind'] == 'imdb' else 'TMDB'} {f['values'][0]} → "
                             + (f"{f['suggest']} ({_i18n.t('idw.from_' + f['from'])})" if f["suggest"] else _i18n.t("idw.lookup"))
                             for f in id_wrong_findings(r))
        known = sum(1 for r in todo if all(f["suggest"] for f in id_wrong_findings(r)))
        head = [_i18n.t("idw.head", n=_n(len(todo), "movie")), _i18n.t("idw.head_known", a=known, b=len(todo) - known),
                _i18n.t("idw.keeps")]
        return self._run_single_ar_step("ids_wrong", todo, _i18n.t("idw.title"), IDS_WRONG_ACTION, head=head,
                                        all_movies=all_movies, confirm=confirm, detail=_detail,
                                        net=known < len(todo))          # online only when a movie needs TMDB

    def _ar_ids_wrong(self, ctx):                                 # worker thread
        nfo, xml = ctx["nfo"], ctx["xml"]
        finds = id_wrong_findings_src(extract_source_ids_from_files(nfo, xml))
        if not finds:
            return "skipped", _i18n.t("idw.skip.none")
        n, notes = 0, []
        for f in finds:
            good, why = (f["suggest"], None) if f["suggest"] else self._idw_lookup(f, ctx)
            if not good:
                notes.append(why)                                 # checkup: the other finding may still be fixed
                continue
            _todo = []                                            # v0.20.2 PA14: both files read (and checked)
            for path, is_xml in ((nfo, False), (xml, True)):      # BEFORE the first write — a movie.xml that is not
                if not path:                                      # UTF-8 no longer leaves the NFO changed alone
                    continue
                text, _bom = _read_for_edit(path)
                new, k = _idr.replace_ids(text, f["kind"], f["values"], good, xml=is_xml)
                if k:
                    _todo.append((path, new, k))
            if _todo:
                ctx["backup"]()
            for path, new, k in _todo:
                _atomic_write_text(path, new)
                n += k
        if n:
            ctx["d"].pop("id_check", None)                        # the Verify result was about the old values
            return "fixed", _i18n.t("idw.fixed", n=n) + ("; " + "; ".join(notes) if notes else "")
        return "skipped", ("; ".join(notes) or _i18n.t("idw.skip.none"))

    def _idw_lookup(self, f, ctx):
        """(the right ID, None) from TMDB for a finding whose file has no valid ID of that kind — only when the
        title and year match — or (None, the reason it is skipped)."""
        key = ctx.get("tmdb_key")
        if not key:
            return None, _i18n.t("uf.no_tmdb_api_key_3c89")
        d, fetch = ctx["d"], ctx.get("fetch")
        local = _local_titles_for(d)
        year = d.get("movie_year_raw") or (d.get("movie_year") if str(d.get("movie_year", "-")).isdigit() else None)
        src = extract_source_ids_from_files(ctx["nfo"], ctx["xml"])
        try:
            if f["kind"] == "imdb":
                tids = [v for v in src.get("tmdb_all_vals") or [] if _idr.valid("tmdb", v)]
                if not tids:
                    return None, _i18n.t("idw.skip.no_other", other="TMDB")
                for tid in tids:
                    data = _tmdb_movie_full(tid, key, ctx.get("lang", "en-US"), fetch)
                    ok, _r, _b = _titles_match(_tmdb_candidate_titles(data), local)
                    if ok and _year_close(year, (data.get("release_date") or "")[:4]):
                        iid = ((data.get("external_ids") or {}).get("imdb_id") or "").strip()
                        return (iid, None) if _idr.valid("imdb", iid) else (None, _i18n.t("idw.skip.tmdb_no_imdb"))
                return None, _i18n.t("idw.skip.no_match")
            iids = [v for v in src.get("imdb_all_vals") or [] if _idr.valid("imdb", v)]
            if not iids:
                return None, _i18n.t("idw.skip.no_other", other="IMDb")
            for iid in iids:
                fr = _tmdb_find_imdb(iid, key, fetch)
                if fr:
                    it = fr[0]
                    ok, _r, _b = _titles_match([it.get("title") or "", it.get("original_title") or ""], local)
                    if ok and _year_close(year, (it.get("release_date") or "")[:4]) and _idr.valid("tmdb", str(it.get("id") or "")):
                        return str(it["id"]), None
            return None, _i18n.t("idw.skip.no_match")
        except Exception as ex:
            if _is_http_404(ex):
                return None, _i18n.t("idw.skip.no_match")
            return None, _i18n.t("idw.skip.tmdb_down", err=str(ex)[:160])

    def _fix_one_issue_all(self):                                ### NEW v0.20.1 BF3 ###
        if self._busy(_i18n.t("bf3.title")) or self._no_scan("No data"):
            return None
        steps = [(c, rs) for c, rs in auto_repair_step_counts(self._results, SETTINGS)
                 if c not in AR_ONE_ISSUE_EXCLUDED]
        if not steps:
            messagebox.showinfo(_i18n.t("bf3.title"), _i18n.t("bf3.nothing"), parent=self)
            return None
        dlg = _FixOneIssueDialog(self, [(c, _AR_LABELS[c], len(rs)) for c, rs in steps])
        self.wait_window(dlg)
        if not dlg.result:
            return None
        rows = dict(steps)[dlg.result]
        return self._run_single_ar_step(dlg.result, rows, _i18n.t("bf3.title"), ONE_ISSUE_ACTION,
                                        head=[_i18n.t("bf3.head", label=_AR_LABELS[dlg.result], n=_n(len(rows), "movie"))],
                                        all_movies=True)

    def _run_single_ar_step(self, code, rows, title, label, head=(), skipped=(), all_movies=False, confirm=True, detail=None,
                            net=None):
        """Preview, then ONE Auto Repair step on *rows* through _BatchJob (one backup run = one Undo, Pause /
        Cancel, the rows refreshed as it goes, no full rescan). *label* is the stored (English) backup label.
        *net* (v0.20.1): None = the step's own kind; False = this run needs no online service."""
        net = (code in AR_NETWORK_STEPS) if net is None else net
        tmdb_key = SETTINGS.get("tmdb_api_key", "").strip()
        omdb_key = SETTINGS.get("omdb_api_key", "").strip()
        if net and not self._confirm_services(("tmdb", "omdb")):
            return None
        if confirm:
            lines = list(head) + [""]
            if all_movies:
                lines.append(_i18n.t("bf.all_note"))
            names = [(r.get("movie_name") or r.get("subfolder", "")) + ((" — " + detail(r)) if detail else "") for r in rows]   # v0.20.1 T2
            lines += ["  " + x for x in names[:300]]
            if len(names) > 300:
                lines.append(_i18n.t("m3.and_more", n=len(names) - 300).strip())
            if skipped:
                lines += ["", _i18n.t("bf.skipped_head", n=len(skipped))]
                lines += [f"  {r.get('movie_name') or r.get('subfolder', '')} — {why}" for r, why in list(skipped)[:300]]
            lines += ["", _i18n.t("bf.undo_note")]
            if not rows:
                messagebox.showinfo(title, "\n".join(lines), parent=self)
                return None
            pv = _PreviewRunDialog(self, title, "\n".join(lines), "fix_one_issue_preview", run_label=_i18n.t("bf.run"))
            self.wait_window(pv)
            if not pv.run:
                return None
        state = {"skip_all_ids": False}
        opts = {"tmdb_key": tmdb_key, "omdb_key": omdb_key, "lang": _tmdb_lang_for(SETTINGS.get("lang_ok_code", "EN")),
                "rating_pref": "votes", "multi": len(rows) > 1}
        coll_renames = []

        def _step(job, d):
            nfo, xml = _metadata_targets(d)
            name = d.get("movie_name") or d["subfolder"]
            backed = [False]

            def _backup():
                if not backed[0]:
                    if not job.backup(name, nfo, xml):
                        raise BackupFailed()
                    backed[0] = True
            ctx = {"d": d, "nfo": nfo, "xml": xml, "name": name, "tmdb_key": opts["tmdb_key"], "omdb_key": opts["omdb_key"],
                   "lang": opts["lang"], "rating_pref": opts["rating_pref"], "backup": _backup,
                   "state": dict(state, tmdb_data=None, verified_tmdb=None), "multi": opts["multi"], "fetch": None,
                   "coll_renames": coll_renames}
            try:
                st, msg = self._ar_run_step(code, ctx)
            except Exception:
                if backed[0]:                                    # v0.20.2 PA14: a file may have changed — refresh the row
                    job.changed.append(d["subfolder_path"])
                raise
            if backed[0] or st == "fixed":
                job.changed.append(d["subfolder_path"])
            if st == "fixed":
                return True
            if st == "skipped":
                raise _bulk.Skip(msg)
            raise RuntimeError(msg)

        def _checkpoint(job):                                    # "save as it goes": rows refreshed (and saved) in batches
            done = list(dict.fromkeys(job.changed))
            del job.changed[:]
            if done:
                self._schedule_refresh(done, need_ffprobe=False)

        def _finish(job):
            msg = _i18n.t("bf.done", label=title, n=_n(job.done, "movie"))
            if job.skipped_items:
                msg += _i18n.t("bf.skipped", n=len(job.skipped_items), join="\n".join(
                    f"  {nm} — {why}" for nm, why, _dt in job.skipped_items[:8]))
            if job.errors:
                msg += _i18n.t("bf.failed", join="\n".join(job.errors[:8]))
            if job.coll_notes:
                msg += "\n\n" + "\n".join(job.coll_notes[:8])
            msg += job.cancel_note()
            msg += ("\n\n" + UNDO_HINT) if job.done else ""
            self._last_one_step = (code, job.done, len(job.skipped_items), list(job.errors))   # read by the self-test
            (messagebox.showwarning if job.errors else messagebox.showinfo)(title, msg, parent=self)

        job = _BatchJob(self, rows, label, progress_title=title + "…", pausable=True)
        job.coll_notes = []
        job.after_steps = lambda j: j.coll_notes.extend(self._migrate_coll_folders(coll_renames, j.ref))   # checkup
        job.checkpoint, job.checkpoint_every = _checkpoint, 500
        if net:
            job.around = lambda run: self._in_service_run(job.prog, run)
        return job.run(_step, _finish)

    def _in_service_run(self, prog, fn):                         ### NEW v0.20.1 BF3 — a network step: one service run (B20 / B22) ###
        _service_run_begin(**self._service_run_args(prog, {"omdb": "TMDB", "tmdb": None}))
        try:
            return fn()
        finally:
            _service_run_end()

    # ── Auto Repair actions (worker thread) ───────────────────────────────────
    def _ar_xml_tags(self, ctx):                                ### NEW v0.20.0 KR1.4 ###
        """Add the movie.xml tags the old programs read: the ID writer writes all three ID tags; <VoteCount> = <Votes>."""
        xml = ctx.get("xml")
        gaps = xml_old_reader_gaps(xml) if xml else []
        if not gaps:
            return "skipped", _i18n.t("kr.ar.none")
        src = extract_source_ids_from_files(None, xml)
        n = 0
        for k in ("imdb", "tmdb"):
            if k in gaps and src.get(f"{k}_val"):
                ctx["backup"]()
                ok, err = _write_source_id_to_files(None, xml, k.upper(), src[f"{k}_val"])
                if not ok:
                    return "failed", f"movie.xml {k}: {err}"
                n += 1
        if "votes" in gaps:
            root = _parse_root(xml)
            v = ((root.findtext("Votes") if root is not None else "") or "").strip()
            content = _read_for_edit(xml)[0]
            rt = re.search(r"</([\w.-]+)\s*>\s*$", content)
            if v and rt:
                ctx["backup"]()
                _atomic_write_text(xml, _still_valid(content, _insert_before_root_close(content, rt.group(1), f"<VoteCount>{v}</VoteCount>")))   # PA7
                n += 1
        return ("fixed", _i18n.t("kr.ar.xml_added", n=n)) if n else ("skipped", _i18n.t("kr.ar.none"))

    def _ar_ids_kodi(self, ctx):                                ### NEW v0.20.0 KR1.1 ###
        """Write <uniqueid> for each NFO ID Kodi cannot see (the writer adds it and keeps <imdbid> / <tmdbid>)."""
        nfo = ctx["nfo"]
        if not nfo:
            return "skipped", _i18n.t("kr.ar.none")
        src = extract_source_ids_from_files(nfo, None)
        ### MODIFIED v0.20.1 BF2 — only the <uniqueid> line(s): no <id> forms, no empty placeholder tags (the full ID
        # writer added them; a tester called such tags junk); one write per NFO ###
        if not (src.get("nfo_kodi_missing") or []):
            return "skipped", _i18n.t("kr.ar.none")
        # checkup: BOTH IDs that have a value — once any <uniqueid> exists Kodi ignores a plain <id>tt…</id>, so adding
        # only the TMDB one made the IMDb ID invisible (a new warning after the run)
        ids = [(k, src.get(f"{k}_val")) for k in ("imdb", "tmdb") if src.get(f"{k}_val")]
        if not ids:
            return "skipped", _i18n.t("kr.ar.none")
        ctx["backup"]()
        n = len(add_kodi_uniqueids(nfo, ids))
        return ("fixed", _i18n.t("kr.ar.added", n=n)) if n else ("skipped", _i18n.t("kr.ar.none"))

    def _ar_fix_ids(self, ctx, mode):
        d, nfo, xml = ctx["d"], ctx["nfo"], ctx["xml"]
        key, lang = ctx["tmdb_key"], ctx["lang"]
        fetch = ctx.get("fetch") or _tmdb_rate_limited_fetch
        src = extract_source_ids_from_files(nfo, xml)
        if mode == "partial":
            n = 0
            for id_type, k in (("IMDB", "imdb"), ("TMDB", "tmdb")):
                vals = [v for v in src[f"{k}_all_vals"] if v]
                if src[f"{k}_status"] in (STATUS_WARN, STATUS_ERROR) and len(set(vals)) == 1:   # P4 (E2)
                    ctx["backup"]()
                    ok, err = _write_source_id_to_files(nfo, xml, id_type, vals[0])
                    if not ok:
                        return "failed", f"copy {id_type} ID: {err}"
                    n += 1
            return ("fixed", _i18n.t("uf.copied_to_the_other_488c", n=_n(n, 'ID'))) if n else ("skipped", _i18n.t("uf.nothing_to_copy_91c1"))
        if not key:
            return "skipped", _i18n.t("uf.no_tmdb_api_key_3c89")
        local_titles = _local_titles_for(d)
        year = d.get("movie_year_raw") or (d.get("movie_year") if str(d.get("movie_year", "-")).isdigit() else None)
        chosen = None
        if mode == "resolve" or src["tmdb_all_vals"] or src["imdb_all_vals"]:   ### MODIFIED v0.20.0 RD11 — one ID missing: the other one first ###
            # keep the candidate that TMDb confirms for this title/year
            matches = []
            for tid in dict.fromkeys(v for v in src["tmdb_all_vals"] if v):
                try:
                    data = _tmdb_movie_full(tid, key, lang, fetch)
                except Exception as ex:
                    if _is_http_404(ex): continue
                    raise
                ok, ratio, _b = _titles_match(_tmdb_candidate_titles(data), local_titles)
                if ok and _year_close(year, (data.get("release_date") or "")[:4]):
                    matches.append({"tmdb_id": str(data.get("id")), "imdb_id": (data.get("external_ids") or {}).get("imdb_id") or "",
                                    "title": data.get("title") or "", "original_title": data.get("original_title") or "",
                                    "year": (data.get("release_date") or "")[:4], "poster_path": data.get("poster_path") or "", "exact": True})
            for iid in dict.fromkeys(v for v in src["imdb_all_vals"] if v):
                try:
                    fr = _tmdb_find_imdb(iid, key, fetch)
                except Exception as ex:
                    if _is_http_404(ex): continue
                    raise
                if not fr: continue
                it = fr[0]
                ok, ratio, _b = _titles_match([it.get("title") or "", it.get("original_title") or ""], local_titles)
                if ok and _year_close(year, (it.get("release_date") or "")[:4]):
                    tid = str(it.get("id"))
                    if not any(m["tmdb_id"] == tid for m in matches):
                        matches.append({"tmdb_id": tid, "imdb_id": iid, "title": it.get("title") or "",
                                        "original_title": it.get("original_title") or "",
                                        "year": (it.get("release_date") or "")[:4], "poster_path": it.get("poster_path") or "", "exact": True})
            if len({m["tmdb_id"] for m in matches}) == 1:
                chosen = matches[0]
        if chosen is None:
            cands = []
            for t in local_titles[:2]:
                cands = _tmdb_search_movie(t, year, key, lang, fetch)
                if cands:
                    break
            exact = [c for c in cands if c.get("exact")]
            if exact and len({c["tmdb_id"] for c in exact}) == 1:
                chosen = exact[0]
            elif not cands:
                return "skipped", _i18n.t("uf.no_tmdb_search_result_8ece")
            else:
                if ctx["state"].get("skip_all_ids"):
                    return "skipped", _i18n.t("uf.no_exact_tmdb_match_500c")
                cand, skip_all = self._ask_id_chooser(ctx["name"], year, cands, show_apply_all=ctx.get("multi", False))
                if skip_all:
                    ctx["state"]["skip_all_ids"] = True
                if cand is None:
                    return "skipped", _i18n.t("uf.no_exact_tmdb_match_de4c")
                chosen = cand
        if not chosen.get("imdb_id") and chosen.get("tmdb_id"):
            chosen["imdb_id"] = _tmdb_external_ids(chosen["tmdb_id"], key, fetch)
        if chosen.get("imdb_only"):                                   ### v0.20.0 AU11 — checked BEFORE the write (it wrote, then said "failed") ###
            _old_tm = get_movie_ids_robust(nfo, xml)[1]               ### NEW v0.19.5 CO-D9 — the rule of Confirm IMDb, on every path ###
            if _old_tm:
                return "failed", _i18n.t("uf.the_files_still_hold_b309", old_tm=_old_tm)
        ctx["backup"]()
        ok, err = _write_both_source_ids(nfo, xml, chosen.get("imdb_id") or None, chosen.get("tmdb_id") or None)
        if not ok:
            return "failed", f"write IDs: {err}"
        ctx["state"]["verified_tmdb"] = chosen.get("tmdb_id")
        if chosen.get("imdb_only"):                                   ### NEW v0.19.1 B14 ###
            d["id_check"] = _imdb_only_check(chosen.get("imdb_id"), chosen.get("title"), chosen.get("year"),
                                             "Confirmed in Auto Repair (Enter ID…): not on TMDB")
            return "fixed", _i18n.t("uf.imdb_confirmed_not_on_aa8f", get=chosen.get('imdb_id'))
        d["id_check"] = {"result": ID_OK, "detail": f"Set by Auto Repair: '{chosen.get('title')}' ({chosen.get('year')})",
                         "imdb_id": chosen.get("imdb_id") or None, "tmdb_id": chosen.get("tmdb_id"),
                         "tmdb_title": chosen.get("title") or "", "tmdb_year": chosen.get("year") or "",
                         "when": datetime.datetime.now().strftime("%Y-%m-%d %H:%M")}
        return "fixed", _i18n.t("uf.ids_set_to_tmdb_dab0", get=chosen.get('tmdb_id'), v=chosen.get('imdb_id') or '—', get2=chosen.get('title'), get3=chosen.get('year'))

    def _ar_ratings(self, ctx):
        pref = ctx.get("rating_pref", "votes")
        if pref == "skip":
            return "skipped", _i18n.t("uf.ratings_not_synced_in_8661")
        d, nfo, xml = ctx["d"], ctx["nfo"], ctx["xml"]
        imdb_id, tmdb_id = get_movie_ids_robust(nfo, xml)
        _take_fetch_errors()
        _why = ratings_skip_reason(imdb_id, tmdb_id, bool(ctx["tmdb_key"]), bool(ctx["omdb_key"]))   ### NEW v0.19.6 TR2 ###
        if _why:
            return "skipped", "ratings: " + _why
        if not ctx["tmdb_key"]:
            tr, tv = None, None
        elif tmdb_id:
            tr, tv = _fetch_tmdb_rating(tmdb_id, ctx["tmdb_key"])
        else:                                                    # v0.19.6 TR2: only an IMDb ID
            tr, tv = _fetch_tmdb_rating_by_imdb(imdb_id, ctx["tmdb_key"])
        or_, ov = _fetch_omdb_rating(imdb_id, ctx["omdb_key"]) if (ctx["omdb_key"] and imdb_id) else (None, None)
        _errs = _take_fetch_errors()                              ### NEW v0.19.1 ###
        if _errs:
            return "failed", "ratings: " + _errs[0]
        tok, ook = self._rating_valid(tr, tv), self._rating_valid(or_, ov)
        if not tok and not ook:
            return "skipped", _i18n.t("uf.no_valid_rating_online_754e")
        if pref == "tmdb":
            r, v, srcl = (tr, tv, "TMDB") if tok else (or_, ov, "OMDb/IMDb")
        elif pref == "omdb":
            r, v, srcl = (or_, ov, "OMDb/IMDb") if ook else (tr, tv, "TMDB")
        else:
            r, v, srcl = self._auto_by_votes(tr, tv, or_, ov) if (tok and ook) else ((tr, tv, "TMDB") if tok else (or_, ov, "OMDb/IMDb"))
        ctx["backup"]()                                          # the run's backup folder (B82: no second one)
        errs = write_rating_to_files(nfo, xml, r, v, movie_name=ctx["name"], backup=False,   ### MODIFIED v0.19.4 B82 ###
                                     source=_rating_source_name(srcl))   # v0.19.5 B122
        if errs:
            return "failed", "ratings: " + "; ".join(errs)
        return "fixed", f"rating {r} / votes {v} ({srcl})"

    def _ar_genres(self, ctx):
        nfo, xml = ctx["nfo"], ctx["xml"]
        info = resolve_movie_genres(nfo, xml)                  ### MODIFIED v0.19.1 — NFO + XML ###
        genres = info["genres"]
        if not genres:
            return "skipped", _i18n.t("uf.no_genres_in_the_4e58")
        normalized, changed = normalize_genre_list(genres)
        sync = bool(info["only_in_xml"] or info["only_in_nfo"] or info["nfo_wrong"])
        if not changed and not sync:
            return "skipped", _i18n.t("uf.genres_already_normalized_1581")
        ctx["backup"]()
        ok_n, err_n = write_genres_to_nfo(nfo, normalized) if nfo else (False, "")
        ok_x, err_x = write_genres_to_xml(xml, normalized) if xml else (False, "")
        if not (ok_n or ok_x):
            return "failed", f"genres: {err_n or err_x}"
        if nfo and xml and not (ok_n and ok_x):                    ### NEW v0.19.5 WR-B3 — one good file is not a success ###
            return "failed", _i18n.t("uf.m.genres_xml_only" if ok_x else "uf.m.genres_nfo_only", err=err_n or err_x)   # UI1f
        return "fixed", ("genres normalized: " if changed else _i18n.t("uf.genres_synced_nfo_xml_1d7c")) + "/".join(normalized)

    def _ar_tmdb_data(self, ctx):
        """Movie data for a VERIFIED TMDB id (verified in this run or by Verify IDs)."""
        if ctx["state"].get("tmdb_data") is not None:
            return ctx["state"]["tmdb_data"]
        d = ctx["d"]
        tid = ctx["state"].get("verified_tmdb")
        if not tid and (d.get("id_check") or {}).get("result") in (ID_OK, ID_INVALID):   # v0.20.1 T4: the film is right
            tid = (d.get("id_check") or {}).get("tmdb_id") or get_movie_ids_robust(ctx["nfo"], ctx["xml"])[1]
        if not tid and ctx["tmdb_key"]:                          ### NEW v0.20.1 L2 — verify here; "skipped: not verified" misled ###
            try:
                chk = verify_movie_ids(d, ctx["tmdb_key"], ctx["lang"], ctx.get("fetch") or _tmdb_rate_limited_fetch)
                if chk.get("result") in (ID_OK, ID_INVALID) and chk.get("tmdb_id"):
                    tid = chk["tmdb_id"]
                    d["id_check"] = chk
            except Exception as ex:
                logger.info(f"Auto Repair: verify for {ctx.get('name')}: {ex}")
        if not tid or not ctx["tmdb_key"]:
            ctx["state"]["tmdb_data"] = {}
            return {}
        try:
            data = _tmdb_movie_full(tid, ctx["tmdb_key"], ctx["lang"], ctx.get("fetch") or _tmdb_rate_limited_fetch)
        except Exception:
            data = {}
        ctx["state"]["tmdb_data"] = data or {}
        return ctx["state"]["tmdb_data"]

    def _ar_genres_tmdb(self, ctx):
        data = self._ar_tmdb_data(ctx)
        if not data:
            return "skipped", _i18n.t("uf.tmdb_id_not_verified_c67b")
        names = [g.get("name") for g in (data.get("genres") or []) if g.get("name")]
        if not names:
            return "skipped", _i18n.t("uf.tmdb_lists_no_genres_952f")
        normalized, _c = normalize_genre_list(names)
        ctx["backup"]()
        ok_n, err_n = write_genres_to_nfo(ctx["nfo"], normalized) if ctx["nfo"] else (False, "no NFO")
        ok_x, err_x = write_genres_to_xml(ctx["xml"], normalized) if ctx["xml"] else (False, "no XML")
        if not (ok_n or ok_x):
            return "failed", _i18n.t("uf.genres_from_tmdb_773b", err_n=err_n, err_x=err_x)
        if ctx["nfo"] and ctx["xml"] and not (ok_n and ok_x):      ### NEW v0.19.5 WR-B3 ###
            return "failed", _i18n.t("uf.m.genres_tmdb_xml_only" if ok_x else "uf.m.genres_tmdb_nfo_only", err=err_n or err_x)   # UI1f
        return "fixed", _i18n.t("uf.genres_from_tmdb_ab65") + "/".join(normalized)

