    def _auto_repair_worker(self, data_list, opts, prog=None):        ### NEW v0.19.1 B20 — one service run ###
        """Runs _auto_repair_worker_run inside a service run (B20): a service that refuses
        (daily limit / invalid key) is not asked again until the run ends."""
        _service_run_begin(**self._service_run_args(prog, {"omdb": "TMDB", "tmdb": None}))   ### B22 ###
        try:
            with _sc.backup_action("Auto Repair"):                     ### NEW v0.19.1 I1 ###
                return self._auto_repair_worker_run(data_list, opts, prog)
        finally:
            _service_run_end()

    def _auto_repair_worker_run(self, data_list, opts, prog=None):     ### NEW v0.19.0 ###
        rules = SETTINGS.get("health_rules", {})
        backup_ref = [None]
        state = {"skip_all_ids": False}
        entries = []
        repaired = []                                            ### v0.19.0 — applied once at the end ###
        coll_renames = []                                        ### NEW v0.19.4 fix 15 ###
        error = None
        for i, d in enumerate(data_list):
            if (prog and prog.cancelled) or _service_run_cancelled():   # B22
                break
            name = d.get("movie_name") or d["subfolder"]
            plan = _auto_repair_plan(d, SETTINGS, rules)
            if opts.get("steps") is not None:                    ### NEW v0.20.1 BF4 — only the ticked steps ###
                plan = [(c, lbl) for c, lbl in plan if c in opts["steps"]]
            e = {"name": name, "planned": [lbl for _c, lbl in plan], "fixed": [], "skipped": [], "failed": [], "failing": []}
            entries.append(e)
            if not plan:
                e["skipped"].append(_i18n.t("uf.nothing_to_repair_automatically_8205"))
                e["failing"] = list(d.get("health_reasons") or [])
                if prog: prog.advance(i + 1)
                continue
            nfo = _metadata_targets(d)[0]   # v0.20.0 F3b
            xml = _metadata_targets(d)[1]   # v0.20.0 F3b
            backed = [False]
            def _backup(n=name, nf=nfo, xm=xml, flag=backed):
                if not flag[0]:
                    if not _batch_backup_ok(n, backup_ref, nf, xm):   ### MODIFIED v0.19.2 B40 — the action fails, nothing written ###
                        raise BackupFailed()
                    flag[0] = True
            ctx = {"d": d, "nfo": nfo, "xml": xml, "name": name, "tmdb_key": opts.get("tmdb_key", ""),
                   "omdb_key": opts.get("omdb_key", ""), "lang": opts.get("lang", "en-US"),
                   "rating_pref": opts.get("rating_pref", "votes"), "backup": _backup,
                   "state": dict(state, tmdb_data=None, verified_tmdb=None), "multi": opts.get("multi", False),
                   "fetch": opts.get("fetch"), "coll_renames": coll_renames}
            for code, label in plan:
                try:
                    st, msg = self._ar_run_step(code, ctx)        ### MODIFIED v0.20.1 BF3 — one table (_AR_STEP_METHODS) ###
                except Exception as ex:
                    ### MODIFIED v0.19.4 B77 — only a network error stops the run; a file error
                    ### (locked / read-only NFO, PermissionError …) fails this movie, with its real reason ###
                    _file_err = False
                    if is_network_error(ex):
                        error = _tmdb_error_message(ex)
                        st, msg = "failed", f"{label}: {error}"
                    else:
                        _file_err = isinstance(ex, OSError)
                        st, msg = "failed", f"{label}: {ex}"
                    logger.error(f"Auto Repair '{name}' {code}: {ex}")
                    if _file_err:
                        e["failed"].append(msg)
                        break                                   # the next movie goes on
                e[{"fixed": "fixed", "skipped": "skipped", "failed": "failed"}[st]].append(msg)
                if error:
                    break
            state["skip_all_ids"] = ctx["state"].get("skip_all_ids", False)
            if e["fixed"] or e["failed"]:                         ### MODIFIED v0.19.5 WR-B2 — a failed step may have changed one file ###
                _sc.note_written([d.get("subfolder_path")])           ### NEW v0.19.5 WR-C1 — Undo can warn about later changes ###
                try:
                    # the summary needs the post-repair health now; the table
                    # rows are applied in one batch at the end (_done)
                    r = self._rescan_row_no_probe(d)
                    e["failing"] = list(r.get("health_reasons") or [])
                    repaired.append(r)
                except Exception as ex:
                    logger.error(f"Auto Repair rescan '{name}': {ex}")
            else:
                e["failing"] = list(d.get("health_reasons") or [])
            if prog: prog.advance(i + 1)
            if (i + 1) % 500 == 0 and repaired:                 ### NEW v0.20.2 PB2 — table + cache every 500 movies ###
                _chunk = list(repaired); del repaired[:]
                ui_post(lambda c=_chunk: (self._apply_rescanned_rows(c), self._incremental_save(self._results)))
            if error:
                break
        coll_notes = []                                          ### NEW v0.19.4 fix 15 — the renamed collections' folders ###
        if coll_renames:
            try:
                coll_notes = self._migrate_coll_folders(coll_renames, backup_ref)
            except Exception as ex:
                coll_notes = [_i18n.t("uf.collection_folders_not_moved_084d", ex=ex)]
        if prog:
            prog.close()
        text = format_auto_repair_summary(entries)
        if coll_notes:
            text += _i18n.t("mc.collection_folders_0de9", join="\n".join("  " + x for x in coll_notes))
        _svc = _service_run_summary()                            ### NEW v0.19.1 B20 ###
        if _svc:
            text = "\n".join(_svc) + "\n\n" + text
        logger.info(f"Auto Repair finished: {sum(1 for x in entries if x['fixed'])} fixed of {len(entries)}")
        def _done():
            self._apply_rescanned_rows(repaired)                 ### MODIFIED v0.19.4 P6 (E11) ###
            self._update_stats()
            self._incremental_save(self._results)
            if error:
                messagebox.showerror(_i18n.t("mc.auto_repair_stopped_f6df"), _i18n.t("mc.the_summary_shows_what_22f6", error=error), parent=self)
            TextReportDialog(self, _i18n.t("uf.auto_repair_summary_4913"), text, "auto_repair_summary")
            if coll_notes:
                self._read_collection_folders()
        ui_post(_done)

    def _fix_ids_for(self, row, on_done=None):                     ### REWRITTEN v0.19.0 — the Auto Repair chooser ###
        """Fix… from the verification report: TMDb search in a worker, the
        chooser (exact match preselected), write the IDs, re-verify, refresh."""
        if not self._confirm_services(("tmdb",)):          ### NEW v0.19.1 B22 — paused service: Try anyway? ###
            return
        key = SETTINGS.get("tmdb_api_key", "").strip()
        if not key:
            messagebox.showwarning(_i18n.t("mc.fix_ids_101e"), _i18n.t("mc.no_tmdb_api_key_51c5"), parent=self); return
        lang = _tmdb_lang_for(SETTINGS.get("lang_ok_code", "EN"))
        def _worker():
            try:
                year = row.get("movie_year_raw") or (row.get("movie_year") if str(row.get("movie_year", "-")).isdigit() else None)
                cands = []
                for t in _local_titles_for(row)[:2]:
                    cands = _tmdb_search_movie(t, year, key, lang)
                    if cands: break
                if not cands:
                    ui_post(lambda: messagebox.showinfo(_i18n.t("mc.fix_ids_101e"), _i18n.t("mc.no_tmdb_result_for_0e05", get=row.get('movie_name')), parent=self)); return
                pre = next((i for i, c in enumerate(cands) if c.get("exact")), None)
                cand, _skip = self._ask_id_chooser(row.get("movie_name") or row["subfolder"], year, cands, False, pre)
                if cand is None:
                    return
                nfo = _metadata_targets(row)[0]   # v0.20.0 F3b
                xml = _metadata_targets(row)[1]   # v0.20.0 F3b
                if not cand.get("imdb_id") and cand.get("tmdb_id"):
                    cand["imdb_id"] = _tmdb_external_ids(cand["tmdb_id"], key)
                if cand.get("imdb_only"):                           ### v0.20.0 AU11 — checked BEFORE writing (Search Sources'
                    _old_tm = get_movie_ids_robust(nfo, xml)[1]     # rule): it used to write the IMDb ID, then say "failed" ###
                    if _old_tm:
                        ui_post(lambda t=_old_tm: messagebox.showwarning(_i18n.t("mc.fix_ids_101e"), _i18n.t("mc.the_files_still_hold_edc2", t=t), parent=self))
                        return
                if not _with_backup_action("Fix IDs", _backup_ok, row.get("movie_name") or row["subfolder"], nfo, xml):   ### MODIFIED v0.19.2 B40; v0.19.5 WR-C1: its label ###
                    ui_post(lambda: messagebox.showerror(_i18n.t("mc.fix_ids_101e"), _i18n.t("mc.backup_failed_nothing_was_7979", v=row.get('movie_name') or row['subfolder']), parent=self)); return
                ok, err = _write_both_source_ids(nfo, xml, cand.get("imdb_id") or None, cand.get("tmdb_id") or None)
                _sc.note_written([row["subfolder_path"]])            ### NEW v0.19.5 WR-C1 ###
                if not ok:
                    self._schedule_refresh([row["subfolder_path"]])   ### NEW v0.19.5 WR-B2 — one file may have changed ###
                    ui_post(lambda m=err: messagebox.showerror(_i18n.t("mc.fix_ids_101e"), _i18n.t("mc.one_file_may_have_b553", m=m), parent=self)); return
                r = self._rescan_row_no_probe(row)
                if cand.get("imdb_only"):                                   ### NEW v0.19.1 B14 ###
                    r["id_check"] = _imdb_only_check(cand.get("imdb_id"), cand.get("title"), cand.get("year"))
                    _apply_health(r)
                else:
                    try:
                        r["id_check"] = verify_movie_ids(r, key, lang)
                        take_collection_data(r, r["id_check"])           # v0.20.0 AU11: as Verify IDs does
                    except Exception as ex:
                        r["id_check"] = {"result": ID_OK, "detail": f"Set to TMDB {cand.get('tmdb_id')} (re-check failed: {_tmdb_error_message(ex)})",
                                         "imdb_id": cand.get("imdb_id"), "tmdb_id": cand.get("tmdb_id"), "tmdb_title": cand.get("title"),
                                         "tmdb_year": cand.get("year"), "when": datetime.datetime.now().strftime("%Y-%m-%d %H:%M")}
                def _ui():
                    old = dict(row)                                  ### MODIFIED v0.19.4 P2 (E9) — on the Tk thread ###
                    row.clear(); row.update(r)           # the report dialog holds this dict
                    self._apply_rescanned_row(row)
                    self._regroup_if_moved(old, row)
                    self._update_stats(); self._incremental_save(self._results)
                    if on_done: on_done(row)
                ui_post(_ui)
            except Exception as ex:
                logger.error(f"Fix IDs: {ex}")
                ui_post(lambda m=_tmdb_error_message(ex): messagebox.showerror(_i18n.t("mc.fix_ids_101e"), m, parent=self))
        _AppJobThread(self, target=_worker, act_paths=(row.get("subfolder_path"),)).start()   # v0.20.0 AU11; v0.20.1 SN3

