    def _ask_backdrop_count(self, movie, local_n, online_n, sources=None):   ### NEW v0.19.1 B17 ###
        """Worker thread: show local vs online backdrop counts before Replace
        All Backdrops deletes anything; True = go ahead.  Fewer online than
        local needs an explicit "Replace anyway".
        ### v0.19.1 I10 ### with sources={"tmdb": n, "fanarttv": m} the user
        also picks the source: "tmdb" | "fanarttv" | "both", False = cancel."""
        res = self._ask_on_ui(lambda: _BackdropCountDialog(self, movie, local_n, online_n, sources=sources),
                              lambda dlg: (dlg.result, dlg.count))
        res, n = res if isinstance(res, tuple) else (res, None)
        if not res:
            return False
        ### MODIFIED v0.19.3 B61 — (source or True, how many) ###
        return ((res if sources else True), n)

    def _image_source_keys(self, title, data_list=(), mode=None):   ### NEW v0.19.1 I10, B25 ###
        """UI thread, before a Fetch dialog: the TMDb key ("" when only
        fanart.tv has one), or None when no image source has a key / a
        paused service was not retried.  ### v0.19.1 B25 ### no key is fine
        when a selected movie can use frames from its video."""
        tmdb_key = SETTINGS.get("tmdb_api_key", "").strip()
        services = tuple(s for s, k in (("tmdb", tmdb_key), ("fanarttv", fanarttv_key())) if k)
        if not services and mode and any("frames" in image_sources_for(d, mode, "") for d in data_list):
            return ""
        if not services:
            messagebox.showwarning(title, _i18n.t("mc.no_tmdb_api_key_c36b"))
            return None
        if not self._confirm_services(services):              ### B22 — paused service: Try anyway? ###
            return None
        return tmdb_key

    def _replace_all_backdrops(self, d):                       ### NEW v0.18.0 ###
        """
        Replace All Backdrops for a single movie:
          1. Backup all existing backdrop*.jpg files
          2. Delete originals
          3. Download ALL TMDB backdrops sequentially
          4. Show progress popup if >15s elapsed
          5. Show final summary dialog
        All work runs in a background thread.
        """
        if self._artwork_busy([d], _i18n.t("uf.replace_all_backdrops_f4cd")):     ### NEW v0.19.3 B62 ###
            return
        tmdb_key = self._image_source_keys(_i18n.t("uf.replace_all_backdrops_f4cd"))   ### MODIFIED v0.19.1 I10 — TMDb and/or fanart.tv ###
        if tmdb_key is None:
            return
        tmdb_id  = d.get("source_tmdb_val")
        imdb_id  = d.get("source_imdb_val")
        sp       = d.get("subfolder_path", "")
        movie    = d.get("movie_name", d.get("subfolder", "?"))
        use_fan  = bool(fanarttv_key()) and bool(tmdb_id or imdb_id)

        if not tmdb_id and not use_fan:
            messagebox.showwarning(_i18n.t("mc.replace_all_backdrops_f4cd"),
                _i18n.t("mc.no_tmdb_id_found_88d1", movie=movie))
            return
        if not os.path.isdir(sp):
            messagebox.showerror(_i18n.t("mc.replace_all_backdrops_f4cd"), _i18n.t("mc.folder_not_found_4e5b", sp=sp), parent=self)
            return

        # Progress popup (created on main thread, shown only after 15s)
        _prog_win    = [None]
        _prog_var    = [None]
        _prog_label  = [None]
        _start_time  = [None]
        _cancelled   = [False]

        def _show_progress(pct, eta_str):
            if _prog_win[0] is None:
                w = tk.Toplevel(self)
                w.title(_i18n.t("mc.replace_all_backdrops_f4cd"))
                w.configure(bg=C_BG)
                w.resizable(False, False)
                w.transient(self)
                tk.Label(w, text=_i18n.t("mc.processing_backdrops_please_wait_01b8"),
                         bg=C_BG, fg=C_TEXT,
                         font=("Helvetica", 10, "bold")).pack(pady=(18, 6), padx=20)
                pv = tk.StringVar(value="0%")
                tk.Label(w, textvariable=pv,
                         bg=C_BG, fg=C_OK,
                         font=("Helvetica", 12, "bold")).pack()
                lv = tk.StringVar(value="")
                tk.Label(w, textvariable=lv,
                         bg=C_BG, fg=C_DIM,
                         font=("Helvetica", 8)).pack(pady=(2, 16), padx=20)
                tk.Button(w, text=_i18n.t("mc.cancel_ea47"),
                          bg=C_ERR, fg=C_BG,
                          relief="flat", cursor="hand2",
                          font=("Helvetica", 9, "bold"),
                          command=lambda: _cancelled.__setitem__(0, True)
                          ).pack(pady=(0, 14))
                w.update_idletasks()
                wx = self.winfo_rootx() + (self.winfo_width()  - w.winfo_width())  // 2
                wy = self.winfo_rooty() + (self.winfo_height() - w.winfo_height()) // 2
                w.geometry(f"+{wx}+{wy}")
                _prog_win[0]   = w
                _prog_var[0]   = pv
                _prog_label[0] = lv
            _prog_var[0].set(f"{int(pct)}%")
            _prog_label[0].set(eta_str)
            try:
                _prog_win[0].update_idletasks()
            except tk.TclError:
                pass

        def _close_progress():
            if _prog_win[0]:
                try:
                    _prog_win[0].destroy()
                except tk.TclError:
                    pass
                _prog_win[0] = None

        def _worker():
            _start_time[0] = time.time()
            backup_count   = 0
            download_count = 0
            delete_count   = 0
            backup_bytes   = 0
            download_bytes = 0
            fail_reason    = None

            # ── STEP 1: Collect existing backdrops ───────────────────────────
            existing_paths = []
            try:
                if not os.path.isdir(sp):
                    raise OSError("folder not found")
                existing_paths = replaceable_backdrops(sp)       ### MODIFIED v0.19.1 B23 — Kodi folders: fanartN ###
            except OSError as e:
                fail_reason = _i18n.t("uf.cannot_read_movie_folder_5cfd", e=e)

            if fail_reason:
                ui_post(lambda m=fail_reason: (
                    _close_progress(),
                    messagebox.showerror(_i18n.t("mc.replace_all_backdrops_failed_7ae1"),
                                         _i18n.t("mc.reason_a163", m=m))))
                return

            total_existing = len(existing_paths)

            # ── STEP 2: Fetch the online lists (TMDb, fanart.tv) ────────────
            ### MODIFIED v0.19.1 I10 — fanart.tv too when a key is set ###
            tm_list, fa_list, errs = [], [], []
            if tmdb_key and tmdb_id:
                tm_list, errs = load_online_images("fanart", "tmdb", tmdb_key, tmdb_id)
            if use_fan:
                fa_list, e2 = load_online_images("fanart", "fanarttv", "", tmdb_id, imdb_id)
                errs += e2
            if not tm_list and not fa_list and errs:
                fail_reason = "\n".join(errs)
                ui_post(lambda m=fail_reason: (
                    _close_progress(),
                    messagebox.showerror(_i18n.t("mc.replace_all_backdrops_failed_7ae1"),
                                         _i18n.t("mc.reason_a163", m=m))))
                return

            _n_all = len(tm_list) + len(fa_list)                     ### NEW v0.20.2 B26 — the artwork-language setting ###
            tm_list, fa_list = offered_online_images(tm_list, "fanart"), offered_online_images(fa_list, "fanart")
            if not tm_list and not fa_list:
                _src_txt = _i18n.t("uf.tmdb_and_fanart_tv_ffd0") if use_fan else _i18n.t("au.tmdb_returned")
                _none_txt = (_i18n.t("art.rab_only_none", movie=movie, name=_ao.language_name(artwork_lang_settings()[0]))
                             if _n_all else _i18n.t("mc.backdrops_nothing_to_download_534a", movie=movie, src_txt=_src_txt))
                ui_post(lambda: (
                    _close_progress(),
                    messagebox.showwarning(_i18n.t("mc.replace_all_backdrops_f4cd"), _none_txt)))
                return

            # ── v0.19.1 B17: compare the counts BEFORE any backup / delete ───
            want = None                                                 ### NEW v0.19.3 B61 — how many (None = all) ###
            if use_fan:                                                 ### v0.19.1 I10 — source choice ###
                choice = self._ask_backdrop_count(movie, total_existing, len(tm_list),
                                                  sources={"tmdb": len(tm_list), "fanarttv": len(fa_list)})
            else:
                choice = self._ask_backdrop_count(movie, total_existing, len(tm_list))   ### NEW v0.19.1 B17 ###
            if isinstance(choice, tuple):
                choice, want = choice
            if not use_fan:
                choice = "tmdb" if choice else False
            if not choice:
                ui_post(_close_progress)
                logger.info(f"Replace All Backdrops cancelled for '{movie}' "
                            f"(local {total_existing}, online {len(tm_list)} + {len(fa_list)}) — nothing touched")
                return
            choice = choice if choice in ("tmdb", "fanarttv", "both") else "tmdb"
            tmdb_imgs = (order_online_images(merge_image_sources(tm_list, fa_list), "fanart") if choice == "both"   # v0.20.1 TF3
                         else fa_list if choice == "fanarttv" else tm_list)
            _src_label = IMAGE_SOURCE_LABEL[choice] if choice != "both" else _i18n.t("uf.tmdb_fanart_tv_733b")
            _start_time[0] = time.time()          # the question's time is not part of the ETA
            want = len(tmdb_imgs) if want is None else max(1, min(int(want), len(tmdb_imgs)))   ### v0.19.3 B61 ###
            failed_dl = [0]

            total_steps = total_existing + total_existing + want
            completed   = [0]

            def _update_progress():
                if _cancelled[0]:
                    return
                elapsed = time.time() - _start_time[0]
                pct = (completed[0] / max(total_steps, 1)) * 100
                if completed[0] > 0 and elapsed > 0:
                    rate = elapsed / completed[0]
                    remaining = rate * (total_steps - completed[0])
                    if remaining > 60:
                        eta = _i18n.t("au.eta_m", m=int(remaining // 60), s=int(remaining % 60))
                    elif remaining > 0:
                        eta = _i18n.t("au.eta_s", s=int(remaining))
                    else:
                        eta = _i18n.t("au.almost")
                else:
                    eta = ""
                if elapsed > 1.0:                                  ### MODIFIED v0.19.1 — was 15 s ###
                    ui_post(lambda p=pct, e=eta: _show_progress(p, e))

            # ── STEP 3: Backup all existing backdrops ────────────────────────
            if existing_paths:
                # ### FIXED v0.19.1 B17 ### was [] → make_batch_backup raised
                # IndexError internally, returned None, NOTHING was backed up,
                # and the originals were still deleted below.
                backup_folder_ref = [None]
                for p in existing_paths:
                    if _cancelled[0]:
                        break
                    try:
                        if not _make_batch_backup(movie, backup_folder_ref, p):   ### FIXED v0.19.1 B17 ###
                            raise OSError("the backup copy could not be made (see logs/app.log)")
                        backup_count  += 1
                        backup_bytes  += os.path.getsize(p)
                        completed[0]  += 1
                        _update_progress()
                    except Exception as e:
                        fail_reason = _i18n.t("uf.backup_failed_for_b010", p=os.path.basename(p), e=e)
                        break

                if fail_reason:
                    ui_post(lambda m=fail_reason: (
                        _close_progress(),
                        messagebox.showerror(_i18n.t("mc.replace_all_backdrops_failed_7ae1"),
                                             _i18n.t("mc.reason_a163", m=m))))
                    return

            if _cancelled[0]:
                ui_post(lambda: (_close_progress(),
                    messagebox.showinfo(_i18n.t("mc.replace_all_backdrops_f4cd"), _i18n.t("mc.cancelled_by_user_63fb"))))
                return

            # ── STEP 4: Download the new backdrops to temp names ─────────────
            ### MODIFIED v0.19.4 B78 — download FIRST ("<name>.mcnew"), swap after: the
            ### originals are deleted only when at least one new image arrived ###
            ### MODIFIED v0.19.3 B61 — only *want* images, best first (the lists are sorted
            ### by resolution); a failed download is replaced by the next image ###
            _new_names = new_backdrop_paths(sp, want, free=existing_paths)   ### NEW v0.19.1 B23; v0.19.4 B78 free= ###
            _staged = []                                         # (temp file, final name)  ### NEW v0.19.4 B78 ###
            for img in tmdb_imgs:
                if _cancelled[0] or download_count >= want:
                    break
                url = img.get("url", "")                                ### MODIFIED v0.19.1 I10 ###
                if not url:
                    failed_dl[0] += 1
                    continue
                dest     = _new_names[download_count]             ### MODIFIED v0.19.1 B23 ###
                fname    = os.path.basename(dest)
                tmp_new  = dest + REPLACE_BACKDROPS_TMP_EXT       ### NEW v0.19.4 B78 ###
                ok, err  = _tmdb_download_image(url, tmp_new)
                if ok:
                    download_count += 1
                    _staged.append((tmp_new, dest))
                    try:
                        download_bytes += os.path.getsize(tmp_new)
                    except OSError:
                        pass
                    completed[0] += 1
                    _update_progress()
                else:
                    failed_dl[0] += 1
                    logger.warning(f"_replace_all_backdrops: failed to download {fname}: {err}")

            def _drop_staged():                                  ### NEW v0.19.4 B78 ###
                for t, _f in _staged:
                    try:
                        if os.path.exists(t):
                            os.remove(t)
                    except OSError as e:
                        logger.warning(f"_replace_all_backdrops: could not remove {t}: {e}")

            if _cancelled[0]:                                    ### NEW v0.19.4 B78 — cancel = nothing changed ###
                _drop_staged()
                ui_post(lambda: (_close_progress(), messagebox.showinfo(
                    _i18n.t("mc.replace_all_backdrops_f4cd"), _i18n.t("mc.cancelled_by_user_the_46e1"))))
                return
            if not _staged:                                      ### NEW v0.19.4 B78 — nothing arrived: keep the originals ###
                ui_post(lambda: (_close_progress(), messagebox.showwarning(
                    _i18n.t("mc.replace_all_backdrops_nothing_9917"),
                    replace_backdrops_none_text(movie, total_existing, want, failed_dl[0], len(tmdb_imgs)))))
                logger.warning(f"Replace All Backdrops: no image arrived for '{movie}' — "
                               f"the {_n(total_existing, 'original backdrop')} {'was' if total_existing == 1 else 'were'} kept")   # v0.19.4 B105
                return

            # ── STEP 5: Swap ─  ### REWRITTEN v0.19.5 WR-B5 ### the new ones first; an old file goes only when its place is safe.
            # It used to delete first: a new file held by an antivirus left neither the old image nor the new one.
            _swap_failed, _not_deleted, _landed = [], [], set()
            _bk_ref = backup_folder_ref if existing_paths else [None]   # v0.19.5 WR-C3
            for t, final in _staged:
                try:
                    existed = os.path.exists(final)
                    _sc._replace_retry(t, final)
                    _cache_forget(final)
                    _landed.add(os.path.normcase(final))
                    if existed:
                        delete_count += 1
                    else:                                        ### NEW v0.19.5 WR-C3 — Undo removes a name that did not exist ###
                        _sc.note_created(_BACKUP_ROOT, movie, _bk_ref, final, None, logger=logger)
                except OSError as e:
                    _swap_failed.append(os.path.basename(final))
                    download_count -= 1
                    logger.warning(f"_replace_all_backdrops: could not rename {t} → {final}: {e}")
                    try:
                        if os.path.exists(t):
                            os.remove(t)
                    except OSError:
                        pass
            _failed_names = {x.casefold() for x in _swap_failed}
            for p in existing_paths:
                try:
                    ### MODIFIED v0.20.0 AU5 ### no new image landed (every swap failed): the originals stay — they used
                    # to be deleted, leaving the folder with fewer or no backdrops
                    if (_landed and os.path.normcase(p) not in _landed and os.path.isfile(p)
                            and os.path.basename(p).casefold() not in _failed_names):
                        os.remove(p)
                        delete_count += 1
                    completed[0] += 1
                    _update_progress()
                except OSError as e:
                    _not_deleted.append(os.path.basename(p))
                    logger.warning(f"_replace_all_backdrops: could not delete {p}: {e}")

            # ── STEP 6: Finish ───────────────────────────────────────────────
            avg_backup   = (backup_bytes   // backup_count)   if backup_count   > 0 else 0
            avg_download = (download_bytes // max(len(_staged), 1)) if _staged else 0

            def _finish():
                _close_progress()
                _bad = _swap_failed or _not_deleted                ### NEW v0.19.5 WR-B5 ###
                T = _i18n.t                                        # v0.20.0 UI1d
                msg = ((T("m3.rb_bad") if _bad else T("m3.rb_ok")) +
                       T("m3.rb_backups", files=_n(backup_count, "file"))
                       + (T("m3.rb_avg", kb=avg_backup // 1024) if avg_backup else "") + "\n" +
                       T("m3.rb_deleted", files=_n(delete_count, "file")) +
                       T("m3.rb_downloaded", src=_src_label, files=_n(download_count, "file"))
                       + (T("m3.rb_avg", kb=avg_download // 1024) if avg_download else "")
                       + (T("m3.rb_only", n=download_count, want=want, failed=failed_dl[0], offered=len(tmdb_imgs))   ### NEW v0.19.3 B61 ###
                          if download_count < want else "")
                       + (T("m3.rb_swap", list=", ".join(_swap_failed)) if _swap_failed else "")   ### NEW v0.19.4 B78 ###
                       + (T("m3.rb_notdel", list=", ".join(_not_deleted)) if _not_deleted else ""))
                (messagebox.showwarning if _bad else messagebox.showinfo)(T("m3.rb_title"), msg)
                self._reval_by_path(d)

            ui_post(_finish)

        _AppJobThread(self, target=lambda: _with_backup_action("Replace All Backdrops", _worker),
                      act_paths=(d.get("subfolder_path"),)).start()   ### I1; P2; v0.20.1 SN3 ###

    def _open_fanart_tv(self, d):                              ### NEW v0.18.0 ###
        """Open the selected movie's Fanart.tv page using its TMDB ID."""
        tmdb_id = d.get("source_tmdb_val")
        if not tmdb_id:
            messagebox.showinfo(_i18n.t("mc.fanart_tv_movie_id_49b5"),
                _i18n.t("mc.no_tmdb_id_found_ab37"),
                parent=self)
            return
        try:
            int(tmdb_id)  # validate it's numeric
        except (ValueError, TypeError):
            messagebox.showwarning(_i18n.t("mc.invalid_tmdb_id_2f25"),
                _i18n.t("mc.the_tmdb_id_appears_0b9b", tmdb_id=tmdb_id),
                parent=self)
            return
        url = f"https://fanart.tv/movie/{tmdb_id}/"
        try:
            open_url_with_browser(url)
        except Exception as e:
            messagebox.showerror(_i18n.t("mc.unable_to_open_fanart_4df1"),
                _i18n.t("mc.could_not_open_the_4037", e=e), parent=self)

    def _clear_all(self):
        """Clear all scan results from the table (Ctrl+L)."""
        if self._scanning: return
        if not self._results:
            messagebox.showinfo(_i18n.t("mc.clear_all_e77f"), _i18n.t("mc.nothing_to_clear_acb2")); return
        if not messagebox.askyesno(_i18n.t("mc.clear_all_e77f"),
                _i18n.t("mc.are_you_sure_you_55b8"),          ### MODIFIED v0.19.4 B104 ###
                icon="warning"):
            return
        self._results = []; self._item_map.clear(); self._inactive_rows = []   # v0.20.0 5j: Clear All clears them too
        self._clear_tree()                                     ### v0.19.4 B110h ###
        self._update_status_bar(0, 0, 0, _i18n.t("mc.cleared"), self.sort_var.get())   # v0.20.0 UI1e
        _sc.save_results_cache([])                             ### NEW v0.19.2 B42 — the old rows no longer return at the next start ###
        self._ignored_data = {}; _sc.save_ignored({})          ### NEW v0.19.2 B53 ###
        self._update_ignored_link()
        logger.info("User cleared scan results")
    def _do_extract(self, d):
        # FIX v0.16.0 — use cached FFmpeg status; never block on main thread  ### FIX v0.16.0 ###
        ff_ok = self._ffmpeg_status[0] if self._ffmpeg_status else False
        if not ff_ok:
            messagebox.showerror(_i18n.t("mc.ffmpeg_missing_b06f"),
                                 _i18n.t("mc.ffmpeg_not_available_set_0c88")); return
        if not d.get("video_path"):
            messagebox.showwarning(_i18n.t("mc.no_video_6fdd"),_i18n.t("mc.no_video_file_in_579e")); return
        timeout = SETTINGS.get("extract_timeout", 60)
        dlg = FrameExtractionDialog(self, d["video_path"], d["subfolder_path"],
                                    timeout_sec=timeout)
        self.wait_window(dlg)
        _used = getattr(dlg, "_used", None)                       # v0.20.0 AU16: the values the run used (a box
        if _used:                                                 # cleared by hand raised TclError here)
            SETTINGS["extract_timeout"], SETTINGS["backdrop_count"] = _used
        _save_settings(SETTINGS)
        self._schedule_refresh([d["subfolder_path"]], need_ffprobe=False)   ### MODIFIED v0.19.0 ###

    # ── Browse / Scan / Update / Cancel ───────────────────────────────────────
    ### NEW v0.10.0 — keyboard shortcut helpers ###
    # ── v0.20.1 TF4: keyboard helpers ──────────────────────────────────────────
    def _kb_typing(self):                                          ### NEW v0.20.1 TF4 ###
        """True when the focus is in a text box: Ctrl+C / Ctrl+Z / arrows keep their text meaning there."""
        try:
            w = self.focus_get()
        except (KeyError, tk.TclError):
            return False
        if not w:
            return False
        cls = w.winfo_class()
        if cls == "TCombobox":                                   # v0.20.1 B22: a read-only list takes no typing
            try:
                return str(w.cget("state")) != "readonly"
            except tk.TclError:
                return True
        return cls in ("Entry", "TEntry", "Text", "Spinbox", "TSpinbox")

    def _kb_rows(self):                                            ### NEW v0.20.1 TF4 ###
        """The selected movies for a table shortcut, or None (typing in a text box, or nothing selected: a status line)."""
        if self._kb_typing():
            return None
        rows = self._selected_rows()
        if not rows:
            flash_status(self, _i18n.t("sc.select_first"))
            return None
        return rows

    def _kb_on_rows(self, fn):                                     ### NEW v0.20.1 TF4 ###
        rows = self._kb_rows()
        return fn(rows) if rows else None

    def _kb_fix_issues_menu(self):                                 ### NEW v0.20.1 TF4 — Alt+X ###
        """The ⚠ Fix issues entries of the selected movie(s), as a menu at the row (keyboard: arrows, Enter, Esc)."""
        rows = self._kb_rows()
        if not rows:
            return None
        issues = ctx_fix_issues(rows, SETTINGS)
        if not issues:
            flash_status(self, _i18n.t("sc.no_issues"))
            return None
        menu = tk.Menu(self, tearoff=0, bg=C_SURFACE, fg=C_TEXT, activebackground=C_HOVER, activeforeground=C_TEXT)
        for key, lbl, rws in issues:
            fn, reason = self._ctx_fix_action(key, rws)
            text = f"{lbl} — {_n(len(rws), 'movie', ',')}" if len(rows) > 1 else lbl
            if fn:
                menu.add_command(label=text, command=lambda f=fn, r=rws: f(r[0], r, None))
            else:
                menu.add_command(label=text + (f"  ({reason})" if reason else ""), state="disabled")
        self._kb_menu = menu                                      # read by the self-test
        iid = self.tree.focus() or (self._selected_movie_iids() or [None])[0]
        bb = (self.tree.bbox(iid) if iid else None) or (0, 0, 0, 0)
        try:
            menu.tk_popup(self.tree.winfo_rootx() + 40, self.tree.winfo_rooty() + bb[1] + bb[3])
        finally:
            menu.grab_release()
        return menu

    def _kb_next_problem(self, step):                              ### NEW v0.20.1 TF4 — F3 / Shift+F3 ###
        """Select the next / previous movie (in the shown order) with a warning or an error; wraps around."""
        if self._kb_typing():
            return None
        ids = self._view_movie_iids()
        probs = [i for i in ids if (self._item_map.get(i) or {}).get("health_status") in ("warning", "error")]
        if not probs:
            flash_status(self, _i18n.t("sc.no_problems"))
            return None
        cur = self.tree.focus()
        pos = ids.index(cur) if cur in ids else (-1 if step > 0 else len(ids))
        seq = ids[pos + 1:] + ids[:pos + 1] if step > 0 else list(reversed(ids[:pos])) + list(reversed(ids[pos:]))
        nxt = next(i for i in seq if i in set(probs))
        wrapped = (ids.index(nxt) <= pos) if step > 0 else (ids.index(nxt) >= pos)
        self.tree.selection_set(nxt); self.tree.focus(nxt); self.tree.see(nxt)
        if wrapped and pos not in (-1, len(ids)):
            flash_status(self, _i18n.t("sc.wrapped"))
        return nxt

    def _kb_toggle_problems(self):                                 ### NEW v0.20.1 TF4 — Alt+O ###
        v = not self._problems_only_var.get()
        self._problems_only_var.set(v)
        self._set_health_filter("problems" if v else None)
        return v

    def _kb_toggle_group(self):                                    ### NEW v0.20.1 TF4 — Alt+G ###
        self._group_var.set(not self._group_var.get())
        self._toggle_grouping()
        return self._group_var.get()

    def _kb_undo_last(self):                                       ### NEW v0.20.1 TF4 — Ctrl+Z ###
        """Backup History / Undo with the newest run selected; restoring still asks first."""
        if self._kb_typing():
            return None
        dlg = BackupHistoryDialog(self)

        def _pick(tries=20):
            try:
                kids = dlg._tree.get_children()
            except tk.TclError:
                return
            if kids:
                dlg._tree.selection_set(kids[0]); dlg._tree.focus(kids[0]); dlg._tree.see(kids[0])
            elif tries:
                dlg.after(100, lambda: _pick(tries - 1))
        dlg.after(50, _pick)
        return dlg

    def _kb_copy(self, paths=False):                               ### NEW v0.20.1 TF4 — Ctrl+C / Ctrl+Shift+C ###
        """Copy the selected movies as "Title (Year)" (or their folder paths), one per line."""
        rows = self._kb_rows()
        if not rows:
            return None
        if paths:
            lines = [r.get("subfolder_path", "") for r in rows]
        else:
            lines = [(f"{r.get('movie_name') or r.get('subfolder', '')} ({r.get('movie_year')})"
                      if str(r.get("movie_year") or "").isdigit() else (r.get("movie_name") or r.get("subfolder", ""))) for r in rows]
        text = "\n".join(lines)
        self.clipboard_clear()
        self.clipboard_append(text)
        flash_status(self, _i18n.t("sc.copied_paths" if paths else "sc.copied", n=_n(len(rows), "movie")))
        return text

    def _open_editor_shortcut(self):
        """Ctrl+E — open NFO of selected row in editor, or Notepad."""
        sel = self._selected_movie_iids()                       ### v0.19.4 B110h ###
        if sel:
            d = self._item_map.get(self._focus_or_first(sel))
            if d and d.get("nfo_exists"):
                open_in_editor(d["nfo_path"]); return
            if d is not None:                                   ### NEW v0.19.4 B109c — no empty editor ###
                flash_status(self, _i18n.t("au.no_nfo_open", movie=d.get('movie_name') or d.get('subfolder')))
                return
        # fallback: open notepad++/notepad
        editor = SETTINGS.get("text_editor","").strip()
        npp    = _find_notepadpp()
        target = editor if (editor and os.path.isfile(editor)) else (npp or "")
        if target:
            try:
                subprocess.Popen([target],
                                 creationflags=getattr(subprocess,"CREATE_NO_WINDOW",0))
            except Exception: pass
        else:
            try: subprocess.Popen(["notepad.exe"])
            except Exception: pass

    def _focus_or_first(self, sel):                               ### NEW v0.20.0 AU22 (audit point 4) ###
        """The row Ctrl+O / Ctrl+E act on: the focused one (last clicked) when it is selected, else the first —
        with several selected they always took the first, whichever the user had clicked."""
        try:
            f = self.tree.focus()
        except tk.TclError:
            f = ""
        return f if f in sel else sel[0]

    def _open_folder_shortcut(self):
        """Ctrl+O — open folder of selected row."""
        sel = self._selected_movie_iids()                       ### v0.19.4 B110h ###
        if not sel: return
        d = self._item_map.get(self._focus_or_first(sel))
        if d: os_open(d["subfolder_path"])

    def _reval_selected_no_ffmpeg(self):
        """Ctrl+R — re-validate selected row without FFMPEG."""
        if self._busy():                                       ### NEW v0.19.4 B91 ###
            return
        sel = self._selected_movie_iids()                       ### v0.19.4 B110h ###
        if not sel: return
        if len(sel) > 1:                                       ### NEW v0.19.4 B102 — every selected movie, like the menu ###
            data = [self._item_map[i] for i in sel if i in self._item_map]
            if data:
                self._reval_multi_no_ffmpeg(list(sel), data)
            return
        iid = sel[0]; d = self._item_map.get(iid)
