    def _reval_rows_ffmpeg(self, rows):                             ### NEW v0.20.2 PA20 (audit) ###
        """Update (with FFprobe) for these rows only (an issue entry's movies — not the whole selection)."""
        if self._busy():
            return
        rows = [r for r in rows or () if r]
        if rows:
            self._reval_multi_ffmpeg([None] * len(rows), rows)

    def _reval_selected_ffmpeg(self):
        """Ctrl+Shift+R — re-validate selected row with FFMPEG."""
        if self._busy():                                       ### NEW v0.19.4 B91 ###
            return
        sel = self._selected_movie_iids()                       ### v0.19.4 B110h ###
        if not sel: return
        if len(sel) > 1:                                       ### NEW v0.19.4 B102 — every selected movie, like the menu ###
            data = [self._item_map[i] for i in sel if i in self._item_map]
            if data:
                self._reval_multi_ffmpeg(list(sel), data)
            return
        iid = sel[0]; d = self._item_map.get(iid)
        if d: self._reval_ffmpeg(iid, d)

    def _browse(self):                                         ### MODIFIED v0.19.0 — adds a library ###
        """Pick a root folder: it is added to the libraries (if new) and the
        table switches to it.  Rows of the other libraries are kept."""
        if self._scanning: return
        p = filedialog.askdirectory(title=_i18n.t("mc.add_a_library_root_ec74"))
        if p:
            libs = self._all_libraries()                        # v0.20.0 5j: keeps the inactive ones
            if _pkey(p) not in {_pkey(x) for x in libs}:
                libs.append(_norm_lib(p))
            res = self._set_libraries(libs, select="")          ### MODIFIED v0.19.2 B55 — stays on "All libraries" ###
            if res and (res[0] or res[1]):                      ### NEW v0.19.1 — offer a scan ###
                self._offer_library_scan(added=bool(res[0]))

    # ══════════════════════════════════════════════════════════════════════════
    # NEW v0.19.0 — multiple library folders
    # ══════════════════════════════════════════════════════════════════════════
    def _libraries(self):                                         ### MODIFIED v0.20.0 5j — the ACTIVE libraries ###
        """The active library roots: everything that scans, shows and counts uses these."""
        return [x for x in self._all_libraries() if library_active(x)]

    def _inactive_keys(self):                                     ### NEW v0.20.0 5j ###
        return {_pkey(x) for x in self._all_libraries() if not library_active(x)}

    def _row_inactive(self, row, keys=None):                      ### NEW v0.20.0 5j ###
        return _pkey(_lib_root_of(row)) in (keys if keys is not None else self._inactive_keys())

    def _apply_library_active(self):                              ### NEW v0.20.0 5j — Tk thread ###
        """Rows of an inactive library leave the results for _inactive_rows (still saved); active again → back.
        Returns the number of rows moved."""
        allr = list(self._results) + list(self._inactive_rows)
        keys = self._inactive_keys()
        off = [r for r in allr if self._row_inactive(r, keys)]
        on = [r for r in allr if not self._row_inactive(r, keys)]
        _was = {id(r) for r in self._inactive_rows}               # v0.20.0 AU10: by row, not by count (A off and B
        moved = sum(1 for r in off if id(r) not in _was) + sum(1 for r in on if id(r) in _was)   # on with as many rows: 0)
        if not moved:
            return 0
        self._inactive_rows = off
        self._results = on
        finalize_results(self._results)
        self._incremental_save(self._results)
        self._item_map.clear()
        self._clear_tree()
        self._refresh_table()
        self._update_library_widgets()
        self._update_stats()
        logger.info(f"Libraries: {len(off)} rows of inactive libraries set aside, {len(on)} shown")
        return moved

    def _all_libraries(self):                                     ### NEW v0.20.0 5j (was _libraries) ###
        """Configured library roots (library_folders); falls back to the single
        legacy folder (last_folder / self._folder)."""
        libs = [_norm_lib(x) for x in (SETTINGS.get("library_folders") or [])     ### MODIFIED v0.19.1 — normpath ###
                if isinstance(x, str) and x.strip()]
        if not libs:
            f = self._folder or SETTINGS.get("last_folder", "")
            libs = [_norm_lib(f)] if f else []
        return list(libs)

    def _library_filter(self):
        f = _norm_lib(SETTINGS.get("library_filter") or "")                       ### MODIFIED v0.19.1 ###
        return f if f and _pkey(f) in {_pkey(x) for x in self._libraries()} else ""

    def _scope_roots(self):
        """Roots covered by Full / Quick Scan: the selected library, or all."""
        f = self._library_filter()
        return [f] if f else self._libraries()

    def _root_offline(self, row):
        root = row.get("library_root") or os.path.dirname(row.get("subfolder_path") or "")
        return _pkey(root) in self._offline_roots if root else False

    def _collect_entries(self, roots):
        """Subfolders of every reachable root → (entries, online, offline).
        ### MODIFIED v0.19.2 B53 ### the videos lying directly in a root are
        noted in self._root_videos (same os.scandir, no extra disk access)."""
        entries, online, offline = [], [], []
        if not hasattr(self, "_root_videos"):
            self._root_videos = {}
        for root in roots:
            try:
                if not os.path.isdir(root):
                    raise OSError("not reachable")
                vids, found = [], []                            ### found: v0.19.4 B92 — this library's folders, added only when the listing completed ###
                for e in os.scandir(root):
                    try:
                        if e.is_dir() and not _is_collection_folder(e.path):   # v0.20.0 CF1
                            found.append(e)
                        elif os.path.splitext(e.name)[1].lower() in VIDEO_EXTENSIONS:
                            vids.append(e.name)
                    except OSError:
                        pass
                entries.extend(found)                           ### NEW v0.19.4 B92 — a library that drops mid-listing is offline, never half-listed ###
                self._root_videos[_norm_lib(root)] = vids
                online.append(root)
            except OSError:
                offline.append(root)
        entries.sort(key=lambda e: (e.name.lower(), e.path.lower()))
        return entries, online, offline

    def run_action(self, aid):                                     ### NEW v0.19.4 I13 ###
        """Run a registry action; the B91 check is the registry's needs_results."""
        a = ACTIONS[aid]
        if a.get("part") and a["part"] != getattr(self, "_part", "movies"):   ### NEW v0.19.4 I14 — the visible part only ###
            return None
        if a["needs_results"] and self._busy():
            return None
        return a["run"](self)

    def _fill_menu(self, menu, ids, short=False):                  ### NEW v0.19.4 I13 ###
        for aid in ids:
            if aid == "-":
                menu.add_separator()
            elif isinstance(aid, tuple):                        ### NEW v0.20.1 TM1 — a submenu ###
                _key, icon, title_key, head_key, sub_ids = aid
                sub = tk.Menu(menu, tearoff=0, bg=menu.cget("bg"), fg=menu.cget("fg"),
                              activebackground=menu.cget("activebackground"), activeforeground=menu.cget("activeforeground"))
                if head_key:
                    sub.add_command(label=_i18n.t(head_key), state="disabled")
                    sub.add_separator()
                self._fill_menu(sub, sub_ids, short=True)
                menu.add_cascade(label=f"{icon}  {_i18n.t(title_key)}", menu=sub)
                self._tools_submenus = getattr(self, "_tools_submenus", {})
                self._tools_submenus[_key] = sub                # read by the self-test
            else:
                menu.add_command(label=action_short_label(aid) if short else ACTIONS[aid]["label"],
                                 command=lambda a=aid: self.run_action(a))

    def _no_scan(self, title=None):                                ### NEW v0.19.4 I17 — one "Run a scan first." ###
        """True (and one message) when there are no rows yet."""
        if self._results:
            return False
        messagebox.showinfo(title or APP_NAME, NO_SCAN_TEXT, parent=self)
        return True

    def _busy_what(self):                                          ### NEW v0.20.0 AU10 — one wording, translated ###
        """'' when idle; else what runs ("a scan", "an image fix", "an action") in the interface language."""
        return (_i18n.t("au.what.scan") if self._scanning else _i18n.t("uf.an_image_fix_8548")
                if getattr(self, "_busy_fix", None) else _i18n.t("au.what.action") if getattr(self, "_bg_running", 0) else "")

    def _restart_now(self):                                        ### NEW v0.20.0 UI1a ###
        """Settings → User Interface → Restart now: refused while a scan, a batch or a Fix image runs; otherwise
        the normal close (settings, results and window memory saved, timers cancelled) and a new start
        (__main__ starts it once the window is gone). Returns True when the close was started."""
        what = self._busy_what()
        if what:
            messagebox.showinfo(APP_NAME, _i18n.t("ui.lang.restart_busy", what=what), parent=self)
            return False
        self._restart_requested = True
        self._on_app_close()
        try:
            alive = bool(self.winfo_exists())
        except tk.TclError:
            alive = False
        if alive:                                               # the close was declined
            self._restart_requested = False
            return False
        return True

    def _busy(self, title=None):                                   ### NEW v0.19.4 B91 ###
        """True (and one message) while a scan runs: every action that reads
        or writes the results calls it first."""
        if not self._scanning:
            return False
        messagebox.showinfo(title or APP_NAME, SCAN_BUSY_TEXT, parent=self)
        return True

    def _note_offline(self, offline, online=()):
        before = set(self._offline_roots)
        for r in online:
            self._offline_roots.discard(_pkey(r))
        for r in offline:
            self._offline_roots.add(_pkey(r))
        if self._offline_roots != before:                            ### NEW v0.20.2 FB3 — grey rows follow at once ###
            self._retag_offline()
        if offline:
            names = ", ".join(offline)
            logger.warning(f"Library offline (skipped, cached rows kept): {names}")
            try:
                self._sb_action.configure(text=_i18n.t("mc.offline_395e", names=names))
            except Exception:
                pass

    def _kept_rows(self, prior, online_roots):
        """Rows to keep when scanning *online_roots*: rows of every other
        configured library (out of scope or offline)."""
        on = {_pkey(r) for r in online_roots}
        libs = {_pkey(r) for r in self._libraries()}
        out = []
        for r in prior:
            k = _pkey(r.get("library_root") or os.path.dirname(r.get("subfolder_path") or ""))
            if k not in on and (not libs or k in libs):
                out.append(r)
        return out

    def _update_library_widgets(self):
        """### MODIFIED v0.19.2 B55 ### the folder box lists EVERY library (the
        filtered one marked ▶, "showing 1 of n (filter)"); the dropdown shows
        each library with its movie count; the tooltip adds the counts."""
        libs = self._libraries()
        f = self._library_filter()
        ov = library_overview(libs, f, self._results, [r for r in libs if _pkey(r) in self._offline_roots])
        self._lib_choices = dict(ov["choices"])
        self._lib_tip = ov["tooltip"]
        try:
            self._lib_combo.configure(values=[d for d, _p in ov["choices"]])
            self._lib_filter_var.set(next((d for d, p in ov["choices"] if _pkey(p or "") == _pkey(f or "")), ov["choices"][0][0])
                                     if f else ov["choices"][0][0])
        except Exception:
            pass
        self.folder_var.set(ov["box"])

    def _on_library_filter(self, _e=None):
        v = self._lib_filter_var.get()
        v = getattr(self, "_lib_choices", {}).get(v, v)          ### NEW v0.19.2 B55 — "Z:\\Kids (312)" → path ###
        SETTINGS["library_filter"] = "" if (not v or v.startswith(_ALL_LIBS)) else v
        _save_settings(SETTINGS)
        self._update_library_widgets()
        self._refresh_table()
        self._update_stats()

    def _set_libraries(self, libs, select=None):
        """Replace the library list (Libraries… dialog, Browse).  Rows of removed
        libraries are dropped; the others are kept; duplicates recomputed."""
        seen, clean = set(), []
        for x in libs:
            x = _norm_lib(x)                                    ### MODIFIED v0.19.1 — normpath ###
            if x and _pkey(x) not in seen:
                seen.add(_pkey(x)); clean.append(x)
        old = {_pkey(x) for x in self._all_libraries()}            # v0.20.0 5j
        removed = old - seen
        added = seen - old
        SETTINGS["library_folders"] = clean
        if select is not None:
            SETTINGS["library_filter"] = _norm_lib(select)
        elif added:                                             ### NEW v0.19.2 B55 — a new library: show all ###
            SETTINGS["library_filter"] = ""
        if SETTINGS.get("library_filter") and _pkey(SETTINGS["library_filter"]) not in seen:
            SETTINGS["library_filter"] = ""
        self._folder = clean[0] if clean else None
        SETTINGS["last_folder"] = self._folder or ""
        _save_settings(SETTINGS)
        if removed and self._results:
            self._results = [r for r in self._results
                             if _pkey(r.get("library_root") or os.path.dirname(r.get("subfolder_path") or "")) not in removed]
            finalize_results(self._results)
            self._incremental_save(self._results)
        if removed:                                             ### NEW v0.20.0 5j — a removed library's set-aside rows go too ###
            self._inactive_rows = [r for r in self._inactive_rows if _pkey(_lib_root_of(r)) not in removed]
        self._offline_roots -= removed
        self._update_library_widgets()
        self._item_map.clear()
        self._clear_tree()                                     ### v0.19.4 B110h ###
        self._refresh_table()
        self._update_stats()
        logger.info(f"Libraries: {clean} (filter: {SETTINGS.get('library_filter') or 'all'})")
        return added, removed                                   ### NEW v0.19.1 ###

    def _offer_library_scan(self, added=True):                    ### NEW v0.19.1 ###
        """Non-blocking prompt after the library list changed:
        Full Scan / Quick Scan / Not now.  Default: Quick Scan after an add
        (only what is new is scanned), Not now after a removal-only change."""
        try:
            if getattr(self, "_lib_prompt", None) is not None and self._lib_prompt.winfo_exists():
                self._lib_prompt.destroy()
        except Exception:
            pass
        dlg = tk.Toplevel(self)
        self._lib_prompt = dlg
        dlg.title(_i18n.t("mc.libraries_changed_8a81"))
        dlg.configure(bg=C_BG)
        dlg.transient(self)
        dlg.resizable(False, False)
        tk.Label(dlg, text=_i18n.t("mc.the_library_list_changed_38c0"),
                 font=("Helvetica", 11, "bold"), bg=C_BG, fg=C_TEXT).pack(padx=22, pady=(18, 4))
        tk.Label(dlg, text=(_i18n.t("mc.quick_scan_reads_only_0b3c")),
                 font=("Helvetica", 9), bg=C_BG, fg=C_SUBTEXT, justify="center").pack(padx=22, pady=(0, 12))
        bf = tk.Frame(dlg, bg=C_BG); bf.pack(pady=(0, 16))
        def _go(kind):
            try: dlg.destroy()
            except Exception: pass
            self._lib_prompt = None
            if self._scanning:
                return
            if kind == "full":
                self._scan()
            elif kind == "quick":
                self._update_scan()
        kw = dict(font=("Helvetica", 10, "bold"), relief="flat", cursor="hand2", padx=10, pady=4)
        b_full  = tk.Button(bf, text=_i18n.t("btn.full_scan"),  bg=C_OK, fg=C_BG, command=lambda: _go("full"), **kw)
        b_quick = tk.Button(bf, text=_i18n.t("btn.quick_scan"), bg="#89dceb", fg=C_BG, command=lambda: _go("quick"), **kw)
        b_none  = tk.Button(bf, text=_i18n.t("mc.not_now_3049"),    bg=C_SURFACE2, fg=C_TEXT, command=lambda: _go("none"), **kw)
        for b in (b_full, b_quick, b_none):
            b.pack(side="left", padx=5)
        default = b_quick if added else b_none
        dlg._buttons = {"full": b_full, "quick": b_quick, "none": b_none}
        dlg.default_kind = "quick" if added else "none"
        dlg.bind("<Return>", lambda e: default.invoke())
        dlg.bind("<Escape>", lambda e: _go("none"))
        dlg.protocol("WM_DELETE_WINDOW", lambda: _go("none"))
        dlg.update_idletasks()
        try:
            x = self.winfo_rootx() + (self.winfo_width() - dlg.winfo_width()) // 2
            y = self.winfo_rooty() + (self.winfo_height() - dlg.winfo_height()) // 2
            dlg.geometry(f"+{max(0, x)}+{max(0, y)}")
        except Exception:
            pass
        default.focus_set()
        return dlg

    def _check_offline_async(self):
        """Startup: test which library roots are reachable without blocking the
        UI (a dead network share can take many seconds to time out)."""
        libs = self._libraries()
        def _work():
            off = [r for r in libs if not os.path.isdir(r)]
            on  = [r for r in libs if r not in off]
            def _ui():
                self._note_offline(off, on)
                if off:
                    self._refresh_table()
            ui_post(_ui)
        threading.Thread(target=_work, daemon=True).start()

    def _scan_roots_or_warn(self):
        roots = self._scope_roots()
        if not roots:
            messagebox.showwarning(_i18n.t("mc.no_folder_fece"), _i18n.t("mc.no_library_folder_yet_6bba"), parent=self)
            return None
        if roots[0] and not self._folder:
            self._folder = self._libraries()[0]
        return roots

    def _drain_ui(self):                                           ### NEW v0.19.4 (D23 / B25) — the workers' calls ###
        if _UI_ROOT[0] is not self:
            return
        try:                                                      # the next round first: an item never stops the queue
            ### MODIFIED v0.19.5 B113 — 25 ms while items arrive; after 1 s with none, 100 ms (idle CPU was 2.5 % of a core, v0.19.3 0.12 %) ###
            _idle = getattr(self, "_ui_idle_rounds", 0)
            self._ui_drain_after = self.after(100 if _idle >= 40 else 25, self._drain_ui)
        except (RuntimeError, tk.TclError):
            return
        self._ui_idle_rounds = _idle + 1
        for _i in range(500):
            try:
                fn, args = _UI_QUEUE.get_nowait()
            except _queue_mod.Empty:
                break
            self._ui_idle_rounds = 0
            try:                                                  # each item its own Tk event: one that opens a window
                self.after(0, _ui_call, fn, args)                 # and waits for it does not hold up the others
            except (RuntimeError, tk.TclError):
                break

    def _bg_done(self):                                           ### NEW v0.19.4 P2 ###
        self._bg_running = max(0, getattr(self, "_bg_running", 0) - 1)

    # ── v0.20.1 SN3: the activity indicator (Tk thread). One ticker, running only while something is busy or a
    # ✓ / ! is still shown; the timings are visual only (they never feed _busy() or _refresh_idle()). ──
    _ACT_TICK_MS = 40
    _ACT_SPIN = "◐◓◑◒"

    def _act_wake(self):
        if getattr(self, "_act_after", None) is not None or APP_CLOSING.is_set():
            return
        try:
            self._act_after = self.after(15, self._act_tick)
        except (tk.TclError, RuntimeError, AttributeError):
            self._act_after = None

    def _act_warm(self, i):
        """Draw the 24 ring positions and load the fonts ahead (one step per 60 ms): the first frame has no stall."""
        if APP_CLOSING.is_set() or not _PIL_AVAILABLE:
            return
        try:
            base = _ACT_CACHE.get(("warm",))
            if base is None:
                base = _ACT_CACHE[("warm",)] = _PILImage.new("RGB", _MoviePanel.POSTER, (40, 40, 60))
            if i < 24:
                act_poster_frame(base, "busy", i * 15 - 90, ["…"] if i == 0 else [], scale=_UI_SCALE)
            else:
                act_poster_frame(base, "done", 0, [], scale=_UI_SCALE)
                act_poster_frame(base, "error", 0, [], scale=_UI_SCALE)
                return
            self.after(60, lambda: self._act_warm(i + 1))
        except (tk.TclError, RuntimeError):
            pass
        except Exception as ex:
            logger.debug(f"activity warm-up: {ex}")

    def _act_now(self):
        """(live entries, movie folders queued / being re-read, a re-read on its way with no folder yet)."""
        live = _ACT.live()
        rf = set(getattr(self, "_rf_pending", None) or {}) | set(getattr(self, "_rf_batch_keys", None) or ())
        return live, rf, bool(getattr(self, "_rf_posted", 0))

    @staticmethod
    def _act_involves(item, e):
        """True when entry *e* (a job / read) touches the panel's *item* ("movie"|"coll", folders, collection key)."""
        kind, pks, key = item
        if pks & e.get("paths", set()):
            return True
        return kind == "coll" and bool(key) and (key in e.get("keys", set()) or "*" in e.get("keys", set()))

    def _act_tick(self):
        self._act_after = None
        if APP_CLOSING.is_set():
            return
        try:
            if not self.winfo_exists():
                return
        except tk.TclError:
            return
        T = _i18n.t
        now = time.monotonic()
        self._act_frame = (self._act_frame + 1) % 10_000
        live, rf, posted = self._act_now()
        # the jobs that ended since the last tick count as busy now (a quick one can start and end in between)
        fresh = _ACT.ended_after(getattr(self, "_act_eseq", 0))
        if fresh:
            self._act_eseq = max(e["eseq"] for e in fresh)
        seen = live + fresh
        # ── the whole app: bar + status line ──
        g = self._act_g
        busy = bool(seen or rf or posted)
        if busy and g.get("since") is None and g.get("until") is None:
            g.pop("job", None); g.pop("text", None)                # a new span: no text of the last one
        jobs = []
        if busy:
            jobs = [e for e in seen if "*" not in e["keys"]]
            cur = max(jobs or seen, key=lambda e: e["t"]) if seen else None
            g["text"] = cur["text"] if cur else T("sn3.refreshing", movies=_n(max(1, len(rf)), "movie"))
            if jobs:
                g["job"] = max(jobs, key=lambda e: e["t"])["text"]
        vis = act_visual(busy, now, g, job=bool(jobs))
        bad = [e for e in fresh if e.get("error")]
        if bad:                                                    # after act_visual: a new span clears "err"
            g["err"] = (bad[-1]["text"], bad[-1]["error"])
        self._act_show_global(vis, g)
        # ── the panel: the shown movie / collection ──
        vis_p = "idle"
        panel = getattr(self, "_movie_panel", None)
        item = None
        try:
            item = panel.act_item() if panel is not None and self._panel_shown() else None
        except Exception:
            item = None
        # the same movies = the same item (a collection keeps its state through a rename of its key)
        if (item[:2] if item else None) != (self._act_p_item[:2] if self._act_p_item else None):
            self._act_p = {}
        self._act_p_item = item
        if item is not None:
            p = self._act_p
            hit = [e for e in seen if self._act_involves(item, e)]
            rf_hit = bool(item[1] & rf)
            pbusy = bool(hit or rf_hit)
            if pbusy and p.get("since") is None and p.get("until") is None:
                for _k in ("job", "text", "net"):
                    p.pop(_k, None)
            jobs = []
            if pbusy:
                jobs = [e for e in hit if "*" not in e["keys"]]
                if jobs:
                    p["job"] = max(jobs, key=lambda e: e["t"])["text"]
                p["text"] = (max(jobs or hit, key=lambda e: e["t"])["text"] if hit else T("sn3.refresh_short"))
                paths = set().union(*[e["paths"] for e in hit]) if hit else set()
                p["net"] = any(is_network_path(x) for x in (list(paths) or list(item[1]))[:5])
            vis_p = act_visual(pbusy, now, p, job=bool(jobs))
            bad = [e for e in fresh if e.get("error") and self._act_involves(item, e)]
            if bad:
                p["err"] = bad[-1]["error"]
            if vis_p == "busy":
                lines = [p.get("text", "") + "…", T("sn3.on_nas") if p.get("net") else T("sn3.on_disk")]
            elif vis_p == "done":
                lines = [T("sn3.done"), p.get("job") or p.get("text", "")]
            elif vis_p == "error":
                lines = [T("sn3.failed"), str(p.get("err") or "")[:80]]
            else:
                lines = []
            try:
                panel.act_show(vis_p, lines, (self._act_frame * 15) % 360 - 90)
            except Exception as ex:
                logger.debug(f"activity overlay: {ex}")
        elif panel is not None:
            try:
                panel.act_show("idle", [], 0)
            except Exception:
                pass
        if vis != "idle" or vis_p != "idle":
            try:
                self._act_after = self.after(self._ACT_TICK_MS, self._act_tick)
            except (tk.TclError, RuntimeError):
                self._act_after = None

    def _act_show_global(self, vis, g):
        """The thin bar above the table (not during a scan: the scan has its own bar) and the status-bar line."""
        T = _i18n.t
        lbl = getattr(self, "_sb_activity", None)
        if lbl is not None:
            if vis == "busy":
                txt = f"{self._ACT_SPIN[(self._act_frame // 4) % 4]}  {g.get('text', '')}…"
                fg = C_ACCENT
            elif vis == "done":
                txt, fg = "✓  " + T("sn3.st_done", text=g.get("job") or g.get("text", "")), C_OK
            elif vis == "error":
                _t, _e = g.get("err") or ("", "")
                txt, fg = "!  " + T("sn3.st_failed", text=_t, err=str(_e)[:120]), C_ERR
            else:
                txt, fg = "", C_ACCENT
            try:
                if lbl.cget("text") != txt or str(lbl.cget("fg")) != fg:
                    lbl.configure(text=txt, fg=fg)
            except tk.TclError:
                pass
        bar = getattr(self, "_act_bar", None)
        if bar is None:
            return
        try:
            if vis in ("idle", "wait") or self._scanning:
                if bar.winfo_ismapped():
                    bar.place_forget()
                return
            y, x, w = self._act_bar_geometry()
            bar.place(x=x, y=y, width=w, height=3)
            bar.delete("all")
            bar.create_rectangle(0, 0, w, 3, fill=C_SURFACE, width=0)
            if vis == "busy":
                seg = max(60, int(w * 0.28))
                pos = (self._act_frame * self._ACT_TICK_MS / 1000.0 * 0.55) % 1.0
                sx = int(pos * (w + seg)) - seg
                imgs = self.__dict__.setdefault("_act_bar_imgs", {})   # Tk images live with the window
                key = ("bar", seg)
                ph = imgs.get(key)
                if ph is None and _PIL_AVAILABLE:
                    from PIL import Image
                    acc = tuple(int(C_ACCENT.lstrip("#")[i:i + 2], 16) for i in (0, 2, 4))
                    im = Image.new("RGBA", (seg, 3))
                    for xx in range(seg):
                        a = int(255 * math.sin(math.pi * xx / (seg - 1)) ** 0.8)
                        for yy in range(3):
                            im.putpixel((xx, yy), acc + (a,))
                    ph = imgs[key] = _PILImageTk.PhotoImage(im)
                if ph is not None:
                    bar.create_image(sx, 0, image=ph, anchor="nw")
                else:
                    bar.create_rectangle(sx, 0, sx + seg, 3, fill=C_ACCENT, width=0)
            else:
                bar.create_rectangle(0, 0, w, 3, fill=C_OK if vis == "done" else C_ERR, width=0)
        except tk.TclError:
            pass

    def _act_bar_geometry(self):
        """(y, x, width) of the 3 px bar: centred between the filter row and what follows the progress frame (the user,
        2026-11-20: "distance above and below shall be the same" — measured to the TEXT of the counters line, not to
        its label's box: the box has a border, padding and the font's leading above the letters)."""
        pf = self.progress_frame
        top = self._filter_row.winfo_y() + self._filter_row.winfo_height()
        below = None
        try:
            sl = pf.master.pack_slaves()
            i = sl.index(pf)
            for w in sl[i + 1:]:
                if w.winfo_ismapped():
                    below = w.winfo_y()
                    if w.winfo_class() == "Label":               # where its letters start (once per label and font)
                        ck = (str(w), str(w.cget("font")), str(w.cget("bd")), str(w.cget("pady")))
                        if getattr(self, "_act_inset_key", None) != ck:
                            asc = int(tk_font.Font(font=w.cget("font")).metrics("ascent"))
                            self._act_inset = (int(w.winfo_fpixels(w.cget("bd"))) + int(w.winfo_fpixels(w.cget("pady")))
                                               + max(0, asc - int(round(asc * 0.75))))
                            self._act_inset_key = ck
                        below += self._act_inset
                    break
        except (ValueError, tk.TclError):
            below = None
        if below is None or below <= top:
            below = pf.winfo_y() + pf.winfo_height() + B70_GAP - 1
        return top + max(0, (below - top - 3) // 2), pf.winfo_x(), max(40, pf.winfo_width())

    def _bg_wait_note(self, title):                               ### NEW v0.19.4 P2 (E15) ###
        """True (and a message) while a long action still runs: a scan would replace the rows it updates."""
        if getattr(self, "_bg_running", 0):
            messagebox.showinfo(title, _i18n.t("mc.an_action_is_still_0936"), parent=self)
            return True
        return False

    def _restore_defer(self, fn):                                 ### NEW v0.20.0 AU9 (pre-build audit) ###
        """True while the last results are still loading (start-up worker): *fn* (the scan asked for) runs right
        after they are in.  A scan started in those seconds used to throw the restored rows away — the other and
        offline libraries' rows and the set-aside ones never loaded, and the scan then saved the cache without them."""
        if getattr(self, "_restore_pending", False) and time.time() - getattr(self, "_restore_t0", 0) > 180:
            self._restore_pending = False                        # the restore never reported back: never block scans
        if getattr(self, "_restore_pending", False):
            self._after_restore = fn
            try:
                self.stats_var.set(_i18n.t("mc.st.loading_last"))
            except Exception:
                pass
            return True
        return False

    def _update_scan(self):
        if self._scanning: return
        if self._restore_defer(self._update_scan): return         # v0.20.0 AU9
        if self._bg_wait_note("Quick Scan"): return               # P2
        roots = self._scan_roots_or_warn()                     ### MODIFIED v0.19.0 — libraries ###
        if not roots: return
        self._scan_label = "Quick Scan"                        ### NEW v0.17.0 ###
        self._start_quick_scan(roots)                          ### FIX v0.17.0-bugB ###

    def _start_quick_scan(self, folder):                       ### REWRITTEN v0.18.4 ###
        """Quick Scan: re-scan only subfolders that were added, removed or whose
        files changed since the last scan (scan_mtime per row).  Changed movies
        are probed with FFprobe when the FFprobe box is ticked (v0.18.4); the
        change detection and the rescans run in parallel."""
        roots = list(folder) if isinstance(folder, (list, tuple)) else [folder]   ### NEW v0.19.0 ###
        ### MODIFIED v0.19.4 B100 — the library listing runs in a worker (a slow share froze the window) ###
        self._scanning = True; self._cancel_scan = False
        self.scan_btn.configure(state="disabled")
        self.update_btn.configure(state="disabled")
        self.cancel_btn.pack(side="left", padx=(6, 0))
        self.pbar_canvas.pack(side="left", fill="x", expand=True)
        self.pbar_label.pack(side="left", padx=(8, 0))
        self._draw_scan_progress(0, _i18n.t("uf.quick_scan_listing_the_71dd"))

        _unread = [(r.get("subfolder_path"), r.get("nfo_path") if r.get("nfo_exists") else None)
                   for r in self._results if r.get("coll_unread")]     ### NEW v0.19.4 B110a ###

        def _list():
            try:
                res = self._collect_entries(roots)
            except Exception as ex:
                logger.error(f"Quick Scan: listing failed: {ex}")
                res = ([], [], list(roots))
            coll = {}                                             ### NEW v0.19.4 B110a — old cached rows: read their <set> ###
            for sp, nfo in _unread:
                try:
                    coll[sp] = _cr.read_set(_read_text(nfo)) if nfo else None
                except Exception:
                    coll[sp] = None
            self._coll_read_pending = coll                        # plain data; the Tk thread applies it
            try:
                ui_post(lambda: self._quick_scan_listed(folder, *res))
            except (RuntimeError, tk.TclError):
                pass
        threading.Thread(target=_list, name="quick-scan-listing", daemon=True).start()

    def _scan_found_nothing(self, online, offline):               ### NEW v0.19.5 AS-A24, SH-E30 ###
        """No sub-folder listed. A library that was read and is empty loses its rows, as Help says; an offline library keeps them."""
        keys = {_pkey(p) for p in online}
        if keys:
            kept = [r for r in self._results if _pkey(r.get("library_root") or "") not in keys]
            if len(kept) != len(self._results):
                self._results = kept
                self._refresh_table()
                self._update_stats()
                self._incremental_save(self._results)
        if offline and not online:
            messagebox.showwarning(_i18n.t("mc.library_offline_74a2"), _i18n.t("mc.not_reachable_cached_rows_a3fd", join="\n".join(offline)), parent=self)
        elif offline:
            messagebox.showinfo(_i18n.t("mc.empty_ce2c"), _i18n.t("mc.no_subfolders_found_not_5ce4", join="\n".join(offline)), parent=self)
        else:
            messagebox.showinfo(_i18n.t("mc.empty_ce2c"), _i18n.t("mc.no_subfolders_found_0410"), parent=self)

    def _scan_ui_idle(self):                                      ### NEW v0.19.4 B100 ###
        """The scan buttons and the progress bar back to idle (no rows touched)."""
        self.scan_btn.configure(state="normal")
        self.update_btn.configure(state="normal")
        self.cancel_btn.pack_forget()
        self.pbar_canvas.pack_forget()
        self.pbar_label.pack_forget()
        self.progress_frame.configure(height=1)

    def _quick_scan_listed(self, folder, entries, online, offline):   ### NEW v0.19.4 B100 — Tk thread ###
        """Quick Scan, after the worker listed the libraries."""
        coll, self._coll_read_pending = getattr(self, "_coll_read_pending", None) or {}, None   ### NEW v0.19.4 B110a ###
        if coll:
            for r in self._results:
                if r.get("coll_unread") and r.get("subfolder_path") in coll:
                    r["coll_nfo"] = coll[r["subfolder_path"]]
                    r.pop("coll_unread", None)
            logger.info(f"Collections: read the <set> of {len(coll)} movie(s) cached before v0.19.4")
        self._note_offline(offline, online)
        if self._cancel_scan or not entries:
            self._scanning = False
            self._scan_ui_idle()
            if not self._cancel_scan:
                self._scan_found_nothing(online, offline)        ### MODIFIED v0.19.5 AS-A24, SH-E30 ###
            return

        prior_by_path = {_pkey(r["subfolder_path"]): r for r in self._results}
        prior_ignored = {_pkey(i["path"]): i for i in (getattr(self, "_ignored_data", None) or {}).get("items", [])}   ### NEW v0.19.2 B53 ###
        prior_for_ff  = list(self._results)
        kept_rows     = self._kept_rows(prior_for_ff, online)          ### NEW v0.19.0 ###
        _online_keys  = {_pkey(r) for r in online}
        probe = bool(self._use_ffprobe.get()) and bool(FFPROBE_PATH)
        n_workers = self._scan_workers()
        n_probe   = self._ffprobe_workers()

        self._scanning = True; self._cancel_scan = False
        self.scan_btn.configure(state="disabled")
        self.update_btn.configure(state="disabled")
        self.cancel_btn.pack(side="left", padx=(6, 0))
        self.pbar_canvas.pack(side="left", fill="x", expand=True)
        self.pbar_label.pack(side="left", padx=(8, 0))
        self._draw_scan_progress(0, _i18n.t("uf.quick_scan_detecting_changes_7f2b"))
        logger.info(f"Quick Scan started: {folder} (ffprobe={'on' if probe else 'off'})")

        def worker():
            _lst_a = {}                                          # E24: Phase A's listing of changed folders
            clear_read_caches()
            # ── Phase A: detect new / modified subfolders (parallel listings) ──
            changed = []; lock = threading.Lock(); n_no_mtime = [0]; n_sig_new = [0]   ### n_sig_new v0.19.4 B85 ###
            still_ignored, ignored_new = [], []                 ### NEW v0.19.2 B53 ###
            ### NEW v0.19.6 TR5 — a folder of folders is walked into; a movie of the last scan is not listed again ###
            _known5, _nested5 = set(prior_by_path), []
            _unread_under = []                                  # v0.20.2 PA1
            def _list5(e):                                      # v0.20.2 PB11: listed in parallel (was one by one)
                if self._cancel_scan:
                    return e, None, None
                _l = _FolderListing(e.path)
                return e, _l, classify_listing(_l)
            with ThreadPoolExecutor(max(1, n_workers)) as _ex5:
                _pre5 = list(_ex5.map(_list5, [e for e in entries if _pkey(e.path) not in _known5]))
            for _en, _l5, _c5 in _pre5:
                if self._cancel_scan or _l5 is None:
                    continue
                if _c5[0] == "unreadable":                      ### NEW v0.20.2 PA1 — a folder of folders keeps its movies ###
                    _u1 = rows_under(prior_by_path, _en.path)
                    if _u1:
                        logger.warning(f"Quick Scan: {_en.path} could not be read — the {len(_u1)} movie(s) inside kept ({_c5[1]})")
                        _unread_under.extend(keep_unreadable_row(r, _c5[1]) for r in _u1)
                if _c5[0] == "container":
                    _e5, _i5, _ls5, _k5 = walk_container(_en.path, library_of(_en.path), 1, _known5, lambda: self._cancel_scan)
                    _nested5 += _e5; ignored_new += _i5; _lst_a.update(_ls5)
                    entries.remove(_en)
                else:
                    _lst_a[_en.path] = _l5
            if _nested5:
                entries.extend(_nested5)
                entries.sort(key=lambda e: (e.name.lower(), e.path.lower()))
            def _check(entry):
                if self._cancel_scan:
                    return
                prior = prior_by_path.get(_pkey(entry.path))
                if prior is None:
                    ig = prior_ignored.get(_pkey(entry.path))     ### NEW v0.19.2 B53 — ignored and unchanged ###
                    if ig is not None:
                        try:
                            _igm = ig.get("mtime")               # 0.0 = only sub-folders: a valid time
                            if _igm is not None and abs(_folder_mtime(entry.path) - float(_igm)) <= 0.5:
                                with lock: still_ignored.append(ig)
                                return
                        except (TypeError, ValueError):
                            pass
                    with lock: changed.append(entry)            # new folder
                    return
                if row_needs_reread(prior):                     ### NEW v0.20.0 XB1 — scanned in another health mode ###
                    with lock: changed.append(entry)
                    return
                if "folder_kind" not in prior and not (prior.get("nfo_exists") or prior.get("xml_exists")) \
                        and (prior.get("video_count", 0) == 0 or prior.get("video_count", 0) >= 3):
                    with lock: changed.append(entry)            # v0.19.1 row that may not be a movie (B53): once
                    return
                recorded = prior.get("scan_mtime")
                if recorded is None:
                    with lock: n_no_mtime[0] += 1; changed.append(entry)
                    return
                ### MODIFIED v0.19.4 B85 — the folder signature decides; a row from before
                ### v0.19.4 has none: D3 = compare the mtime as before and, when unchanged,
                ### store the signature without rescanning ###
                _lst = _FolderListing(entry.path)
                _sig = folder_signature(entry.path, _lst)
                if prior.get("scan_sig"):
                    if _sig != prior["scan_sig"]:
                        with lock: changed.append(entry); _lst_a[entry.path] = _lst   # modified (E24: listing kept)
                    return
                try:
                    if abs(_lst.newest_mtime() - float(recorded)) > 0.5:
                        with lock: changed.append(entry)        # modified
                    else:
                        with lock: prior["scan_sig"] = _sig; n_sig_new[0] += 1
                except (TypeError, ValueError):
                    with lock: changed.append(entry)
            self._run_parallel(entries, _check, n_workers)
            if self._cancel_scan:
                ui_post(lambda: self._scan_done(prior_for_ff)); return
            order = {e.path: i for i, e in enumerate(entries)}
            changed.sort(key=lambda e: order[e.path])

            current_paths = {_pkey(e.path) for e in entries}
            n_changed = len(changed); n_total = len(entries)
            n_removed = sum(1 for p, rr in prior_by_path.items() if p not in current_paths      ### MODIFIED v0.19.0 ###
                            and _pkey(rr.get("library_root") or os.path.dirname(rr["subfolder_path"])) in _online_keys)
            logger.info(f"Quick Scan: {n_changed}/{n_total} changed, {n_removed} removed"
                        + (f", {n_no_mtime[0]} without recorded scan time" if n_no_mtime[0] else ""))
            if n_sig_new[0]:                                     ### NEW v0.19.4 B85 (D3) ###
                logger.info(f"Quick Scan: folder signatures stored for {n_sig_new[0]} movie(s) (first run after the update)")
            if n_changed == 0 and n_removed == 0:
                ui_post(lambda: (
                    self._scan_done(prior_for_ff),
                    messagebox.showinfo("Quick Scan",
                                        _i18n.t("mc.no_changes_detected_library_c1ec"))))
                return

            # ── Phase B: rescan changed/new subfolders (parallel) ───────────
            _KEEP = ("video_width", "video_height", "video_quality",
                     "subs_internal", "audio_tracks", "ffprobe_ran", "ffprobe_failed")   # ffprobe_failed: v0.19.4 B87
            rescanned = {}
            def _rescan(entry):
                _lst = _lst_a.pop(entry.path, None) or _FolderListing(entry.path)   ### B53; v0.19.4 (E24) — Phase A's listing ###
                kind, reason, detail = classify_listing(_lst)
                _rd88 = prior_by_path.get(_pkey(entry.path))
                if kind == "unreadable" and _rd88 is not None:   ### NEW v0.19.4 B88 — keep the previous row, flagged ###
                    logger.warning(f"Quick Scan: {entry.path} could not be read — previous row kept ({reason})")
                    with lock:
                        rescanned[entry.path] = keep_unreadable_row(_rd88, reason)
                    return
                if kind in _fc.IGNORED_KINDS:
                    with lock:
                        ignored_new.append(ignored_item(entry.path, kind, reason, detail, _lst))
                    return
                r  = scan_one_subfolder(entry.path, entry.name, use_ffprobe=probe, listing=_lst)   # E24
                r["folder_kind"] = kind
                rd = prior_by_path.get(_pkey(entry.path))
                if rd and not probe and rd.get("ffprobe_ran") and ffprobe_reusable(rd, r):   ### MODIFIED v0.19.4 B86 — the same video only ###
                    # keep FFprobe-derived data from the prior scan; external
                    # subtitles are always re-read                ### v0.18.4 ###
                    for key in _KEEP:
                        if rd.get(key) is not None:
                            r[key] = rd[key]
                    r["subs_summary"] = _subs_summary(r["subs_internal"], r["subs_external"], r.get("video_path"), r.get("subs_hard"))
                    _refill_audio_row(r)                        ### NEW v0.19.1 B16 ###
                    if r.get("video_path") and lang_in_stored_streams(r, SETTINGS.get("lang_ok_code", "PT")):   # MODIFIED v0.19.5 AS-A1
                        r["lang_ok"] = "Y"
                r["duplicate_of"] = list(rd.get("duplicate_of") or []) if rd else []
                carry_id_check(r, rd)                                   ### NEW v0.19.4 B90 ###
                _apply_health(r)
                with lock:
                    rescanned[entry.path] = r
            label = f"Quick Scan — {n_changed} changed, {n_removed} removed" + (" (FFprobe)" if probe else "")
            self._run_phase(changed, [None] * len(changed), lambda e, _r: _rescan(e),
                            label, 0, 100, n_probe if probe else n_workers, None)

            # ── Phase C: rebuild full results list in folder order ──────────
            new_results = []
            _ign = {_pkey(i["path"]) for i in ignored_new}      ### NEW v0.19.2 B53 — a row whose folder is now ignored goes ###
            for entry in entries:
                if entry.path in rescanned:
                    new_results.append(rescanned[entry.path])
                elif _pkey(entry.path) in prior_by_path and _pkey(entry.path) not in _ign:
                    new_results.append(prior_by_path[_pkey(entry.path)])
            _have1 = {_pkey(r.get("subfolder_path") or "") for r in new_results}   ### NEW v0.20.2 PA1 ###
            new_results.extend(r for r in _unread_under if _pkey(r.get("subfolder_path") or "") not in _have1)
            new_results.extend(kept_rows)                       ### NEW v0.19.0 — other / offline libraries ###
            _ffprobe_cache_flush([r.get("video_path") for r in new_results])   ### NEW v0.19.1 I5; known v0.19.4 B93 ###
            self._scan_ignored = {"items": still_ignored + ignored_new, "online": list(online), "new": ignored_new}
            ui_post(lambda r=new_results: self._scan_done(r))

        def _worker_guarded():
            try:
                worker()
            except Exception as _exc:
                logger.error(f"Scan worker crashed: {_exc}", exc_info=True)
                ### MODIFIED v0.19.4 P2 (E4) — the previous rows stay (was: an empty result list) ###
                ui_post(lambda e=_exc: (self._scan_done(prior_for_ff),
                                       messagebox.showerror("Quick Scan", _i18n.t("mc.quick_scan_stopped_the_b6fa", e=e), parent=self)))

        threading.Thread(target=_worker_guarded, daemon=True).start()

    # ── Parallel helpers (v0.18.4) ─────────────────────────────────────────────
    def _scan_workers(self):
        try:
            return max(1, min(16, int(SETTINGS.get("scan_workers", 6) or 6)))
        except (TypeError, ValueError):
            return 6

    def _ffprobe_workers(self):
        try:
            return max(1, min(8, int(SETTINGS.get("ffprobe_workers", 2) or 2)))
        except (TypeError, ValueError):
            return 2

    def _run_parallel(self, items, fn, workers):
        """Run fn(item) for every item on a thread pool; exceptions are logged."""
        def _task(item):
            if self._cancel_scan:
                return
            try:
                fn(item)
            except Exception as ex:
                logger.warning(f"parallel task failed for {getattr(item, 'name', item)}: {ex}")
        with ThreadPoolExecutor(max_workers=max(1, workers)) as ex:
            list(ex.map(_task, items))

    def _run_phase(self, entries, rows, fn, label, pct_lo, pct_hi, workers, save_rows):
        """Run fn(entry, row) for every (entry, row) pair on a thread pool, with
        throttled progress updates and ETA.  Stops submitting work after Cancel."""
        total = len(entries); done = [0]; lock = threading.Lock()
        t_start = time.time(); last_post = [0.0]
        def _eta(n):
            if n == 0: return ""
            rem = (time.time() - t_start) / n * (total - n)
            return f"{int(rem // 60)}m {int(rem % 60)}s remaining" if rem > 60 else f"{int(rem)}s remaining"
        def _task(pair):
            entry, row = pair
            if self._cancel_scan:
                return
            try:
                fn(entry, row)
            except Exception as ex:
                logger.warning(f"{label} skipped '{entry.name}': {ex}")
            with lock:
                done[0] += 1; n = done[0]
                now = time.time()
                post = (now - last_post[0] > 0.1) or n == total
                if post: last_post[0] = now
            if post:
                pct = pct_lo + int(n / max(total, 1) * (pct_hi - pct_lo))
                ui_post(lambda p=pct, e=_eta(n): self._draw_scan_progress(p, f"{label} {p}%  {e}"))
            if save_rows is not None and n % 25 == 0:
                ui_post(lambda r=list(save_rows): self._incremental_save(r, throttle=True))
        with ThreadPoolExecutor(max_workers=max(1, workers)) as ex:
            list(ex.map(_task, zip(entries, rows)))

    ### NEW v0.11.1 — scan variants used by SettingsDialog._offer_rescan ###
    def _update_scan_no_ff(self):
        """Update scan without FFprobe — called after settings change.
        Preserves existing FFprobe data (video quality, subs, lang).
        """
        if self._scanning: return
        if self._restore_defer(self._update_scan_no_ff): return   # v0.20.0 AU9
        if self._bg_wait_note("Update Scan"): return              # v0.20.0 AU9: as Full / Quick Scan (P2 E15)
        roots = self._scan_roots_or_warn()                     ### MODIFIED v0.19.0 ###
        if not roots: return
        self._scan_label = "Update Scan"
        self._start_scan(roots, use_ff=False)                  ### FIXED v0.18.3 ###

    def _update_scan_with_ff(self):
        """Update scan with FFprobe — called after settings change.
        Refreshes all data including video resolution, audio streams, subs.
        """
        if self._scanning: return
        if self._restore_defer(self._update_scan_with_ff): return   # v0.20.0 AU9
        if self._bg_wait_note("Update Scan"): return              # v0.20.0 AU9
        roots = self._scan_roots_or_warn()                     ### MODIFIED v0.19.0 ###
        if not roots: return
        self._scan_label = "Update Scan"
        self._start_scan(roots, use_ff=True)                   ### FIXED v0.18.3 ###

    def _scan(self):
        if self._scanning: return
        if self._restore_defer(self._scan): return                # v0.20.0 AU9
        if self._bg_wait_note("Full Scan"): return                # P2
        roots = self._scan_roots_or_warn()                     ### MODIFIED v0.19.0 — libraries ###
        if not roots: return
        self._scan_label = "Full Scan"                         ### NEW v0.17.0 ###
        self._start_scan(roots, use_ff=self._use_ffprobe.get())

    def _cancel(self):
        self._cancel_scan = True
        self.pbar_label.configure(text=_i18n.t("mc.cancelling_9bdc"))

    def _draw_scan_progress(self, pct, text):
        c = self.pbar_canvas; c.delete("all")
        w = c.winfo_width() or 400; h = 22
        c.create_rectangle(0, 0, w, h, fill=C_SURFACE, outline="")
        fw = int(w * pct / 100)
        if fw > 0:
            c.create_rectangle(0, 0, fw, h, fill="#2d6e3f", outline="")
        c.create_text(w//2, h//2, text=f"{pct}%",
                      fill=C_TEXT, font=("Helvetica",10,"bold"))
        self.pbar_label.configure(text=text)

