    def _download_upscaler(self, parent=None, done=None):      ### NEW v0.19.2 F4b ###
        """Ask, download the pinned Real-ESRGAN zip (progress, cancel), check
        it, unpack it, test it once; the result is kept in image_fix_prefs."""
        info = upscaler_download_info()
        par = parent or self
        if not info:
            messagebox.showinfo(_i18n.t("mc.ai_upscaler_643b"), _i18n.t("mc.the_ai_upscaler_is_fa66"), parent=par)
            return None
        if not messagebox.askyesno(
                _i18n.t("mc.ai_upscaler_643b"),
                _i18n.t("mc.download_mb_checked_against_a89a", release=info['release'], url=info['url'], v=format(info['size'] / 1e6, '.0f'), upscaler_dir=upscaler_dir()), parent=par):
            return None
        prog = _BatchProgressDialog(par, _i18n.t("uf.downloading_the_ai_upscaler_3426"), total=100)

        def work():
            try:
                download_upscaler(progress=lambda n, t: prog.advance(min(99, int(n * 100 / max(t, 1)))),
                                  cancel=lambda: prog.cancelled)
                ok, why = test_upscaler()
                err = None
            except Exception as ex:
                ok, why, err = False, "", str(ex)
                logger.warning(f"AI upscaler download failed: {ex}")
            prog.close()
            ui_post(lambda: self._upscaler_result(ok, why, err, par, done))
        threading.Thread(target=work, daemon=True).start()
        return prog

    def _test_upscaler_again(self, parent=None, done=None):    ### NEW v0.19.2 F4b ###
        par = parent or self

        def work():
            ok, why = test_upscaler()
            ui_post(lambda: self._upscaler_result(ok, why, None, par, done))
        threading.Thread(target=work, daemon=True).start()

    def _upscaler_result(self, ok, why, err, parent, done):
        if err is None:
            prefs = dict(SETTINGS.get("image_fix_prefs") or {})
            prefs["ai_test"] = "ok" if ok else why
            SETTINGS["image_fix_prefs"] = prefs
            _save_settings(SETTINGS)
        try:
            par = parent if parent.winfo_exists() else self
        except tk.TclError:
            par = self
        if err:
            messagebox.showerror(_i18n.t("mc.ai_upscaler_643b"), _i18n.t("mc.not_installed_ec73", err=err), parent=par)
        elif ok:
            messagebox.showinfo(_i18n.t("mc.ai_upscaler_643b"), _i18n.t("mc.real_esrgan_is_installed_4e94"), parent=par)
        else:
            messagebox.showwarning(_i18n.t("mc.ai_upscaler_643b"), _i18n.t("mc.installed_but_the_test_7b55", why=why), parent=par)
        if done:
            done()

