    def _fix_images_batch(self, rows):                         ### NEW v0.19.2 F4a ###
        """Preview (every image, its fix or why it is skipped), then the run
        with a progress window; one backup folder for the run."""
        plan = image_fix_batch_plan(rows)
        if not plan:
            messagebox.showinfo(shown_action(IMAGE_FIX_ACTION),
                                _i18n.t("mc.no_poster_folder_image_b139"),
                                parent=self)
            return None
        todo = [p for p in plan if p[3]]
        up = None
        ### NEW v0.20.1 TF6 — the AI upscaler, when it is installed and tested, can take the images that need up to ×2 ###
        if upscaler_state()[0]:
            plan_ai = image_fix_batch_plan(rows, ai=True)
            more = sum(1 for x in plan_ai if x[3]) - len(todo)
            if more > 0 and messagebox.askyesno(shown_action(IMAGE_FIX_ACTION), _i18n.t("tf6.ask", n=_n(more, "image")), parent=self):
                plan, todo, up = plan_ai, [x for x in plan_ai if x[3]], "ai"
        pv = _PreviewRunDialog(self, f"🛠  {shown_action(IMAGE_FIX_ACTION)} — " + _i18n.t("f3r.preview"),
                               image_fix_batch_text(plan) + _i18n.t("tf2.why", n=len(plan) - len(todo)) * bool(len(plan) - len(todo)),
                               file_stem="image_fix_preview", run_label=_i18n.t("mc.fix_images_e814"))
        self._image_fix_preview = pv
        self.wait_window(pv)
        if not pv.run or not todo:
            return None
        prog = _BatchProgressDialog(self, _i18n.t("au.prog.fix_images"), total=len(todo)) if len(todo) >= _PROGRESS_MIN else None

        ### MODIFIED v0.19.3 I7 — on the _BatchJob helper (same backups, messages, refresh) ###
        def _step(job, item):
            r, k, m, target, _note = item
            _up = upscale_function(cancel=job.cancelled) if up == "ai" else None   # v0.20.1 TF6
            _w = apply_image_fix(r, k, m, target, _up, job.ref, copy_to=image_fix_batch_copy(r, k))   ### v0.19.3 B66 ###
            job.changed.append(r["subfolder_path"])
            job.notes = getattr(job, "notes", []) + [f"{r.get('movie_name') or r.get('subfolder')}: {p}" for p in getattr(_w, "problems", [])]   # v0.19.5 WR-B6
            return True

        def _finish(job, skipped=len(plan) - len(todo)):
            msg = _i18n.t("m3.images_fixed", images=_n(job.done, "image")) + (_i18n.t("m3.skipped_preview", n=skipped) if skipped else "")
            if getattr(job, "notes", None):                       # v0.19.5 WR-B6
                msg += _i18n.t("mc.fixed_but_not_everything_d802", join="\n".join(job.notes[:8]))
            if job.errors:
                msg += _i18n.t("mc.not_changed_2fc6", join="\n".join(job.errors[:8]))
            msg += job.cancel_note()                                 ### NEW v0.19.4 B83 ###
            msg += ("\n\n" + UNDO_HINT) if job.done else ""            ### NEW v0.19.4 B109e ###
            ### NEW v0.20.1 TF2 — why images were skipped, and the posters among them can be replaced online at once ###
            _sk_rows = list({id(x[0]): x[0] for x in plan if not x[3] and x[1] == "poster"}.values())
            if skipped:
                msg += _i18n.t("tf2.why", n=skipped)
            if job.done:                                           # v0.20.1 RV4: players keep a copy of the old image
                _rn = artwork_refresh_note([x[0] for x in todo])
                msg += ("\n\n" + _rn) if _rn else ""
            if _sk_rows and (SETTINGS.get("tmdb_api_key", "").strip() or fanarttv_key()):
                ### MODIFIED v0.20.1 TF5 — a third choice: review the skipped posters one by one ###
                ch = _ChoiceDialog.ask(self, shown_action(IMAGE_FIX_ACTION), msg + _i18n.t("tf2.offer2", n=_n(len(_sk_rows), "poster")),
                                       [("replace", _i18n.t("tf2.btn_replace"), "ok"), ("review", _i18n.t("tf2.btn_review"), None),
                                        (None, _i18n.t("mc.close_cbdd"), None)])
                if ch == "replace":
                    self._replace_posters_for(_sk_rows)
                elif ch == "review":
                    self._review_posters_for(_sk_rows, preset="selection", sel_key="tf5.set.skipped")
                return
            messagebox.showinfo(shown_action(IMAGE_FIX_ACTION), msg, parent=self)

        _BatchJob(self, todo, IMAGE_FIX_ACTION, prog=prog,
                  name_of=lambda it: f"{it[0].get('movie_name', it[0].get('subfolder', ''))} ({it[1]})").run(_step, _finish)
        return todo

    def _copy_poster_to_folder(self, data_list, confirm=True):   # backups labelled "Copy poster → folder" (I1)
        """Overwrite folder.jpg with poster.jpg where they differ (backup first)."""
        if self._artwork_busy(data_list, _i18n.t("uf.copy_poster_folder_85f2")):   ### NEW v0.19.3 B62 ###
            return
        if self._busy(_i18n.t("uf.copy_poster_folder_85f2")):                ### MODIFIED v0.19.4 B91 — one message ###
            return
        targets = [d for d in data_list if copy_poster_needed(d)]   ### MODIFIED v0.19.1 B23; v0.19.4 B103 — the same test as the menu ###
        if not targets:
            messagebox.showinfo(_i18n.t("mc.copy_poster_jpg_folder_488b"),
                                _i18n.t("mc.nothing_to_do_folder_0e84"), parent=self)
            return
        if confirm and len(targets) > 1:                          ### NEW v0.19.3 I6 — several: a preview ###
            if not _ask_preview(self, _i18n.t("uf.copy_poster_jpg_folder_bf77"), copy_poster_preview_text(targets),
                                "copy_poster_preview", "  ▶ Copy  "):
                return
        elif confirm and not messagebox.askyesno(
                _i18n.t("mc.copy_poster_jpg_folder_488b"),
                _i18n.t("mc.overwrite_folder_jpg_with_fb56", n=_n(len(targets), 'movie')), icon="warning", parent=self):
            return
        prog = _BatchProgressDialog(self, _i18n.t("uf.copying_poster_jpg_folder_bd91"), total=len(targets)) \
               if len(targets) >= _PROGRESS_MIN else None     ### MODIFIED v0.19.1 ###

        ### MODIFIED v0.19.3 I7 — on the _BatchJob helper (same backups, messages, refresh) ###
        def _step(job, d):
            if not job.backup(d.get("movie_name", d["subfolder"]), d["folder_path"]):   ### MODIFIED v0.19.2 B40 ###
                raise BackupFailed()
            _new_f = not os.path.exists(d["folder_path"])         # v0.19.5 WR-C4
            _copy_image_as(d["poster_path"], d["folder_path"])   ### MODIFIED v0.19.1 B23 — .png/.tbn posters converted ###
            if _new_f:
                _sc.note_created(_BACKUP_ROOT, d.get("movie_name", d["subfolder"]), job.ref, d["folder_path"], None, logger=logger)
            logger.info(f"poster.jpg copied to folder.jpg: {d['subfolder_path']}")
            job.changed.append(d["subfolder_path"])              ### v0.19.0 ###
            return True

        def _finish(job):
            msg = _i18n.t("mc.folder_jpg_updated_in_5277", n=_n(job.done, 'movie'))
            if job.errors:
                msg += _i18n.t("mc.errors_83c4", join="\n".join(job.errors[:5]))
            msg += job.cancel_note()                                 ### NEW v0.19.4 B83 ###
            msg += ("\n\n" + UNDO_HINT) if job.done else ""            ### NEW v0.19.4 B109e ###
            messagebox.showinfo(_i18n.t("mc.copy_poster_jpg_folder_488b"), msg, parent=self)

        _BatchJob(self, targets, "Copy poster → folder", prog=prog,     ### I1 label ###
                  name_of=lambda d: d.get("movie_name", d["subfolder"])).run(_step, _finish)

    # ── Refresh table ──────────────────────────────────────────────────────────
    def _view_state(self):                                     ### NEW v0.19.3 I4 — Tk thread ###
        """(sort spec, filter text, health filter, library filter) of the table."""
        return ([dict(l) for l in getattr(self, "_sort_spec", _se.DEFAULT_SPEC)],
                self._filter_var.get() if hasattr(self, "_filter_var") else "",   ### ADDED_BY_CLAUDE_v18.2 ###
                getattr(self, "_health_filter", None),                            ### NEW v0.18.4 ###
                self._library_filter() if hasattr(self, "_lib_filter_var") else "")   ### NEW v0.19.0 ###

    def _refresh_table(self, prepared=None):                   ### prepared v0.19.3 I4 ###
        """*prepared* = (view state, rows already sorted and filtered for it) —
        the restore does that work in its worker; used when the view is unchanged."""
        if hasattr(self, "_sb_sel"):                                   ### NEW v0.19.1 B21 — counter follows rebuilds ###
            self.after_idle(self._update_sel_count)
        if not self._results:
            self._clear_tree()                                   ### NEW v0.19.5 SH-E2 — the last rows went: they leave the screen too ###
            return
        keep = self._view_keep()                                 ### NEW v0.19.4 P1 ###
        self._fill_swaps = {}                                    ### NEW v0.19.4 P1 — rows replaced during the fill ###
        self._clear_tree()                                      ### MODIFIED v0.19.3 I4 / v0.19.4 B110h ###
        view = self._view_state()
        _spec, term, hf, lf = view
        self._update_heading_marks()
        if prepared is not None and prepared[0] == view:
            filtered = prepared[1]
        else:
            filtered = view_rows(self._results, view)             ### v0.19.3 I4 — sort (B63) + filter, pure ###

        ### MODIFIED v0.19.3 I4 — a big table is filled TABLE_CHUNK rows at a time
        ### (after()), so the window answers while it fills; a newer refresh stops it ###
        self._tbl_gen = getattr(self, "_tbl_gen", 0) + 1
        grouped = self._grouped()                               ### NEW v0.19.4 B110h ###
        self.tree.configure(show="tree headings" if grouped else "headings")
        self.tree.column("#0", width=px(34) if grouped else 0, minwidth=0, stretch=False)
        self._year_on_group(grouped)                            ### NEW v0.19.4 fix 2a ###
        items = _cr.group_rows(filtered, group_order(view[0])) if grouped else [("movie", r) for r in filtered]   # B118
        totals = {}
        if grouped:
            for r in self._results:
                k = _cr.group_key(r)
                if k:
                    totals[k] = totals.get(k, 0) + 1
        self._coll_totals = totals                               # v0.20.2 PB12: read by _coll_row_update
        gen, chunk = self._tbl_gen, (TABLE_CHUNK if len(filtered) > TABLE_CHUNK_FROM else len(items) or 1)

        def _fill(start):
            if gen != self._tbl_gen:
                return
            end = min(len(items), start + chunk)
            for i in range(start, end):                          ### MODIFIED_BY_CLAUDE_v18.2 ###
                it = items[i]
                if it[0] == "movie":
                    r = self._fill_swaps.get(it[1].get("subfolder_path"), it[1]) if self._fill_swaps else it[1]   # P1
                    tag = r["health_status"] + ("_odd" if i % 2 else "")
                    iid = self.tree.insert("", "end", values=self._rv(r), tags=self._tags(r, tag))   # FB3
                    self._item_map[iid] = r
                    continue
                _k, key, name, rows = it                         ### NEW v0.19.4 B110h — a collection row ###
                if self._fill_swaps:                                 # P1
                    rows = [self._fill_swaps.get(r.get("subfolder_path"), r) for r in rows]
                piid = self.tree.insert("", "end", text="", open=key in self._coll_open,
                                        values=self._coll_values(name, rows, totals.get(key, len(rows))),
                                        tags=(_cr.worst_health(rows) + ("_odd" if i % 2 else ""), "coll"))
                self._coll_map[piid] = (key, name, rows)
                for j, r in enumerate(rows):
                    tag = r["health_status"] + ("_odd" if (i + j + 1) % 2 else "")
                    iid = self.tree.insert(piid, "end", values=self._child_values(self._rv(r)), tags=self._tags(r, tag))   # fix 7; FB3
                    self._item_map[iid] = r
            if end < len(items):
                self.after(1, lambda: _fill(end))
            else:
                self._tbl_filling = False
                self._fill_swaps = {}
                self._view_restore(keep)                         ### NEW v0.19.4 P1 ###
        self._tbl_filling = len(items) > chunk
        _fill(0)

        if hasattr(self, "_filter_label"):                       ### ADDED_BY_CLAUDE_v18.2 ###
            if term.strip() or hf or lf:
                self._filter_label.configure(
                    text=_i18n.t("filter.shown", shown=_i18n.num(len(filtered)), total=_i18n.num(len(self._results))))
            else:
                self._filter_label.configure(text="")

