def cert_fields(nfo_path, xml_path=None):                        ### NEW v0.20.2 CR ###
    """{"cert_tags": {"nfo:mpaa": text | '' | None, …}} — the age-rating tags of the files (None = the file has no such
    tag; a file that is not there gives no keys). The cached text: no extra disk access."""
    out = {}
    if nfo_path:
        out.update(_ce.read_tags(_read_text(nfo_path), "nfo"))
    if xml_path:
        out.update(_ce.read_tags(_read_text(xml_path), "xml"))
    return {"cert_tags": out}


def cert_settings(settings=None):                                ### NEW v0.20.2 CR ###
    """(the accepted countries in order, the most values a list tag keeps) — the app language's country + US by default."""
    s = settings if settings is not None else SETTINGS
    cc = _ce.clean_countries(s.get("cert_countries") or []) or _ce.default_countries(_i18n.current())
    try:
        mx = max(1, min(10, int(s.get("cert_max") or 3)))
    except (TypeError, ValueError):
        mx = 3
    return cc, mx


def cert_tags_in_use(row, tags=None):                            ### NEW v0.20.2 CR ###
    """The row's age-rating tags of the files the library uses (health mode / NFO only)."""
    lib = _lib_root_of(row)
    use = {"nfo": nfo_in_use(lib), "xml": xml_in_use(lib)}
    return {k: v for k, v in (row.get("cert_tags") if tags is None else tags or {}).items() if use.get(k.split(":", 1)[0])}


def cert_candidate(row):                                         ### NEW v0.20.2 CR ###
    nfo, xml = _metadata_targets(row)[:2]
    return bool(nfo or xml)


def cert_plan_row(row, countries, max_n, key="", omdb_key="", fetch=None):   ### NEW v0.20.2 CR — worker ###
    """Read the files now (strict UTF-8), fetch online only what the files lack (TMDB release_dates; OMDb's US rating
    when TMDB has none), and plan.  Returns {"row", "nfo", "xml", "tags", "online", "plan", "error", "fetched"}."""
    nfo, xml = _metadata_targets(row)[:2]
    it = {"row": row, "nfo": nfo, "xml": xml, "tags": {}, "online": {}, "plan": None, "error": None, "fetched": False}
    try:
        if nfo:
            it["tags"].update(_ce.read_tags(_read_for_edit(nfo)[0], "nfo"))
        if xml:
            it["tags"].update(_ce.read_tags(_read_for_edit(xml)[0], "xml"))
    except (OSError, NotUtf8Error, ValueError) as ex:
        it["error"] = f"{os.path.basename(str(getattr(ex, 'filename', '') or nfo or xml or ''))}: {ex}"
        return it
    have, _u = _ce.file_values(it["tags"])
    lists = any((k.split(":", 1)[0], k.split(":", 1)[1]) in _ce.LIST or len(_ce.parse(v)) > 1
                for k, v in it["tags"].items() if v)
    need = [cc for cc in countries[:(max_n if lists else 1)] if cc not in have]
    if need and not any(cc in have for cc in countries):
        need = list(countries)
    online = {}
    if need:
        tid = (row.get("source_tmdb_val") or "").strip()
        if key and tid.isdigit():
            try:
                data = (fetch or _tmdb_rate_limited_fetch)(f"https://api.themoviedb.org/3/movie/{tid}/release_dates?api_key={key}")
                online = _ce.pick_tmdb((data or {}).get("results"))
                it["fetched"] = True
            except Exception as ex:
                if not _is_http_404(ex):
                    raise
        imdb = (row.get("source_imdb_val") or "").strip()
        if "US" not in online and not any(cc in online or cc in have for cc in countries) and omdb_key and imdb:
            try:
                d = (fetch or (lambda u: _http_get_json("omdb", u, timeout=10)))(
                    f"https://www.omdbapi.com/?apikey={omdb_key}&i={imdb}&type=movie")
                us = _ce.omdb_us((d or {}).get("Rated")) if (d or {}).get("Response", "True") == "True" else None
                if us:
                    online["US"] = us
                it["fetched"] = True
            except Exception as ex:
                if not _is_http_404(ex):
                    raise
    it["online"] = online
    it["plan"] = _ce.plan(it["tags"], countries, max_n, online)
    return it


def cert_preview_text(items, countries, max_n):                  ### NEW v0.20.2 CR ###
    T = _i18n.t
    nm = lambda r: (r.get("movie_name") or r.get("subfolder") or "?") + (f" ({r['movie_year']})" if r.get("movie_year") not in (None, "", "-") else "")
    ch = [it for it in items if it["plan"] and it["plan"]["status"] == "change"]
    L = [T("cr.pv_head", n=len(ch), cc=", ".join(countries), mx=max_n), "=" * 60, ""]
    for it in ch:
        L.append("  " + nm(it["row"]) + ("   " + T("cr.pv_us") if it["plan"]["us_fallback"] else ""))
        for k, v in sorted(it["plan"]["writes"].items()):
            old = it["tags"].get(k)
            L.append(f"      <{k.split(':', 1)[1]}> ({k.split(':', 1)[0]}): "
                     + (T("cr.pv_added") if old is None else f"'{old}'") + " → " + (f"'{v}'" if v else T("cr.pv_blank")))
    none = [it for it in items if it["plan"] and it["plan"]["status"] == "none"]
    if none:
        L += ["", T("cr.pv_none", n=len(none))] + ["  " + nm(it["row"]) for it in none]
    err = [it for it in items if it["error"]]
    if err:
        L += ["", T("cr.pv_errors", n=len(err))] + ["  " + nm(it["row"]) + " — " + it["error"] for it in err]
    return "\n".join(L)


def collection_fields(nfo_path, xml_path=None):                  ### NEW v0.19.4 B110a ###
    """Row keys of B110 read from the files (the NFO text is the cached one; no extra disk access)."""
    c = _cr.read_set(_read_text(nfo_path)) if nfo_path else None
    xt = _read_text(xml_path) if xml_path else None
    return {"coll_nfo": c, "coll_xml": _cr.read_xml_collection(xt) if xt else None,   ### v0.19.4 fix 6 — movie.xml read ###
            "coll_xml_read": 1, "coll_xml_hint": xml_collection_hint(xt) if xt else 0}


def read_unread_collections(rows):                              ### NEW v0.19.4 review fix 1 ###
    """Rows cached before v0.19.4 (coll_unread): read their NFO <set> now (worker thread, no Tk).
    A library that cannot be reached, or an NFO that cannot be read, keeps the mark (the next scan reads it).
    Returns how many rows were read."""
    todo = [r for r in rows if r.get("coll_unread")]
    if not todo:
        return 0
    roots_ok, n = {}, 0
    for r in todo:
        root = r.get("library_root") or os.path.dirname(r.get("subfolder_path") or "")
        if root not in roots_ok:
            try:
                roots_ok[root] = bool(root) and os.path.isdir(root)
            except OSError:
                roots_ok[root] = False
        if not roots_ok[root]:
            continue
        nfo = r.get("nfo_path") if r.get("nfo_exists") else None
        if nfo:
            text = _read_text(nfo)
            if text is None:
                continue
            try:
                r["coll_nfo"] = _cr.read_set(text)
            except Exception:
                continue
        else:
            r["coll_nfo"] = None
        xp = r.get("xml_path") if r.get("xml_exists") else None    ### NEW v0.19.4 fix 6 — movie.xml too ###
        if xp:
            xt = _read_text(xp)
            if xt is not None:
                r["coll_xml"], r["coll_xml_read"] = _cr.read_xml_collection(xt), 1
        else:
            r["coll_xml_read"] = 1
        r.pop("coll_unread", None)
        n += 1
    left = len(todo) - n
    logger.info(f"Collections: read the <set> of {n} movie(s) cached before v0.19.4"
                + (f"; {left} not reachable (read on the next scan)" if left else ""))
    return n


def old_tag_rows(rows, old_cache):                                ### NEW v0.20.1 T8 ###
    """The rows read_old_tag_values would read (the start-up shows the rows first and reads these after)."""
    return [r for r in rows if old_cache or r.get("tags_unread")]


def read_old_tag_values(rows, old_cache, progress=None, cancelled=None, workers=1):   ### NEW v0.19.5 B121, B123, B124 ###
    """Rows saved before v0.19.5 keep values those versions read differently: Language OK, the Language column, the rating, Date
    added. Read once more from the files (worker thread, no online call, no FFprobe run). A library that cannot be reached keeps
    the mark. Returns how many rows were read.
    ### MODIFIED v0.20.1 T8 ### progress(done, total), cancelled() (a scan or closing stops it: the rest keep the mark and are
    read next time), several rows at once (a NAS answers much faster in parallel)."""
    todo = old_tag_rows(rows, old_cache)
    roots_ok = {}
    iso = SETTINGS.get("lang_ok_code", "PT")
    for r in todo:
        r["tags_unread"] = True                                    # cleared when the row is read
        root = r.get("library_root") or os.path.dirname(r.get("subfolder_path") or "")
        if root not in roots_ok:
            try:
                roots_ok[root] = bool(root) and os.path.isdir(root)
            except OSError:
                roots_ok[root] = False
    todo = [r for r in todo if roots_ok.get(r.get("library_root") or os.path.dirname(r.get("subfolder_path") or ""))]
    done = [0]
    lock = threading.Lock()

    def _one(r):
        if cancelled and cancelled():
            return 0
        got = _read_old_tags_row(r, iso)
        with lock:
            done[0] += 1
            k = done[0]
        if progress and (k % 25 == 0 or k == len(todo)):
            progress(k, len(todo))
        return got
    if workers > 1 and len(todo) > 1:
        import concurrent.futures as _cf
        with _cf.ThreadPoolExecutor(max_workers=workers, thread_name_prefix="old-rows") as ex:
            n = sum(ex.map(_one, todo))
    else:
        n = sum(_one(r) for r in todo)
    if todo:
        logger.info(f"Read the language, rating and date of {n} movie(s) saved by an older version")
    return n


def _read_old_tags_row(r, iso):                                   ### v0.20.1 T8 — the body of the old loop, one row ###
    nfo = r.get("nfo_path") if r.get("nfo_exists") else None
    xml = r.get("xml_path") if r.get("xml_exists") else None
    try:
        r["language"] = r["xml_language"] = extract_language_from_xml(xml) if xml else "—"
        r["nfo_language"], r["nfo_audio_lang"] = nfo_language_fields(nfo)   ### NEW v0.19.6 TR1 ###
        (r["rating_str"], r["rating_status"], r["rating_value"], r["rating_votes"], r["rating_votes_src"],
         r["rating_src"]) = extract_rating_from_files(nfo, xml)
        r["date_added"], r["date_added_src"] = date_added_for(nfo, xml, r.get("video_path"), r.get("subfolder_path"))
        r.update(cert_fields(nfo, xml))                            ### NEW v0.20.2 CR ###
        lo = compute_lang_ok(r.get("video_path"), r.get("subs_internal") or [], r.get("subs_external") or [], nfo, xml, iso,
                             use_ffprobe=False, subs_hard=r.get("subs_hard"))
        if r.get("video_path") and lang_in_stored_streams(r, iso):
            lo = "Y"
        r["lang_ok"] = lo
        r.pop("tags_unread", None)
        return 1
    except Exception as ex:
        r["tags_unread"] = True
        logger.warning(f"Old row not read again: {r.get('subfolder')}: {ex}")
        return 0


def _matches_filter(row: dict, term: str) -> bool:              ### ADDED_BY_CLAUDE_v18.2 ###
    """Return True if the row matches the filter term (case-insensitive OR logic)."""
    if not term or not term.strip():
        return True
    t = term.strip().lower()
    name    = (row.get("movie_name") or row.get("subfolder", "")).lower()
    year    = str(row.get("movie_year", "-")).lower()
    genre   = row.get("genre_display", "").lower()
    health  = row.get("health_status", "").lower()
    lang    = row.get("language", "").lower()
    quality = row.get("video_quality", "").lower()
    reasons = " | ".join(row.get("health_reasons", []) or []).lower()   ### NEW v0.18.4 ###
    coll = collection_name(row).lower()                                ### NEW v0.19.4 B110a ###
    if (t in name or year.startswith(t) or t in genre
            or t == health or t in lang or t in quality or t in reasons or (bool(coll) and t in coll)):
        return True
    if _i18n.current() == "en":
        return False
    ### NEW v0.20.0 UI1e — the reasons and the status as SHOWN in Portuguese / Spanish match too (the stored text is English)
    if health and _i18n.has("ex.health." + health) and t == _i18n.t("ex.health." + health).lower():
        return True
    return any(t in _shown_reason_lower(r) for r in (row.get("health_reasons", []) or []))


_SHOWN_REASON_CACHE = {}                                          ### NEW v0.20.0 UI1e ###


def _shown_reason_lower(r):
    """reason_text(r).lower(), remembered per language (the filter runs on every key press over every row)."""
    k = (_i18n.current(), r)
    v = _SHOWN_REASON_CACHE.get(k)
    if v is None:
        if len(_SHOWN_REASON_CACHE) > 20000:
            _SHOWN_REASON_CACHE.clear()
        v = _SHOWN_REASON_CACHE[k] = reason_text(r).lower()
    return v


