### NEW v0.19.2 B59 — single instance (family item X5) ###
# A named mutex dies with its process, so no lock survives a crash.
SINGLE_INSTANCE_MUTEX = "Local\\MediaClinic.SingleInstance"
_ERROR_ALREADY_EXISTS = 183


def acquire_single_instance(name=SINGLE_INSTANCE_MUTEX):
    """(handle, first): first=False when another MediaClinic holds *name*.
    Off Windows (or on any error) the app simply starts: (None, True)."""
    if os.name != "nt":
        return None, True
    try:
        import ctypes
        k32 = ctypes.WinDLL("kernel32", use_last_error=True)
        k32.CreateMutexW.restype = ctypes.c_void_p
        h = k32.CreateMutexW(None, False, name)
        if not h:
            return None, True
        if ctypes.get_last_error() == _ERROR_ALREADY_EXISTS:
            k32.CloseHandle(ctypes.c_void_p(h))
            return None, False
        return h, True
    except Exception:
        return None, True


def windows_ui_locale():                                        ### NEW v0.20.0 UI1a ###
    """The Windows display language as a locale name ("pt-BR", "en-US" …), "" off Windows or on any error."""
    if os.name != "nt":
        return ""
    try:
        import ctypes
        k32 = ctypes.windll.kernel32
        lang = k32.GetUserDefaultUILanguage()
        buf = ctypes.create_unicode_buffer(85)
        if k32.LCIDToLocaleName(int(lang), buf, 85, 0):
            return buf.value
    except Exception:
        pass
    return ""


